INSERT INTO dbo.sc_sop_meta (meta_key, data) VALUES (N'meta', N'{"purpose":"This docket sets out, at corporate level, how Swish supply chain and production processes work today (As-is 2026), how they must work after the ERP implementation (To-be 2027), why (interview evidence and management decisions), how each step is governed (controls, policies, KPIs, approvals) and how far the ERP is expected to support it. It is the reference for stakeholders, policy reviewers, department heads and the ERP provider. It is reviewed periodically and formally once a year; at each review the approved To-be becomes the next As-is.","scope":"28 processes (PA-01 to PA-28): foundation and master data; planning and replenishment; inbound and quality; warehouse operations; transfers and distribution (warehouse, CPU and direct-to-store); inventory control (counts, wastage, expiry); recipe and production (CPU / CBU, R&D, substitution, finished goods); cost control, traceability, month-end close and reporting; programme governance (migration, POS transition, change and training); vendor and purchase-to-pay; standard cost, budget and overhead allocation; non-inventoriable procurement. Retail / cooperative channel, Call Center orders and equipment maintenance are covered within these processes. Franchise is kept as future readiness only.","approach":"Structured interviews with department officials (CPU, CBU, Warehouse, Purchase, QC, Operations, R&D, Training, Cost Control), the Finance Director''s As-is / To-be review and the warehouse replenishment workbook (Swish SPS) were recorded word for word in an evidence log. Contradictions and open questions were resolved by management decision and recorded as policies (POL-D). Each process was then built step by step (one action, one role, one record), mapped one-to-one to the ERP provider''s 247-task list, and tagged with governance pillar, controls, policies, KPIs, ERP fit and evidence. Method references: APQC / SCOR process levels, SIPOC, COSO controls, RICEFW gap types, MoSCoW priority."}');
INSERT INTO dbo.sc_sop_meta (meta_key, data) VALUES (N'polsumm', N'[["POL-D01","ERP replaces MC and the self-developed platforms in phases; Foodics POS stays integrated meanwhile."],["POL-D02","Swish inventory article is primary; brand / pack variants carry yield and unit effects; Costing is custodian."],["POL-D03","One document from start to finish, corrected in place — not rejected and re-raised."],["POL-D04","48-hour store ordering; additional orders case by case; changes only by production with approval."],["POL-D05","Maker-checker on every workflow except simple day-to-day tasks; nothing without a PO; QC at every source and dispatch point."],["POL-D06–08","100% receipt confirmation; daily stock / wastage for main items, monthly for all; batch and expiry for all items; minimum shelf life on the PO."],["POL-D10–11","Standard cost daily, actual at inventory-log close; actual consumption drives cost; WhatsApp / email outcomes recorded in the system."],["POL-D21","CPU / CBU output transferred at gate value (material + labour + production overhead at normal capacity), 0% mark-up, monthly settlement of over / under absorption (IAS 2)."],["POL-D22–26","Single agreed approval level per transaction; R&D food-safety checklist; month-end close calendar WD-1 to WD+5; store ordering guidance and Costing approval of store-to-store transfers."],["POL-D27–31","EGC owns CPU, CBU and the warehouse; ERP Administrator and department ERP representatives; recipe ownership R&D → CPU → Costing; EGC supply documented like a vendor; limited D365 Store Commerce at stores."],["POL-D32","Programme phasing (section 6)."]]');
INSERT INTO dbo.sc_sop_meta (meta_key, data) VALUES (N'phasing', N'[["Project 1","Supply chain ERP — core inventory, purchasing, warehouse, CPU / CBU production, costing and Foodics integration; MC retired. Built in waves W1 Foundation → W2 Core transactions → W3 CPU / CBU → W4 Cost control → W5 Optimisation (order finalised with the ERP consultant)."],["Project 2","Replacement of the Swish portals / warehouse system (integrated until then) and overhead absorption."],["Project 3","POS replacement (Foodics stays integrated until then) and franchise readiness."],["Mitigation","Wave entry gates and UAT; MC parallel run until W1–W4 are live and reconciled; portals and Foodics integrated until replaced."]]');
INSERT INTO dbo.sc_sop_meta (meta_key, data) VALUES (N'openitems', N'["Variance-review frequency (PA-17-S080) — daily audit not feasible; frequency to be agreed.","Implementation wave order and dependencies — to be finalised with the ERP consultant (PA-23-S065).","Approval levels in KWD (Master - Lists §M) — for confirmation by the Costing Head and Finance Director.","KPI targets marked ''to be set'' and proposed time limits — to be confirmed at docket review.","Power BI reports and Swish portals — review pending access; findings will be added at the next update."]');
INSERT INTO dbo.sc_sop_meta (meta_key, data) VALUES (N'depts', N'["Warehouse","CPU / CBU","Store Operations","Call Center","Purchase","Finance","Cost Control","Quality Control","R&D","Logistics","Marketing","Data & Analytics","IT / ERP","Operational Excellence","Training","Requesting department","Management / Programme"]');
INSERT INTO dbo.sc_sop_meta (meta_key, data) VALUES (N'roles', N'{"Warehouse":"Receiver, Checker, Picker, Dispatcher, Supervisor, Manager","CPU / CBU":"CPU Administrator, Section Supervisor, Sous Chef, Senior Chef, Assistant Manager, Manager","Store Operations":"Store Manager, Store Senior, Area Manager, Brand Manager, Operations GM","Call Center":"Agent, Supervisor","Purchase":"Buyer, Assistant Purchase Manager, Purchase Chief","Finance":"Accountant, Finance Manager, Finance Director","Cost Control":"Cost Controller, Costing Manager","Quality Control":"QC Officer, QC Head","R&D":"R&D Chef, R&D Manager","Logistics":"Dispatcher, Driver, Logistics Supervisor","Marketing":"Marketing Executive, Marketing Manager","Data & Analytics":"Analyst","IT / ERP":"IT / ERP Support, Integration Team","Operational Excellence":"Operational Excellence Manager","Training":"Training Manager, Trainers","Requesting department":"Any department raising the request","Management / Programme":""}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-01', 1, N'Foundation & Master Data', N'Item Master', N'Cost Control', N'{"id":"PA-01","grp":"Foundation & Master Data","name":"Item Master","lead":"Cost Control","depts":"Cost Control (9); Requesting department (1); R&D (1); Purchase (1); CPU / CBU (1); Marketing (1); Finance (1); IT / ERP (1)","steps":18,"new":6,"modify":10,"keepRetire":"0 / 2","fit":"7 / 9 / 0 / 2","open":0,"desc":"Create, approve, activate and maintain an inventory item.\nFlow: Item request → Duplicate check → Classification → UOM and conversions → Batch/expiry tracking setup → Posting and cost groups → Approval and activation → Release to legal entities → Change control"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-02', 2, N'Foundation & Master Data', N'Site & Location Structure', N'Warehouse', N'{"id":"PA-02","grp":"Foundation & Master Data","name":"Site & Location Structure","lead":"Warehouse","depts":"Warehouse (6); Finance (1); IT / ERP (1); CPU / CBU (1); Store Operations (1); Quality Control (1)","steps":11,"new":6,"modify":5,"keepRetire":"0 / 0","fit":"8 / 3 / 0 / 0","open":0,"desc":"Create the physical and logical inventory structure for Shwish.\nFlow: Legal-entity mapping → Site setup → Warehouse setup (central, CPU, bakery, outlets) → Zone design (frozen, chilled, ambient) → Location creation → Transit locations → Quarantine and rejected stock → Damaged/expired stock → Location profiles and capacity"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-03', 3, N'Planning & Replenishment', N'Planning & Replenishment', N'Warehouse', N'{"id":"PA-03","grp":"Planning & Replenishment","name":"Planning & Replenishment","lead":"Warehouse","depts":"Warehouse (5); Purchase (4); Data & Analytics (2); Marketing (1); Requesting department (1)","steps":18,"new":6,"modify":7,"keepRetire":"0 / 5","fit":"7 / 4 / 2 / 5","open":0,"desc":"Calculate what the warehouse, CPU, bakery and outlets need, and when they need it.\nFlow: Sales demand (POS) → Forecast → Min/max and lead times → Safety stock → Net requirement calculation → Planned-order review → Approval → Firm to purchase, transfer or production order → Monitor exceptions"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-04', 4, N'Inbound & Quality', N'Warehouse Receiving', N'Warehouse', N'{"id":"PA-04","grp":"Inbound & Quality","name":"Warehouse Receiving","lead":"Warehouse","depts":"Warehouse (16); Quality Control (5); Purchase (2); Cost Control (1)","steps":28,"new":10,"modify":13,"keepRetire":"1 / 4","fit":"12 / 6 / 5 / 5","open":0,"desc":"Receive supplier goods against an approved purchase order.\nFlow: Approved PO → Delivery arrival → Document check → Quantity registration → Batch and expiry capture → Quality inspection → Accept, reject or quarantine → Putaway → Product receipt"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-05', 5, N'Warehouse Operations', N'Warehouse Operations', N'Warehouse', N'{"id":"PA-05","grp":"Warehouse Operations","name":"Warehouse Operations","lead":"Warehouse","depts":"Warehouse (9); Quality Control (1)","steps":10,"new":6,"modify":2,"keepRetire":"2 / 0","fit":"8 / 1 / 1 / 0","open":0,"desc":"Move accepted inventory from receiving to the correct warehouse location.\nFlow: Product receipt → Putaway work created → Storage zone selected → Scan item/licence plate → Scan and validate location → Confirm quantity → Blocked/full location handling → Replenish picking locations → Capacity monitoring"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-06', 6, N'Transfers & Distribution', N'Warehouse to Outlet', N'Warehouse', N'{"id":"PA-06","grp":"Transfers & Distribution","name":"Warehouse to Outlet","lead":"Warehouse","depts":"Warehouse (12); Store Operations (9); Logistics (3); Quality Control (1); Cost Control (1)","steps":32,"new":22,"modify":2,"keepRetire":"2 / 6","fit":"15 / 5 / 6 / 6","open":0,"desc":"Supply inventory from the central warehouse to outlets.\nFlow: Demand or request → Approval → Transfer order → Reservation → Picking → Checking → Staging → Dispatch → In transit → Outlet receiving → Difference resolution → Closure"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-07', 7, N'Transfers & Distribution', N'Store to Store', N'Store Operations', N'{"id":"PA-07","grp":"Transfers & Distribution","name":"Store to Store","lead":"Store Operations","depts":"Store Operations (6); Cost Control (1)","steps":7,"new":7,"modify":0,"keepRetire":"0 / 0","fit":"7 / 0 / 0 / 0","open":0,"desc":"Transfer stock between outlets when there is an urgent operational need.\nFlow: Shortage identified → Availability confirmed by supplying outlet → Area Manager approval → Transfer order → Dispatch → Receipt → Difference resolution"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-08', 8, N'Inbound & Quality', N'Direct to Outlet', N'Store Operations', N'{"id":"PA-08","grp":"Inbound & Quality","name":"Direct to Outlet","lead":"Store Operations","depts":"Store Operations (6); Purchase (3); Finance (1)","steps":13,"new":7,"modify":3,"keepRetire":"0 / 3","fit":"6 / 2 / 2 / 3","open":0,"desc":"Receive supplier goods directly at an outlet while maintaining Procurement, Inventory and Finance controls.\nFlow: Direct-delivery approval → PO to outlet warehouse → Supplier delivery → Document check → Quantity and expiry recording → Rejected/missing stock reported → Product receipt → Supplier difference resolution"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-09', 9, N'Inventory Control', N'Counting & Adjustment', N'Cost Control', N'{"id":"PA-09","grp":"Inventory Control","name":"Counting & Adjustment","lead":"Cost Control","depts":"Cost Control (8); Store Operations (3)","steps":13,"new":10,"modify":1,"keepRetire":"0 / 2","fit":"7 / 4 / 0 / 2","open":0,"desc":"Verify physical stock and post approved differences.\nFlow: Count plan and ABC frequency → Count schedule → Blind physical count → System variance → Independent recount → Variance reason → Approval → Adjustment posting → Root-cause investigation"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-10', 10, N'Inventory Control', N'Wastage & Expiry', N'Store Operations', N'{"id":"PA-10","grp":"Inventory Control","name":"Wastage & Expiry","lead":"Store Operations","depts":"Store Operations (5); Cost Control (5); Warehouse (1)","steps":12,"new":6,"modify":5,"keepRetire":"0 / 1","fit":"7 / 3 / 1 / 1","open":0,"desc":"Record, approve and financially post inventory that can no longer be used or sold.\nFlow: Loss identified → Item, quantity, batch and reason recorded → Reason classification → Evidence attached → Supervisor verification → Cost Control/QA approval → Disposal → Inventory posting → Wastage reporting"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-11', 11, N'Recipe & Production', N'Recipe Governance', N'Cost Control', N'{"id":"PA-11","grp":"Recipe & Production","name":"Recipe Governance","lead":"Cost Control","depts":"Cost Control (8); CPU / CBU (2); R&D (2); Quality Control (1)","steps":15,"new":1,"modify":12,"keepRetire":"0 / 2","fit":"7 / 6 / 0 / 2","open":0,"desc":"Create, test, cost, approve and activate production recipes.\nFlow: Recipe request → Ingredient setup → Quantity and UOM validation → Sub-recipe linking → Yield test → Cost calculation → QA approval → Business approval → Version activation → Previous version expired"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-12', 12, N'Recipe & Production', N'Production Planning', N'CPU / CBU', N'{"id":"PA-12","grp":"Recipe & Production","name":"Production Planning","lead":"CPU / CBU","depts":"CPU / CBU (10); Store Operations (1)","steps":13,"new":3,"modify":8,"keepRetire":"0 / 2","fit":"3 / 7 / 1 / 2","open":0,"desc":"Convert outlet demand and forecasts into an approved production plan.\nFlow: Demand → Requirement calculation → Planned batch order → Material check → Capacity review → Firming → Scheduling → Release"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-13', 13, N'Recipe & Production', N'Material Issue', N'CPU / CBU', N'{"id":"PA-13","grp":"Recipe & Production","name":"Material Issue","lead":"CPU / CBU","depts":"CPU / CBU (8); Warehouse (3); Training (2); Cost Control (1); R&D (1)","steps":19,"new":5,"modify":10,"keepRetire":"0 / 4","fit":"9 / 5 / 1 / 4","open":0,"desc":"Issue ingredients to an approved CPU or bakery batch order and record what was actually consumed.\nFlow: Ingredient requirement → Batch reservation → Pick list → Picking and scanning → FEFO/expiry selection → Issue to production → Actual consumption → Excess return → Variance review"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-14', 14, N'Recipe & Production', N'Production Execution', N'CPU / CBU', N'{"id":"PA-14","grp":"Recipe & Production","name":"Production Execution","lead":"CPU / CBU","depts":"CPU / CBU (9); Quality Control (2); Cost Control (1); Finance (1); Store Operations (1)","steps":15,"new":5,"modify":8,"keepRetire":"1 / 1","fit":"10 / 3 / 1 / 1","open":0,"desc":"Produce, inspect and record finished goods from a CPU or bakery batch order.\nFlow: Batch order start → Process stages → Actual consumption → QA checks → Finished output and batch → Loss/scrap → Yield calculation → Report as finished → Variance review → Order end"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-15', 15, N'Recipe & Production', N'Ingredient Substitution', N'CPU / CBU', N'{"id":"PA-15","grp":"Recipe & Production","name":"Ingredient Substitution","lead":"CPU / CBU","depts":"CPU / CBU (6); Quality Control (2); R&D (1); Cost Control (1)","steps":11,"new":3,"modify":7,"keepRetire":"0 / 1","fit":"4 / 6 / 0 / 1","open":0,"desc":"Replace an unavailable ingredient through a controlled and approved process.\nFlow: Shortage reported → Approved alternatives reviewed → Culinary impact → QA quality/allergen check → Cost impact → Approval → Substitute recorded on batch order → Consumption recorded → Yield and quality review"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-16', 16, N'Recipe & Production', N'CPU Finished Goods', N'CPU / CBU', N'{"id":"PA-16","grp":"Recipe & Production","name":"CPU Finished Goods","lead":"CPU / CBU","depts":"CPU / CBU (8); Quality Control (2); Store Operations (1)","steps":11,"new":2,"modify":7,"keepRetire":"2 / 0","fit":"6 / 5 / 0 / 0","open":0,"desc":"Transfer completed production from CPU or bakery to warehouses and outlets.\nFlow: QA batch release → Finished-goods availability → Allocation to outlets → Transfer orders → FEFO picking and staging → Dispatch confirmation → Receipt → Shortage/damage investigation"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-17', 17, N'Costing & Close', N'Cost Control & Consumption', N'Cost Control', N'{"id":"PA-17","grp":"Costing & Close","name":"Cost Control & Consumption","lead":"Cost Control","depts":"Cost Control (8); IT / ERP (1); Call Center (1)","steps":11,"new":6,"modify":4,"keepRetire":"0 / 1","fit":"3 / 3 / 2 / 3","open":1,"desc":"Compare expected ingredient consumption based on sales and recipes with actual inventory usage.\nFlow: POS sales import → Recipe mapping and explosion → Theoretical consumption → Actual usage → Exclude wastage, transfers and counts → Variance comparison → Investigation → Corrective action → Negative-stock alert"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-18', 18, N'Inventory Control', N'Traceability & Recall', N'Quality Control', N'{"id":"PA-18","grp":"Inventory Control","name":"Traceability & Recall","lead":"Quality Control","depts":"Quality Control (10)","steps":10,"new":9,"modify":1,"keepRetire":"0 / 0","fit":"8 / 2 / 0 / 0","open":0,"desc":"Trace a raw-material or finished-goods batch backward to its supplier and forward to affected production and outlets.\nFlow: Affected batch identified → Supplier receipt traced → Warehouse locations → Production batches using it → Finished products → Receiving outlets → Stock blocked → Recall instructions → Returns/destruction reconciled and closed"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-19', 19, N'Costing & Close', N'Month-End Close', N'Finance', N'{"id":"PA-19","grp":"Costing & Close","name":"Month-End Close","lead":"Finance","depts":"Finance (5); Cost Control (3); Warehouse (1); Purchase (1); Store Operations (1); CPU / CBU (1)","steps":13,"new":11,"modify":1,"keepRetire":"0 / 1","fit":"10 / 2 / 0 / 1","open":0,"desc":"Close inventory activity, value stock and reconcile the inventory subledger to Finance.\nFlow: Transaction cutoff → Complete receipts → Complete transfers → Review production → Post approved counts → Review negative inventory → Run costing → Generate valuation → Reconcile GL → Sign-off"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-20', 20, N'Reporting & Analytics', N'Reporting & Analytics', N'Data & Analytics', N'{"id":"PA-20","grp":"Reporting & Analytics","name":"Reporting & Analytics","lead":"Data & Analytics","depts":"Data & Analytics (5); IT / ERP (2)","steps":7,"new":4,"modify":3,"keepRetire":"0 / 0","fit":"0 / 7 / 0 / 0","open":0,"desc":"Provide management with timely operational, financial and exception reporting.\nFlow: KPI definitions agreed → Workspaces and inquiries → Dashboards by company, brand and role → Integration-failure alerts → Exception owners → Reconcile to transactions → Access-control test"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-21', 21, N'Inbound & Quality', N'Direct to CPU', N'CPU / CBU', N'{"id":"PA-21","grp":"Inbound & Quality","name":"Direct to CPU","lead":"CPU / CBU","depts":"CPU / CBU (5); Purchase (3); Quality Control (2)","steps":13,"new":1,"modify":9,"keepRetire":"0 / 3","fit":"7 / 2 / 1 / 3","open":0,"desc":"Receive perishable, CPU-specific categories (e.g. dairy, meat, and other items nominated by Operations) directly at a dedicated CPU receiving point, bypassing the central warehouse, while maintaining Procurement, Inventory and Finance controls equivalent to PA-04.\nFlow: Approved PO → Direct-to-CPU routing approval (category-restricted) → CPU receiving-bay arrival → Document check → Quantity, batch and expiry registration → Quality/temperature inspection → Accept, reject or quarantine → Product receipt → Immediate production allocation or CPU cold-store putaway"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-22', 22, N'Franchise Readiness', N'Franchise Readiness', N'Finance', N'{"id":"PA-22","grp":"Franchise Readiness","name":"Franchise Readiness","lead":"Finance","depts":"Finance (7); IT / ERP (1)","steps":8,"new":8,"modify":0,"keepRetire":"0 / 0","fit":"0 / 7 / 1 / 0","open":0,"desc":"Define transfer pricing, royalty/management-fee calculation, cost allocation and data-visibility rules needed once the CPU begins supplying franchised stores in addition to sister-company outlets.\nFlow: Legal-entity / franchise-account setup → Franchise price-list and mark-up definition → Royalty / management-fee calculation basis → Franchise-store transfer and invoicing → Franchise-store COGS and margin reporting → Data-visibility and access-boundary enforcement → Franchise dispute / variance resolution"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-23', 23, N'Programme Governance', N'Migration & Cutover', N'IT / ERP', N'{"id":"PA-23","grp":"Programme Governance","name":"Migration & Cutover","lead":"IT / ERP","depts":"IT / ERP (9); Operational Excellence (2)","steps":11,"new":11,"modify":0,"keepRetire":"0 / 0","fit":"0 / 0 / 0 / 11","open":1,"desc":"Migrate legacy master data and open transactions from the existing Material Control system, standalone warehouse/maintenance apps, and Office-based costing/purchasing files into Dynamics 365, and validate readiness through structured testing ahead of a single overnight cutover (Priority 2) - not a phased, module-by-module changeover.\nFlow: Legacy data inventory and cleansing → Migration mapping (item master, BOM/recipe, open PO, batch/expiry, opening stock) → Trial migration and reconciliation → Mock cutover rehearsal(s) → Go/no-go decision → Cutover planning and freeze windows → UAT scenario design → UAT execution and sign-off → Single overnight go-live → Parallel decommission of legacy MC system and self-developed web apps → Hypercare"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-24', 24, N'Programme Governance', N'POS Transition', N'IT / ERP', N'{"id":"PA-24","grp":"Programme Governance","name":"POS Transition","lead":"IT / ERP","depts":"IT / ERP (7); Store Operations (1)","steps":8,"new":7,"modify":1,"keepRetire":"0 / 0","fit":"0 / 1 / 0 / 7","open":0,"desc":"Foodics to Dynamics 365 Commerce - Replace the third-party Foodics POS platform with Dynamics 365 Commerce (or confirmed equivalent native POS) at the outlets, including all third-party integrations currently running through Foodics (payment gateways, delivery aggregators, loyalty, kitchen display). Explicitly Priority 5 - begins only after the Priority 1-4 work (to-be process design, big-bang MC cutover, Dynamics adoption, and legacy web-app retirement) is stable.\nFlow: Confirm Dynamics 365 Commerce fit for QSR outlet operations → Inventory existing Foodics functionality and third-party integrations → Design POS hardware/peripheral compatibility → Pilot at a small number of outlets → Parallel-run Foodics and Dynamics POS at pilot outlets → Staged outlet-by-outlet rollout → Decommission Foodics"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-25', 25, N'Foundation & Master Data', N'Vendor & Purchase-to-Pay', N'Purchase', N'{"id":"PA-25","grp":"Foundation & Master Data","name":"Vendor & Purchase-to-Pay","lead":"Purchase","depts":"Purchase (15); Finance (4); R&D (1); Cost Control (1)","steps":21,"new":6,"modify":14,"keepRetire":"1 / 0","fit":"10 / 10 / 1 / 0","open":0,"desc":"Govern supplier onboarding, tendering and trade-agreement/price-list setup upstream of PA-04 receiving, and complete the purchase cycle downstream through invoice matching, payment and vendor-statement reconciliation - closing the gap between ''goods received'' (PA-04) and ''supplier paid''.\nFlow: Vendor onboarding and vetting → Tender / RFQ management → Trade agreement and price-list setup in Dynamics → Contract renewal and compliance tracking → Invoice receipt and 3-way match to PO/GRN → Payment run processing → Vendor statement reconciliation → Vendor scorecard feed to Procurement"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-26', 26, N'Costing & Close', N'Standard Cost & Budget', N'Cost Control', N'{"id":"PA-26","grp":"Costing & Close","name":"Standard Cost & Budget","lead":"Cost Control","depts":"Cost Control (11); Finance (8)","steps":19,"new":17,"modify":2,"keepRetire":"0 / 0","fit":"12 / 7 / 0 / 0","open":0,"desc":"Define the periodic (typically annual) policy for setting and revising standard costs, and the process for building, submitting, consolidating and approving outlet and CPU budgets - distinct from PA-19''s month-end actual-cost closure and from the outlet budget-vs-actual KPI (KPI-08), which measures against the budget this process produces.\nFlow: Cost-roll trigger and methodology (e.g. annual, or on material price movement) → Standard cost recalculation from recipe/BOM and current prices → Standard cost review and approval → Budget template and assumptions setup → Outlet and CPU budget submission → Budget consolidation → Budget approval and lock → In-year revision / reforecast process"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-27', 27, N'Programme Governance', N'Change & Training', N'IT / ERP', N'{"id":"PA-27","grp":"Programme Governance","name":"Change & Training","lead":"IT / ERP","depts":"IT / ERP (13)","steps":13,"new":13,"modify":0,"keepRetire":"0 / 0","fit":"2 / 2 / 0 / 9","open":0,"desc":"Decompose what was previously a single deferred line item into a full process: assess training needs, build role-based training material, roll out mobile/barcode-scanning training for a user base that has not previously used these workflows, run a change-champion network, and monitor adoption through and beyond the Priority 2 big-bang cutover.\nFlow: Training needs assessment by role → Training material and scenario development → Train-the-trainer programme → Role-based training rollout (warehouse, CPU, outlet, Finance, Cost Control) → Change-champion network setup → User adoption monitoring post-go-live → Hypercare helpdesk and issue triage → Lessons-learned and refresher-training cycle"}');
INSERT INTO dbo.sc_sop_processes (id, seq, grp, name, lead_dept, data) VALUES (N'PA-28', 28, N'Non-inventoriable Procurement', N'Non-inventoriable Procurement (assets, projects, services)', N'Purchase', N'{"id":"PA-28","grp":"Non-inventoriable Procurement","name":"Non-inventoriable Procurement (assets, projects, services)","lead":"Purchase","depts":"Purchase (12); IT / ERP (5); Requesting department (5); Warehouse (5); CPU / CBU (4); Finance (3); Cost Control (2); Operational Excellence (2)","steps":43,"new":8,"modify":28,"keepRetire":"2 / 5","fit":"1 / 0 / 37 / 5","open":0,"desc":"Procure non-inventoriable items (assets, services, consumables, stationery) through request, approval by value band, purchase order, receipt or service acceptance, invoice and payment; asset items are capitalised on acceptance."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S010', N'PA-01', 1, N'Cost Control', N'Modify', N'Covered', N'{"id":"PA-01-S010","pa":"PA-01","phase":"1. Item master policy","scor":"Enable – Manage product data","stype":"Setup","asis":"Costing keeps the production item master to items that are part of a recipe (officials flagged this for verification).","asisActor":"Costing","asisSys":"MC — item master","gapFlag":"Check","gapDesc":"Stated as a rule; not confirmed whether the system enforces it.","change":"Modify","tobe":"Every article is assigned a category and description; production-class articles require a recipe link before activation.","dept":"Cost Control","role":"Costing","sys":"D365 — Product categories","input":"Trigger: start of process","output":"Classified article","pillars":"Master Data | Control","refs":"POL-D02","fit":"Covered","erpReq":"Recipe link mandatory for production-class articles.","ricefw":"Configuration","moscow":"Must","prev":"— (start)","next":"PA-01-S020","evId":"EV-INV-1.0","evQuote":"Ensure the production item master holds only items that are part of a recipe.","taskId":"PA-01-T03","taskDesc":"Item classification - Assign item category and description","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S020', N'PA-01', 2, N'Cost Control', N'Modify', N'Partial', N'{"id":"PA-01-S020","pa":"PA-01","phase":"1. Item master policy","scor":"Enable – Manage product data","stype":"Control check","asis":"Non-recipe items are allowed in the production item master only where they are on the approved list, e.g. housekeeping material.","asisActor":"Costing","asisSys":"MC; approved list held outside the system","gapFlag":"Check","gapDesc":"Approved list not held in the system.","change":"Modify","tobe":"Approved non-recipe categories held as a controlled list; an article outside recipe linkage and the approved categories cannot be activated.","dept":"Cost Control","role":"Costing","sys":"D365 — Category hierarchy","input":"Classified article","output":"Category check","pillars":"Master Data | Control","refs":"POL-D02","fit":"Partial","erpReq":"Controlled non-recipe category list.","ricefw":"Configuration","moscow":"Should","prev":"PA-01-S010","next":"PA-01-S030","evId":"EV-INV-1.1","evQuote":"holds non-recipe items only where they are on the approved list"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S030', N'PA-01', 3, N'Cost Control', N'Retire', N'Non-system', N'{"id":"PA-01-S030","pa":"PA-01","phase":"1. Item master policy","scor":"Enable – Manage product data","stype":"Activity","asis":"Raw-material master sheet prepared as an active list in Excel and uploaded into MC.","asisActor":"Costing","asisSys":"Excel upload","gapFlag":"Gap","gapDesc":"Master maintained offline. (Root cause: outside the system)","change":"Retire","tobe":"Retired — articles created only through the request route (S050–S140).","dept":"Cost Control","role":"Costing","pillars":"Master Data","fit":"Non-system","moscow":"Must","prev":"PA-01-S020","next":"PA-01-S040","evId":"EV-CC-0.2","evQuote":"Active list preparation - in excel - file upload into MC or Dynamics"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S040', N'PA-01', 4, N'Requesting department', N'Retire', N'Non-system', N'{"id":"PA-01-S040","pa":"PA-01","phase":"2. Request","scor":"Enable – Manage product data","stype":"Activity","asis":"Where a required item is not in the item master, the originating department emails Purchase, Warehouse and Costing to request its creation; many existing items overlap.","asisActor":"Requesting department","asisSys":"Email","gapFlag":"Control Gap","gapDesc":"No control over requests for new items; overlapping articles. (Root cause: outside the system)","change":"Retire","tobe":"Retired — replaced by S050.","dept":"Requesting department","role":"Requesting department","pillars":"Control","fit":"Non-system","moscow":"Must","prev":"PA-01-S030","next":"PA-01-S050","evId":"EV-INV-1.2","evQuote":"emails Purchase, Warehouse and Costing to request its creation"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S050', N'PA-01', 5, N'Requesting department', N'New', N'Partial', N'{"id":"PA-01-S050","pa":"PA-01","phase":"2. Request","scor":"Enable – Manage product data","stype":"Activity","asis":"— (see S040)","change":"New","tobe":"Requester raises a new-article request in the ERP (auto-numbered) with description, intended use, recipe or category link, pack and UOM; requester searches existing articles first.","dept":"Requesting department","role":"Requesting department","sys":"D365 — Item request workflow","input":"New-article request (requester / R&D)","output":"New-article request","pillars":"Master Data | Process","fit":"Partial","erpReq":"Item request form with mandatory fields and search.","ricefw":"Customization","moscow":"Must","prev":"PA-01-S040","next":"PA-01-S060","evId":"From task list","taskId":"PA-01-T01","taskDesc":"Item request - Submit item-creation request","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S060', N'PA-01', 6, N'R&D', N'Modify', N'Partial', N'{"id":"PA-01-S060","pa":"PA-01","phase":"2. Request","scor":"Enable – Manage product data","stype":"Exception","asis":"Alternate or new items: samples go to the CPU Administrator and R&D; R&D approves with the CPU chefs and tells Purchase by WhatsApp / email; Purchase asks Costing to create the article and price.","asisActor":"CPU Administrator; R&D; Purchase; Costing","asisSys":"WhatsApp group; email","gapFlag":"Gap","gapDesc":"Approval chain outside the system. (Root cause: outside the system)","change":"Modify","tobe":"R&D''s sample approval (with CPU chefs'' consent) recorded on the new-article request; Purchase and Costing act on the same request.","dept":"R&D","role":"R&D (approver); CPU Chef","sys":"D365 — Item request workflow","input":"New-article request","output":"R&D approval","pillars":"Control | Process","refs":"POL-D11 | POL-D17","fit":"Partial","erpReq":"R&D approval step on item request.","ricefw":"Workflow","moscow":"Must","prev":"PA-01-S050","next":"PA-01-S070","evId":"EV-CPU-OR-13.6; EV-CPU-OR-13.4; EV-CPU-OR-13.5","evQuote":"The purchase department will communicate with the costing department to enter the new article and the price in the system."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S070', N'PA-01', 7, N'Purchase', N'Modify', N'Partial', N'{"id":"PA-01-S070","pa":"PA-01","phase":"3. Review","scor":"Enable – Manage product data","stype":"Control check","asis":"Purchase raises the request to Costing, validating that it is not a duplicate; no system support.","asisActor":"Purchase","asisSys":"Email","gapFlag":"Gap","gapDesc":"Duplicate check by eye. (Root cause: outside the system)","change":"Modify","tobe":"System runs a duplicate check on material, brand, pack and UOM; Purchase adds sourcing details.","dept":"Purchase","role":"Buyer","sys":"D365 — Duplicate check","input":"R&D approval","output":"Duplicate-checked request","pillars":"Master Data","fit":"Partial","erpReq":"Duplicate check rule.","ricefw":"Customization","moscow":"Must","prev":"PA-01-S060","next":"PA-01-S080","evId":"EV-INV-1.3","evQuote":"validating that it is not a duplicate","taskId":"PA-01-T02","taskDesc":"Duplicate-item check - Confirm item does not already exist","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S080', N'PA-01', 8, N'Cost Control', N'Modify', N'Partial', N'{"id":"PA-01-S080","pa":"PA-01","phase":"3. Review","scor":"Enable – Manage product data","stype":"Approval","asis":"Costing analyses the request and cross-checks with the recipe and the relevant department; manual documents with oral confirmation only.","asisActor":"Costing","asisSys":"Manual documents; oral confirmation","gapFlag":"Control Gap","gapDesc":"No system confirmation by anyone other than Costing; R&D has no role in the system. (Root cause: outside the system)","change":"Modify","tobe":"Costing reviews and approves the article in the ERP after R&D / department confirmation. [SLA: within 2 working days of complete request — proposed]","dept":"Cost Control","role":"Costing (approver)","sys":"D365 — Item approval workflow","input":"Duplicate-checked request","output":"Approved article","pillars":"Control | Master Data","refs":"CTL-01-1 | POL-D02 | K-01-1","fit":"Partial","erpReq":"Confirm: Approval workflow on new / changed released products (Costing approver), with SLA timer and change history.","ricefw":"Workflow","moscow":"Must","prev":"PA-01-S070","next":"PA-01-S090","evId":"EV-INV-1.4; EV-INV-1.5","evQuote":"Manual documents with oral confirmation only","taskId":"PA-01-T08","taskDesc":"Approval and activation - Review and approve the item","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S090', N'PA-01', 9, N'Cost Control', N'Modify', N'Partial', N'{"id":"PA-01-S090","pa":"PA-01","phase":"4. Configure","scor":"Enable – Manage product data","stype":"Setup","asis":"Costing creates the item and configures the item master; MC holds one Swish article with no variant or substitute structure.","asisActor":"Costing","asisSys":"MC — item master","gapFlag":"Gap","gapDesc":"Brands and packs cannot be told apart. (Root cause: no variant setup)","change":"Modify","tobe":"Swish inventory article created as primary, with brand / pack variants; variant effects (yield, UOM) set per variant by Costing; pack size mapped to each variant.","dept":"Cost Control","role":"Costing","sys":"D365 — Product masters and variants","input":"Approved article","output":"Article with variants","pillars":"Master Data","refs":"POL-D02","fit":"Partial","erpReq":"Variant structure per Swish article.","ricefw":"Configuration","moscow":"Must","prev":"PA-01-S080","next":"PA-01-S095","evId":"EV-INV-1.5; EV-CPU-MGT-3.5; EV-CC-1.1; EV-QL-P02","evQuote":"Create the new item and, where required, configure the item master."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S095', N'PA-01', 10, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-01-S095","pa":"PA-01","phase":"4. Configure","scor":"Enable – Manage product data","stype":"Setup","asis":"The standard packaging matrix is defined and maintained by production, brand-specific, and issued to sections on the segregator sheet.","asisActor":"CPU Production","asisSys":"Segregator sheet","gapFlag":"Gap","gapDesc":"Packaging matrix held outside the system.","change":"Modify","tobe":"Standard packaging matrix (pack size and packaging material per production article and brand) held in ERP master data; drives order multiples and the packing lines of the formula.","dept":"CPU / CBU","role":"CPU Manager; Costing (custodian)","sys":"D365 — Released product / formula packing lines","input":"Article with variants (PA-01-S090)","output":"Packaging matrix","pillars":"Master Data","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-01-S090","next":"PA-01-S096","evId":"EV-CPU-PRD-8.1","evQuote":"the individual section holders produce as per the STANDARD PACKAGING MATRIX defined and maintained by the production team","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S096', N'PA-01', 11, N'Marketing', N'New', N'Partial', N'{"id":"PA-01-S096","pa":"PA-01","phase":"4. Configure","scor":"Enable – Manage product data","stype":"Approval","asis":"— (new step; no as-is activity reported)","change":"New","tobe":"New or changed printed packaging: specification and artwork approved by Marketing (brand) and QC (food-contact and labelling) with a version; Purchase may order only the approved version.","dept":"Marketing","role":"Marketing Manager; Approver: QC Manager","sys":"D365 — Item attachments / approval workflow","input":"Packaging matrix (PA-01-S095)","output":"Approved packaging specification","pillars":"Compliance & Food Safety | Master Data","fit":"Partial","erpReq":"Confirm: versioned specification / artwork attachment on the item with approval before purchase.","ricefw":"Configuration","moscow":"Should","prev":"PA-01-S095","next":"PA-01-S100","evId":"(Analyst proposal — confirm at docket review)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S100', N'PA-01', 12, N'Cost Control', N'Modify', N'Covered', N'{"id":"PA-01-S100","pa":"PA-01","phase":"4. Configure","scor":"Enable – Manage product data","stype":"Setup","asis":"Costing decides the base unit (minimum sub-dividable unit) and the receiving unit (supplier package) per item.","asisActor":"Costing","asisSys":"MC","change":"Modify","tobe":"Purchase, inventory and recipe units defined per article / variant. Issue unit can be smaller than the purchase unit (e.g. gloves, hair nets, packaging issued by piece or pack, not full carton) so stores order only what they consume.","dept":"Cost Control","role":"Costing","sys":"D365 — Unit of measure","input":"Article with variants","output":"Units defined","pillars":"Master Data","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-01-S096","next":"PA-01-S110","evId":"EV-CC-1.2; EV-CC-0.4; EV-CC-0.5; EV-FD-025","evQuote":"Costing decides base unit (minimum sub-dividable unit) and receiving unit (supplier package) per item","taskId":"PA-01-T04","taskDesc":"Unit-of-measure setup - Define purchase, inventory and recipe units","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S110', N'PA-01', 13, N'Cost Control', N'New', N'Covered', N'{"id":"PA-01-S110","pa":"PA-01","phase":"4. Configure","scor":"Enable – Manage product data","stype":"Setup","asis":"— (conversions applied by judgement)","change":"New","tobe":"Carton, piece, kilogram and gram conversions fixed per article and applied automatically.","dept":"Cost Control","role":"Costing","sys":"D365 — UOM conversions","input":"Units defined","output":"Conversions","pillars":"Master Data","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-01-S100","next":"PA-01-S120","evId":"From task list","taskId":"PA-01-T05","taskDesc":"Unit-of-measure setup - Define carton, piece, kilogram and gram conversions","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S120', N'PA-01', 14, N'Cost Control', N'New', N'Covered', N'{"id":"PA-01-S120","pa":"PA-01","phase":"4. Configure","scor":"Enable – Manage product data","stype":"Setup","asis":"— (batch / expiry not set in MC)","change":"New","tobe":"Batch and expiry tracking set per article (all items; fresh / daily items by the agreed method).","dept":"Cost Control","role":"Costing; QC","sys":"D365 — Tracking dimension","input":"Conversions","output":"Tracking set","pillars":"Tracking & Traceability","refs":"POL-D08","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-01-S110","next":"PA-01-S130","evId":"From task list","taskId":"PA-01-T06","taskDesc":"Inventory and tracking setup - Define batch and expiry requirements","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S130', N'PA-01', 15, N'Finance', N'New', N'Covered', N'{"id":"PA-01-S130","pa":"PA-01","phase":"4. Configure","scor":"Enable – Manage product data","stype":"Setup","asis":"— (not described)","change":"New","tobe":"Inventory posting and cost groups assigned.","dept":"Finance","role":"Finance; Costing","sys":"D365 — Item model / posting","input":"Tracking set","output":"Financial setup","pillars":"Finance","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-01-S120","next":"PA-01-S140","evId":"From task list","taskId":"PA-01-T07","taskDesc":"Financial setup - Assign inventory posting and cost groups","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S140', N'PA-01', 16, N'Cost Control', N'New', N'Covered', N'{"id":"PA-01-S140","pa":"PA-01","phase":"5. Release","scor":"Enable – Manage product data","stype":"Hand-off","asis":"— (no notification back)","change":"New","tobe":"Article released to the applicable legal entities; requester, Purchase and Warehouse notified with the article reference.","dept":"Cost Control","role":"Costing","sys":"D365 — Release products","input":"Financial setup","output":"Released article","pillars":"Master Data | Process","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-01-S130","next":"PA-01-S150","evId":"From task list","taskId":"PA-01-T09","taskDesc":"Approval and activation - Release item to applicable legal entities","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S150', N'PA-01', 17, N'Cost Control', N'Modify', N'Partial', N'{"id":"PA-01-S150","pa":"PA-01","phase":"6. Change & lifecycle","scor":"Enable – Manage product data","stype":"Control check","asis":"Discontinued or replaced production articles are still ordered by stores; Costing marks them discontinued at brand level, but store user IDs can still order.","asisActor":"Costing; stores","asisSys":"MC","gapFlag":"Control Gap","gapDesc":"Inactive articles still transactable. (Root cause: open user administration)","change":"Modify","tobe":"Item changes submitted and approved through change control with history; inactive / discontinued articles blocked from every transaction. Article movement status maintained in the ERP: Active, Slow-moving (no movement 2 months), Super slow-moving (3 months), Non-moving (4 months), Seasonal, Direct supply, To be deactivated — set automatically from movement history and reviewed monthly by Warehouse with Costing.","dept":"Cost Control","role":"Costing (approver)","sys":"D365 — Engineering change / product lifecycle state","input":"Released article (PA-01-S140)","output":"Item change record (RPT-01)","pillars":"Control | Master Data","refs":"CTL-01-1 | POL-D20","fit":"Partial","erpReq":"Lifecycle state blocks transactions; change history.","ricefw":"Configuration","moscow":"Must","prev":"PA-01-S140","next":"PA-01-S160","evId":"EV-CPU-MGT-6.3; EV-OPS-0.4; EV-WH-0.7; EV-SPS-07","evQuote":"Many production articles have been discontinued or replaced by a new production article, but stores continue to order the discontinued item","taskId":"PA-01-T10","taskDesc":"Item-change management - Submit and approve item master changes through change control, keeping a change history","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-01-S160', N'PA-01', 18, N'IT / ERP', N'Modify', N'Partial', N'{"id":"PA-01-S160","pa":"PA-01","phase":"6. Change & lifecycle","scor":"Enable – Manage product data","stype":"Control check","asis":"Store users can order any quantity off the standard pack through the repositioning / assortment privilege; visibility of items per store is a user-level setting.","asisActor":"Stores; system administration","asisSys":"MC user privileges","gapFlag":"Control Gap","gapDesc":"Standard pack bypassed through user privilege. (Root cause: open user administration)","change":"Modify","tobe":"Assortment per store controls which articles each store can order; standard pack enforced; repositioning privilege removed.","dept":"IT / ERP","role":"ERP security administrator; Costing","sys":"D365 — Assortments; security roles","input":"Released article","output":"Store assortment","pillars":"Access & Segregation of Duties | Master Data","refs":"CTL-01-2 | POL-D20","fit":"Partial","erpReq":"Store assortment; pack-size enforcement.","ricefw":"Configuration","moscow":"Must","prev":"PA-01-S150","next":"PA-02-S010","evId":"EV-WH-0.6; EV-OPS-0.3; EV-CPU-MGT-6.1","evQuote":"user level configuration of what items to be visible to that specific store"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-02-S010', N'PA-02', 19, N'Finance', N'New', N'Partial', N'{"id":"PA-02-S010","pa":"PA-02","phase":"1. Entity & site","scor":"Enable – Manage network","stype":"Setup","asis":"— (legal-entity mapping of sites not described)","change":"New","tobe":"Each site mapped to its legal entity: the EGC service company owns CPU, CBU, the central warehouse and the staff cafeteria; the store company (or companies) owns the outlets — matching the gate-value transfers of POL-D21.","dept":"Finance","role":"Finance Manager; ERP Functional Lead","sys":"D365 — Legal entities","input":"Store assortment (PA-01-S160)","output":"Entity map","pillars":"Master Data | Finance","refs":"CTL-02-1 | POL-D27","fit":"Partial","erpReq":"Confirm: Legal-entity design: EGC (CPU, CBU, warehouse, cafeteria) and store company (outlets); inter-company transfer orders and pricing between entities.","ricefw":"Configuration","moscow":"Must","prev":"PA-01-S160","next":"PA-02-S020","evId":"EV-QL-ES01","taskId":"PA-02-T01","taskDesc":"Legal-entity mapping - Map each site, warehouse and outlet to its legal entity","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-02-S020', N'PA-02', 20, N'IT / ERP', N'New', N'Partial', N'{"id":"PA-02-S020","pa":"PA-02","phase":"1. Entity & site","scor":"Enable – Manage network","stype":"Setup","asis":"— (sites not structured in MC)","change":"New","tobe":"Sites defined for the central warehouse, CPU, CBU / bakery and outlets; R&D kitchen set up as a section of CPU; Training kitchen under Operations.","dept":"IT / ERP","role":"ERP Functional Lead","sys":"D365 — Sites","input":"Entity map","output":"Sites","pillars":"Master Data","fit":"Partial","erpReq":"Confirm: Site / warehouse hierarchy with CPU sections (incl. R&D kitchen) as sub-warehouses or locations; confirm costing by section.","ricefw":"Configuration","moscow":"Must","prev":"PA-02-S010","next":"PA-02-S030","evId":"EV-RND-5.1; EV-TRN-1.2","taskId":"PA-02-T02","taskDesc":"Site setup - Define sites for the central warehouse, CPU, bakery and outlets","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-02-S030', N'PA-02', 21, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-02-S030","pa":"PA-02","phase":"2. Warehouses","scor":"Enable – Manage network","stype":"Setup","asis":"Central warehouse runs on the Swish WMS; expiry and batch details recorded there, not in MC.","asisActor":"Warehouse","asisSys":"Swish WMS","change":"Modify","tobe":"Central warehouse defined as an inventory warehouse in the ERP.","dept":"Warehouse","role":"ERP Functional Lead; Warehouse Head","sys":"D365 — Warehouses","input":"Sites","output":"Central warehouse","pillars":"Master Data","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-02-S020","next":"PA-02-S040","evId":"EV-WH-4.1","evQuote":"the expiry date and other batch details are recorded in the WMS (Swish domain)","taskId":"PA-02-T03","taskDesc":"Warehouse setup - Define the central warehouse","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-02-S040', N'PA-02', 22, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-02-S040","pa":"PA-02","phase":"2. Warehouses","scor":"Enable – Manage network","stype":"Setup","asis":"Inside CPU, the dry store is open to all sections and there is no record of item movement once stock enters it.","asisActor":"CPU sections","gapFlag":"Control Gap","gapDesc":"No stock accountability inside CPU. (Root cause: outside the system)","change":"Modify","tobe":"CPU and bakery defined as inventory warehouses; each CPU section, the R&D kitchen and the staff cafeteria set up as a sub-warehouse with its own stock, consumption and cost centre (needed for section-level overhead allocation, POL-D21).","dept":"CPU / CBU","role":"ERP Functional Lead; CPU Manager","sys":"D365 — Warehouses","input":"Sites","output":"CPU / CBU warehouses","pillars":"Master Data | Tracking & Traceability","refs":"POL-D25 | POL-D27","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-02-S030","next":"PA-02-S050","evId":"EV-CPU-OR-11.2; EV-CPU-OR-11.1; EV-QL-ES01","evQuote":"there is no track of items movement once it came inside the dry store of CPU controlled environment","taskId":"PA-02-T04","taskDesc":"Warehouse setup - Define CPU and bakery warehouses","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-02-S050', N'PA-02', 23, N'Store Operations', N'Modify', N'Covered', N'{"id":"PA-02-S050","pa":"PA-02","phase":"2. Warehouses","scor":"Enable – Manage network","stype":"Setup","asis":"Store stock is not held day to day in MC; it is entered only at month end.","asisActor":"Stores","asisSys":"MC (monthly)","gapFlag":"Gap","gapDesc":"No live stock per outlet.","change":"Modify","tobe":"Every outlet defined as an inventory warehouse.","dept":"Store Operations","role":"ERP Functional Lead","sys":"D365 — Warehouses","input":"Sites","output":"Outlet warehouses","pillars":"Master Data","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-02-S040","next":"PA-02-S060","evId":"EV-OPS-5.1","evQuote":"This is NOT entered as an everyday closing stock in MC","taskId":"PA-02-T05","taskDesc":"Warehouse setup - Define every outlet as an inventory warehouse","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-02-S060', N'PA-02', 24, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-02-S060","pa":"PA-02","phase":"3. Zones & locations","scor":"Enable – Manage network","stype":"Setup","asis":"Storage at the proper temperature and shelving, validated by QC.","asisActor":"QC; Warehouse","asisSys":"Physical","change":"Modify","tobe":"Frozen, chilled, ambient and packaging zones created.","dept":"Warehouse","role":"Warehouse Head","sys":"D365 — Zones","input":"Warehouses","output":"Zones","pillars":"Compliance & Food Safety | Master Data","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-02-S050","next":"PA-02-S070","evId":"EV-QC-6.3","evQuote":"storage at the proper temperature, proper shelving","taskId":"PA-02-T06","taskDesc":"Warehouse-zone design - Create frozen, chilled, ambient and packaging zones","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-02-S070', N'PA-02', 25, N'Warehouse', N'New', N'Covered', N'{"id":"PA-02-S070","pa":"PA-02","phase":"3. Zones & locations","scor":"Enable – Manage network","stype":"Setup","asis":"— (locations held in the WMS)","change":"New","tobe":"Receiving, storage, picking, staging and dispatch locations created.","dept":"Warehouse","role":"Warehouse Head","sys":"D365 — Locations","input":"Zones","output":"Locations","pillars":"Master Data","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-02-S060","next":"PA-02-S080","evId":"From task list","taskId":"PA-02-T07","taskDesc":"Location creation - Create receiving, storage, picking, staging and dispatch locations","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-02-S080', N'PA-02', 26, N'Warehouse', N'New', N'Covered', N'{"id":"PA-02-S080","pa":"PA-02","phase":"3. Zones & locations","scor":"Enable – Manage network","stype":"Setup","asis":"— (not described)","change":"New","tobe":"Location profiles and capacity rules assigned.","dept":"Warehouse","role":"Warehouse Head","sys":"D365 — Location profiles","input":"Locations","output":"Location profiles","pillars":"Master Data","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-02-S070","next":"PA-02-S090","evId":"From task list","taskId":"PA-02-T08","taskDesc":"Location creation - Assign location profiles and capacity rules","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-02-S090', N'PA-02', 27, N'Warehouse', N'New', N'Covered', N'{"id":"PA-02-S090","pa":"PA-02","phase":"3. Zones & locations","scor":"Enable – Manage network","stype":"Setup","asis":"— (no in-transit stock)","change":"New","tobe":"In-transit warehouses defined for transfers.","dept":"Warehouse","role":"ERP Functional Lead","sys":"D365 — Transit warehouses","input":"Warehouses","output":"Transit warehouses","pillars":"Tracking & Traceability","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-02-S080","next":"PA-02-S100","evId":"From task list","taskId":"PA-02-T09","taskDesc":"Transit-location setup - Define in-transit warehouses","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-02-S100', N'PA-02', 28, N'Quality Control', N'Modify', N'Covered', N'{"id":"PA-02-S100","pa":"PA-02","phase":"4. Quality locations","scor":"Enable – Manage network","stype":"Setup","asis":"Short-dated goods proposed to be parked and approved by Warehouse Supervisor, Warehouse Manager, Quality team or CPU Managers.","asisActor":"Warehouse; QC","asisSys":"Physical","change":"Modify","tobe":"Quarantine and rejected-stock locations defined; release from quarantine follows PA-04-S200.","dept":"Quality Control","role":"QC Officer; Warehouse Head","sys":"D365 — Quarantine locations","input":"Locations","output":"Quarantine locations","pillars":"Compliance & Food Safety | Control","refs":"CTL-02-1 | POL-D05","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-02-S090","next":"PA-02-S110","evId":"EV-WH-V03","evQuote":"short-dated goods parked and approved by any one of Warehouse Supervisor, Warehouse Manager, Quality team or CPU Managers","taskId":"PA-02-T10","taskDesc":"Quality and quarantine setup - Define quarantine and rejected-stock locations","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-02-S110', N'PA-02', 29, N'Warehouse', N'New', N'Partial', N'{"id":"PA-02-S110","pa":"PA-02","phase":"4. Quality locations","scor":"Enable – Manage network","stype":"Setup","asis":"— (damaged / expired stock locations not described)","change":"New","tobe":"Damaged and expired stock locations and inventory statuses defined (stock in these statuses cannot be issued).","dept":"Warehouse","role":"Warehouse Head; QC Officer","sys":"D365 — Inventory statuses","input":"Locations","output":"Loss locations / statuses","pillars":"Compliance & Food Safety | Control","fit":"Partial","erpReq":"Confirm: Inventory statuses (damaged, expired, quarantine) that block issue, sale and transfer until changed by an authorised role.","ricefw":"Configuration","moscow":"Must","prev":"PA-02-S100","next":"— (end)","evId":"From task list","taskId":"PA-02-T11","taskDesc":"Damaged and expired stock setup - Define damaged and expired stock locations and inventory statuses","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S010', N'PA-03', 30, N'Data & Analytics', N'Modify', N'Partial', N'{"id":"PA-03-S010","pa":"PA-03","phase":"1. Demand","scor":"Plan – Source","stype":"Activity","asis":"Interim demand planning (Power BI and other tools) generates the items requested and required by each store; not mapped to CPU sections; the forecast team gives raw-material forecasts.","asisActor":"Data & Analytics (forecast team)","asisSys":"Power BI (interim)","gapFlag":"Gap","gapDesc":"Store-wise only; partly implemented; not linked to sales. (Root cause: outside the system)","change":"Modify","tobe":"Sales demand imported from Foodics POS by outlet and item into the planning engine.","dept":"Data & Analytics","role":"Data & Analytics","sys":"D365 + Foodics integration","input":"Trigger: start of process","output":"Sales demand","pillars":"Data & Reporting","refs":"POL-D01 | POL-D12","fit":"Partial","erpReq":"Foodics sales import for planning.","ricefw":"Interface","moscow":"Must","prev":"— (start)","next":"PA-03-S020","evId":"EV-CPU-MGT-4.2; EV-CPU-MGT-4.1; EV-CC-0.9","evQuote":"generates the items requested and required by each store","taskId":"PA-03-T01","taskDesc":"Sales-demand collection - Import sales demand from POS or Foodics","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S020', N'PA-03', 31, N'Data & Analytics', N'Modify', N'Covered', N'{"id":"PA-03-S020","pa":"PA-03","phase":"1. Demand","scor":"Plan – Source","stype":"Activity","asis":"Bakery forecasts produced-ahead items from previous order history, the specialty of the week, marketing events and calls to brand managers.","asisActor":"CBU management","asisSys":"Manual / phone","gapFlag":"Gap","gapDesc":"Forecast built by hand per unit. (Root cause: outside the system)","change":"Modify","tobe":"Forecast reviewed for promotions, seasonality, events and outlet openings by the forecasting pool (Data & Analytics with Operations GM, CPU chief, Warehouse Head, Costing Head).","dept":"Data & Analytics","role":"Data & Analytics; forecasting pool","sys":"D365 — Demand forecasting","input":"Sales demand","output":"Approved forecast","pillars":"Process | Data & Reporting","refs":"POL-D12","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-03-S010","next":"PA-03-S025","evId":"EV-CBU-3.3; EV-CBU-3.8","evQuote":"PREVIOUS HISTORY of orders","taskId":"PA-03-T02","taskDesc":"Forecast preparation - Review promotions, seasonality and outlet openings","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S025', N'PA-03', 32, N'Marketing', N'New', N'Partial', N'{"id":"PA-03-S025","pa":"PA-03","phase":"1. Demand","scor":"Plan – Source","stype":"Activity","asis":"Promotions and events reach production only through store orders; volumes from the marketing event system are received separately.","asisActor":"Marketing / Stores","asisSys":"Store orders; event management system","gapFlag":"Gap","gapDesc":"No advance demand signal for promotions. (Root cause: outside the system)","change":"New","tobe":"Marketing lodges promotions and events (dates, outlets, items, expected uplift) in the ERP / event calendar; they feed the demand forecast and the production plan. Campaign articles, recipes and wastage-module set-up completed before launch; campaign timing changes notified to stores and CPU to avoid campaign-stock wastage. [SLA: at least 7 days before start — proposed]","dept":"Marketing","role":"Marketing Manager","sys":"D365 — Demand forecast adjustments","input":"Promotion calendar","output":"Adjusted demand forecast","pillars":"Process | Data & Reporting","fit":"Partial","erpReq":"Confirm: promotion / event calendar as a forecast adjustment input by item and outlet.","ricefw":"Configuration","moscow":"Should","prev":"PA-03-S020","next":"PA-03-S030","evId":"EV-OPS-0.8; EV-CPU-MGT-0.2; EV-FD-038; EV-FD-115; EV-FD-175","evQuote":"Promotions and offers often reach production only through store orders.","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S030', N'PA-03', 33, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-03-S030","pa":"PA-03","phase":"2. Parameters","scor":"Plan – Source","stype":"Setup","asis":"Lead time or reorder level noted as a requirement; replenishment requests are not matched with a reorder level.","asisActor":"Warehouse","gapFlag":"Gap","gapDesc":"No min / max held. (Root cause: outside the system)","change":"Modify","tobe":"Minimum and maximum stock maintained per item and location. Initial min / max per item taken from the Swish SPS parameter master (target cover, delivery frequency) and reviewed before go-live; items marked ''OnDemand'' / ''NoNeed'' in SPS set up as order-on-demand (no automatic replenishment).","dept":"Warehouse","role":"Planner; Warehouse Head","sys":"D365 — Item coverage","input":"Approved forecast","output":"Min / max","pillars":"Process","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-03-S025","next":"PA-03-S040","evId":"EV-WH-0.9; EV-WH-6.1; EV-SPS-02","evQuote":"lead time or reorder level","taskId":"PA-03-T03","taskDesc":"Minimum and maximum review - Maintain minimum and maximum stock","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S040', N'PA-03', 34, N'Warehouse', N'New', N'Partial', N'{"id":"PA-03-S040","pa":"PA-03","phase":"2. Parameters","scor":"Plan – Source","stype":"Setup","asis":"Procurement plan holds a stock cover of at least one week to ten days, depending on the item.","asisActor":"CPU production","asisSys":"Manual","change":"New","tobe":"Safety stock calculated and maintained by item and location (short-expiry and imported items set separately). Safety stock for frozen items reflects storage capacity: where space keeps the buffer below cover (today under 3 days), the delivery frequency is raised instead of accepting stock-outs. Safety stock days migrated from the SPS parameter master (10 / 15 days for most items) as starting values; calculated on average usage plus variability, not on the maximum month.","dept":"Warehouse","role":"Planner","sys":"D365 — Safety stock","input":"Min / max","output":"Safety stock","pillars":"Process","fit":"Partial","erpReq":"Confirm: Safety-stock calculation per item / warehouse with separate parameters for short-expiry and imported items.","ricefw":"Configuration","moscow":"Should","prev":"PA-03-S030","next":"PA-03-S050","evId":"EV-CPU-PRD-2.7; EV-CPU-PRD-2.6; EV-FD-033; EV-SPS-02; EV-QL-SPS01","evQuote":"a stock cover of at least one week to ten days is needed","taskId":"PA-03-T04","taskDesc":"Safety-stock calculation - Calculate and maintain safety stock by item and location","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S050', N'PA-03', 35, N'Purchase', N'Modify', N'Covered', N'{"id":"PA-03-S050","pa":"PA-03","phase":"2. Parameters","scor":"Plan – Source","stype":"Setup","asis":"Daily purchase requests are based on each item''s lead time, from the latest inputs of the procurement team.","asisActor":"Warehouse; Procurement","asisSys":"MC; manual","change":"Modify","tobe":"Supplier and production lead times maintained per item / vendor. Lead times migrated from the SPS parameter master (3 / 7 / 15 / 30 / 90 days) and used in the planning dates (SPS uses fixed 15 / 7-day offsets).","dept":"Purchase","role":"Buyer","sys":"D365 — Lead times","input":"Safety stock","output":"Lead times","pillars":"Master Data","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-03-S040","next":"PA-03-S055","evId":"EV-CC-0.11; EV-SPS-02; EV-QL-SPS01","evQuote":"Daily purchase request based on lead time of the specific item based on the latest inputs from procurement team","taskId":"PA-03-T05","taskDesc":"Net-requirement calculation - Maintain supplier and production lead times","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S055', N'PA-03', 36, N'Warehouse', N'Retire', N'Non-system', N'{"id":"PA-03-S055","pa":"PA-03","phase":"2. Parameters","scor":"Plan – Source","stype":"Activity","asis":"Warehouse planner runs the Swish SPS Excel workbook daily: MC extracts refreshed by Power Query; per article, actual SOH (system SOH + open delivery notes − unposted transfers out), days to last on the maximum month of the last 4 months, OOS date, order request date (OOS − 15 days), receiving date (OOS − 7 days), MTD run-rate, open PO pipeline and suppliers; parameters (lead time, target cover, delivery frequency, safety stock) kept manually per item; monthly sheets re-pointed by hand. Used for warehouse-handled items only, not CPU direct items (user, to confirm with Warehouse).","asisActor":"Warehouse planner / buyer","asisSys":"Swish SPS V3 (Excel .xlsm, Power Query from MC)","gapFlag":"Gap","gapDesc":"Replenishment planned outside the system: manual parameter master, monthly re-pointing, open delivery notes excluded by a formula range, lead time not used in order dates, projection columns not built. (Root cause: no planning engine in MC)","change":"Retire","tobe":"Retired — replaced by planning parameters (S030–S050), the daily planning run (S060) and the planner workspace (S070).","dept":"Warehouse","role":"Warehouse planner","input":"MC extracts","output":"Replenishment list (Excel)","pillars":"Process | Data & Reporting","fit":"Non-system","prev":"PA-03-S050","next":"PA-03-S060","evId":"EV-SPS-03; EV-SPS-01; EV-SPS-05; EV-SPS-08; EV-QL-SPS01","evQuote":"Order request date = OOS date - 15 days; receiving date = OOS date - 7 days."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S060', N'PA-03', 37, N'Warehouse', N'New', N'Covered', N'{"id":"PA-03-S060","pa":"PA-03","phase":"3. Plan","scor":"Plan – Source","stype":"Activity","asis":"— (no planning run)","change":"New","tobe":"Planning Optimization run daily to calculate net requirements.","dept":"Warehouse","role":"Planner","sys":"D365 — Planning Optimization","input":"Forecast; stock; parameters","output":"Planned orders","pillars":"Process","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-03-S055","next":"PA-03-S070","evId":"From task list","taskId":"PA-03-T06","taskDesc":"Net-requirement calculation - Run Planning Optimization","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S070', N'PA-03', 38, N'Warehouse', N'New', N'Covered', N'{"id":"PA-03-S070","pa":"PA-03","phase":"3. Plan","scor":"Plan – Source","stype":"Activity","asis":"— (not described)","change":"New","tobe":"Planner reviews shortages and excess stock. Planner workspace shows, per item: days of cover, projected out-of-stock date, risk bucket (out of stock, < 3, < 7, < 15 days), month-to-date run-rate vs history, open PO pipeline and last suppliers — replacing the Swish SPS Replen Planning sheet.","dept":"Warehouse","role":"Planner","sys":"D365 — Planned orders","input":"Planned orders","output":"Reviewed plan","pillars":"Monitoring","refs":"K-03-2","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-03-S060","next":"PA-03-S080","evId":"From task list; EV-SPS-09","taskId":"PA-03-T07","taskDesc":"Planned-order review - Review shortages and excess stock","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S080', N'PA-03', 39, N'CPU / CBU', N'Retire', N'Non-system', N'{"id":"PA-03-S080","pa":"PA-03","phase":"3. Plan","scor":"Plan – Source","stype":"Exception","asis":"For some non-fresh items, Production contacts the supplier directly, usually orally — mostly for new items, sometimes for existing ones.","asisActor":"Production","asisSys":"Oral / telephone","gapFlag":"Control Gap","gapDesc":"Bypasses requisition, approval and vendor control. (Root cause: outside the system)","change":"Retire","tobe":"Retired — urgent needs go through S090.","dept":"CPU / CBU","role":"CPU Chef","pillars":"Control","refs":"POL-D05","fit":"Non-system","moscow":"Must","prev":"PA-03-S070","next":"PA-03-S090","evId":"EV-INV-2.4","evQuote":"Production contacts the supplier directly to place an order, usually orally"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S090', N'PA-03', 40, N'Warehouse', N'New', N'Covered', N'{"id":"PA-03-S090","pa":"PA-03","phase":"3. Plan","scor":"Plan – Source","stype":"Exception","asis":"— (see S080)","change":"New","tobe":"Urgent and overdue requirements monitored; genuine urgency raised in the ERP as an emergency requisition with fast-track approval.","dept":"Warehouse","role":"Planner; Purchase","sys":"D365 — Planned orders / urgent requisition","input":"Reviewed plan","output":"Urgent requisition","pillars":"Monitoring | Control","refs":"POL-D05","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-03-S080","next":"PA-03-S100","evId":"From task list","taskId":"PA-03-T08","taskDesc":"Planned-order review - Monitor urgent and overdue requirements","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S100', N'PA-03', 41, N'CPU / CBU', N'Retire', N'Non-system', N'{"id":"PA-03-S100","pa":"PA-03","phase":"4. Requisition","scor":"Plan – Source","stype":"Activity","asis":"CPU raises purchase requests in MC for all available items (dry, frozen, CPU-controlled, fresh); requested assortment and volume need not match the actual purchase.","asisActor":"CPU","asisSys":"MC — purchase request","gapFlag":"Gap","gapDesc":"Request and purchase diverge. (Root cause: no variant setup)","change":"Retire","tobe":"Retired — replaced by planned orders (S060–S150).","dept":"CPU / CBU","role":"CPU Administrator","pillars":"Process","fit":"Non-system","moscow":"Must","prev":"PA-03-S090","next":"PA-03-S110","evId":"EV-INV-2.0","evQuote":"Purchase request raised in MC for all available items"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S110', N'PA-03', 42, N'Store Operations', N'Retire', N'Non-system', N'{"id":"PA-03-S110","pa":"PA-03","phase":"4. Requisition","scor":"Plan – Source","stype":"Activity","asis":"Operations raises purchase requests in MC for dry, frozen and direct-delivery store items.","asisActor":"Operations","asisSys":"MC — purchase request","gapFlag":"Gap","gapDesc":"Same as S100. (Root cause: no variant setup)","change":"Retire","tobe":"Retired — store direct-delivery orders follow PA-08.","dept":"Store Operations","role":"Operations","pillars":"Process","fit":"Non-system","moscow":"Must","prev":"PA-03-S100","next":"PA-03-S120","evId":"EV-INV-2.1","evQuote":"all direct store operation direct-delivery items"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S120', N'PA-03', 43, N'Warehouse', N'Retire', N'Non-system', N'{"id":"PA-03-S120","pa":"PA-03","phase":"4. Requisition","scor":"Plan – Source","stype":"Activity","asis":"Warehouse raises purchase requests in MC for dry, frozen and warehouse-controlled items; base article mapped straight to a purchase article without variants.","asisActor":"Warehouse","asisSys":"MC — purchase request","gapFlag":"Gap","gapDesc":"Assortment used as a workaround for variants. (Root cause: no variant setup)","change":"Retire","tobe":"Retired — replaced by planned orders (S060–S150).","dept":"Warehouse","role":"Warehouse","pillars":"Master Data","fit":"Non-system","moscow":"Must","prev":"PA-03-S110","next":"PA-03-S130","evId":"EV-INV-2.2; EV-INV-2.3","evQuote":"all warehouse-controlled items"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S130', N'PA-03', 44, N'Requesting department', N'Modify', N'Not covered', N'{"id":"PA-03-S130","pa":"PA-03","phase":"4. Requisition","scor":"Plan – Source","stype":"Exception","asis":"Purchase request raised for new items that are not yet in the system.","asisActor":"Requesting department","asisSys":"MC — purchase request","gapFlag":"Gap","gapDesc":"Request has no article, so no variant, UOM or price.","change":"Modify","tobe":"A requisition for a missing article raises a linked new-article request (PA-01-S050) and is held until the article is released.","dept":"Requesting department","role":"Requesting department","sys":"D365 — Requisition + item request","input":"Requirement","output":"Pending requisition","pillars":"Master Data | Control","fit":"Not covered","erpReq":"Link requisition to item request; hold until release.","ricefw":"Extension","moscow":"Should","prev":"PA-03-S120","next":"PA-03-S140","evId":"EV-INV-2.3","evQuote":"Purchase request raised for new items that are not available in the system."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S140', N'PA-03', 45, N'Purchase', N'New', N'Partial', N'{"id":"PA-03-S140","pa":"PA-03","phase":"4. Requisition","scor":"Plan – Source","stype":"Approval","asis":"— (no approval of plans)","change":"New","tobe":"Planned orders approved before they are firmed (maker-checker). Planned / requested quantities checked against the approved forecast and purchase limit before firming; Warehouse sees the limit at request. [SLA: before the daily planning cut-off — proposed]","dept":"Purchase","role":"Purchase Chief / Warehouse Head (approver)","sys":"D365 — Planned order approval","input":"Reviewed plan","output":"Approved planned orders (RPT-03)","pillars":"Control | Access & Segregation of Duties","refs":"CTL-03-1 | POL-D05","fit":"Partial","erpReq":"Approval before firming.","ricefw":"Workflow","moscow":"Must","prev":"PA-03-S130","next":"PA-03-S150","evId":"From task list; EV-FD-022","taskId":"PA-03-T09","taskDesc":"Planned-order approval - Approve planned orders before they are firmed","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S150', N'PA-03', 46, N'Purchase', N'Modify', N'Covered', N'{"id":"PA-03-S150","pa":"PA-03","phase":"4. Requisition","scor":"Plan – Source","stype":"Hand-off","asis":"No audit trail or history of purchase requests once converted into purchase orders; the warehouse loses track.","asisActor":"Warehouse","asisSys":"MC","gapFlag":"Control Gap","gapDesc":"Request-to-order link lost. (Root cause: outside the system)","change":"Modify","tobe":"Approved recommendations firmed into purchase, transfer or batch orders; the order keeps its link to the requirement (one document).","dept":"Purchase","role":"Buyer / Planner","sys":"D365 — Firming","input":"Approved planned orders","output":"PO / transfer / batch order","pillars":"Tracking & Traceability | Process","refs":"POL-D03","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-03-S140","next":"PA-03-S160","evId":"EV-WH-6.1","evQuote":"There is no audit trail or history record of Purchase Requests once they are converted into Purchase Orders","taskId":"PA-03-T10","taskDesc":"Firming of purchase, transfer or production orders - Convert approved recommendations into purchase, transfer or batch orders","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-03-S160', N'PA-03', 47, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-03-S160","pa":"PA-03","phase":"4. Requisition","scor":"Plan – Source","stype":"Control check","asis":"Volumes ordered directly sometimes do not match the request placed with the vendor or the request raised in the system.","asisActor":"Production; Purchase","gapFlag":"Control Gap","gapDesc":"Three quantities for one purchase. (Root cause: outside the system)","change":"Modify","tobe":"One quantity carried from requirement to PO to receipt; differences calculated and reported against tolerance.","dept":"Purchase","role":"Buyer; Cost Controller","sys":"D365 — Variance report","input":"PO / receipt","output":"Quantity variance report","pillars":"Monitoring | Control","refs":"CTL-03-2 | POL-D03 | POL-D09 | K-03-1","fit":"Not covered","erpReq":"Requirement–PO–receipt variance report.","ricefw":"Report","moscow":"Should","prev":"PA-03-S150","next":"— (end)","evId":"EV-INV-2.4","evQuote":"Volumes sometimes do not match"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S010', N'PA-04', 48, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-04-S010","pa":"PA-04","phase":"1. Arrival & documents","scor":"Source – Receive","stype":"Activity","asis":"Receiving supervisor receives the delivery with invoice and delivery note most of the time.","asisActor":"Receiving Supervisor","asisSys":"Paper invoice / delivery note","change":"Modify","tobe":"Receiver registers the supplier''s arrival at the dock in the ERP before unloading. [SLA: on arrival, before unloading — proposed]","dept":"Warehouse","role":"Receiving Supervisor","sys":"D365 — Inbound load / arrival","input":"Supplier delivery; PO","output":"Arrival record","pillars":"Tracking & Traceability","fit":"Covered","erpReq":"Arrival registration at dock.","ricefw":"Configuration","moscow":"Should","prev":"— (start)","next":"PA-04-S020","evId":"EV-CC-0.16; EV-WH-3.1","evQuote":"Receiving supervisor receive item with invoice & delivery note most of the time","taskId":"PA-04-T01","taskDesc":"Delivery arrival - Register supplier delivery arrival at the receiving dock","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S020', N'PA-04', 49, N'Warehouse', N'Modify', N'Partial', N'{"id":"PA-04-S020","pa":"PA-04","phase":"1. Arrival & documents","scor":"Source – Receive","stype":"Exception","asis":"Partial delivery of a PO arrives with a delivery note only; supplier submits a consolidated invoice once the PO is complete.","asisActor":"Receiving Supervisor","asisSys":"Delivery note","gapFlag":"Gap","gapDesc":"Partial receipts and invoice tracked outside one document.","change":"Modify","tobe":"Each partial delivery is received against the same PO; the open balance stays on the PO and the consolidated invoice is matched to all receipts.","dept":"Warehouse","role":"Receiving Supervisor","sys":"D365 — Partial product receipt","input":"Arrival record","output":"Partial receipt","pillars":"Process | Finance","refs":"POL-D03","fit":"Partial","erpReq":"Partial receipts; invoice matched to multiple receipts.","ricefw":"Configuration","moscow":"Must","prev":"PA-04-S010","next":"PA-04-S030","evId":"EV-CC-0.17","evQuote":"submit consolidated invoice once complete PO is delivered"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S030', N'PA-04', 50, N'Warehouse', N'Retire', N'Non-system', N'{"id":"PA-04-S030","pa":"PA-04","phase":"1. Arrival & documents","scor":"Source – Receive","stype":"Exception","asis":"Items are received without a PO for practical reasons (brand change, supplier change, PO coordinated over phone).","asisActor":"Warehouse; Purchase","gapFlag":"Control Gap","gapDesc":"Receipt without a commitment document. (Root cause: outside the system)","change":"Retire","tobe":"Retired — no receipt without a PO (S040).","dept":"Warehouse","role":"Receiving Supervisor","pillars":"Control","refs":"POL-D05","fit":"Non-system","moscow":"Must","prev":"PA-04-S020","next":"PA-04-S040","evId":"EV-CC-0.22; EV-WH-3.3","evQuote":"Without PO also item received in case of practical requirement"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S040', N'PA-04', 51, N'Warehouse', N'New', N'Covered', N'{"id":"PA-04-S040","pa":"PA-04","phase":"1. Arrival & documents","scor":"Source – Receive","stype":"Control check","asis":"— (not described)","change":"New","tobe":"Receiver scans or selects the purchase order; the system blocks receipt without a valid PO.","dept":"Warehouse","role":"Receiving Supervisor","sys":"D365 — Product receipt","input":"Arrival record","output":"PO selected","pillars":"Control","refs":"POL-D05","fit":"Covered","erpReq":"Receipt only against an open PO.","ricefw":"Configuration","moscow":"Must","prev":"PA-04-S030","next":"PA-04-S050","evId":"From task list","taskId":"PA-04-T02","taskDesc":"PO and delivery-note validation - Receiver scans or selects the purchase order","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S050', N'PA-04', 52, N'Warehouse', N'New', N'Covered', N'{"id":"PA-04-S050","pa":"PA-04","phase":"1. Arrival & documents","scor":"Source – Receive","stype":"Control check","asis":"— (who checks documents and against what is not yet captured)","change":"New","tobe":"Receiver verifies supplier, invoice and delivery note against the PO.","dept":"Warehouse","role":"Receiving Supervisor","sys":"D365 — Product receipt","input":"PO selected","output":"Documents verified","pillars":"Control","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-04-S040","next":"PA-04-S060","evId":"From task list","taskId":"PA-04-T03","taskDesc":"PO and delivery-note validation - Verify supplier, invoice and delivery note","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S060', N'PA-04', 53, N'Warehouse', N'Modify', N'Partial', N'{"id":"PA-04-S060","pa":"PA-04","phase":"2. Vehicle & condition","scor":"Source – Receive","stype":"Control check","asis":"Receiving team checks the products, the truck, the pallet condition and the driver''s hygiene, and ticks a QC paper checklist.","asisActor":"Receiving team","asisSys":"QC paper checklist","gapFlag":"Gap","gapDesc":"Checklist on paper; not linked to the receipt. (Root cause: outside the system)","change":"Modify","tobe":"Receiving team completes the vehicle, pallet, driver-hygiene and product-condition checklist as an ERP quality order linked to the receipt; a failed check blocks acceptance. The restaurant checklist tool stays for store checklists.","dept":"Warehouse","role":"Receiving team","sys":"D365 — Quality order on receipt","input":"Documents verified","output":"Condition checklist","pillars":"Compliance & Food Safety | Control","refs":"CTL-R01 | POL-D15 | K-R02","fit":"Partial","erpReq":"Receiving checklist linked to product receipt.","ricefw":"Customization","moscow":"Must","prev":"PA-04-S050","next":"PA-04-S070","evId":"EV-QC-3.1; EV-QC-9.2; EV-QL-QC01","evQuote":"the condition of the pallet (wooden or plastic); and the hygiene of the driver delivering"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S070', N'PA-04', 54, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-04-S070","pa":"PA-04","phase":"2. Vehicle & condition","scor":"Source – Receive","stype":"Control check","asis":"Product temperature recorded on the paper checklist.","asisActor":"Receiving team","asisSys":"QC paper checklist","change":"Modify","tobe":"Receiver records product temperature on the receipt for chilled and frozen items; out-of-range blocks acceptance. [SLA: at unloading, before putaway — proposed]","dept":"Warehouse","role":"Receiving team","sys":"D365 — Product receipt (temperature field)","input":"Condition checklist","output":"Temperature record","pillars":"Compliance & Food Safety","refs":"CTL-R01","fit":"Covered","erpReq":"Temperature field and limits per item.","ricefw":"Customization","moscow":"Must","prev":"PA-04-S060","next":"PA-04-S080","evId":"EV-QC-3.1","evQuote":"They tick a CHECKLIST provided by the Quality Control team / Operational Excellence team","taskId":"PA-04-T08","taskDesc":"Temperature and condition check - Record temperature where applicable","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S080', N'PA-04', 55, N'Quality Control', N'Retire', N'Non-system', N'{"id":"PA-04-S080","pa":"PA-04","phase":"2. Vehicle & condition","scor":"Source – Receive","stype":"Report","asis":"The receiving checklist is a manual paper record kept for ISO document traceability, not entered in Excel or a database.","asisActor":"Quality Control","asisSys":"Paper file","gapFlag":"Gap","gapDesc":"No searchable record of receiving inspections.","change":"Retire","tobe":"Retired — records held in the ERP with the receipt (S060, S070).","dept":"Quality Control","role":"QC Officer","pillars":"Data & Reporting","fit":"Non-system","moscow":"Must","prev":"PA-04-S070","next":"PA-04-S090","evId":"EV-QC-9.1","evQuote":"kept for ISO document traceability and not entered in Excel or a database"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S090', N'PA-04', 56, N'Warehouse', N'New', N'Covered', N'{"id":"PA-04-S090","pa":"PA-04","phase":"3. Unload & stage","scor":"Source – Receive","stype":"Activity","asis":"— (not described)","change":"New","tobe":"Delivery unloaded to the receiving staging area.","dept":"Warehouse","role":"Warehouse Worker","sys":"D365 — Receiving location","input":"Temperature record","output":"Goods in staging","pillars":"Process","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-04-S080","next":"PA-04-S100","evId":"From task list","taskId":"PA-04-T04","taskDesc":"Physical unloading - Unload the delivery to the receiving staging area","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S100', N'PA-04', 57, N'Quality Control', N'Modify', N'Not covered', N'{"id":"PA-04-S100","pa":"PA-04","phase":"3. Unload & stage","scor":"Source – Receive","stype":"Control check","asis":"QC watches product temperature at the staging stage until the goods are stored.","asisActor":"QC Officer","asisSys":"Physical","change":"Modify","tobe":"Staging time and temperature recorded for chilled and frozen goods; maximum 30 minutes in staging (QC to confirm), alert when passed.","dept":"Quality Control","role":"QC Officer","sys":"D365 — Staging","input":"Goods in staging","output":"Staging record","pillars":"Compliance & Food Safety | Monitoring","fit":"Not covered","erpReq":"Staging time limit and alert.","ricefw":"Extension","moscow":"Should","prev":"PA-04-S090","next":"PA-04-S110","evId":"EV-QC-6.3; EV-QL-QC01","evQuote":"the temperature of the product at the staging stage until it is stored"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S110', N'PA-04', 58, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-04-S110","pa":"PA-04","phase":"4. Count & register","scor":"Source – Receive","stype":"Activity","asis":"Data entry and GRN after quality control.","asisActor":"Receiving Supervisor","asisSys":"MC GRN","change":"Modify","tobe":"Receiver records the delivered quantity on the receipt line.","dept":"Warehouse","role":"Receiving Supervisor","sys":"D365 — Product receipt (mobile)","input":"Staging record","output":"Delivered quantity","pillars":"Tracking & Traceability","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-04-S100","next":"PA-04-S120","evId":"EV-CC-0.20","evQuote":"Data entry and GRN","taskId":"PA-04-T05","taskDesc":"Quantity registration - Record delivered quantity","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S120', N'PA-04', 59, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-04-S120","pa":"PA-04","phase":"4. Count & register","scor":"Source – Receive","stype":"Activity","asis":"Warehouse can receive more or less than the PO; the PO is kept open for convenience.","asisActor":"Receiving Supervisor","asisSys":"MC","gapFlag":"Control Gap","gapDesc":"No receipt tolerance; PO left open. (Root cause: outside the system)","change":"Modify","tobe":"Receiver records damaged, short or excess quantity on the receipt line; only accepted quantity is posted to stock.","dept":"Warehouse","role":"Receiving Supervisor","sys":"D365 — Product receipt","input":"Delivered quantity","output":"Accepted / rejected quantity","pillars":"Control | Finance","refs":"POL-D09","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-04-S110","next":"PA-04-S130","evId":"EV-CC-0.18; EV-WH-3.4","evQuote":"Can receive more or less than PO and kept open for conveinent","taskId":"PA-04-T06","taskDesc":"Quantity registration - Record damaged, short or excess quantity","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S130', N'PA-04', 60, N'Warehouse', N'New', N'Partial', N'{"id":"PA-04-S130","pa":"PA-04","phase":"4. Count & register","scor":"Source – Receive","stype":"Control check","asis":"— (no tolerance today)","change":"New","tobe":"System applies the receipt tolerance per item / vendor; over-receipt beyond tolerance needs Purchase approval; PO closed when complete.","dept":"Warehouse","role":"System; Purchase (approver beyond tolerance)","sys":"D365 — Over / under delivery tolerance","input":"Accepted quantity","output":"Tolerance check","pillars":"Control","refs":"POL-D09 | POL-D03","fit":"Partial","erpReq":"Tolerance % per item / vendor; PO auto-close.","ricefw":"Configuration","moscow":"Must","prev":"PA-04-S120","next":"PA-04-S140","evId":"EV-QL-P09 (Recommended)"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S140', N'PA-04', 61, N'Warehouse', N'Modify', N'Partial', N'{"id":"PA-04-S140","pa":"PA-04","phase":"4. Count & register","scor":"Source – Receive","stype":"Exception","asis":"Vendor supplies extra quantity unbilled to cover a yield shortfall; it is not entered in the system.","asisActor":"Vendor; Receiving","gapFlag":"Control Gap","gapDesc":"Stock and cost understated. (Root cause: outside the system)","change":"Modify","tobe":"Unbilled quantity is received as a zero-price line against the same PO so stock and yield are correct.","dept":"Warehouse","role":"Receiving Supervisor; Cost Controller (review)","sys":"D365 — Zero-price receipt line","input":"Delivered quantity","output":"Free-goods receipt","pillars":"Finance | Control","refs":"POL-D10","fit":"Partial","erpReq":"Free / zero-price receipt line with reason.","ricefw":"Configuration","moscow":"Should","prev":"PA-04-S130","next":"PA-04-S150","evId":"EV-CC-5.4","evQuote":"Vendor supplies extra quantity unbilled for yield shortfall; not entered in the system."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S150', N'PA-04', 62, N'Warehouse', N'New', N'Covered', N'{"id":"PA-04-S150","pa":"PA-04","phase":"4. Count & register","scor":"Source – Receive","stype":"Activity","asis":"— (see S160)","change":"New","tobe":"Receiver records batch, manufacture and expiry dates for every item at variant level; fresh / daily items follow the separate tracking method.","dept":"Warehouse","role":"Receiving Supervisor","sys":"D365 — Batch dimension","input":"Accepted quantity","output":"Batch record","pillars":"Tracking & Traceability | Compliance & Food Safety","refs":"CTL-R02 | POL-D02 | POL-D08","fit":"Covered","erpReq":"Batch / expiry mandatory at variant level.","ricefw":"Configuration","moscow":"Must","prev":"PA-04-S140","next":"PA-04-S160","evId":"EV-CPU-OR-19.3","evQuote":"It should be like variant level movement of article and inventory","taskId":"PA-04-T07","taskDesc":"Batch and expiry registration - Record batch, manufacture and expiry dates","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S160', N'PA-04', 63, N'Warehouse', N'Retire', N'Non-system', N'{"id":"PA-04-S160","pa":"PA-04","phase":"4. Count & register","scor":"Source – Receive","stype":"Activity","asis":"Expiry and batch details are recorded in the WMS against the PO ''to some extent''; MC does not capture them and holds one article without variants.","asisActor":"Warehouse","asisSys":"Swish WMS; paper","gapFlag":"Gap","gapDesc":"Batch data not visible to production, R&D or Purchase. (Root cause: no variant setup)","change":"Retire","tobe":"Retired — batch held in the ERP (S150).","dept":"Warehouse","role":"Warehouse","pillars":"Tracking & Traceability","fit":"Non-system","moscow":"Must","prev":"PA-04-S150","next":"PA-04-S170","evId":"EV-WH-4.1; EV-CPU-OR-19.1; EV-CPU-OR-19.2","evQuote":"MC does not capture expiry or minimum-expiry data"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S170', N'PA-04', 64, N'Quality Control', N'New', N'Not covered', N'{"id":"PA-04-S170","pa":"PA-04","phase":"5. Quality decision","scor":"Source – Receive","stype":"Setup","asis":"No per-item minimum shelf life held in the system; receiver judges.","asisActor":"Receiver","asisSys":"Judgement","gapFlag":"Gap","gapDesc":"No acceptance criterion per item.","change":"New","tobe":"QC sets the minimum remaining shelf life per item (food, cleaning materials, consumables), mapped to the purchase article and printed on the PO.","dept":"Quality Control","role":"QC Head","sys":"D365 — Item quality attributes","input":"Item master","output":"Shelf-life criterion","pillars":"Compliance & Food Safety | Master Data","refs":"POL-D07 | POL-R01","fit":"Not covered","erpReq":"Minimum remaining shelf life per item, printed on PO.","ricefw":"Extension","moscow":"Must","prev":"PA-04-S160","next":"PA-04-S180","evId":"EV-WH-3.2; EV-WH-V03","evQuote":"The criterion is the shelf life REMAINING in that batch at the time of receipt"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S180', N'PA-04', 65, N'Warehouse', N'New', N'Not covered', N'{"id":"PA-04-S180","pa":"PA-04","phase":"5. Quality decision","scor":"Source – Receive","stype":"Control check","asis":"— (judgement at receipt)","change":"New","tobe":"System checks remaining shelf life at receipt: pass → continue; fail → quarantine (S200); fresh / daily items judged by physical audit.","dept":"Warehouse","role":"System; Receiving Supervisor","sys":"D365 — Receipt validation","input":"Batch record; shelf-life criterion","output":"Pass / quarantine","pillars":"Compliance & Food Safety | Control","refs":"CTL-R02 | POL-D07 | K-R01","fit":"Not covered","erpReq":"Shelf-life validation on receipt.","ricefw":"Extension","moscow":"Must","prev":"PA-04-S170","next":"PA-04-S190","evId":"EV-QC-10.2","evQuote":"product received: the system should hold the conditions that must be met for the product to be received"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S190', N'PA-04', 66, N'Quality Control', N'Modify', N'Covered', N'{"id":"PA-04-S190","pa":"PA-04","phase":"5. Quality decision","scor":"Source – Receive","stype":"Control check","asis":"QC decides by scale of defect — reject full batch, part batch or isolated pieces — and signs off manually.","asisActor":"QC Officer","asisSys":"Paper sign-off","gapFlag":"Gap","gapDesc":"Decision on paper; not linked to batch. (Root cause: outside the system)","change":"Modify","tobe":"QA records test results and the decision (accept / partial reject / reject) in the ERP before putaway.","dept":"Quality Control","role":"QC Officer","sys":"D365 — Quality order","input":"Pass / quarantine","output":"Quality decision","pillars":"Compliance & Food Safety","refs":"CTL-R03 | POL-D15","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-04-S180","next":"PA-04-S200","evId":"EV-QC-4.1","evQuote":"reject the FULL batch; reject PART of the batch; or reject only minor / isolated pieces","taskId":"PA-04-T09","taskDesc":"Quality decision - QA records test results","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S200', N'PA-04', 67, N'Quality Control', N'Modify', N'Partial', N'{"id":"PA-04-S200","pa":"PA-04","phase":"5. Quality decision","scor":"Source – Receive","stype":"Approval","asis":"Short-dated or doubtful goods proposed to be parked and approved by any one of Warehouse Supervisor, Warehouse Manager, Quality team or CPU Managers.","asisActor":"Warehouse Supervisor / Manager; QC; CPU Manager","asisSys":"Verbal","change":"Modify","tobe":"Short-dated or doubtful goods held in quarantine; released by an approver other than the receiver (QC, CPU Manager, Warehouse Supervisor or Manager); stakeholders notified. [SLA: QC decision within 24 hours; release within 48 hours — proposed]","dept":"Quality Control","role":"QC Officer / CPU Manager / Warehouse Supervisor or Manager (approver)","sys":"D365 — Inventory status + workflow","input":"Quality decision","output":"Quarantine release / rejection","pillars":"Control | Compliance & Food Safety","refs":"CTL-R04 | POL-D05 | POL-R01","fit":"Partial","erpReq":"Quarantine release approval ≠ receiver; notification.","ricefw":"Workflow","moscow":"Must","prev":"PA-04-S190","next":"PA-04-S210","evId":"EV-WH-V03; EV-WH-3.2","evQuote":"short-dated goods parked and approved by any one of Warehouse Supervisor, Warehouse Manager, Quality team or CPU Managers"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S210', N'PA-04', 68, N'Warehouse', N'New', N'Covered', N'{"id":"PA-04-S210","pa":"PA-04","phase":"5. Quality decision","scor":"Source – Receive","stype":"Exception","asis":"— (rejections handled physically)","change":"New","tobe":"Rejected stock moved to the rejected location and returned or held for disposal.","dept":"Warehouse","role":"Warehouse Supervisor","sys":"D365 — Rejected stock location","input":"Quarantine release / rejection","output":"Rejected stock","pillars":"Compliance & Food Safety","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-04-S200","next":"PA-04-S220","evId":"From task list","taskId":"PA-04-T10","taskDesc":"Quality decision - Rejected stock is returned or quarantined","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S220', N'PA-04', 69, N'Quality Control', N'Keep', N'Non-system', N'{"id":"PA-04-S220","pa":"PA-04","phase":"5. Quality decision","scor":"Source – Receive","stype":"Exception","asis":"Defects investigated and registered on the OPEX platform; QC''s judgement; high-risk cases escalated.","asisActor":"QC","asisSys":"OPEX platform","change":"Keep","tobe":"QC investigates defects on the OPEX platform; the receipt / batch number is recorded on the OPEX case (reference only, no integration); high-risk cases escalated.","dept":"Quality Control","role":"QC Officer","sys":"OPEX platform (receipt / batch reference)","input":"Rejected stock","output":"Investigation case","pillars":"Compliance & Food Safety | Monitoring","fit":"Non-system","erpReq":"Reference field / integration to OPEX case.","moscow":"Should","prev":"PA-04-S210","next":"PA-04-S230","evId":"EV-QC-4.5; EV-QL-QC01","evQuote":"The investigation is purely the judgement of the QC department"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S230', N'PA-04', 70, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-04-S230","pa":"PA-04","phase":"6. Receipt posting","scor":"Source – Receive","stype":"Control check","asis":"Warehouse GRN practice not confirmed; at CPU direct supply one person orders, receives and posts the GRN.","asisActor":"Receiving Supervisor","asisSys":"MC GRN","gapFlag":"Control Gap","gapDesc":"No segregation between ordering and receiving. (Root cause: open user administration)","change":"Modify","tobe":"Authorised receiver posts the product receipt; the PO creator cannot post the receipt. [SLA: same day as delivery — proposed]","dept":"Warehouse","role":"Receiving Supervisor","sys":"D365 — Product receipt; security roles","input":"Accepted quantity; quality decision","output":"Posted receipt (GRN)","pillars":"Access & Segregation of Duties | Control","refs":"CTL-R05 | POL-D05 | POL-D16 | K-R03","fit":"Covered","erpReq":"PO creator ≠ receipt poster.","ricefw":"Configuration","moscow":"Must","prev":"PA-04-S220","next":"PA-04-S240","evId":"EV-CC-0.20; EV-CPU-MGT-7.4","evQuote":"Data entry and GRN","taskId":"PA-04-T11","taskDesc":"Product receipt - Authorized user posts the product receipt","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S240', N'PA-04', 71, N'Cost Control', N'Modify', N'Partial', N'{"id":"PA-04-S240","pa":"PA-04","phase":"6. Receipt posting","scor":"Source – Receive","stype":"Control check","asis":"Costing reviews and matches GRNs mostly on a sample basis, not 100%.","asisActor":"Costing","asisSys":"MC","change":"Modify","tobe":"Costing reviews receipts by exception: the system flags every receipt line with a price or quantity variance against the PO daily; Costing reviews 100% of flagged lines plus a monthly random 5% of clean receipts.","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Variance report","input":"Posted receipt","output":"Receipt variance review","pillars":"Monitoring | Finance","refs":"K-R03 | POL-D24","fit":"Partial","erpReq":"Receipt-vs-PO variance report.","ricefw":"Report","moscow":"Should","prev":"PA-04-S230","next":"PA-04-S250","evId":"EV-CC-5.1; EV-QL-CC01","evQuote":"Costing reviews and matches GRNs mostly on a sample basis, not 100%"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S250', N'PA-04', 72, N'Finance', N'Retire', N'Non-system', N'{"id":"PA-04-S250","pa":"PA-04","phase":"7. Discrepancy & return","scor":"Source – Receive","stype":"Exception","asis":"No credit or debit note used; transaction closed at the actual quantity while waiting for a revised invoice, so the system value differs from the document.","asisActor":"CPU / Warehouse; Finance","asisSys":"MC; manual GRN edit","gapFlag":"Control Gap","gapDesc":"System value differs from supplier document until a revised invoice arrives. (Root cause: rate contract without timeline / audit trail)","change":"Retire","tobe":"Retired — replaced by S260.","dept":"Finance","role":"AP Accountant","pillars":"Finance","fit":"Non-system","moscow":"Must","prev":"PA-04-S240","next":"PA-04-S260","evId":"EV-CPU-OR-7.6","evQuote":"we do not adopt a credit note or debit note concept"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S260', N'PA-04', 73, N'Purchase', N'New', N'Not covered', N'{"id":"PA-04-S260","pa":"PA-04","phase":"7. Discrepancy & return","scor":"Source – Receive","stype":"Exception","asis":"— (see S250)","change":"New","tobe":"Receiver raises the supplier discrepancy (short, damaged, excess) against the receipt; Procurement follows up and settles by credit / debit note or a tracked pending replacement. [SLA: within 24 hours of receipt — proposed]","dept":"Purchase","role":"Receiving Supervisor (raises); Buyer (settles)","sys":"D365 — Vendor discrepancy / credit note","input":"Accepted / rejected quantity","output":"Discrepancy case; credit / debit note","pillars":"Finance | Control","refs":"POL-R02 | POL-D09","fit":"Not covered","erpReq":"Discrepancy case with settlement by credit / debit note or replacement.","ricefw":"Extension","moscow":"Must","prev":"PA-04-S250","next":"PA-04-S270","evId":"From task list","taskId":"PA-04-T12","taskDesc":"Supplier discrepancy follow-up - Raise and follow up supplier discrepancies (short, damaged, excess) with Procurement","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S270', N'PA-04', 74, N'Purchase', N'New', N'Not covered', N'{"id":"PA-04-S270","pa":"PA-04","phase":"7. Discrepancy & return","scor":"Source – Receive","stype":"Report","asis":"No vendor scorecard described.","change":"New","tobe":"Return to vendor processed; rejections, receipt variances and OPEX cases feed the monthly supplier quality scorecard used by Purchase in vendor evaluation.","dept":"Purchase","role":"Buyer; QC Officer","sys":"D365 — Return order; vendor evaluation","input":"Rejected stock; discrepancy cases","output":"Supplier quality scorecard","pillars":"Monitoring | Data & Reporting","refs":"K-R04","fit":"Not covered","erpReq":"RTV and vendor scorecard.","ricefw":"Report","moscow":"Should","prev":"PA-04-S260","next":"PA-04-S280","evId":"EV-PUR-3.2; EV-QL-QC01","taskId":"PA-04-T14","taskDesc":"Return-to-vendor (RTV) and supplier quality scorecard update - Process return-to-vendor and update the supplier quality scorecard","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-04-S280', N'PA-04', 75, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-04-S280","pa":"PA-04","phase":"8. Release to putaway","scor":"Source – Receive","stype":"Hand-off","asis":"Staff rotate stock by hand, older at the front; where new stock expires later, the order is a judgement call.","asisActor":"Warehouse / QC / CPU","asisSys":"Physical","gapFlag":"Gap","gapDesc":"FEFO by judgement; no batch selection record.","change":"Modify","tobe":"Accepted stock released for putaway (PA-05) with FEFO guidance; user selects the batch and the selection is logged. [SLA: putaway within 4 hours of receipt (chilled / frozen within 30 minutes) — proposed]","dept":"Warehouse","role":"Warehouse Supervisor","sys":"D365 — Putaway work","input":"Posted receipt","output":"Putaway work (to PA-05)","pillars":"Tracking & Traceability | Compliance & Food Safety","refs":"POL-D07","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-04-S270","next":"PA-05-S010","evId":"EV-QC-6.3","evQuote":"the new product is not placed in front of old product","taskId":"PA-04-T13","taskDesc":"Putaway - Accepted stock is released for putaway","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-05-S010', N'PA-05', 76, N'Warehouse', N'New', N'Covered', N'{"id":"PA-05-S010","pa":"PA-05","phase":"1. Putaway","scor":"Source – Transfer","stype":"Hand-off","asis":"— (putaway not system-directed)","change":"New","tobe":"System creates putaway work when the product receipt is posted.","dept":"Warehouse","role":"System","sys":"D365 — Warehouse management","input":"Putaway work (from PA-04-S280)","output":"Putaway work","pillars":"Process","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-04-S280","next":"PA-05-S020","evId":"From task list","taskId":"PA-05-T01","taskDesc":"Putaway-work creation - System creates putaway work on product receipt","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-05-S020', N'PA-05', 77, N'Warehouse', N'New', N'Covered', N'{"id":"PA-05-S020","pa":"PA-05","phase":"1. Putaway","scor":"Source – Transfer","stype":"Activity","asis":"— (zone chosen by staff)","change":"New","tobe":"System proposes the storage zone (frozen, chilled, ambient, packaging) from the item''s storage profile.","dept":"Warehouse","role":"System","sys":"D365 — Location directives","input":"Putaway work","output":"Proposed zone","pillars":"Compliance & Food Safety","fit":"Covered","erpReq":"Location directives by temperature zone.","ricefw":"Configuration","moscow":"Must","prev":"PA-05-S010","next":"PA-05-S030","evId":"From task list","taskId":"PA-05-T02","taskDesc":"Storage-zone selection - System identifies the appropriate storage zone","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-05-S030', N'PA-05', 78, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-05-S030","pa":"PA-05","phase":"1. Putaway","scor":"Source – Transfer","stype":"Activity","asis":"Warehouse, QC or CPU team rotate stock by hand so the older product is at the front and the new behind.","asisActor":"Warehouse / QC / CPU team","asisSys":"Physical","gapFlag":"Gap","gapDesc":"No location or batch record of where stock is placed. (Root cause: outside the system)","change":"Modify","tobe":"Warehouse worker scans the item or licence plate to start putaway.","dept":"Warehouse","role":"Warehouse Worker","sys":"D365 — Mobile app","input":"Proposed zone","output":"Item scanned","pillars":"Tracking & Traceability","refs":"POL-D07","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-05-S020","next":"PA-05-S040","evId":"EV-QC-6.3","evQuote":"the warehouse, QC or CPU team rotate stock so the older product is at the front and the new","taskId":"PA-05-T03","taskDesc":"Mobile location confirmation - Warehouse worker scans the item or license plate","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-05-S040', N'PA-05', 79, N'Warehouse', N'New', N'Covered', N'{"id":"PA-05-S040","pa":"PA-05","phase":"1. Putaway","scor":"Source – Transfer","stype":"Activity","asis":"— (not described)","change":"New","tobe":"Worker scans the destination location.","dept":"Warehouse","role":"Warehouse Worker","sys":"D365 — Mobile app","input":"Item scanned","output":"Location scanned","pillars":"Tracking & Traceability","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-05-S030","next":"PA-05-S050","evId":"From task list","taskId":"PA-05-T04","taskDesc":"Mobile location confirmation - Worker scans the destination location","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-05-S050', N'PA-05', 80, N'Warehouse', N'New', N'Covered', N'{"id":"PA-05-S050","pa":"PA-05","phase":"1. Putaway","scor":"Source – Transfer","stype":"Control check","asis":"— (not described)","change":"New","tobe":"System validates that the location is allowed for the item (zone, temperature, status) before confirming putaway.","dept":"Warehouse","role":"System","sys":"D365 — Location validation","input":"Location scanned","output":"Stock in location","pillars":"Control | Compliance & Food Safety","refs":"CTL-05-1","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-05-S040","next":"PA-05-S060","evId":"From task list","taskId":"PA-05-T05","taskDesc":"Mobile location confirmation - System validates whether the location is allowed","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-05-S060', N'PA-05', 81, N'Quality Control', N'Keep', N'Partial', N'{"id":"PA-05-S060","pa":"PA-05","phase":"2. Storage control","scor":"Source – Transfer","stype":"Control check","asis":"QC validates storage at the proper temperature, proper shelving, FIFO with the earliest stock at the front, and proper stacking through its checklist.","asisActor":"QC team","asisSys":"QC checklist (paper)","gapFlag":"Gap","gapDesc":"Storage checklist on paper. (Root cause: outside the system)","change":"Keep","tobe":"QC records the storage validation (temperature, shelving, stock rotation, stacking) digitally by location; findings raise corrective actions.","dept":"Quality Control","role":"QC Officer","sys":"QC checklist tool / D365 quality","input":"Stock in location","output":"Storage validation record","pillars":"Compliance & Food Safety | Monitoring","refs":"CTL-05-1 | POL-D15","fit":"Partial","erpReq":"Digital storage checklist by location.","ricefw":"Customization","moscow":"Should","prev":"PA-05-S050","next":"PA-05-S070","evId":"EV-QC-6.3; EV-QC-V03","evQuote":"proper stacking are all VALIDATED BY THE QC TEAM through the checklist"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-05-S070', N'PA-05', 82, N'Warehouse', N'Keep', N'Not covered', N'{"id":"PA-05-S070","pa":"PA-05","phase":"2. Storage control","scor":"Source – Transfer","stype":"Control check","asis":"Freezer and chiller temperatures are monitored by a system with an alarm.","asisActor":"CPU / Warehouse","asisSys":"Temperature monitoring system with alarm","change":"Keep","tobe":"Storage temperature alarms logged and linked to the affected location and batches; breach triggers a QC hold.","dept":"Warehouse","role":"Warehouse Supervisor; QC Officer","sys":"Temperature system ↔ D365 (interface)","input":"Temperature readings","output":"Alarm log; QC hold","pillars":"Monitoring | Compliance & Food Safety","refs":"CTL-05-1 | K-05-1","fit":"Not covered","erpReq":"Temperature-alarm interface to batch hold.","ricefw":"Interface","moscow":"Could","prev":"PA-05-S060","next":"PA-05-S080","evId":"EV-CPU-OR-N06; EV-CPU-OR-4.5","evQuote":"There is a system to monitor the temperature of the freezer and chiller, with an alarm system."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-05-S080', N'PA-05', 83, N'Warehouse', N'New', N'Covered', N'{"id":"PA-05-S080","pa":"PA-05","phase":"3. Internal movement","scor":"Source – Transfer","stype":"Activity","asis":"— (not described)","change":"New","tobe":"Worker confirms the quantity moved between locations.","dept":"Warehouse","role":"Warehouse Worker","sys":"D365 — Movement work","input":"Stock in location","output":"Movement record","pillars":"Tracking & Traceability","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-05-S070","next":"PA-05-S090","evId":"From task list","taskId":"PA-05-T06","taskDesc":"Internal stock movement - Worker confirms the quantity moved","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-05-S090', N'PA-05', 84, N'Warehouse', N'New', N'Covered', N'{"id":"PA-05-S090","pa":"PA-05","phase":"3. Internal movement","scor":"Source – Transfer","stype":"Activity","asis":"— (not described)","change":"New","tobe":"Picking locations replenished from bulk storage.","dept":"Warehouse","role":"Warehouse Worker","sys":"D365 — Replenishment","input":"Pick-face minimum","output":"Replenished pick location","pillars":"Process","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-05-S080","next":"PA-05-S100","evId":"From task list","taskId":"PA-05-T07","taskDesc":"Replenishment of picking locations - Picking locations are replenished from bulk storage","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-05-S100', N'PA-05', 85, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-05-S100","pa":"PA-05","phase":"3. Internal movement","scor":"Source – Transfer","stype":"Control check","asis":"Storage space is a constraint (bakery finished goods compared with CPU finished goods).","asisActor":"CBU management","gapFlag":"Gap","gapDesc":"Capacity not monitored.","change":"Modify","tobe":"Supervisor monitors location capacity and handles blocked or full locations.","dept":"Warehouse","role":"Warehouse Supervisor","sys":"D365 — Location capacity","input":"Location status","output":"Capacity action","pillars":"Monitoring","fit":"Covered","ricefw":"Configuration","moscow":"Could","prev":"PA-05-S090","next":"— (end)","evId":"EV-CBU-3.7","evQuote":"Storage is also a constraint","taskId":"PA-05-T08","taskDesc":"Location-capacity monitoring - Supervisor handles blocked or full locations","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S010', N'PA-06', 86, N'Store Operations', N'Retire', N'Non-system', N'{"id":"PA-06-S010","pa":"PA-06","phase":"1. Order preparation","scor":"Deliver – Ship","stype":"Activity","asis":"Store manager checks current stock of every item and updates the paper ordering-cum-inventory sheet daily.","asisActor":"Store Manager","asisSys":"Paper ordering-cum-inventory sheet","gapFlag":"Gap","gapDesc":"Stock and order worked out on paper; nothing visible to supply chain. (Root cause: outside the system)","change":"Retire","tobe":"Retired — replaced by system stock and proposal (S040).","dept":"Store Operations","role":"Store Manager","pillars":"Process","fit":"Non-system","moscow":"Must","prev":"— (start)","next":"PA-06-S020","evId":"EV-OPS-2.1; EV-OPS-V02","evQuote":"ALL ON PAPER; nothing is captured in a digital sheet","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S020', N'PA-06', 87, N'Store Operations', N'Retire', N'Non-system', N'{"id":"PA-06-S020","pa":"PA-06","phase":"1. Order preparation","scor":"Deliver – Ship","stype":"Activity","asis":"Store counts main food items in Excel, adjusting against previous day''s opening stock and sales usage worked out by hand from the POS.","asisActor":"Store Manager","asisSys":"Excel; Foodics POS (read manually)","gapFlag":"Gap","gapDesc":"POS not integrated; usage recalculated manually. (Root cause: outside the system)","change":"Retire","tobe":"Retired — daily count of main items in the ERP (PA-09) and POS-driven usage (PA-17).","dept":"Store Operations","role":"Store Manager","pillars":"Data & Reporting","refs":"POL-D06","fit":"Non-system","moscow":"Must","prev":"PA-06-S010","next":"PA-06-S030","evId":"EV-OPS-2.1; EV-OPS-V04","evQuote":"updating sales usage in the Excel by manual calculation from the POS","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S030', N'PA-06', 88, N'Store Operations', N'Retire', N'Non-system', N'{"id":"PA-06-S030","pa":"PA-06","phase":"1. Order preparation","scor":"Deliver – Ship","stype":"Activity","asis":"Store manager works out the next-day quantity and writes it on the ordering sheet; stores order any quantity, off the standard pack.","asisActor":"Store Manager","asisSys":"Paper sheet; MC repositioning privilege","gapFlag":"Control Gap","gapDesc":"Quantity by judgement; standard pack bypassed through user privilege. (Root cause: open user administration)","change":"Retire","tobe":"Retired — replaced by S040 / S050.","dept":"Store Operations","role":"Store Manager","pillars":"Control","fit":"Non-system","moscow":"Must","prev":"PA-06-S020","next":"PA-06-S040","evId":"EV-OPS-2.1; EV-OPS-0.3","evQuote":"works out how much is required for the next day, and writes it on the ordering sheet","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S040', N'PA-06', 89, N'Store Operations', N'New', N'Covered', N'{"id":"PA-06-S040","pa":"PA-06","phase":"1. Order preparation","scor":"Deliver – Ship","stype":"Activity","asis":"— (no system proposal today)","gapFlag":"Gap","change":"New","tobe":"Order guidance generated by the demand-forecast tool within the ERP, together with the existing demand-planning / Data & Analytics tool (integrated in the interim), from POS sales, forecast and par level; the Store Manager decides the order quantity supported by this guidance; finalised under PA-06-S060 (within the agreed level AM-01; above it, Costing).","dept":"Store Operations","role":"System (guidance); Store Manager (decides)","sys":"D365 — Replenishment / transfer requisition","input":"Store stock; POS sales; min / max","output":"Proposed requirement","pillars":"Process | Data & Reporting","fit":"Covered","erpReq":"Min / max per item per store; pack-size rounding.","ricefw":"Configuration","moscow":"Should","prev":"PA-06-S030","next":"PA-06-S050","evId":"EV-QL-SO01","taskId":"— (see PA-06-S050, task T01)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S050', N'PA-06', 90, N'Store Operations', N'Modify', N'Covered', N'{"id":"PA-06-S050","pa":"PA-06","phase":"1. Order preparation","scor":"Deliver – Ship","stype":"Activity","asis":"Store manager places the order directly into MC one day before delivery.","asisActor":"Store Manager","asisSys":"MC material request","gapFlag":"Gap","gapDesc":"24-hour lead time too short for CPU / bakery planning. (Root cause: outside the system)","change":"Modify","tobe":"Store manager reviews the proposal and submits the requirement in the ERP 48 hours before delivery; standard pack enforced; repositioning privilege removed.","dept":"Store Operations","role":"Store Manager","sys":"D365 — Transfer requisition","input":"Proposed requirement","output":"Outlet requirement","pillars":"Process | Control","refs":"POL-D04","fit":"Covered","erpReq":"48-hour cut-off by delivery date; pack-size rule.","ricefw":"Configuration","moscow":"Must","prev":"PA-06-S040","next":"PA-06-S060","evId":"EV-OPS-2.2; EV-OPS-0.7","evQuote":"ordering 2 days before instead of 1 day before","taskId":"PA-06-T01","taskDesc":"Outlet requirement - Outlet submits a requirement or the system calculates replenishment","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S060', N'PA-06', 91, N'Store Operations', N'Keep', N'Partial', N'{"id":"PA-06-S060","pa":"PA-06","phase":"1. Order preparation","scor":"Deliver – Ship","stype":"Approval","asis":"Store manager confirms the order once with an Area Manager or store senior, if required.","asisActor":"Store Manager; Area Manager","asisSys":"Verbal / phone","change":"Keep","tobe":"Additional or off-pattern store orders within the agreed level (AM-01) proceed; above the level they route to Costing for approval.","dept":"Store Operations","role":"System / Store Manager (within AM-01); Costing (above level)","sys":"D365 — Workflow","input":"Outlet requirement","output":"Approved requirement","pillars":"Control","refs":"POL-D22","fit":"Partial","erpReq":"Conditional approval workflow on requisition.","ricefw":"Workflow","moscow":"Should","prev":"PA-06-S050","next":"PA-06-S070","evId":"EV-OPS-2.2; EV-QL-AM01","evQuote":"confirms it once with an AREA MANAGER or a store senior, IF REQUIRED","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S070', N'PA-06', 92, N'Store Operations', N'New', N'Not covered', N'{"id":"PA-06-S070","pa":"PA-06","phase":"1. Order preparation","scor":"Deliver – Ship","stype":"Exception","asis":"Over-supply from the standard batch: store asked to raise an additional order for the difference; short supply carried to the next schedule.","asisActor":"Store Manager; CPU","asisSys":"MC","gapFlag":"Gap","gapDesc":"Missed and extra units handled outside the original order.","change":"New","tobe":"Store raises an additional requirement for missed units, linked to the original order and flagged as additional.","dept":"Store Operations","role":"Store Manager","sys":"D365 — Transfer requisition","input":"Shortfall","output":"Additional requirement","pillars":"Process","refs":"POL-D04","fit":"Not covered","erpReq":"Additional-order flag and link to original requirement.","ricefw":"Extension","moscow":"Should","prev":"PA-06-S060","next":"PA-06-S080","evId":"EV-OPS-0.6","evQuote":"store asked to raise an additional order for the difference; short supply carried to the next schedule","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S080', N'PA-06', 93, N'Store Operations', N'New', N'Not covered', N'{"id":"PA-06-S080","pa":"PA-06","phase":"1. Order preparation","scor":"Deliver – Ship","stype":"Setup","asis":"Stores order food, non-food and raw items from the warehouse a day before; some non-food delivered daily; bulk-discount buys leave low-volume stores with weeks of stock.","asisActor":"Supply chain; Purchase","asisSys":"Delivery schedule (manual)","gapFlag":"Gap","gapDesc":"Delivery frequency and routing not set by item group and store volume.","change":"New","tobe":"Delivery calendar held per store and route in the ERP (days, windows by brand); the supply route is a flag per item and store — via warehouse by default, direct only for items approved under PA-08-S010; low-volume stores take bulk-discount items via the warehouse. Delivery windows set per store outside peak trading hours (e.g. lunch peak), agreed with Operations, so receiving checks are not weakened.","dept":"Store Operations","role":"Operations Manager; Purchase","sys":"D365 — Delivery schedule","input":"Store profile; item groups","output":"Delivery calendar","pillars":"Process | Finance","fit":"Not covered","erpReq":"Delivery schedule per store and item group; routing rule.","ricefw":"Configuration","moscow":"Should","prev":"PA-06-S070","next":"PA-06-S085","evId":"EV-OPS-2.3; EV-OPS-3.2; EV-OPS-V07; EV-FD-031; EV-FD-036; EV-FD-120","evQuote":"deliver non-food items every 3 days instead of daily, where store space allows","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S085', N'PA-06', 94, N'Logistics', N'New', N'Partial', N'{"id":"PA-06-S085","pa":"PA-06","phase":"1. Order preparation","scor":"Deliver – Ship","stype":"Setup","asis":"— (new step; no as-is activity reported)","change":"New","tobe":"Logistics plans routes and loads per the delivery calendar: vehicle, driver, stops, temperature zone and loading sequence.","dept":"Logistics","role":"Logistics Supervisor","sys":"D365 — Load / route planning (or integrated tool)","input":"Delivery calendar; approved transfers","output":"Route and load plan","pillars":"Process | Monitoring","fit":"Partial","erpReq":"Confirm: load and route planning per delivery calendar (standard load planning or integration with a route tool).","ricefw":"Configuration","moscow":"Should","prev":"PA-06-S080","next":"PA-06-S090","evId":"(Analyst proposal — confirm at docket review)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S090', N'PA-06', 95, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-06-S090","pa":"PA-06","phase":"2. Review & reserve","scor":"Deliver – Ship","stype":"Activity","asis":"Warehouse arranges stock against the MR; CPU / stores learn of non-availability only after the MR is raised; live warehouse stock not visible.","asisActor":"Warehouse","asisSys":"MC; WMS","gapFlag":"Gap","gapDesc":"No live stock visibility at ordering. (Root cause: outside the system)","change":"Modify","tobe":"Planner reviews stock availability against all requirements before the cut-off; live warehouse stock visible to stores and CPU at ordering.","dept":"Warehouse","role":"Planner / Warehouse Supervisor","sys":"D365 — Transfer planning","input":"Approved requirement","output":"Reviewed requirement","pillars":"Process | Data & Reporting","fit":"Covered","erpReq":"Availability view for requesting sites.","ricefw":"Configuration","moscow":"Must","prev":"PA-06-S085","next":"PA-06-S100","evId":"EV-CPU-MGT-5.5","evQuote":"CPU learns they are not available only when the warehouse informs them after the MR has been raised","taskId":"PA-06-T02","taskDesc":"Request review - Planner reviews stock availability","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S100', N'PA-06', 96, N'Warehouse', N'New', N'Not covered', N'{"id":"PA-06-S100","pa":"PA-06","phase":"2. Review & reserve","scor":"Deliver – Ship","stype":"Exception","asis":"Non-availability communicated by warehouse after the MR (reasons: product, vendor, market).","asisActor":"Warehouse","asisSys":"Phone / WhatsApp","gapFlag":"Gap","gapDesc":"Shortage notice outside the system.","change":"New","tobe":"Short or unavailable lines flagged on the order with reason and proposed substitute; requester notified in the system.","dept":"Warehouse","role":"Warehouse Supervisor","sys":"D365 — Transfer order / alerts","input":"Reviewed requirement","output":"Shortage notice","pillars":"Monitoring","refs":"POL-D11","fit":"Not covered","erpReq":"Line-level shortage reason and notification.","ricefw":"Extension","moscow":"Should","prev":"PA-06-S090","next":"PA-06-S110","evId":"EV-CPU-MGT-5.5","evQuote":"Reasons vary: product availability, vendor availability, market conditions and others","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S110', N'PA-06', 97, N'Warehouse', N'Retire', N'Non-system', N'{"id":"PA-06-S110","pa":"PA-06","phase":"2. Review & reserve","scor":"Deliver – Ship","stype":"Activity","asis":"Warehouse prints the MR, corrects the quantity and books it as an Issue Note; or the MR is cancelled and re-uploaded within the time frame, otherwise adjusted in a future order.","asisActor":"Warehouse; CPU / Store","asisSys":"MC printout; Issue Note","gapFlag":"Control Gap","gapDesc":"Order replaced instead of corrected; no audit trail of changes. (Root cause: outside the system)","change":"Retire","tobe":"Retired — replaced by S120 / S130 (one document, changed in place).","dept":"Warehouse","role":"Warehouse Supervisor","pillars":"Control","refs":"POL-D03","fit":"Non-system","moscow":"Must","prev":"PA-06-S100","next":"PA-06-S120","evId":"EV-WH-5.1; EV-OPS-2.4; EV-CPU-MGT-5.4","evQuote":"the specific MR is cancelled and a new MR is raised to match exactly what the warehouse has provided","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S120', N'PA-06', 98, N'Warehouse', N'New', N'Covered', N'{"id":"PA-06-S120","pa":"PA-06","phase":"2. Review & reserve","scor":"Deliver – Ship","stype":"Hand-off","asis":"— (MR is the only document)","change":"New","tobe":"Transfer order created from the approved requirement; the same document carries the order to receipt. [SLA: by the order cut-off (48-hour ordering, POL-D04) — proposed]","dept":"Warehouse","role":"Planner","sys":"D365 — Transfer order","input":"Reviewed requirement","output":"Transfer order","pillars":"Tracking & Traceability","refs":"POL-D03 | K-06-1","fit":"Covered","erpReq":"Requisition-to-transfer link.","ricefw":"Configuration","moscow":"Must","prev":"PA-06-S110","next":"PA-06-S130","evId":"From task list","taskId":"PA-06-T03","taskDesc":"Transfer-order creation - Transfer order is created","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S130', N'PA-06', 99, N'Warehouse', N'New', N'Not covered', N'{"id":"PA-06-S130","pa":"PA-06","phase":"2. Review & reserve","scor":"Deliver – Ship","stype":"Control check","asis":"Changes made by editing or re-uploading the MR at dispatch time.","asisActor":"CPU / Warehouse","asisSys":"MC","gapFlag":"Control Gap","gapDesc":"Changes not reasoned or approved. (Root cause: outside the system)","change":"New","tobe":"Changes to quantity are made on the same order with reason code, by the supplying team, before the order locks; after lock only by exception with approval.","dept":"Warehouse","role":"Warehouse Supervisor (maker); Warehouse Manager (approver after lock)","sys":"D365 — Transfer order","input":"Transfer order","output":"Amended transfer order","pillars":"Control","refs":"CTL-06-3 | POL-D04","fit":"Not covered","erpReq":"Amendment with reason code, change history and lock point.","ricefw":"Extension + Workflow","moscow":"Must","prev":"PA-06-S120","next":"PA-06-S140","evId":"EV-OPS-2.4","evQuote":"any plus or minus is handled from the CPU or warehouse side by EDITING the MR","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S140', N'PA-06', 100, N'Warehouse', N'New', N'Covered', N'{"id":"PA-06-S140","pa":"PA-06","phase":"2. Review & reserve","scor":"Deliver – Ship","stype":"Activity","asis":"— (FEFO by hand: older stock at the front)","change":"New","tobe":"Stock reserved against the transfer by batch, FEFO-guided.","dept":"Warehouse","role":"System / Planner","sys":"D365 — Reservation","input":"Transfer order","output":"Reserved stock","pillars":"Tracking & Traceability | Compliance & Food Safety","refs":"POL-D07","fit":"Covered","erpReq":"FEFO reservation by batch.","ricefw":"Configuration","moscow":"Must","prev":"PA-06-S130","next":"PA-06-S150","evId":"From task list","taskId":"PA-06-T04","taskDesc":"Stock reservation - Reserve stock by batch/FEFO against the transfer order","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S150', N'PA-06', 101, N'Warehouse', N'New', N'Covered', N'{"id":"PA-06-S150","pa":"PA-06","phase":"3. Pick & dispatch","scor":"Deliver – Ship","stype":"Hand-off","asis":"— (not described)","change":"New","tobe":"Warehouse releases the transfer to picking.","dept":"Warehouse","role":"Warehouse Supervisor","sys":"D365 — Warehouse management","input":"Reserved stock","output":"Pick work","pillars":"Process","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-06-S140","next":"PA-06-S160","evId":"From task list","taskId":"PA-06-T05","taskDesc":"Release to warehouse - Warehouse releases the transfer to picking","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S160', N'PA-06', 102, N'Warehouse', N'New', N'Covered', N'{"id":"PA-06-S160","pa":"PA-06","phase":"3. Pick & dispatch","scor":"Deliver – Ship","stype":"Activity","asis":"— (not described for warehouse picking)","change":"New","tobe":"Picker scans item, batch and quantity; user selects the batch with FEFO as guidance.","dept":"Warehouse","role":"Picker","sys":"D365 — Mobile app","input":"Pick work","output":"Picked stock","pillars":"Tracking & Traceability","refs":"POL-D07","fit":"Covered","erpReq":"Mobile picking with batch scan.","ricefw":"Configuration","moscow":"Must","prev":"PA-06-S150","next":"PA-06-S170","evId":"From task list","taskId":"PA-06-T06","taskDesc":"Picking - Picker scans item, batch and quantity","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S170', N'PA-06', 103, N'Warehouse', N'New', N'Covered', N'{"id":"PA-06-S170","pa":"PA-06","phase":"3. Pick & dispatch","scor":"Deliver – Ship","stype":"Control check","asis":"— (not described)","change":"New","tobe":"A checker other than the picker verifies picked quantity and batch. [SLA: before loading — proposed]","dept":"Warehouse","role":"Checker","sys":"D365 — Mobile app","input":"Picked stock","output":"Verified load","pillars":"Access & Segregation of Duties | Control","refs":"CTL-06-1 | POL-D05","fit":"Covered","erpReq":"Picker ≠ checker rule.","ricefw":"Configuration","moscow":"Must","prev":"PA-06-S160","next":"PA-06-S180","evId":"From task list","taskId":"PA-06-T07","taskDesc":"Dispatch verification - Checker verifies picked quantity","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S180', N'PA-06', 104, N'Quality Control', N'Keep', N'Partial', N'{"id":"PA-06-S180","pa":"PA-06","phase":"3. Pick & dispatch","scor":"Deliver – Ship","stype":"Control check","asis":"QC signs off warehouse dispatch and every truck before it leaves: hygiene and freezer temperature.","asisActor":"QC Officer","asisSys":"Manual sign-off","change":"Keep","tobe":"QC records the dispatch and truck sign-off (hygiene, product and truck temperature) on the shipment in the ERP before release; temperature loggers on frozen / chilled trucks recommended (Logistics). [SLA: before the truck leaves — proposed]","dept":"Quality Control","role":"QC Officer","sys":"D365 — Quality order on shipment","input":"Verified load","output":"QC dispatch release","pillars":"Compliance & Food Safety | Control","refs":"CTL-06-1 | POL-D05","fit":"Partial","erpReq":"Quality check on shipment; blocks dispatch until passed.","ricefw":"Customization","moscow":"Must","prev":"PA-06-S170","next":"PA-06-S185","evId":"EV-QC-8.1; EV-QL-QC01","evQuote":"before logistics leaves the facility there must be a QC sign-off (''sanction'')","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S185', N'PA-06', 105, N'Logistics', N'New', N'Partial', N'{"id":"PA-06-S185","pa":"PA-06","phase":"3. Pick & dispatch","scor":"Deliver – Ship","stype":"Control check","asis":"— (new step; no as-is activity reported)","change":"New","tobe":"Driver checks vehicle temperature and hygiene before loading and records the reading on the load. [SLA: before loading — proposed]","dept":"Logistics","role":"Driver","sys":"D365 — Load checklist (mobile)","input":"Route and load plan","output":"Vehicle pre-check record","pillars":"Compliance & Food Safety | Control","refs":"CTL-06-1","fit":"Partial","erpReq":"Confirm: mobile checklist on the load with temperature reading.","ricefw":"Configuration","moscow":"Should","prev":"PA-06-S180","next":"PA-06-S190","evId":"(Analyst proposal — confirm at docket review)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S190', N'PA-06', 106, N'Warehouse', N'New', N'Covered', N'{"id":"PA-06-S190","pa":"PA-06","phase":"3. Pick & dispatch","scor":"Deliver – Ship","stype":"Activity","asis":"— (not described)","change":"New","tobe":"Dispatcher confirms vehicle, driver and dispatch.","dept":"Warehouse","role":"Dispatcher","sys":"D365 — Shipment","input":"QC dispatch release","output":"Shipment","pillars":"Tracking & Traceability","refs":"K-06-2","fit":"Covered","erpReq":"Vehicle / driver fields and confirmation.","ricefw":"Customization","moscow":"Must","prev":"PA-06-S185","next":"PA-06-S200","evId":"From task list","taskId":"PA-06-T08","taskDesc":"Shipment - Dispatcher confirms vehicle and dispatch","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S200', N'PA-06', 107, N'Warehouse', N'New', N'Covered', N'{"id":"PA-06-S200","pa":"PA-06","phase":"3. Pick & dispatch","scor":"Deliver – Ship","stype":"Activity","asis":"— (no in-transit stock)","change":"New","tobe":"Stock moves to in-transit until the outlet receives it.","dept":"Warehouse","role":"System","sys":"D365 — Transfer shipment","input":"Shipment","output":"In-transit stock","pillars":"Tracking & Traceability","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-06-S190","next":"PA-06-S205","evId":"From task list","taskId":"PA-06-T09","taskDesc":"Shipment - Stock moves to in-transit status","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S205', N'PA-06', 108, N'Logistics', N'New', N'Partial', N'{"id":"PA-06-S205","pa":"PA-06","phase":"3. Pick & dispatch","scor":"Deliver – Ship","stype":"Control check","asis":"— (new step; no as-is activity reported)","change":"New","tobe":"Proof of delivery: on arrival the store confirms delivery digitally (time, product temperature, seal / crate count); late or warm deliveries flagged.","dept":"Logistics","role":"Driver; Store receiver","sys":"D365 — Mobile proof of delivery","input":"In-transit transfer","output":"Proof of delivery (RPT-06)","pillars":"Tracking & Traceability | Control","refs":"CTL-06-2 | K-06-2","fit":"Partial","erpReq":"Confirm: mobile proof of delivery with timestamp and temperature against the transfer.","ricefw":"Configuration","moscow":"Should","prev":"PA-06-S200","next":"PA-06-S210","evId":"(Analyst proposal — confirm at docket review)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S210', N'PA-06', 109, N'Store Operations', N'Retire', N'Non-system', N'{"id":"PA-06-S210","pa":"PA-06","phase":"4. Receipt","scor":"Deliver – Ship","stype":"Activity","asis":"Store prints the finalised MR and next day cross-checks it against items received; the MR is closed in MC so receipt cannot be confirmed.","asisActor":"Store Manager","asisSys":"MR printout","gapFlag":"Control Gap","gapDesc":"System records issue, not receipt. (Root cause: outside the system)","change":"Retire","tobe":"Retired — replaced by S240.","dept":"Store Operations","role":"Store Manager","pillars":"Control","fit":"Non-system","moscow":"Must","prev":"PA-06-S205","next":"PA-06-S220","evId":"EV-OPS-4.1","evQuote":"once the store places the MR it is CLOSED and NOT EDITABLE","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S220', N'PA-06', 110, N'Store Operations', N'Retire', N'Non-system', N'{"id":"PA-06-S220","pa":"PA-06","phase":"4. Receipt","scor":"Deliver – Ship","stype":"Exception","asis":"Defective or short items received at the store reported by WhatsApp, email and phone and matched manually with supply chain and warehouse.","asisActor":"Store Manager","asisSys":"WhatsApp; email; phone","gapFlag":"Control Gap","gapDesc":"No system route for receipt defects. (Root cause: outside the system)","change":"Retire","tobe":"Retired — replaced by S250 / S260.","dept":"Store Operations","role":"Store Manager","pillars":"Control","refs":"POL-D11","fit":"Non-system","moscow":"Must","prev":"PA-06-S210","next":"PA-06-S230","evId":"EV-OPS-4.2","evQuote":"Stores currently use WhatsApp, email and phone calls","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S230', N'PA-06', 111, N'Store Operations', N'New', N'Covered', N'{"id":"PA-06-S230","pa":"PA-06","phase":"4. Receipt","scor":"Deliver – Ship","stype":"Activity","asis":"— (see S210)","change":"New","tobe":"Store receiver records the actual quantity received on the same transfer for 100% of receipts. [SLA: On delivery]","dept":"Store Operations","role":"Store Manager / Store Chef","sys":"D365 — Transfer receipt (mobile)","input":"In-transit stock","output":"Outlet receipt","pillars":"Control | Tracking & Traceability","refs":"POL-D06","fit":"Covered","erpReq":"Mobile receipt against transfer.","ricefw":"Configuration","moscow":"Must","prev":"PA-06-S220","next":"PA-06-S240","evId":"EV-OPS-V07","evQuote":"(d) 4.1 — one MR from store order to store receipt","taskId":"PA-06-T10","taskDesc":"Outlet receiving - Outlet receiver records actual quantity received","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S240', N'PA-06', 112, N'Store Operations', N'New', N'Not covered', N'{"id":"PA-06-S240","pa":"PA-06","phase":"4. Receipt","scor":"Deliver – Ship","stype":"Exception","asis":"— (see S220)","change":"New","tobe":"Store records short, damaged or wrong items with reason and photo on the receipt; routed to warehouse and, for quality, to QC. [SLA: at receipt, before the transfer is closed — proposed]","dept":"Store Operations","role":"Store Manager / Store Chef","sys":"D365 — Receipt variance","input":"Outlet receipt","output":"Receipt variance","pillars":"Control | Compliance & Food Safety","refs":"CTL-06-2 | POL-D11 | K-06-3","fit":"Not covered","erpReq":"Variance reason codes and photo on transfer receipt; routing.","ricefw":"Extension + Workflow","moscow":"Must","prev":"PA-06-S230","next":"PA-06-S250","evId":"Recommended","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S250', N'PA-06', 113, N'Warehouse', N'New', N'Covered', N'{"id":"PA-06-S250","pa":"PA-06","phase":"4. Receipt","scor":"Deliver – Ship","stype":"Approval","asis":"— (manual coordination)","change":"New","tobe":"Warehouse supervisor investigates and resolves differences on the transfer; material differences reviewed by Cost Control. [SLA: within 24 hours — proposed]","dept":"Warehouse","role":"Warehouse Supervisor; Cost Controller (material differences)","sys":"D365 — Transfer difference","input":"Receipt variance","output":"Resolved difference","pillars":"Control | Finance","refs":"CTL-06-2 | POL-D05","fit":"Covered","erpReq":"Approval limit for write-off of transfer differences.","ricefw":"Workflow","moscow":"Must","prev":"PA-06-S240","next":"PA-06-S260","evId":"From task list","taskId":"PA-06-T11","taskDesc":"Difference management - Differences are investigated and resolved","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S260', N'PA-06', 114, N'Store Operations', N'New', N'Not covered', N'{"id":"PA-06-S260","pa":"PA-06","phase":"4. Receipt","scor":"Deliver – Ship","stype":"Report","asis":"— (no report)","change":"New","tobe":"Daily report of open transfers, in-transit age and receipt differences by store and item. [SLA: daily by 10:00 — proposed] Stock availability includes in-transit transfers and received-not-posted delivery notes, so planners no longer correct SOH manually (as in Swish SPS).","dept":"Store Operations","role":"Operations Manager; Warehouse Manager","sys":"D365 — Report","input":"Transfers; receipts","output":"Open transfer & difference report","pillars":"Monitoring | Data & Reporting","refs":"CTL-06-2","fit":"Not covered","erpReq":"Open transfer and difference report.","ricefw":"Report","moscow":"Should","prev":"PA-06-S250","next":"PA-06-S270","evId":"Recommended; EV-SPS-03","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S270', N'PA-06', 115, N'Store Operations', N'New', N'Covered', N'{"id":"PA-06-S270","pa":"PA-06","phase":"5. Store returns","scor":"Deliver – Ship","stype":"Activity","asis":"— (new step; no as-is activity reported)","change":"New","tobe":"Store raises a return request in the ERP for unused, wrong, damaged or near-expiry stock (or on recall), with reason code; approved by Area Manager (Costing where the value exceeds the agreed level, POL-D22).","dept":"Store Operations","role":"Store Manager; Approver: Area Manager","sys":"D365 — Return transfer order","input":"Store stock","output":"Approved return request","pillars":"Process | Control","refs":"POL-D22","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-06-S260","next":"PA-06-S280","evId":"(Analyst proposal — confirm at docket review)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S280', N'PA-06', 116, N'Warehouse', N'New', N'Covered', N'{"id":"PA-06-S280","pa":"PA-06","phase":"5. Store returns","scor":"Deliver – Ship","stype":"Hand-off","asis":"— (new step; no as-is activity reported)","change":"New","tobe":"Return carried on the return trip (with crates and containers) as a return transfer; warehouse / CPU receives it and QC decides: restock, quarantine or write-off.","dept":"Warehouse","role":"Warehouse receiver; QC Officer","sys":"D365 — Return transfer receipt; quality order","input":"Approved return request","output":"Return receipt with QC decision","pillars":"Compliance & Food Safety | Tracking & Traceability","refs":"CTL-R04","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-06-S270","next":"PA-06-S290","evId":"(Analyst proposal — confirm at docket review)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-06-S290', N'PA-06', 117, N'Cost Control', N'New', N'Covered', N'{"id":"PA-06-S290","pa":"PA-06","phase":"5. Store returns","scor":"Deliver – Ship","stype":"Activity","asis":"— (new step; no as-is activity reported)","change":"New","tobe":"Restocked value credited to the store; items not fit for use written off with reason through PA-10.","dept":"Cost Control","role":"Costing Officer","sys":"D365 — Inventory / wastage journal","input":"Return receipt","output":"Return settlement","pillars":"Finance","refs":"K-10-1","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-06-S280","next":"— (end)","evId":"(Analyst proposal — confirm at docket review)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-07-S010', N'PA-07', 118, N'Store Operations', N'New', N'Covered', N'{"id":"PA-07-S010","pa":"PA-07","phase":"1. Request","scor":"Deliver – Ship","stype":"Exception","asis":"— (store-to-store transfers not described in the interviews)","change":"New","tobe":"Requesting outlet records the shortage in an outlet transfer request in the ERP; Costing is notified automatically (mandatory). The request is lodged before the physical move; in an emergency move it must be lodged within 2 hours of the move.","dept":"Store Operations","role":"Store Manager (requesting)","sys":"D365 — Transfer order / Outlet Transfer Request","input":"Shortage","output":"Outlet transfer request","pillars":"Tracking & Traceability","refs":"POL-D26","fit":"Covered","ricefw":"Customization","moscow":"Should","prev":"— (start)","next":"PA-07-S020","evId":"EV-QL-SO01","taskId":"PA-07-T01","taskDesc":"Emergency request - Requesting outlet identifies the shortage","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-07-S020', N'PA-07', 119, N'Store Operations', N'New', N'Covered', N'{"id":"PA-07-S020","pa":"PA-07","phase":"1. Request","scor":"Deliver – Ship","stype":"Activity","asis":"— (store-to-store transfers not described in the interviews)","change":"New","tobe":"Supplying outlet reviews the request and confirms availability.","dept":"Store Operations","role":"Store Manager (supplying)","sys":"D365 — Transfer order / Outlet Transfer Request","input":"Outlet transfer request (PA-07-S010)","output":"Availability confirmation","pillars":"Tracking & Traceability","fit":"Covered","ricefw":"Customization","moscow":"Should","prev":"PA-07-S010","next":"PA-07-S030","evId":"From task list","taskId":"PA-07-T02","taskDesc":"Stock-availability confirmation - Supplying outlet confirms availability","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-07-S030', N'PA-07', 120, N'Cost Control', N'New', N'Covered', N'{"id":"PA-07-S030","pa":"PA-07","phase":"1. Request","scor":"Deliver – Ship","stype":"Approval","asis":"— (store-to-store transfers not described in the interviews)","change":"New","tobe":"Costing approves every store-to-store transfer in the ERP, irrespective of value (no lower limit — even KWD 1), within 4 working hours of lodging and no later than the same business day; transfers not approved by the next morning are escalated to the Costing Head.","dept":"Cost Control","role":"Costing (approver, every transfer)","sys":"D365 — Transfer order / Outlet Transfer Request","input":"Availability confirmation (PA-07-S020)","output":"Approved transfer request","pillars":"Control","refs":"CTL-07-1 | POL-D05 | POL-D26 | K-07-1","fit":"Covered","ricefw":"Customization","moscow":"Should","prev":"PA-07-S020","next":"PA-07-S040","evId":"EV-QL-SO01","taskId":"PA-07-T03","taskDesc":"Operations approval - Area Manager approves the movement","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-07-S040', N'PA-07', 121, N'Store Operations', N'New', N'Covered', N'{"id":"PA-07-S040","pa":"PA-07","phase":"2. Move","scor":"Deliver – Ship","stype":"Hand-off","asis":"— (store-to-store transfers not described in the interviews)","change":"New","tobe":"Transfer order created from the approved request.","dept":"Store Operations","role":"System","sys":"D365 — Transfer order","input":"Approved transfer request (PA-07-S030)","output":"Store-to-store transfer order (RPT-07)","pillars":"Tracking & Traceability","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-07-S030","next":"PA-07-S050","evId":"From task list","taskId":"PA-07-T04","taskDesc":"Transfer creation - Transfer order is created","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-07-S050', N'PA-07', 122, N'Store Operations', N'New', N'Covered', N'{"id":"PA-07-S050","pa":"PA-07","phase":"2. Move","scor":"Deliver – Ship","stype":"Activity","asis":"— (store-to-store transfers not described in the interviews)","change":"New","tobe":"Supplying outlet records the dispatch. Transfer status visible to both outlets (requested, dispatched, in transit, received) with transport mode recorded (warehouse truck, area coach, logistics, taxi).","dept":"Store Operations","role":"Store Manager (supplying)","sys":"D365 — Transfer order","input":"Store-to-store transfer order (PA-07-S040)","output":"Dispatched transfer","pillars":"Tracking & Traceability","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-07-S040","next":"PA-07-S060","evId":"From task list; EV-FD-121; EV-FD-156","taskId":"PA-07-T05","taskDesc":"Dispatch - Supplying outlet records dispatch","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-07-S060', N'PA-07', 123, N'Store Operations', N'New', N'Covered', N'{"id":"PA-07-S060","pa":"PA-07","phase":"2. Move","scor":"Deliver – Ship","stype":"Activity","asis":"— (store-to-store transfers not described in the interviews)","change":"New","tobe":"Receiving outlet confirms receipt of the actual quantity. Receiving outlet records quality and temperature on receipt; late or poor-quality transfers flagged to the Area Manager. [SLA: same day as dispatch — proposed]","dept":"Store Operations","role":"Store Manager (receiving)","sys":"D365 — Transfer order","input":"Dispatched transfer (PA-07-S050)","output":"Confirmed transfer receipt","pillars":"Tracking & Traceability","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-07-S050","next":"PA-07-S070","evId":"From task list; EV-FD-157","taskId":"PA-07-T06","taskDesc":"Receipt - Receiving outlet confirms receipt","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-07-S070', N'PA-07', 124, N'Store Operations', N'New', N'Covered', N'{"id":"PA-07-S070","pa":"PA-07","phase":"2. Move","scor":"Deliver – Ship","stype":"Exception","asis":"— (store-to-store transfers not described in the interviews)","change":"New","tobe":"Transport or quantity issue recorded and resolved on the transfer.","dept":"Store Operations","role":"Store Manager; Area Manager","sys":"D365 — Transfer order","input":"Confirmed transfer receipt (PA-07-S060)","output":"Resolved transfer difference","pillars":"Tracking & Traceability","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-07-S060","next":"— (end)","evId":"From task list","taskId":"PA-07-T07","taskDesc":"Difference resolution - Transport or quantity issue is recorded","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-08-S010', N'PA-08', 125, N'Purchase', N'Modify', N'Partial', N'{"id":"PA-08-S010","pa":"PA-08","phase":"1. Setup","scor":"Source – Receive","stype":"Setup","asis":"Direct-to-store items are listed, handled and managed by the Purchase department, which informs the vendor; items such as fries still come through the warehouse.","asisActor":"Purchase","asisSys":"List (offline)","change":"Modify","tobe":"Direct-delivery items and suppliers are selected and approved centrally — proposed by Purchase and approved by Costing — and flagged per store in the ERP; stores have no role in selecting or deciding direct items. Items such as fries may move to direct supply where it supports operations; low-volume stores take bulk-discount items via the warehouse.","dept":"Purchase","role":"Purchase (proposes); Costing (approves) — stores excluded","sys":"D365 — Item / vendor / store flag","input":"Trigger: start of process","output":"Approved direct-delivery list","pillars":"Master Data | Process","refs":"POL-D26","fit":"Partial","erpReq":"Direct-delivery flag per item / vendor / store.","ricefw":"Configuration","moscow":"Must","prev":"— (start)","next":"PA-08-S020","evId":"EV-OPS-V03; EV-OPS-3.1; EV-QL-SO01","evQuote":"Those items are listed, handled and managed by the purchase department, which informs the vendor","taskId":"PA-08-T01","taskDesc":"Direct-delivery approval - Approve items and suppliers eligible for direct delivery to outlets","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-08-S020', N'PA-08', 126, N'Purchase', N'Modify', N'Covered', N'{"id":"PA-08-S020","pa":"PA-08","phase":"1. Setup","scor":"Source – Receive","stype":"Setup","asis":"An open PO exists in MC, so whatever is ordered is delivered directly by the vendor.","asisActor":"Purchase","asisSys":"MC open PO","change":"Modify","tobe":"Procurement creates the PO / purchase agreement for the outlet warehouse with rates and validity.","dept":"Purchase","role":"Buyer","sys":"D365 — Purchase agreement / PO","input":"Approved direct-delivery list","output":"Outlet PO / agreement","pillars":"Finance | Control","refs":"POL-D09","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-08-S010","next":"PA-08-S030","evId":"EV-OPS-3.1","evQuote":"An OPEN PO exists in MC, so whatever is ordered is delivered directly by the vendor","taskId":"PA-08-T02","taskDesc":"PO creation - Procurement creates PO for the outlet warehouse","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-08-S030', N'PA-08', 127, N'Store Operations', N'Retire', N'Non-system', N'{"id":"PA-08-S030","pa":"PA-08","phase":"2. Order","scor":"Source – Receive","stype":"Activity","asis":"Each store person orders directly with the vendor in a WhatsApp group; no MR.","asisActor":"Store staff","asisSys":"WhatsApp group","gapFlag":"Control Gap","gapDesc":"Store orders exist only in chat. (Root cause: outside the system)","change":"Retire","tobe":"Retired — replaced by S040.","dept":"Store Operations","role":"Store Manager","pillars":"Control","refs":"POL-D11","fit":"Non-system","moscow":"Must","prev":"PA-08-S020","next":"PA-08-S040","evId":"EV-OPS-3.1; EV-OPS-V03","evQuote":"There is a WHATSAPP GROUP in which each store person orders directly with the vendor"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-08-S040', N'PA-08', 128, N'Store Operations', N'New', N'Not covered', N'{"id":"PA-08-S040","pa":"PA-08","phase":"2. Order","scor":"Source – Receive","stype":"Activity","asis":"— (see S030)","change":"New","tobe":"Store raises a release order against the outlet PO / agreement in the ERP; vendor notified from the system; any WhatsApp coordination has its outcome recorded.","dept":"Store Operations","role":"Store Manager","sys":"D365 — Release order","input":"Outlet PO / agreement","output":"Release order","pillars":"Control | Process","refs":"POL-D11 | POL-D04","fit":"Not covered","erpReq":"Store release order from agreement; vendor notification.","ricefw":"Configuration + Interface","moscow":"Must","prev":"PA-08-S030","next":"PA-08-S050","evId":"EV-OPS-3.1 (Recommended)"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-08-S050', N'PA-08', 129, N'Store Operations', N'New', N'Covered', N'{"id":"PA-08-S050","pa":"PA-08","phase":"3. Receive","scor":"Source – Receive","stype":"Activity","asis":"— (vendor delivers to the store)","change":"New","tobe":"Supplier delivers to the outlet against the PO / release order.","dept":"Store Operations","role":"Vendor","sys":"D365 — PO","input":"Release order","output":"Delivery at store","pillars":"Process","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-08-S040","next":"PA-08-S060","evId":"From task list","taskId":"PA-08-T03","taskDesc":"Supplier delivery - Supplier delivers to the outlet against the purchase order","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-08-S060', N'PA-08', 130, N'Store Operations', N'Modify', N'Covered', N'{"id":"PA-08-S060","pa":"PA-08","phase":"3. Receive","scor":"Source – Receive","stype":"Control check","asis":"Store receives the items and enters them in MC with the supporting GRN and invoice, without any MR; the invoice number is entered on the GRN itself.","asisActor":"Store staff","asisSys":"MC direct GRN","gapFlag":"Gap","gapDesc":"Receipt not linked to an order. (Root cause: outside the system)","change":"Modify","tobe":"Outlet receiver checks the supplier documents against the release order.","dept":"Store Operations","role":"Store Chef / Store Manager","sys":"D365 — Product receipt","input":"Delivery at store","output":"Documents checked","pillars":"Control","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-08-S050","next":"PA-08-S070","evId":"EV-OPS-3.1","evQuote":"the store enters the invoice number on the GRN itself and enters the items","taskId":"PA-08-T04","taskDesc":"Outlet receiving - Outlet receiver checks supplier documents","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-08-S070', N'PA-08', 131, N'Store Operations', N'New', N'Covered', N'{"id":"PA-08-S070","pa":"PA-08","phase":"3. Receive","scor":"Source – Receive","stype":"Control check","asis":"— (expiry not recorded at store)","change":"New","tobe":"Outlet records actual quantity and expiry; fresh / daily items judged by physical condition.","dept":"Store Operations","role":"Store Chef","sys":"D365 — Product receipt (mobile)","input":"Documents checked","output":"Accepted quantity","pillars":"Compliance & Food Safety | Tracking & Traceability","refs":"POL-D07 | POL-D08","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-08-S060","next":"PA-08-S080","evId":"From task list","taskId":"PA-08-T05","taskDesc":"Quality and expiry check - Outlet records actual quantity and expiry","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-08-S080', N'PA-08', 132, N'Store Operations', N'New', N'Covered', N'{"id":"PA-08-S080","pa":"PA-08","phase":"3. Receive","scor":"Source – Receive","stype":"Control check","asis":"— (same store staff order and receive)","change":"New","tobe":"Authorised user posts the receipt; the person who raised the release order cannot post the receipt alone (Store Chef receives, Store Manager confirms). [SLA: same day as delivery — proposed]","dept":"Store Operations","role":"Store Chef (receives); Store Manager (confirms)","sys":"D365 — Product receipt; security roles","input":"Accepted quantity","output":"Posted receipt","pillars":"Access & Segregation of Duties","refs":"CTL-08-1 | POL-D05 | K-08-1","fit":"Covered","erpReq":"Maker-checker on store receipts.","ricefw":"Configuration","moscow":"Must","prev":"PA-08-S070","next":"PA-08-S090","evId":"From task list","taskId":"PA-08-T06","taskDesc":"Product receipt - Authorized user posts the receipt","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-08-S090', N'PA-08', 133, N'Store Operations', N'Retire', N'Non-system', N'{"id":"PA-08-S090","pa":"PA-08","phase":"4. Discrepancy","scor":"Source – Receive","stype":"Exception","asis":"Shortage or damage noted on the invoice or delivery note and signed by the vendor''s delivery person; the store still enters the full invoiced quantity; pending replacement tracked in a store logbook.","asisActor":"Store staff; vendor driver","asisSys":"Annotated delivery note; logbook","gapFlag":"Control Gap","gapDesc":"Stock overstated; pending replacement outside the system. (Root cause: outside the system)","change":"Retire","tobe":"Retired — replaced by S100 / S110.","dept":"Store Operations","role":"Store Manager","pillars":"Control","fit":"Non-system","moscow":"Must","prev":"PA-08-S080","next":"PA-08-S100","evId":"EV-OPS-3.3; EV-OPS-V06","evQuote":"the difference is noted on the invoice or delivery note, and the vendor''s delivery person accepts and signs it"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-08-S100', N'PA-08', 134, N'Store Operations', N'New', N'Partial', N'{"id":"PA-08-S100","pa":"PA-08","phase":"4. Discrepancy","scor":"Source – Receive","stype":"Exception","asis":"— (see S090)","change":"New","tobe":"Outlet reports rejected or missing stock on the receipt; the balance is held as pending from the vendor until replaced or credited. [SLA: at receipt — proposed]","dept":"Store Operations","role":"Store Manager","sys":"D365 — Receipt variance","input":"Posted receipt","output":"Pending-vendor balance","pillars":"Control | Finance","refs":"POL-R02","fit":"Partial","erpReq":"Pending-replacement balance per vendor and store.","ricefw":"Extension","moscow":"Must","prev":"PA-08-S090","next":"PA-08-S110","evId":"From task list","taskId":"PA-08-T07","taskDesc":"Discrepancy reporting - Outlet reports rejected or missing stock","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-08-S110', N'PA-08', 135, N'Purchase', N'New', N'Covered', N'{"id":"PA-08-S110","pa":"PA-08","phase":"4. Discrepancy","scor":"Source – Receive","stype":"Exception","asis":"— (resolved by phone / WhatsApp)","change":"New","tobe":"Procurement resolves supplier differences by credit / debit note or tracked replacement.","dept":"Purchase","role":"Buyer","sys":"D365 — Credit note / replacement","input":"Pending-vendor balance","output":"Settled difference","pillars":"Finance","refs":"POL-R02 | POL-D09","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-08-S100","next":"PA-08-S120","evId":"From task list","taskId":"PA-08-T08","taskDesc":"Discrepancy reporting - Procurement resolves supplier differences","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-08-S120', N'PA-08', 136, N'Finance', N'Retire', N'Non-system', N'{"id":"PA-08-S120","pa":"PA-08","phase":"5. Invoice","scor":"Source – Receive","stype":"Activity","asis":"GRN and invoice are photographed and attached in the finance domain, where Finance tracks direct supplies in a separate system; no hold for pending shortages.","asisActor":"Store staff; Finance (AP / COGS)","asisSys":"Finance direct-supply tracker (photos)","gapFlag":"Gap","gapDesc":"Invoice matching outside MC; no hold for pending shortages. (Root cause: outside the system)","change":"Retire","tobe":"Retired — replaced by S130.","dept":"Finance","role":"AP Accountant","pillars":"Finance","fit":"Non-system","moscow":"Must","prev":"PA-08-S110","next":"PA-08-S130","evId":"EV-OPS-3.1; EV-QL-D07","evQuote":"Finance has a separate tracking system in which these invoices are received, accumulated and sent to the finance department for accounting"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-08-S130', N'PA-08', 137, N'Finance', N'New', N'Not covered', N'{"id":"PA-08-S130","pa":"PA-08","phase":"5. Invoice","scor":"Source – Receive","stype":"Control check","asis":"— (see S120)","change":"New","tobe":"Invoice matched to PO and receipt in the ERP (see PA-25); documents attached to the receipt; pending shortages hold the invoice line.","dept":"Finance","role":"AP Accountant","sys":"D365 — Three-way match","input":"Posted receipt; pending-vendor balance","output":"Matched invoice","pillars":"Finance | Control","refs":"CTL-08-2","fit":"Not covered","erpReq":"Three-way match for store receipts; attachment; invoice hold.","ricefw":"Configuration","moscow":"Must","prev":"PA-08-S120","next":"— (end)","evId":"EV-OPS-3.1 (Recommended)"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-09-S010', N'PA-09', 138, N'Cost Control', N'New', N'Partial', N'{"id":"PA-09-S010","pa":"PA-09","phase":"1. Plan","scor":"Enable – Manage inventory","stype":"Setup","asis":"— (no item classification for counting)","change":"New","tobe":"Items classified by ABC value and risk (e.g. high-value proteins) to set count frequency.","dept":"Cost Control","role":"Inventory Controller","sys":"D365 — ABC classification","input":"Trigger: start of process","output":"Count tiers","pillars":"Monitoring | Master Data","fit":"Partial","erpReq":"ABC / risk tiering drives count frequency.","ricefw":"Configuration","moscow":"Should","prev":"— (start)","next":"PA-09-S020","evId":"From task list","taskId":"PA-09-T11","taskDesc":"ABC/risk-based count-frequency tiering - Classify items by ABC/risk and set the count frequency","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-09-S020', N'PA-09', 139, N'Cost Control', N'Modify', N'Covered', N'{"id":"PA-09-S020","pa":"PA-09","phase":"1. Plan","scor":"Enable – Manage inventory","stype":"Setup","asis":"Stores count main food items daily and record closing stock in Excel; this is not entered as an everyday closing stock in MC.","asisActor":"Store Manager","asisSys":"Excel","gapFlag":"Control Gap","gapDesc":"Daily counts outside the system. (Root cause: outside the system)","change":"Modify","tobe":"Inventory Controller creates the count plan per site: main items daily at stores, all items monthly, warehouse and CPU per tier.","dept":"Cost Control","role":"Inventory Controller","sys":"D365 — Counting","input":"Count tiers","output":"Count plan","pillars":"Monitoring | Control","refs":"POL-D06","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-09-S010","next":"PA-09-S030","evId":"EV-OPS-5.1","evQuote":"This is NOT entered as an everyday closing stock in MC","taskId":"PA-09-T01","taskDesc":"Count planning - Inventory Controller creates the count plan","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-09-S030', N'PA-09', 140, N'Cost Control', N'New', N'Partial', N'{"id":"PA-09-S030","pa":"PA-09","phase":"1. Plan","scor":"Enable – Manage inventory","stype":"Setup","asis":"— (warehouse and CPU count cycle not described)","change":"New","tobe":"Counts scheduled by location and frequency, generated automatically from the plan. Count sheets list only active articles at the site (stopped / unused articles excluded) with article number and counting UOM.","dept":"Cost Control","role":"Inventory Controller","sys":"D365 — Cycle count schedule","input":"Count plan","output":"Count schedule","pillars":"Monitoring","fit":"Partial","erpReq":"Cycle count schedule by location and frequency.","ricefw":"Configuration","moscow":"Must","prev":"PA-09-S020","next":"PA-09-S040","evId":"From task list; EV-FD-141; EV-FD-144; EV-FD-165","taskId":"PA-09-T02","taskDesc":"Count scheduling - Schedule counts by location and frequency","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-09-S040', N'PA-09', 141, N'Store Operations', N'Retire', N'Non-system', N'{"id":"PA-09-S040","pa":"PA-09","phase":"2. Count","scor":"Enable – Manage inventory","stype":"Activity","asis":"Stores count the main food items daily and record the closing stock in Excel.","asisActor":"Store Manager","asisSys":"Excel","gapFlag":"Gap","gapDesc":"Count outside the system. (Root cause: outside the system)","change":"Retire","tobe":"Retired — replaced by S060 / S070.","dept":"Store Operations","role":"Store Manager","pillars":"Data & Reporting","fit":"Non-system","moscow":"Must","prev":"PA-09-S030","next":"PA-09-S050","evId":"EV-OPS-5.1","evQuote":"stores count the main food items and record the closing stock in Excel"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-09-S050', N'PA-09', 142, N'Store Operations', N'Retire', N'Non-system', N'{"id":"PA-09-S050","pa":"PA-09","phase":"2. Count","scor":"Enable – Manage inventory","stype":"Activity","asis":"Stores enter closing stock for all items in MC at month end when Costing opens it.","asisActor":"Store Manager; Costing","asisSys":"MC (monthly)","gapFlag":"Gap","gapDesc":"System stock correct only once a month.","change":"Retire","tobe":"Retired — counts entered in the ERP on schedule (S060).","dept":"Store Operations","role":"Store Manager","pillars":"Data & Reporting","fit":"Non-system","moscow":"Must","prev":"PA-09-S040","next":"PA-09-S060","evId":"EV-CC-6.1; EV-OPS-5.1","evQuote":"Stores enter closing stock for all items in MC at month end when Costing opens it"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-09-S060', N'PA-09', 143, N'Store Operations', N'New', N'Covered', N'{"id":"PA-09-S060","pa":"PA-09","phase":"2. Count","scor":"Enable – Manage inventory","stype":"Activity","asis":"— (see S040, S050)","change":"New","tobe":"Warehouse, CPU or outlet staff perform the physical count on schedule. [SLA: main items daily before trading; all items at month end (POL-D06) — proposed]","dept":"Store Operations","role":"Store / Warehouse / CPU staff","sys":"D365 — Counting journal (mobile)","input":"Count schedule","output":"Physical count","pillars":"Control","refs":"POL-D06","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-09-S050","next":"PA-09-S070","evId":"From task list","taskId":"PA-09-T03","taskDesc":"Blind physical count - Warehouse or outlet staff perform the physical count","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-09-S070', N'PA-09', 144, N'Store Operations', N'New', N'Covered', N'{"id":"PA-09-S070","pa":"PA-09","phase":"2. Count","scor":"Enable – Manage inventory","stype":"Control check","asis":"— (counter sees yesterday''s figures)","change":"New","tobe":"Counter enters the physical quantity without seeing the expected quantity (blind count) where practical.","dept":"Store Operations","role":"Store / Warehouse / CPU staff","sys":"D365 — Blind count","input":"Physical count","output":"Count entry","pillars":"Control","refs":"CTL-09-1","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-09-S060","next":"PA-09-S080","evId":"From task list","taskId":"PA-09-T04","taskDesc":"Blind physical count - Counter enters physical quantity without seeing expected quantity where practical","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-09-S080', N'PA-09', 145, N'Cost Control', N'New', N'Covered', N'{"id":"PA-09-S080","pa":"PA-09","phase":"3. Resolve","scor":"Enable – Manage inventory","stype":"Activity","asis":"— (variance worked out by hand)","change":"New","tobe":"System calculates the variance against book stock (POS-driven usage, see PA-17).","dept":"Cost Control","role":"System","sys":"D365 — Counting","input":"Count entry","output":"Count variance (RPT-09)","pillars":"Data & Reporting","refs":"K-09-1","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-09-S070","next":"PA-09-S090","evId":"From task list","taskId":"PA-09-T05","taskDesc":"System comparison - System calculates the variance","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-09-S090', N'PA-09', 146, N'Cost Control', N'New', N'Partial', N'{"id":"PA-09-S090","pa":"PA-09","phase":"3. Resolve","scor":"Enable – Manage inventory","stype":"Control check","asis":"— (no recount)","change":"New","tobe":"Variances above the agreed threshold are recounted by a different employee. [SLA: within 24 hours of the count — proposed]","dept":"Cost Control","role":"Independent counter","sys":"D365 — Recount step","input":"Count variance","output":"Recount","pillars":"Control | Access & Segregation of Duties","refs":"CTL-09-1 | POL-D05","fit":"Partial","erpReq":"Recount assigned to another user above threshold.","ricefw":"Customization","moscow":"Must","prev":"PA-09-S080","next":"PA-09-S100","evId":"From task list","taskId":"PA-09-T06","taskDesc":"Recount - Independent employee performs a recount","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-09-S100', N'PA-09', 147, N'Store Operations', N'New', N'Partial', N'{"id":"PA-09-S100","pa":"PA-09","phase":"3. Resolve","scor":"Enable – Manage inventory","stype":"Activity","asis":"— (no reason recorded)","change":"New","tobe":"Supervisor selects a mandatory reason for each count difference before adjustment.","dept":"Store Operations","role":"Store / Warehouse Supervisor","sys":"D365 — Reason codes","input":"Recount","output":"Reasoned variance","pillars":"Control","refs":"CTL-09-2","fit":"Partial","erpReq":"Mandatory variance reason.","ricefw":"Customization","moscow":"Must","prev":"PA-09-S090","next":"PA-09-S110","evId":"From task list","taskId":"PA-09-T07","taskDesc":"Variance investigation - Supervisor assigns a variance reason","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-09-S110', N'PA-09', 148, N'Cost Control', N'New', N'Covered', N'{"id":"PA-09-S110","pa":"PA-09","phase":"3. Resolve","scor":"Enable – Manage inventory","stype":"Approval","asis":"— (who approves adjustments not described)","change":"New","tobe":"Count differences within the agreed level (AM-02) are approved by the supervisor; above the level they are approved by Costing. Any count revised after a store''s explanation (before freeze) is a recorded recount with reason and approver, not an overwrite.","dept":"Cost Control","role":"Supervisor (within AM-02); Costing (above level)","sys":"D365 — Workflow","input":"Reasoned variance","output":"Approved adjustment","pillars":"Control | Finance","refs":"POL-D22","fit":"Covered","erpReq":"Approval limits by value.","ricefw":"Workflow","moscow":"Must","prev":"PA-09-S100","next":"PA-09-S120","evId":"EV-QL-AM01; EV-FD-195","taskId":"PA-09-T08","taskDesc":"Approval - Cost Control or Finance approves material differences","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-09-S120', N'PA-09', 149, N'Cost Control', N'New', N'Covered', N'{"id":"PA-09-S120","pa":"PA-09","phase":"3. Resolve","scor":"Enable – Manage inventory","stype":"Activity","asis":"— (adjustment by month-end stock entry)","change":"New","tobe":"Authorised user posts the approved adjustment. [SLA: within 2 working days of the count — proposed]","dept":"Cost Control","role":"Inventory Controller","sys":"D365 — Counting journal","input":"Approved adjustment","output":"Posted adjustment","pillars":"Finance","refs":"CTL-09-2 | K-09-2","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-09-S110","next":"PA-09-S130","evId":"From task list","taskId":"PA-09-T09","taskDesc":"Posting - Authorized user posts the adjustment","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-09-S130', N'PA-09', 150, N'Cost Control', N'New', N'Covered', N'{"id":"PA-09-S130","pa":"PA-09","phase":"3. Resolve","scor":"Enable – Manage inventory","stype":"Report","asis":"— (not described)","change":"New","tobe":"Repeated variances by item and site investigated; corrective actions assigned.","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Variance history","input":"Posted adjustments","output":"Root-cause actions","pillars":"Monitoring","fit":"Covered","ricefw":"Report","moscow":"Should","prev":"PA-09-S120","next":"— (end)","evId":"From task list","taskId":"PA-09-T10","taskDesc":"Root-cause action - Repeated variances are investigated","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-10-S010', N'PA-10', 151, N'Store Operations', N'Modify', N'Covered', N'{"id":"PA-10-S010","pa":"PA-10","phase":"1. Identify & record","scor":"Enable – Manage inventory","stype":"Activity","asis":"After operation, any leftover not usable next day is not counted as closing stock; it is marked, weighed and written in a manual wastage report.","asisActor":"Store staff","asisSys":"Manual wastage report","gapFlag":"Gap","gapDesc":"Recorded on paper first. (Root cause: outside the system)","change":"Modify","tobe":"Outlet, warehouse or CPU employee identifies the loss and records it in the ERP (mobile) at the operation cut-off. [SLA: same shift as the loss — proposed]","dept":"Store Operations","role":"Store / Warehouse / CPU employee","sys":"D365 — Wastage journal (mobile)","input":"Closing check","output":"Loss identified","pillars":"Finance | Data & Reporting","refs":"POL-D06","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"— (start)","next":"PA-10-S020","evId":"EV-OPS-6.1","evQuote":"It is marked, weighed and written in a manual wastage report","taskId":"PA-10-T01","taskDesc":"Wastage identification - Outlet, warehouse or CPU employee identifies the loss","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-10-S020', N'PA-10', 152, N'Store Operations', N'Retire', N'Non-system', N'{"id":"PA-10-S020","pa":"PA-10","phase":"1. Identify & record","scor":"Enable – Manage inventory","stype":"Activity","asis":"Store wastage weighed, recorded on paper, confirmed by supervisor and entered in MC daily; the MC entry screen needs changes.","asisActor":"Store staff","asisSys":"Paper; MC wastage entry","gapFlag":"Gap","gapDesc":"Paper then re-keyed; entry screen not fit for use. (Root cause: outside the system)","change":"Retire","tobe":"Retired — replaced by S010 / S030.","dept":"Store Operations","role":"Store Manager","pillars":"Data & Reporting","fit":"Non-system","moscow":"Must","prev":"PA-10-S010","next":"PA-10-S030","evId":"EV-CC-4.3; EV-QL-D05","evQuote":"Store wastage weighed, recorded on paper, confirmed by supervisor and entered in MC daily"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-10-S030', N'PA-10', 153, N'Store Operations', N'New', N'Covered', N'{"id":"PA-10-S030","pa":"PA-10","phase":"1. Identify & record","scor":"Enable – Manage inventory","stype":"Activity","asis":"— (see S020)","change":"New","tobe":"Employee records item, quantity, batch and reason. Cancelled orders recorded as the full menu item; the ERP explodes the approved recipe / sub-recipes automatically into ingredient wastage (no manual breakdown by store users).","dept":"Store Operations","role":"Store / Warehouse / CPU employee","sys":"D365 — Wastage journal","input":"Loss identified","output":"Wastage record","pillars":"Tracking & Traceability","refs":"POL-D08","fit":"Covered","erpReq":"Quick-entry screen (EV-QL-D05).","ricefw":"Extension","moscow":"Must","prev":"PA-10-S020","next":"PA-10-S040","evId":"From task list; EV-FD-158; EV-FD-176","taskId":"PA-10-T02","taskDesc":"Quantity and batch recording - Employee records item, quantity, batch and reason","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-10-S040', N'PA-10', 154, N'Cost Control', N'Modify', N'Partial', N'{"id":"PA-10-S040","pa":"PA-10","phase":"1. Identify & record","scor":"Enable – Manage inventory","stype":"Setup","asis":"CPU wastage captured at three levels with different owners and accounting cycles; each section has a standard wastage derived from yield.","asisActor":"CPU sections","asisSys":"Section records","gapFlag":"Gap","gapDesc":"No common reason codes across sites.","change":"Modify","tobe":"Standard reason codes (wastage, damage, spoilage, expiry, production level) used by all sites. Reason codes extended for store use: expiry, quality issue, overcooked, undercooked, broken, cancelled order, spoilage, brand-standard failure, end-of-day balance (e.g. skewer balance), each recorded by type, not as a day-end total.","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Reason codes","input":"Wastage record (PA-10-S030)","output":"Reason code list","pillars":"Master Data | Data & Reporting","fit":"Partial","erpReq":"Reason codes incl. CPU wastage levels.","ricefw":"Configuration","moscow":"Must","prev":"PA-10-S030","next":"PA-10-S050","evId":"EV-CPU-PRD-6.4; EV-FD-173; EV-FD-174; EV-FD-167","evQuote":"WASTAGE IS CAPTURED AT THREE DISTINCT LEVELS","taskId":"PA-10-T03","taskDesc":"Reason classification - Classify the loss by standard reason code (wastage, damage, spoilage, expiry)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-10-S050', N'PA-10', 155, N'Store Operations', N'New', N'Covered', N'{"id":"PA-10-S050","pa":"PA-10","phase":"1. Identify & record","scor":"Enable – Manage inventory","stype":"Activity","asis":"— (no evidence captured)","change":"New","tobe":"Photo or supporting evidence attached where required (above a value or for quality losses).","dept":"Store Operations","role":"Store / Warehouse / CPU employee","sys":"D365 — Attachments","input":"Wastage record","output":"Evidence attached","pillars":"Control","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-10-S040","next":"PA-10-S060","evId":"From task list","taskId":"PA-10-T04","taskDesc":"Evidence capture - Photo or supporting evidence is attached where required","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-10-S060', N'PA-10', 156, N'Store Operations', N'Modify', N'Covered', N'{"id":"PA-10-S060","pa":"PA-10","phase":"2. Approve & post","scor":"Enable – Manage inventory","stype":"Approval","asis":"Wastage is confirmed by the store in-charge or supervisor before entry in MC.","asisActor":"Store in-charge / Supervisor","asisSys":"Manual confirmation","change":"Modify","tobe":"Supervisor verifies the physical item before the wastage is approved. [SLA: before disposal, same day — proposed]","dept":"Store Operations","role":"Store Supervisor (approver)","sys":"D365 — Workflow","input":"Evidence attached","output":"Verified wastage","pillars":"Control","refs":"CTL-10-1","fit":"Covered","ricefw":"Workflow","moscow":"Must","prev":"PA-10-S050","next":"PA-10-S070","evId":"EV-OPS-6.1","evQuote":"After confirmation by the store in-charge or supervisor","taskId":"PA-10-T05","taskDesc":"Approval - Supervisor verifies the physical item","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-10-S070', N'PA-10', 157, N'Cost Control', N'New', N'Covered', N'{"id":"PA-10-S070","pa":"PA-10","phase":"2. Approve & post","scor":"Enable – Manage inventory","stype":"Approval","asis":"Who reviews store wastage beyond the supervisor is not stated.","gapFlag":"Gap","gapDesc":"No defined review of material losses.","change":"New","tobe":"Wastage within the agreed level (AM-03) is approved by the supervisor; above the level it is approved by Costing, with QC consulted for quality losses. Store wastage needs Operations (Area Manager / MUM) approval at posting; once posted it is locked — any correction is a new reversing entry with reason and approval, not an edit by the Store Manager or Cost Control.","dept":"Cost Control","role":"Supervisor (within AM-03); Costing (above level; QC consulted for quality losses)","sys":"D365 — Workflow","input":"Verified wastage","output":"Approved wastage","pillars":"Control | Finance","refs":"POL-D22","fit":"Covered","erpReq":"Approval limits by value.","ricefw":"Workflow","moscow":"Must","prev":"PA-10-S060","next":"PA-10-S080","evId":"EV-CC-4.3; EV-QL-AM01; EV-FD-159; EV-FD-160","evQuote":"who reviews not stated","taskId":"PA-10-T06","taskDesc":"Approval - Cost Control or QA reviews material losses","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-10-S080', N'PA-10', 158, N'Store Operations', N'New', N'Covered', N'{"id":"PA-10-S080","pa":"PA-10","phase":"2. Approve & post","scor":"Enable – Manage inventory","stype":"Activity","asis":"— (disposal not recorded)","change":"New","tobe":"Disposal confirmed and recorded.","dept":"Store Operations","role":"Store / Warehouse Supervisor","sys":"D365 — Wastage journal","input":"Approved wastage","output":"Disposal record","pillars":"Compliance & Food Safety","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-10-S070","next":"PA-10-S090","evId":"From task list","taskId":"PA-10-T07","taskDesc":"Disposal - Disposal is confirmed","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-10-S090', N'PA-10', 159, N'Cost Control', N'New', N'Covered', N'{"id":"PA-10-S090","pa":"PA-10","phase":"2. Approve & post","scor":"Enable – Manage inventory","stype":"Activity","asis":"— (posted at month end for most CPU sections)","change":"New","tobe":"Approved quantity posted out of inventory.","dept":"Cost Control","role":"System / Inventory Controller","sys":"D365 — Wastage journal posting","input":"Disposal record","output":"Posted wastage (RPT-10)","pillars":"Finance","refs":"K-10-1","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-10-S080","next":"PA-10-S100","evId":"From task list","taskId":"PA-10-T08","taskDesc":"Inventory posting - Approved quantity is posted out of inventory","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-10-S100', N'PA-10', 160, N'Cost Control', N'Modify', N'Not covered', N'{"id":"PA-10-S100","pa":"PA-10","phase":"2. Approve & post","scor":"Enable – Manage inventory","stype":"Exception","asis":"Butchery by-products (poultry, beef) are monitored, weighed and reported to Costing, and reused by other brands and staff cooking; transfer value and staff-cooking accounting not stated.","asisActor":"Butchery section; Costing","asisSys":"Reports to Costing","gapFlag":"Gap","gapDesc":"By-product value and reuse not recorded in the system.","change":"Modify","tobe":"Butchery by-products recorded as co-product output, valued at net realisable value / standard and credited to the main product''s cost, then transferred to the using brand. Staff meals: the staff cafeteria is a section of CPU / CBU; issues to it are recorded at standard cost and its cost forms part of factory overhead (production support pool, POL-D21) — not wastage.","dept":"Cost Control","role":"Butchery Supervisor; Cost Controller","sys":"D365 — Co-products / transfer","input":"Butchery output","output":"By-product transfer","pillars":"Finance | Tracking & Traceability","refs":"POL-D10 | POL-D25","fit":"Not covered","erpReq":"Co-product / by-product valuation and transfer.","ricefw":"Configuration","moscow":"Should","prev":"PA-10-S090","next":"PA-10-S110","evId":"EV-CPU-PRD-6.5; EV-CC-4.2; EV-QL-CC01","evQuote":"By-products are MONITORED, WEIGHED AND REPORTED TO THE COSTING DEPARTMENT"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-10-S110', N'PA-10', 161, N'Warehouse', N'New', N'Partial', N'{"id":"PA-10-S110","pa":"PA-10","phase":"2. Approve & post","scor":"Enable – Manage inventory","stype":"Exception","asis":"Warehouse expiry and short-dated write-off not described.","change":"New","tobe":"Near-expiry and expired stock listed by batch daily; write-off raised through the same wastage approval. [SLA: daily near-expiry list; write-off within 2 working days of expiry — proposed]","dept":"Warehouse","role":"Warehouse Supervisor","sys":"D365 — Batch expiry report","input":"Batch stock","output":"Expiry write-off request","pillars":"Compliance & Food Safety | Monitoring","refs":"CTL-10-2 | POL-D07 | POL-D08 | K-10-2 | K-10-3","fit":"Partial","erpReq":"Near-expiry report by batch.","ricefw":"Report","moscow":"Should","prev":"PA-10-S100","next":"PA-10-S120","evId":"From task list; EV-FD-233"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-10-S120', N'PA-10', 162, N'Cost Control', N'Modify', N'Partial', N'{"id":"PA-10-S120","pa":"PA-10","phase":"3. Report","scor":"Enable – Manage inventory","stype":"Report","asis":"Poultry and beef accounted daily; vegetables and other sections at month end.","asisActor":"Costing","asisSys":"MC","gapFlag":"Gap","gapDesc":"Late visibility of wastage trends.","change":"Modify","tobe":"Wastage reported daily by item, site, quantity, value, reason and batch.","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Wastage report","input":"Posted wastage","output":"Wastage report","pillars":"Data & Reporting | Monitoring","fit":"Partial","erpReq":"Wastage analysis report.","ricefw":"Report","moscow":"Should","prev":"PA-10-S110","next":"— (end)","evId":"EV-CC-4.1; EV-CPU-PRD-6.4","evQuote":"Poultry and beef accounted daily; vegetables and other sections at month end.","taskId":"PA-10-T09","taskDesc":"Financial reporting - Wastage is reported by item, outlet and cause","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S010', N'PA-11', 163, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-11-S010","pa":"PA-11","phase":"1. Recipe creation","scor":"Make – Enable","stype":"Activity","asis":"R&D gives CPU a small-quantity recipe; CPU works out the detailed production recipe at batch size (yield, vendor and item list, costing), case by case.","asisActor":"R&D; CPU","asisSys":"Recipe card (paper / Excel)","gapFlag":"Gap","gapDesc":"Recipe developed outside the system. (Root cause: outside the system)","change":"Modify","tobe":"R&D prepares the sample / test-batch recipe and hands it over to CPU; CPU tests and finalises the production-level batch recipe (quantities, yield, method) and coordinates with R&D for confirmation; Costing lodges the confirmed production recipe (formula) into the ERP. [SLA: lodged before first production batch — proposed]","dept":"CPU / CBU","role":"CPU Chef (tests and finalises); R&D (confirms); Costing (lodges in ERP)","sys":"D365 — Formula (entered by Costing)","input":"R&D recipe card","output":"Draft formula","pillars":"Master Data | Process","refs":"POL-D29","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"— (start)","next":"PA-11-S020","evId":"EV-RND-0.7; EV-CPU-MGT-0.1; EV-CPU-MGT-0.4; EV-QL-FD01; EV-FD-179","evQuote":"CPU recipe small quantity given to CPU based on which they work there detailed recipe with yield and final vendor and item list and costing at bigger volume","taskId":"PA-11-T01","taskDesc":"Recipe request - CPU or Culinary team prepares the recipe","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S020', N'PA-11', 164, N'CPU / CBU', N'Retire', N'Non-system', N'{"id":"PA-11-S020","pa":"PA-11","phase":"1. Recipe creation","scor":"Make – Enable","stype":"Activity","asis":"Batch / production recipe prepared in Excel and given to Costing with confirmation by email; Costing enters it into MC.","asisActor":"CPU; Costing","asisSys":"Excel; email","gapFlag":"Gap","gapDesc":"Re-keyed by Costing. (Root cause: outside the system)","change":"Retire","tobe":"Retired — formula entered once in the ERP (S010).","dept":"CPU / CBU","role":"CPU Chef","pillars":"Master Data","fit":"Non-system","moscow":"Must","prev":"PA-11-S010","next":"PA-11-S030","evId":"EV-CPU-MGT-0.7","evQuote":"Bulk receeipe or Batch receipe or Production receipe is prepared in excel and given Costing department with confirmation over email"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S030', N'PA-11', 165, N'CPU / CBU', N'Retire', N'Non-system', N'{"id":"PA-11-S030","pa":"PA-11","phase":"1. Recipe creation","scor":"Make – Enable","stype":"Activity","asis":"The event management app offers an alternate way to enter production recipes but is not fully functional.","asisActor":"CPU","asisSys":"Event management app","gapFlag":"Gap","gapDesc":"Parallel tool, not functional.","change":"Retire","tobe":"Retired — one recipe record in the ERP.","dept":"CPU / CBU","role":"CPU Manager","pillars":"Master Data","refs":"POL-D01","fit":"Non-system","moscow":"Should","prev":"PA-11-S020","next":"PA-11-S040","evId":"EV-CPU-MGT-0.6","evQuote":"Event management app is serving the some altrenate option to enter production receipe which is not fully functional"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S040', N'PA-11', 166, N'Cost Control', N'Modify', N'Partial', N'{"id":"PA-11-S040","pa":"PA-11","phase":"2. Ingredients & structure","scor":"Make – Enable","stype":"Setup","asis":"For a new ingredient, R&D emails Purchase; once the purchase item is finalised it is updated in MC.","asisActor":"R&D; Purchase","asisSys":"Email; MC","change":"Modify","tobe":"Ingredients and packaging set up as released items before use in a formula (new items via PA-01-S050).","dept":"Cost Control","role":"Costing","sys":"D365 — Released products","input":"Draft formula","output":"Formula lines","pillars":"Master Data","refs":"POL-D02","fit":"Partial","erpReq":"Confirm: Formula lines restricted to released, approved items; block draft or unapproved items.","ricefw":"Configuration","moscow":"Must","prev":"PA-11-S030","next":"PA-11-S050","evId":"EV-RND-0.6","evQuote":"new ingredient - email send to purchase department","taskId":"PA-11-T02","taskDesc":"Ingredient setup - Set up ingredients and packaging as released items for the recipe","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S050', N'PA-11', 167, N'Cost Control', N'Modify', N'Covered', N'{"id":"PA-11-S050","pa":"PA-11","phase":"2. Ingredients & structure","scor":"Make – Enable","stype":"Control check","asis":"Checking and updating of the recipe are handled and controlled by Costing, who also enters it.","asisActor":"Costing","asisSys":"MC","gapFlag":"Control Gap","gapDesc":"Same function enters and checks. (Root cause: open user administration)","change":"Modify","tobe":"Cost Control verifies ingredients, quantities and units on the formula entered by CPU (maker-checker).","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Formula approval","input":"Formula lines","output":"Verified formula","pillars":"Control | Access & Segregation of Duties","refs":"CTL-11-1 | POL-D05","fit":"Covered","ricefw":"Workflow","moscow":"Must","prev":"PA-11-S040","next":"PA-11-S060","evId":"EV-CPU-MGT-2.5","evQuote":"checking and updating of the recipe are handled and controlled by the Costing department","taskId":"PA-11-T03","taskDesc":"Quantity and UOM validation - Cost Control verifies ingredients and units","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S060', N'PA-11', 168, N'Cost Control', N'Modify', N'Partial', N'{"id":"PA-11-S060","pa":"PA-11","phase":"2. Ingredients & structure","scor":"Make – Enable","stype":"Setup","asis":"Production recipes have sub-recipes and a further sub-recipe level, all held in MC (e.g. Marinated Shawarma → Minced onion → Peeled onion).","asisActor":"Costing","asisSys":"MC recipe","change":"Modify","tobe":"Sub-recipes linked to their parent formulas (multi-level), each a production article with its own yield.","dept":"Cost Control","role":"Costing","sys":"D365 — Multi-level formula","input":"Verified formula","output":"Linked formula tree","pillars":"Master Data","fit":"Partial","erpReq":"Confirm: Multi-level formulas (sub-recipes as production articles with own yield) with cost roll-up through all levels.","ricefw":"Configuration","moscow":"Must","prev":"PA-11-S050","next":"PA-11-S070","evId":"EV-CPU-MGT-0.11","evQuote":"Production receipe will have sub production receipe and it may have one more level of sub receipe","taskId":"PA-11-T04","taskDesc":"Sub-recipe linking - Link sub-recipes to their parent recipes","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S070', N'PA-11', 169, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-11-S070","pa":"PA-11","phase":"3. Yield & cost","scor":"Make – Enable","stype":"Activity","asis":"Yield test run by CPU and Costing at production batch size; Costing evidences it; R&D is not responsible for yield or costing.","asisActor":"CPU; Costing","asisSys":"Manual","change":"Modify","tobe":"Production performs the yield test at batch size with Costing; the result is recorded on the formula.","dept":"CPU / CBU","role":"CPU Chef; Cost Controller","sys":"D365 — Formula yield","input":"Linked formula tree","output":"Tested yield","pillars":"Finance | Process","refs":"POL-D18","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-11-S060","next":"PA-11-S080","evId":"EV-CC-2.2; EV-RND-0.11; EV-CPU-MGT-0.12; EV-QL-C12","evQuote":"Yield test run by CPU and Costing at production batch size; Costing evidences it.","taskId":"PA-11-T05","taskDesc":"Yield testing - Production performs a yield test","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S080', N'PA-11', 170, N'Cost Control', N'Modify', N'Partial', N'{"id":"PA-11-S080","pa":"PA-11","phase":"3. Yield & cost","scor":"Make – Enable","stype":"Setup","asis":"Costing fixes standard recipe wastage with a default yield and wastage matrix; butchery (poultry, beef) has a separate matrix because of by-products; no yield % in MC.","asisActor":"Costing","asisSys":"Matrix (offline)","gapFlag":"Gap","gapDesc":"Yield / wastage standards held outside the system.","change":"Modify","tobe":"Yield % and standard wastage held per formula line and stage, including butchery co-products.","dept":"Cost Control","role":"Costing","sys":"D365 — Formula line yield / co-products","input":"Tested yield","output":"Yield standards","pillars":"Finance | Master Data","refs":"POL-D10","fit":"Partial","erpReq":"Yield per stage; co-product setup.","ricefw":"Configuration","moscow":"Must","prev":"PA-11-S070","next":"PA-11-S090","evId":"EV-CC-2.3; EV-CC-2.1","evQuote":"Costing fixes standard recipe wastage with a default yield and wastage matrix"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S090', N'PA-11', 171, N'Cost Control', N'Modify', N'Covered', N'{"id":"PA-11-S090","pa":"PA-11","phase":"3. Yield & cost","scor":"Make – Enable","stype":"Activity","asis":"MC recipe is used as a standard costing and allocation module, not for live production.","asisActor":"Costing","asisSys":"MC recipe","gapFlag":"Gap","gapDesc":"Recipe serves costing only.","change":"Modify","tobe":"Cost Control calculates the formula cost in the ERP (material; factory overhead and labour added when management decides).","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Cost calculation","input":"Yield standards","output":"Standard cost","pillars":"Finance","refs":"POL-D10","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-11-S080","next":"PA-11-S100","evId":"EV-CPU-MGT-3.6; EV-CC-2.1; EV-CC-7.2","evQuote":"used as a standard recipe costing and allocation module","taskId":"PA-11-T06","taskDesc":"Cost calculation - Finance or Cost Control calculates recipe cost","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S100', N'PA-11', 172, N'Quality Control', N'New', N'Covered', N'{"id":"PA-11-S100","pa":"PA-11","phase":"4. Approval & release","scor":"Make – Enable","stype":"Control check","asis":"— (food-safety and quality review of a new recipe not described)","change":"New","tobe":"QC is notified automatically of every new or changed recipe and reviews all changes introduced in the period on a monthly basis (allergens, shelf life, critical control points); findings raise corrective actions. QC does not hold production.","dept":"Quality Control","role":"QC Officer (periodic review)","sys":"D365 — Formula approval","input":"Standard cost","output":"QA approval","pillars":"Compliance & Food Safety","refs":"CTL-11-1 | POL-D23","fit":"Covered","ricefw":"Workflow","moscow":"Must","prev":"PA-11-S090","next":"PA-11-S110","evId":"EV-QL-QC01","taskId":"PA-11-T07","taskDesc":"Quality approval - QA reviews food-safety and quality requirements","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S110', N'PA-11', 173, N'R&D', N'Modify', N'Partial', N'{"id":"PA-11-S110","pa":"PA-11","phase":"4. Approval & release","scor":"Make – Enable","stype":"Approval","asis":"CPU''s production recipe card is shown to R&D but with no documentation or signing by R&D.","asisActor":"CPU; R&D","gapFlag":"Control Gap","gapDesc":"No recorded recipe approval. (Root cause: outside the system)","change":"Modify","tobe":"R&D (having confirmed the production recipe with CPU, PA-11-S010) completes a mandatory food-safety checklist (allergens, shelf-life basis, critical control points, labelling) and formally signs off the formula in the ERP; the authorised owner approves it. [SLA: before activation of the recipe — proposed]","dept":"R&D","role":"R&D Head (approver)","sys":"D365 — Formula approval workflow","input":"QA approval","output":"Approved formula","pillars":"Control","refs":"CTL-11-1 | POL-D23 | K-11-1 | POL-D29","fit":"Partial","erpReq":"Confirm: Mandatory food-safety checklist (allergens, shelf-life basis, CCPs, labelling) attached to the formula version; formula cannot be approved until complete.","ricefw":"Workflow","moscow":"Must","prev":"PA-11-S100","next":"PA-11-S120","evId":"EV-RND-0.8; EV-RND-6.1; EV-QL-QC01","evQuote":"shown to R&D but no documentation or signing from R&D","taskId":"PA-11-T08","taskDesc":"Business approval - Authorized owner approves the formula","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S120', N'PA-11', 174, N'Cost Control', N'Modify', N'Covered', N'{"id":"PA-11-S120","pa":"PA-11","phase":"4. Approval & release","scor":"Make – Enable","stype":"Activity","asis":"Costing directly administers the recipe card and enters the batch recipe items and allocation to menus in MC.","asisActor":"Costing","asisSys":"MC","change":"Modify","tobe":"Master data activates the approved formula version with an effective date.","dept":"Cost Control","role":"Costing (master data)","sys":"D365 — Formula version","input":"Approved formula","output":"Active formula","pillars":"Master Data","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-11-S110","next":"PA-11-S130","evId":"EV-RND-0.9; EV-CPU-MGT-0.13","evQuote":"Costing directly administrate the Recipe card","taskId":"PA-11-T09","taskDesc":"Formula activation - Master Data activates the effective version","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S130', N'PA-11', 175, N'Cost Control', N'Modify', N'Covered', N'{"id":"PA-11-S130","pa":"PA-11","phase":"4. Approval & release","scor":"Make – Enable","stype":"Control check","asis":"Two recipe records: production works from a manual recipe book; MC holds the same recipe for costing.","asisActor":"CPU; Costing","asisSys":"Manual recipe book; MC","gapFlag":"Control Gap","gapDesc":"Book and system can differ. (Root cause: outside the system)","change":"Modify","tobe":"One version-controlled formula; previous version expired, not deleted; printed recipe books withdrawn at go-live and staff view the current recipe version in the ERP. Recipes reviewed every six months and on complaint or change; yield re-tested periodically, not only when the item changes.","dept":"Cost Control","role":"Costing","sys":"D365 — Formula versions","input":"Active formula","output":"Version history","pillars":"Control | Master Data","refs":"CTL-11-1","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-11-S120","next":"PA-11-S140","evId":"EV-CPU-MGT-2.4; EV-CPU-MGT-3.6; EV-FD-179; EV-FD-203","evQuote":"two recipe records exist","taskId":"PA-11-T10","taskDesc":"Version change management - Previous version is expired, not deleted","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S140', N'PA-11', 176, N'Cost Control', N'Modify', N'Partial', N'{"id":"PA-11-S140","pa":"PA-11","phase":"5. Menu mapping","scor":"Make – Enable","stype":"Setup","asis":"Cost Control maps each production recipe to stores by brand; production recipe output feeds the branch recipe, which is always the menu selling quantity.","asisActor":"Cost Control","asisSys":"MC","change":"Modify","tobe":"Menu (branch) recipes held in the ERP per brand, linked to the POS menu item for consumption (PA-17).","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Menu recipe + POS item mapping","input":"Active formula","output":"Menu recipe","pillars":"Master Data | Finance","fit":"Partial","erpReq":"Menu recipe per brand linked to Foodics item.","ricefw":"Configuration + Interface","moscow":"Must","prev":"PA-11-S130","next":"PA-11-S150","evId":"EV-CPU-MGT-0.8; EV-CPU-MGT-0.9; EV-CC-7.1","evQuote":"Cost control department will map each Production receipe item to relevant and applicable stores based on their brand"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-11-S150', N'PA-11', 177, N'R&D', N'Modify', N'Partial', N'{"id":"PA-11-S150","pa":"PA-11","phase":"5. Menu mapping","scor":"Make – Enable","stype":"Setup","asis":"Store-level recipe cards (raw materials plus CPU production items) are used by stores and the Training department, held in Excel, not in the system.","asisActor":"R&D; stores; Training","asisSys":"Excel","gapFlag":"Gap","gapDesc":"Store recipes outside the system. (Root cause: outside the system)","change":"Modify","tobe":"Store menu recipe cards published from the ERP to stores and Training.","dept":"R&D","role":"R&D; Training","sys":"D365 — Menu recipe","input":"Menu recipe","output":"Published recipe card","pillars":"Master Data | People & Training","fit":"Partial","erpReq":"Confirm: Publish approved menu recipe cards (read-only, current version) to stores and Training via ERP / portal / mobile.","ricefw":"Report","moscow":"Should","prev":"PA-11-S140","next":"— (end)","evId":"EV-RND-0.14; EV-RND-0.15","evQuote":"this is available excel not in system"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-12-S010', N'PA-12', 178, N'Store Operations', N'Modify', N'Covered', N'{"id":"PA-12-S010","pa":"PA-12","phase":"1. Demand capture","scor":"Make – Plan","stype":"Hand-off","asis":"Stores order approved production articles mapped to each brand through MC material requests, under brand-group cut-off times.","asisActor":"Stores","asisSys":"MC material request","change":"Modify","tobe":"Outlet requirements for production articles arrive from PA-06 (48-hour rule).","dept":"Store Operations","role":"Store Manager","sys":"D365 — Transfer requisition","input":"Trigger: start of process","output":"Outlet requirements","pillars":"Process","refs":"POL-D04","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"— (start)","next":"PA-12-S020","evId":"EV-CPU-PRD-2.2; EV-CPU-PRD-2.5","evQuote":"Production articles are approved production articles, mapped to each brand."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-12-S020', N'PA-12', 179, N'CPU / CBU', N'Retire', N'Non-system', N'{"id":"PA-12-S020","pa":"PA-12","phase":"1. Demand capture","scor":"Make – Plan","stype":"Control check","asis":"CPU prints the store MRs, checks them against the pattern and rejects abnormal ones; corrections coordinated in WhatsApp.","asisActor":"CPU production team","asisSys":"MR printout; WhatsApp","gapFlag":"Control Gap","gapDesc":"Validation on paper; whole order rejected. (Root cause: outside the system)","change":"Retire","tobe":"Retired — abnormal lines flagged on the requirement and amended in place (PA-06-S130).","dept":"CPU / CBU","role":"CPU Chef","pillars":"Control","refs":"POL-D03 | POL-D04","fit":"Non-system","moscow":"Must","prev":"PA-12-S010","next":"PA-12-S030","evId":"EV-CPU-PRD-2.8","evQuote":"the CPU production team takes a PRINTOUT, goes through it and assesses the production plan for the day"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-12-S030', N'PA-12', 180, N'CPU / CBU', N'Modify', N'Partial', N'{"id":"PA-12-S030","pa":"PA-12","phase":"2. Consolidate & calculate","scor":"Make – Plan","stype":"Activity","asis":"Store MC requests are not auto-compiled into a production plan; done in Excel, with a fix being tried in the event management tool.","asisActor":"CPU","asisSys":"Excel","gapFlag":"Gap","gapDesc":"No consolidated demand. (Root cause: outside the system)","change":"Modify","tobe":"Planner consolidates outlet demand by CPU section and product group in the ERP.","dept":"CPU / CBU","role":"CPU Planner","sys":"D365 — Demand consolidation","input":"Outlet requirements","output":"Consolidated demand","pillars":"Process | Data & Reporting","fit":"Partial","erpReq":"Confirm: Demand consolidation by CPU section and product group from store orders (transfer requirements).","ricefw":"Customization","moscow":"Must","prev":"PA-12-S020","next":"PA-12-S040","evId":"EV-CPU-MGT-0.14","evQuote":"MC request raised by store is not auto compiled to derive production plan","taskId":"PA-12-T01","taskDesc":"Demand consolidation - Planner consolidates outlet demand","solType":"Customization + Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-12-S040', N'PA-12', 181, N'CPU / CBU', N'Retire', N'Non-system', N'{"id":"PA-12-S040","pa":"PA-12","phase":"2. Consolidate & calculate","scor":"Make – Plan","stype":"Activity","asis":"After finalising brand-wise requirements, the summary is re-keyed by hand into section Excel sheets.","asisActor":"CPU chefs","asisSys":"Excel","gapFlag":"Gap","gapDesc":"Double work; error risk. (Root cause: outside the system)","change":"Retire","tobe":"Retired — section view produced by the ERP (S030).","dept":"CPU / CBU","role":"CPU Chef","pillars":"Data & Reporting","fit":"Non-system","moscow":"Must","prev":"PA-12-S030","next":"PA-12-S050","evId":"EV-CPU-PRD-2.9; EV-CPU-MGT-5.1; EV-CBU-3.9","evQuote":"SECTION ALLOCATION — MANUAL RE-KEYING INTO EXCEL"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-12-S050', N'PA-12', 182, N'CPU / CBU', N'Modify', N'Partial', N'{"id":"PA-12-S050","pa":"PA-12","phase":"2. Consolidate & calculate","scor":"Make – Plan","stype":"Activity","asis":"Bakery products cannot be made the same day and must be planned ahead; volume from the marketing event system is an input; forecasting is a big challenge.","asisActor":"CBU; CPU","asisSys":"Manual","gapFlag":"Gap","gapDesc":"Produce-ahead volume set by judgement.","change":"Modify","tobe":"System calculates production requirements from outlet demand plus forecast (produced-ahead items) and events.","dept":"CPU / CBU","role":"CPU Planner","sys":"D365 — Production requirements","input":"Consolidated demand; forecast (PA-03)","output":"Production requirement","pillars":"Process","refs":"POL-D04 | POL-D12","fit":"Partial","erpReq":"Confirm: Production requirement = store demand + forecast for produced-ahead items + events; planning optimisation by section.","ricefw":"Customization","moscow":"Must","prev":"PA-12-S040","next":"PA-12-S060","evId":"EV-CBU-3.5; EV-CPU-MGT-0.2; EV-CPU-MGT-0.10","evQuote":"none of the products can be produced within the same day","taskId":"PA-12-T02","taskDesc":"Production requirement calculation - System calculates production requirements","solType":"Customization + Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-12-S060', N'PA-12', 183, N'CPU / CBU', N'New', N'Partial', N'{"id":"PA-12-S060","pa":"PA-12","phase":"2. Consolidate & calculate","scor":"Make – Plan","stype":"Activity","asis":"— (finished-goods stock not reviewed in a system)","change":"New","tobe":"Planner reviews available finished goods (e.g. frozen bakery stock) before planning batches.","dept":"CPU / CBU","role":"CPU Planner","sys":"D365 — On-hand","input":"Production requirement","output":"Net requirement","pillars":"Process","fit":"Partial","erpReq":"Confirm: Net available finished goods (incl. frozen stock) before planned batches are proposed.","ricefw":"Customization","moscow":"Should","prev":"PA-12-S050","next":"PA-12-S070","evId":"From task list","taskId":"PA-12-T03","taskDesc":"Production requirement calculation - Planner reviews available finished goods","solType":"Customization + Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-12-S070', N'PA-12', 184, N'CPU / CBU', N'Modify', N'Partial', N'{"id":"PA-12-S070","pa":"PA-12","phase":"3. Batch & checks","scor":"Make – Plan","stype":"Setup","asis":"Standard packaging matrix (segregator sheet) defined by production, brand-specific rather than product-specific.","asisActor":"CPU production","asisSys":"Segregator sheet","gapFlag":"Gap","gapDesc":"Batch / pack rules outside the system.","change":"Modify","tobe":"Batch size set by item, capacity and minimum / multiple; standard pack per production article.","dept":"CPU / CBU","role":"CPU Manager","sys":"D365 — Batch size / pack rules","input":"Net requirement","output":"Batch sizes","pillars":"Master Data | Process","fit":"Partial","erpReq":"Batch size and multiple per item.","ricefw":"Configuration","moscow":"Must","prev":"PA-12-S060","next":"PA-12-S080","evId":"EV-CPU-PRD-8.1; EV-CPU-MGT-0.15","evQuote":"STANDARD PACKAGING MATRIX — DEFINED BY PRODUCTION, BUT BRAND-SPECIFIC RATHER THAN PRODUCT-SPECIFIC","taskId":"PA-12-T04","taskDesc":"Batch-size determination - Determine batch size by item, capacity and minimum/multiple quantities","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-12-S080', N'PA-12', 185, N'CPU / CBU', N'Modify', N'Not covered', N'{"id":"PA-12-S080","pa":"PA-12","phase":"3. Batch & checks","scor":"Make – Plan","stype":"Exception","asis":"Over-supply from the standard batch is common; stores are asked to raise an additional order for the difference.","asisActor":"CPU; stores","asisSys":"MC","gapFlag":"Gap","gapDesc":"Batch rounding pushed to stores.","change":"Modify","tobe":"Batch rounding shown at planning; excess kept as finished-goods stock or offered to stores as an additional order linked to the original.","dept":"CPU / CBU","role":"CPU Planner","sys":"D365 — Planned order","input":"Batch sizes","output":"Excess plan","pillars":"Process | Finance","refs":"POL-D04","fit":"Not covered","erpReq":"Excess-from-batch handling.","ricefw":"Extension","moscow":"Should","prev":"PA-12-S070","next":"PA-12-S090","evId":"EV-CPU-PRD-10.7; EV-OPS-0.6","evQuote":"most of the time there will be plus"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-12-S090', N'PA-12', 186, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-12-S090","pa":"PA-12","phase":"3. Batch & checks","scor":"Make – Plan","stype":"Control check","asis":"CPU learns items are unavailable only when the warehouse informs them after the MR; live warehouse stock not visible.","asisActor":"CPU","asisSys":"Phone / WhatsApp","gapFlag":"Gap","gapDesc":"No material availability check. (Root cause: outside the system)","change":"Modify","tobe":"Planner checks raw-material availability for planned batches before release.","dept":"CPU / CBU","role":"CPU Planner","sys":"D365 — Availability check","input":"Batch sizes","output":"Material check","pillars":"Process","refs":"CTL-12-1","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-12-S080","next":"PA-12-S100","evId":"EV-CPU-MGT-5.5","evQuote":"CPU learns they are not available only when the warehouse informs them after the MR has been raised","taskId":"PA-12-T05","taskDesc":"Material-availability check - Planner checks raw-material availability","solType":"Customization + Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-12-S100', N'PA-12', 187, N'CPU / CBU', N'Modify', N'Partial', N'{"id":"PA-12-S100","pa":"PA-12","phase":"3. Batch & checks","scor":"Make – Plan","stype":"Control check","asis":"Bakery equipment runs 18–20 hours a day with no periodic or preventive maintenance; some critical equipment is a single unit.","asisActor":"CBU management","gapFlag":"Control Gap","gapDesc":"Capacity at risk from breakdowns.","change":"Modify","tobe":"CPU / bakery confirm capacity, shifts and equipment availability per planned batch (maintenance in PA-28-S410).","dept":"CPU / CBU","role":"CPU / CBU Manager","sys":"D365 — Resources / capacity","input":"Material check","output":"Capacity check","pillars":"Process | Monitoring","fit":"Partial","erpReq":"Confirm: Finite capacity check by resource / equipment and shift; link to maintenance downtime.","ricefw":"Configuration","moscow":"Should","prev":"PA-12-S090","next":"PA-12-S110","evId":"EV-CBU-5.5","evQuote":"most equipment works an average of 18 to 20 hours a day","taskId":"PA-12-T06","taskDesc":"Capacity and shift review - CPU/Bakery confirms production capacity","solType":"Customization + Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-12-S110', N'PA-12', 188, N'CPU / CBU', N'Modify', N'Partial', N'{"id":"PA-12-S110","pa":"PA-12","phase":"4. Release","scor":"Make – Plan","stype":"Activity","asis":"Production plan collected daily from individual section holders on paper and consolidated.","asisActor":"Section holders","asisSys":"Paper plans","gapFlag":"Gap","gapDesc":"Plan on paper. (Root cause: outside the system)","change":"Modify","tobe":"Planned batch orders reviewed by section.","dept":"CPU / CBU","role":"CPU Planner; Section heads","sys":"D365 — Planned batch orders","input":"Capacity check","output":"Reviewed batch plan","pillars":"Process","fit":"Partial","erpReq":"Confirm: Planned batch orders listed and editable by section before firming.","ricefw":"Customization","moscow":"Must","prev":"PA-12-S100","next":"PA-12-S120","evId":"EV-CPU-PRD-2.1","evQuote":"information is collected from the individual section holders on a daily basis","taskId":"PA-12-T07","taskDesc":"Planned-order review - Planned batch orders are reviewed","solType":"Customization + Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-12-S120', N'PA-12', 189, N'CPU / CBU', N'New', N'Partial', N'{"id":"PA-12-S120","pa":"PA-12","phase":"4. Release","scor":"Make – Plan","stype":"Approval","asis":"— (no approval)","change":"New","tobe":"CPU Manager approves and firms the batch orders. [SLA: before the production plan cut-off for the next day — proposed]","dept":"CPU / CBU","role":"CPU Manager (approver)","sys":"D365 — Firming","input":"Reviewed batch plan","output":"Firm batch orders","pillars":"Control","refs":"CTL-12-1 | POL-D05","fit":"Partial","erpReq":"Confirm: Firming of planned batch orders by an authorised role only (CPU Manager), with cut-off control.","ricefw":"Customization","moscow":"Must","prev":"PA-12-S110","next":"PA-12-S130","evId":"From task list","taskId":"PA-12-T08","taskDesc":"Batch-order creation - Approved orders are firmed","solType":"Customization + Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-12-S130', N'PA-12', 190, N'CPU / CBU', N'New', N'Covered', N'{"id":"PA-12-S130","pa":"PA-12","phase":"4. Release","scor":"Make – Plan","stype":"Hand-off","asis":"— (not described)","change":"New","tobe":"Batch orders scheduled and released to the floor (material issue PA-13).","dept":"CPU / CBU","role":"CPU Planner","sys":"D365 — Scheduling / release","input":"Firm batch orders","output":"Released batch orders (RPT-12)","pillars":"Process","refs":"K-12-1","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-12-S120","next":"— (end)","evId":"From task list","taskId":"PA-12-T09","taskDesc":"Scheduling and release - Orders are scheduled and released","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S010', N'PA-13', 191, N'CPU / CBU', N'Retire', N'Non-system', N'{"id":"PA-13-S010","pa":"PA-13","phase":"1. Section request","scor":"Make – Issue material","stype":"Activity","asis":"Each section supervisor, with the sous chef''s consent, writes the section''s requirement on a unified paper MR in the chef office.","asisActor":"Section Supervisor","asisSys":"Unified paper MR","gapFlag":"Gap","gapDesc":"Section requests not in the system. (Root cause: outside the system)","change":"Retire","tobe":"Retired — requirements come from released batch orders (S030).","dept":"CPU / CBU","role":"Section Supervisor","pillars":"Process","fit":"Non-system","moscow":"Must","prev":"— (start)","next":"PA-13-S020","evId":"EV-CPU-OR-15.2; EV-CPU-OR-15.1; EV-CPU-OR-15.6","evQuote":"a unified material request paper kept in the chef office"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S020', N'PA-13', 192, N'CPU / CBU', N'Modify', N'Partial', N'{"id":"PA-13-S020","pa":"PA-13","phase":"1. Section request","scor":"Make – Issue material","stype":"Approval","asis":"Sous chef reviews, verifies and adjusts the unified list; it is submitted to the CPU Administrator around 2 p.m. for a final discussion.","asisActor":"Sous Chef; CPU Administrator","asisSys":"Paper","gapFlag":"Gap","gapDesc":"Approval on paper. (Root cause: outside the system)","change":"Modify","tobe":"Sous chef approves section requirements (beyond batch-order needs) in the ERP before the cut-off.","dept":"CPU / CBU","role":"Sous Chef (approver)","sys":"D365 — Requisition workflow","input":"Section requirement list","output":"Approved section requirement","pillars":"Control","refs":"POL-D05","fit":"Partial","erpReq":"Confirm: Approval of section requirements beyond batch needs (sous chef) before warehouse cut-off.","ricefw":"Workflow","moscow":"Should","prev":"PA-13-S010","next":"PA-13-S030","evId":"EV-CPU-OR-15.3; EV-CPU-OR-15.4","evQuote":"the sous chef will apply the changes"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S030', N'PA-13', 193, N'CPU / CBU', N'Modify', N'Partial', N'{"id":"PA-13-S030","pa":"PA-13","phase":"2. Request to warehouse","scor":"Make – Issue material","stype":"Activity","asis":"CPU Administrator raises the MR in MC by selecting the Swish article and quantity; MRs received by 3 p.m. are issued next morning.","asisActor":"CPU Administrator","asisSys":"MC material request","change":"Modify","tobe":"System calculates ingredient requirements from released batch orders and generates the pick list to the warehouse.","dept":"CPU / CBU","role":"System; CPU Planner","sys":"D365 — Production picking list","input":"Released batch orders (PA-12)","output":"Pick list","pillars":"Process","refs":"CTL-13-1 | POL-D04","fit":"Partial","erpReq":"Confirm: Picking list generated from released batch orders (BOM explosion) to the warehouse.","ricefw":"Customization","moscow":"Must","prev":"PA-13-S020","next":"PA-13-S040","evId":"EV-CPU-OR-5.1; EV-CPU-OR-15.5","evQuote":"selecting the Swish article, mentioning the quantity and placing the order","taskId":"PA-13-T02","taskDesc":"Pick-list generation - System calculates ingredient requirements","solType":"Customization + Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S040', N'PA-13', 194, N'CPU / CBU', N'Modify', N'Partial', N'{"id":"PA-13-S040","pa":"PA-13","phase":"2. Request to warehouse","scor":"Make – Issue material","stype":"Exception","asis":"The 2 p.m. section cut-off is not strictly followed because of 24/7 production; missed items are requested later.","asisActor":"Sections","asisSys":"Paper","gapFlag":"Gap","gapDesc":"Late requests outside any control.","change":"Modify","tobe":"Late or additional requests raised in the ERP with a reason; visible to the warehouse.","dept":"CPU / CBU","role":"Sous Chef","sys":"D365 — Requisition","input":"Pick list","output":"Additional request","pillars":"Control | Process","refs":"POL-D04","fit":"Partial","erpReq":"Confirm: Late / additional request flagged with reason code and visible to the warehouse queue.","ricefw":"Configuration","moscow":"Should","prev":"PA-13-S030","next":"PA-13-S050","evId":"EV-CPU-OR-15.7","evQuote":"the cutoff procedure of 2 p.m. is not strictly followed"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S050', N'PA-13', 195, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-13-S050","pa":"PA-13","phase":"3. Reserve & pick","scor":"Make – Issue material","stype":"Control check","asis":"Item non-availability is not visible when raising the MR; CPU learns the next day when the warehouse issues.","asisActor":"CPU Administrator","asisSys":"MC","gapFlag":"Gap","gapDesc":"No reservation or availability view. (Root cause: outside the system)","change":"Modify","tobe":"Warehouse reserves the required batches against the pick list; shortages shown immediately.","dept":"Warehouse","role":"Warehouse Supervisor","sys":"D365 — Reservation","input":"Pick list","output":"Reserved batches","pillars":"Process","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-13-S040","next":"PA-13-S060","evId":"EV-CPU-OR-5.3","evQuote":"you will come to know the next day when warehouse team is providing you","taskId":"PA-13-T01","taskDesc":"Material reservation - Warehouse reserves the required batches","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S060', N'PA-13', 196, N'Warehouse', N'Modify', N'Covered', N'{"id":"PA-13-S060","pa":"PA-13","phase":"3. Reserve & pick","scor":"Make – Issue material","stype":"Activity","asis":"Warehouse prints the MR, picks and books it; sometimes the wrong item is selected in the system while the correct article is issued.","asisActor":"Warehouse","asisSys":"MC Issue Note","gapFlag":"Control Gap","gapDesc":"System and physical issue differ. (Root cause: outside the system)","change":"Modify","tobe":"Picker collects and scans each ingredient; scan must match the pick line.","dept":"Warehouse","role":"Picker","sys":"D365 — Mobile picking","input":"Reserved batches","output":"Picked ingredients","pillars":"Tracking & Traceability | Control","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-13-S050","next":"PA-13-S070","evId":"EV-CPU-OR-16.3; EV-CPU-OR-16.2","evQuote":"So in system product A is selected, but actually issued is product B.","taskId":"PA-13-T03","taskDesc":"Raw-material picking - Picker collects and scans ingredients","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S070', N'PA-13', 197, N'Warehouse', N'Modify', N'Partial', N'{"id":"PA-13-S070","pa":"PA-13","phase":"3. Reserve & pick","scor":"Make – Issue material","stype":"Control check","asis":"CPU learns the expiry of warehouse-routed items only on receipt; near-expiry items are sometimes received.","asisActor":"CPU Administrator","asisSys":"Physical","gapFlag":"Gap","gapDesc":"No FEFO or expiry visibility at issue.","change":"Modify","tobe":"Ingredient batches selected by FEFO / expiry at picking; user may override with reason.","dept":"Warehouse","role":"Picker","sys":"D365 — Batch selection","input":"Picked ingredients","output":"Batch-selected issue","pillars":"Compliance & Food Safety | Tracking & Traceability","refs":"POL-D07","fit":"Partial","erpReq":"Confirm: FEFO batch proposal at picking with override reason captured.","ricefw":"Configuration","moscow":"Must","prev":"PA-13-S060","next":"PA-13-S080","evId":"EV-CPU-OR-8.5","evQuote":"by that time only we will come to know what is the expiry period of the specific item we are receiving","taskId":"PA-13-T04","taskDesc":"Batch and expiry selection - Select ingredient batches by FEFO/expiry when picking","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S080', N'PA-13', 198, N'Warehouse', N'Retire', N'Non-system', N'{"id":"PA-13-S080","pa":"PA-13","phase":"3. Reserve & pick","scor":"Make – Issue material","stype":"Exception","asis":"Unavailable items are accepted on the MR with zero quantity; alternates communicated by the warehouse and a revised list accepted.","asisActor":"Warehouse; CPU Administrator","asisSys":"MC; phone","gapFlag":"Gap","gapDesc":"Shortage and substitution handled informally.","change":"Retire","tobe":"Retired — shortages follow PA-15 (substitution).","dept":"Warehouse","role":"Warehouse Supervisor","pillars":"Process","fit":"Non-system","moscow":"Must","prev":"PA-13-S070","next":"PA-13-S090","evId":"EV-CPU-OR-5.7; EV-CPU-OR-5.8","evQuote":"they will accept that MR with zero quantity for the specific item which is not available"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S090', N'PA-13', 199, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-13-S090","pa":"PA-13","phase":"4. Receive at CPU","scor":"Make – Issue material","stype":"Control check","asis":"The MR is converted into an Issue Note; CPU prints it, checks physical quantity and asks the warehouse to change the quantity for any variance.","asisActor":"CPU Administrator","asisSys":"Issue Note printout","gapFlag":"Control Gap","gapDesc":"Variance fixed by editing the issue. (Root cause: outside the system)","change":"Modify","tobe":"Production confirms receipt of the issued materials on the same document; differences recorded with reason. [SLA: at receipt in the section, same shift — proposed]","dept":"CPU / CBU","role":"CPU Receiver (not the requester)","sys":"D365 — Issue confirmation","input":"Batch-selected issue","output":"Materials at CPU","pillars":"Control | Access & Segregation of Duties","refs":"CTL-13-1 | POL-D03 | POL-D05 | K-13-1","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-13-S080","next":"PA-13-S100","evId":"EV-CPU-OR-5.4; EV-CPU-OR-5.6","evQuote":"The MR itself will be converted into issue note in the material control.","taskId":"PA-13-T05","taskDesc":"Issue to production - Production receives the materials","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S100', N'PA-13', 200, N'CPU / CBU', N'Retire', N'Non-system', N'{"id":"PA-13-S100","pa":"PA-13","phase":"4. Receive at CPU","scor":"Make – Issue material","stype":"Exception","asis":"For a wrong item, CPU accepts the whole issue and then informs the warehouse to take back the wrong item.","asisActor":"CPU Administrator","asisSys":"MC; phone","gapFlag":"Control Gap","gapDesc":"Wrong item booked into CPU stock.","change":"Retire","tobe":"Retired — wrong items rejected at confirmation (S090).","dept":"CPU / CBU","role":"CPU Administrator","pillars":"Control","fit":"Non-system","moscow":"Must","prev":"PA-13-S090","next":"PA-13-S110","evId":"EV-CPU-OR-16.4","evQuote":"the CPU administrator will accept the whole item received"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S110', N'PA-13', 201, N'CPU / CBU', N'Retire', N'Non-system', N'{"id":"PA-13-S110","pa":"PA-13","phase":"5. Use & return","scor":"Make – Issue material","stype":"Activity","asis":"No documentation of items received and consumed within CPU sections; the dry store is open to all sections.","asisActor":"CPU sections","gapFlag":"Control Gap","gapDesc":"Consumption untracked. (Root cause: outside the system)","change":"Retire","tobe":"Retired — consumption recorded against batch orders (S120).","dept":"CPU / CBU","role":"Section Supervisor","pillars":"Control","fit":"Non-system","moscow":"Must","prev":"PA-13-S100","next":"PA-13-S120","evId":"EV-CPU-OR-11.2; EV-CPU-OR-11.1","evQuote":"There is no specific documentation of items received and consumed within the sections of CPU"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S120', N'PA-13', 202, N'CPU / CBU', N'New', N'Covered', N'{"id":"PA-13-S120","pa":"PA-13","phase":"5. Use & return","scor":"Make – Issue material","stype":"Activity","asis":"— (see S110)","change":"New","tobe":"CPU records actual quantities used against each batch order. [SLA: by the end of the shift — proposed]","dept":"CPU / CBU","role":"Section Supervisor","sys":"D365 — Picking list journal","input":"Materials at CPU","output":"Actual consumption","pillars":"Finance | Tracking & Traceability","refs":"POL-D11","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-13-S110","next":"PA-13-S130","evId":"From task list","taskId":"PA-13-T06","taskDesc":"Actual-consumption recording - CPU records actual quantities used","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S130', N'PA-13', 203, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-13-S130","pa":"PA-13","phase":"5. Use & return","scor":"Make – Issue material","stype":"Exception","asis":"When CPU wants to return part of a correct issue (e.g. 5 kg of 10 kg), the CPU Administrator informs the warehouse.","asisActor":"CPU Administrator","asisSys":"Phone / WhatsApp","change":"Modify","tobe":"Unused materials returned to the warehouse through a recorded return against the batch order. [SLA: within 24 hours of batch completion — proposed]","dept":"CPU / CBU","role":"Section Supervisor","sys":"D365 — Return to stock","input":"Actual consumption","output":"Material return","pillars":"Tracking & Traceability","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-13-S120","next":"PA-13-S140","evId":"EV-CPU-OR-16.5","evQuote":"we want to return 5 kg back","taskId":"PA-13-T07","taskDesc":"Excess-material return - Unused materials are returned","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S140', N'PA-13', 204, N'Cost Control', N'New', N'Covered', N'{"id":"PA-13-S140","pa":"PA-13","phase":"5. Use & return","scor":"Make – Issue material","stype":"Control check","asis":"— (no consumption review)","change":"New","tobe":"Difference between actual consumption and the standard recipe reviewed per batch.","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Consumption variance","input":"Actual consumption","output":"Consumption variance","pillars":"Monitoring | Finance","refs":"POL-D10","fit":"Covered","ricefw":"Report","moscow":"Must","prev":"PA-13-S130","next":"PA-13-S150","evId":"From task list","taskId":"PA-13-T08","taskDesc":"Consumption-variance review - Difference from standard recipe is reviewed","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S150', N'PA-13', 205, N'CPU / CBU', N'Modify', N'Not covered', N'{"id":"PA-13-S150","pa":"PA-13","phase":"5. Use & return","scor":"Make – Issue material","stype":"Exception","asis":"Sections coordinate materials between each other through WhatsApp.","asisActor":"Section in-charges","asisSys":"WhatsApp","gapFlag":"Gap","gapDesc":"Inter-section moves unrecorded. (Root cause: outside the system)","change":"Modify","tobe":"Inter-section transfers recorded in the ERP (WhatsApp only for coordination, outcome recorded).","dept":"CPU / CBU","role":"Section Supervisor","sys":"D365 — Transfer journal","input":"Consumption variance (PA-13-S140)","output":"Inter-section transfer","pillars":"Tracking & Traceability","refs":"POL-D11","fit":"Not covered","erpReq":"Quick inter-section transfer.","ricefw":"Configuration","moscow":"Should","prev":"PA-13-S140","next":"PA-13-S160","evId":"EV-CPU-PRD-4.1","evQuote":"INTER-SECTION MATERIAL COORDINATION VIA WHATSAPP"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S160', N'PA-13', 206, N'CPU / CBU', N'Modify', N'Partial', N'{"id":"PA-13-S160","pa":"PA-13","phase":"5. Use & return","scor":"Make – Issue material","stype":"Control check","asis":"The CPU Administrator acts as gatekeeper for quality, quantity, price, wrong items and vendor follow-up, with no backup.","asisActor":"CPU Administrator","gapFlag":"Control Gap","gapDesc":"Single point of dependency. (Root cause: open user administration)","change":"Modify","tobe":"Ordering, receiving and confirmation split across roles (CPU Administrator, CPU Chef / Supervisor) with a named backup and delegation.","dept":"CPU / CBU","role":"CPU Manager","sys":"D365 — Security roles / delegation","input":"Inter-section transfer (PA-13-S150)","output":"Security role assignment (CPU)","pillars":"Access & Segregation of Duties","refs":"CTL-13-2 | POL-D05","fit":"Partial","erpReq":"Confirm: Security roles separate ordering, receiving and confirmation for CPU; delegation to named backup.","ricefw":"Configuration","moscow":"Must","prev":"PA-13-S150","next":"PA-13-S170","evId":"EV-CPU-OR-18.2; EV-CPU-OR-18.1","evQuote":"there is no proper backup to take care of all this process"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S170', N'PA-13', 207, N'R&D', N'New', N'Covered', N'{"id":"PA-13-S170","pa":"PA-13","phase":"6. Internal issues to R&D, Training and cafeteria","scor":"Make – Issue material","stype":"Activity","asis":"R&D takes small-quantity consumables from CPU, outlets and the bakery on a regular basis without documents; an internal Excel sheet is kept and one entry is made in MC monthly.","asisActor":"R&D","asisSys":"Internal Excel; monthly MC entry","gapFlag":"Control Gap","gapDesc":"Samples and trial materials leave stock unrecorded. (Root cause: outside the system)","change":"New","tobe":"R&D requests samples and trial materials in the ERP; the issuing section (CPU / CBU / warehouse / outlet) records an inter-section transfer charged to the R&D cost centre on the day.","dept":"R&D","role":"R&D Chef (requests); issuing section supervisor (issues)","sys":"D365 — Transfer journal to R&D sub-warehouse / cost centre","input":"Security role assignment (CPU) (PA-13-S160)","output":"R&D issue record","pillars":"Tracking & Traceability | Finance","refs":"POL-D27","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-13-S160","next":"PA-13-S180","evId":"EV-RND-0.3; EV-RND-0.4; EV-RND-5.1","evQuote":"just an update in excel sheet maintained internally and month one entry once as intendent by R&D","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S180', N'PA-13', 208, N'Training', N'New', N'Covered', N'{"id":"PA-13-S180","pa":"PA-13","phase":"6. Internal issues to R&D, Training and cafeteria","scor":"Make – Issue material","stype":"Activity","asis":"Training has no MC access; raw materials for training menus are requested from CPU, bakery and stores by email, as per the training programme.","asisActor":"Training","asisSys":"Email","gapFlag":"Control Gap","gapDesc":"Training consumption requested and issued outside the system. (Root cause: outside the system)","change":"New","tobe":"Training raises requisitions in the ERP as a requesting cost centre under Operations, per the training programme; CPU / CBU / stores issue against them, charged to the Training cost centre (not production cost). Assets and stationery follow PA-28.","dept":"Training","role":"Training Manager (requests); issuing supervisor","sys":"D365 — Requisition / transfer to Training cost centre","input":"Training programme","output":"Training issue record","pillars":"Finance | Process","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-13-S170","next":"PA-13-S190","evId":"EV-TRN-0.3; EV-TRN-0.1; EV-TRN-0.7; EV-TRN-5.1","evQuote":"raw material - ck, bakery, stores - No MC acess - all through email","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-13-S190', N'PA-13', 209, N'Training', N'New', N'Covered', N'{"id":"PA-13-S190","pa":"PA-13","phase":"6. Internal issues to R&D, Training and cafeteria","scor":"Make – Issue material","stype":"Control check","asis":"Receipt is acknowledged on a printed copy.","asisActor":"Training","asisSys":"Printed copy","gapFlag":"Gap","gapDesc":"Acknowledgement on paper.","change":"New","tobe":"Receiving section (R&D, Training, staff cafeteria) confirms receipt of internal issues in the ERP on the same document.","dept":"Training","role":"Receiving section owner","sys":"D365 — Transfer receipt","input":"Issue record","output":"Confirmed internal issue","pillars":"Control","refs":"POL-D03","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-13-S180","next":"— (end)","evId":"EV-TRN-0.6; EV-TRN-3.1","evQuote":"printed copy reciept acknowledgement","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S010', N'PA-14', 210, N'CPU / CBU', N'New', N'Covered', N'{"id":"PA-14-S010","pa":"PA-14","phase":"1. Start","scor":"Make – Produce","stype":"Activity","asis":"— (production run itself not yet described)","change":"New","tobe":"Production Supervisor starts the batch order.","dept":"CPU / CBU","role":"Production Supervisor","sys":"D365 — Batch order","input":"Materials at CPU","output":"Started batch","pillars":"Process","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"— (start)","next":"PA-14-S020","evId":"From task list","taskId":"PA-14-T01","taskDesc":"Production start - Production Supervisor starts the batch order","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S020', N'PA-14', 211, N'CPU / CBU', N'New', N'Partial', N'{"id":"PA-14-S020","pa":"PA-14","phase":"1. Start","scor":"Make – Produce","stype":"Activity","asis":"— (not described)","change":"New","tobe":"Process stages / operation progress recorded.","dept":"CPU / CBU","role":"Production Supervisor","sys":"D365 — Route operations","input":"Started batch","output":"Stage record","pillars":"Tracking & Traceability","fit":"Partial","erpReq":"Confirm: Route / operation progress reporting per batch (optional for CPU; confirm effort).","ricefw":"Configuration","moscow":"Could","prev":"PA-14-S010","next":"PA-14-S030","evId":"From task list","taskId":"PA-14-T02","taskDesc":"Process-stage recording - Record production process stages / operation progress","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S030', N'PA-14', 212, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-14-S030","pa":"PA-14","phase":"2. Produce","scor":"Make – Produce","stype":"Activity","asis":"No documentation of items consumed within CPU sections.","asisActor":"Sections","gapFlag":"Control Gap","gapDesc":"Consumption untracked. (Root cause: outside the system)","change":"Modify","tobe":"Production records actual ingredient consumption on the batch order.","dept":"CPU / CBU","role":"Production Supervisor","sys":"D365 — Picking list journal","input":"Stage record","output":"Actual consumption","pillars":"Finance","refs":"POL-D11","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-14-S020","next":"PA-14-S040","evId":"EV-CPU-OR-11.2","evQuote":"There is no specific documentation of items received and consumed within the sections of CPU","taskId":"PA-14-T03","taskDesc":"Actual ingredient consumption - Production records actual consumption","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S040', N'PA-14', 213, N'Quality Control', N'Modify', N'Covered', N'{"id":"PA-14-S040","pa":"PA-14","phase":"2. Produce","scor":"Make – Produce","stype":"Control check","asis":"QC validates every CPU and CBU section — critical control points, prerequisite programmes, hygiene.","asisActor":"QC team","asisSys":"Checklists","gapFlag":"Gap","gapDesc":"Checks not linked to batches. (Root cause: outside the system)","change":"Modify","tobe":"QA records production checks against the batch order.","dept":"Quality Control","role":"QC Officer","sys":"D365 — Quality order","input":"Actual consumption","output":"Production QC record","pillars":"Compliance & Food Safety","refs":"CTL-14-2 | POL-D15","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-14-S030","next":"PA-14-S050","evId":"EV-QC-5.1","evQuote":"The QC team is responsible for validating every section in the CBU and every section in the CPU","taskId":"PA-14-T04","taskDesc":"Quality testing - QA records production checks","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S050', N'PA-14', 214, N'Quality Control', N'Keep', N'Partial', N'{"id":"PA-14-S050","pa":"PA-14","phase":"2. Produce","scor":"Make – Produce","stype":"Control check","asis":"Every section has an unannounced weekly GMP inspection; results tracked by section and by individual.","asisActor":"QC team","asisSys":"QC records","change":"Keep","tobe":"Weekly GMP inspection kept; results recorded digitally by section and person.","dept":"Quality Control","role":"QC Officer","sys":"QC checklist tool","input":"Production QC record (PA-14-S040)","output":"GMP results","pillars":"Compliance & Food Safety | Monitoring","fit":"Partial","erpReq":"Confirm: Digital GMP inspection checklist by section and person (quality orders or checklist add-on).","ricefw":"Customization","moscow":"Should","prev":"PA-14-S040","next":"PA-14-S060","evId":"EV-QC-5.2","evQuote":"Every section has a GMP inspection once a week."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S060', N'PA-14', 215, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-14-S060","pa":"PA-14","phase":"3. Output","scor":"Make – Produce","stype":"Activity","asis":"No central packing department; packing is mostly done by the producing section (dedicated team only for sauce and frozen poultry).","asisActor":"Sections","asisSys":"Physical","change":"Modify","tobe":"Operator records finished output quantity on the batch order.","dept":"CPU / CBU","role":"Section Supervisor","sys":"D365 — Report as finished (quantity)","input":"Production QC record","output":"Output quantity","pillars":"Tracking & Traceability","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-14-S050","next":"PA-14-S070","evId":"EV-CPU-PRD-8.4","evQuote":"NO CENTRAL PACKING DEPARTMENT","taskId":"PA-14-T05","taskDesc":"Finished output recording - Operator records finished output","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S070', N'PA-14', 216, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-14-S070","pa":"PA-14","phase":"3. Output","scor":"Make – Produce","stype":"Activity","asis":"Batch code and expiry are printed on a physical sticker only; not captured in the system.","asisActor":"QC; dispatch","asisSys":"Physical sticker","gapFlag":"Control Gap","gapDesc":"No system traceability from batch number. (Root cause: outside the system)","change":"Modify","tobe":"System creates the finished-goods batch with expiry and prints the batch label.","dept":"CPU / CBU","role":"System; Section Supervisor","sys":"D365 — Batch number / label","input":"Output quantity","output":"FG batch","pillars":"Tracking & Traceability | Compliance & Food Safety","refs":"POL-D08","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-14-S060","next":"PA-14-S080","evId":"EV-CPU-PRD-8.2; EV-QC-0.3","evQuote":"BATCH STICKER WITH EXPIRY — PHYSICAL ONLY, NOT IN THE SYSTEM","taskId":"PA-14-T06","taskDesc":"Finished output recording - System creates the finished-goods batch","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S080', N'PA-14', 217, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-14-S080","pa":"PA-14","phase":"4. Yield & waste","scor":"Make – Produce","stype":"Activity","asis":"Wastage captured at three levels with different owners and accounting cycles.","asisActor":"Sections","asisSys":"Section records","gapFlag":"Gap","gapDesc":"Most wastage accounted only at month end.","change":"Modify","tobe":"Production loss recorded separately on the batch with reason code.","dept":"CPU / CBU","role":"Section Supervisor","sys":"D365 — Scrap","input":"FG batch","output":"Production loss","pillars":"Finance | Data & Reporting","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-14-S070","next":"PA-14-S090","evId":"EV-CPU-PRD-6.4","evQuote":"WASTAGE IS CAPTURED AT THREE DISTINCT LEVELS","taskId":"PA-14-T07","taskDesc":"Waste and scrap recording - Production loss is recorded separately","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S090', N'PA-14', 218, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-14-S090","pa":"PA-14","phase":"4. Yield & waste","scor":"Make – Produce","stype":"Control check","asis":"Seniors and chefs review yield against the standard recipe; Costing samples gross-level daily, chiefs check batch-wise; not reconciled.","asisActor":"Chefs; Costing","asisSys":"Judgement","gapFlag":"Control Gap","gapDesc":"No system yield comparison. (Root cause: outside the system)","change":"Modify","tobe":"System calculates actual yield per batch against standard.","dept":"CPU / CBU","role":"System; CPU Chef","sys":"D365 — Yield","input":"Production loss","output":"Actual yield","pillars":"Finance | Monitoring","refs":"POL-D10","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-14-S080","next":"PA-14-S100","evId":"EV-CPU-PRD-6.1; EV-CPU-PRD-6.6","evQuote":"the seniors and the chefs go through the yield and consumption as per the standard recipe model","taskId":"PA-14-T08","taskDesc":"Yield calculation - System calculates actual yield","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S100', N'PA-14', 219, N'CPU / CBU', N'Modify', N'Partial', N'{"id":"PA-14-S100","pa":"PA-14","phase":"4. Yield & waste","scor":"Make – Produce","stype":"Exception","asis":"Exceptions to standard yield are accepted where explained: quality, substitute, different brand, size or quantity change.","asisActor":"Chefs","asisSys":"Discussion","gapFlag":"Gap","gapDesc":"Reasons not recorded.","change":"Modify","tobe":"Yield variance reason recorded on the batch (quality, substitute, brand, size).","dept":"CPU / CBU","role":"CPU Chef","sys":"D365 — Reason codes","input":"Actual yield","output":"Explained variance (RPT-14)","pillars":"Data & Reporting","refs":"CTL-14-1 | K-14-1","fit":"Partial","erpReq":"Confirm: Mandatory reason code on yield variance beyond tolerance at batch report-as-finished.","ricefw":"Customization","moscow":"Should","prev":"PA-14-S090","next":"PA-14-S110","evId":"EV-CPU-PRD-6.3","evQuote":"Exceptions to the standard yield arise and are accepted where explained."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S110', N'PA-14', 220, N'CPU / CBU', N'Retire', N'Non-system', N'{"id":"PA-14-S110","pa":"PA-14","phase":"4. Yield & waste","scor":"Make – Produce","stype":"Exception","asis":"Extra quantity the vendor supplies for a yield shortfall is issued to production but not captured in the system.","asisActor":"CPU Administrator; vendor","gapFlag":"Control Gap","gapDesc":"Stock and cost understated. (Root cause: outside the system)","change":"Retire","tobe":"Retired — top-ups received as zero-price lines (PA-04-S140).","dept":"CPU / CBU","role":"CPU Administrator","pillars":"Finance | Control","fit":"Non-system","moscow":"Must","prev":"PA-14-S100","next":"PA-14-S120","evId":"EV-CPU-OR-14.6; EV-CPU-OR-14.5","evQuote":"This additional inventory received from the vendor and issued to the production is not captured in the system"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S120', N'PA-14', 221, N'CPU / CBU', N'New', N'Covered', N'{"id":"PA-14-S120","pa":"PA-14","phase":"5. Close","scor":"Make – Produce","stype":"Activity","asis":"— (not described)","change":"New","tobe":"Authorised user reports the batch order as finished. [SLA: by the end of the shift — proposed]","dept":"CPU / CBU","role":"Production Supervisor","sys":"D365 — Report as finished","input":"Explained variance","output":"Finished batch","pillars":"Process","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-14-S110","next":"PA-14-S130","evId":"From task list","taskId":"PA-14-T09","taskDesc":"Report as finished - Authorized user reports the order as finished","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S130', N'PA-14', 222, N'Cost Control', N'New', N'Covered', N'{"id":"PA-14-S130","pa":"PA-14","phase":"5. Close","scor":"Make – Produce","stype":"Approval","asis":"— (not described)","change":"New","tobe":"Cost Control reviews the batch variance. [SLA: within 2 working days — proposed]","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Variance review","input":"Finished batch","output":"Reviewed variance","pillars":"Control | Finance","refs":"CTL-14-1","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-14-S120","next":"PA-14-S140","evId":"From task list","taskId":"PA-14-T10","taskDesc":"Batch-order ending - Cost Control reviews variance","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S140', N'PA-14', 223, N'Finance', N'New', N'Covered', N'{"id":"PA-14-S140","pa":"PA-14","phase":"5. Close","scor":"Make – Produce","stype":"Activity","asis":"— (not described)","change":"New","tobe":"Finance or Production Control ends the batch order.","dept":"Finance","role":"Production Controller","sys":"D365 — End order","input":"Reviewed variance","output":"Closed batch","pillars":"Finance","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-14-S130","next":"PA-14-S150","evId":"From task list","taskId":"PA-14-T11","taskDesc":"Batch-order ending - Finance or Production Control ends the order","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-14-S150', N'PA-14', 224, N'Store Operations', N'Modify', N'Not covered', N'{"id":"PA-14-S150","pa":"PA-14","phase":"6. Store completion","scor":"Make – Produce","stype":"Activity","asis":"For some products (fresh-dough pizza) the final production stage is completed at store level after part-fermentation at CBU.","asisActor":"CBU; stores","asisSys":"Physical","gapFlag":"Gap","gapDesc":"Store stage not represented.","change":"Modify","tobe":"Store-completed items transferred as semi-finished with shelf life; final stage handled in the store''s consumption (PA-17).","dept":"Store Operations","role":"Store Chef","sys":"D365 — Semi-finished item","input":"Closed batch","output":"Semi-finished transfer","pillars":"Process | Compliance & Food Safety","fit":"Not covered","erpReq":"Semi-finished item flow to store.","ricefw":"Configuration","moscow":"Could","prev":"PA-14-S140","next":"— (end)","evId":"EV-CBU-5.4","evQuote":"For some products the final production stage is completed at store level."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-15-S010', N'PA-15', 225, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-15-S010","pa":"PA-15","phase":"1. Shortage","scor":"Make – Enable","stype":"Exception","asis":"Where an approved article is not available in the market, the warehouse confirms it with Purchase and they look for an alternate.","asisActor":"Warehouse; Purchase","asisSys":"Phone / WhatsApp","gapFlag":"Gap","gapDesc":"Shortage not recorded against production. (Root cause: outside the system)","change":"Modify","tobe":"Production / warehouse reports the unavailable ingredient against the batch order.","dept":"CPU / CBU","role":"CPU Planner; Warehouse Supervisor","sys":"D365 — Shortage on batch order","input":"Trigger: start of process","output":"Shortage record","pillars":"Process","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"— (start)","next":"PA-15-S020","evId":"EV-CPU-OR-13.1; EV-CPU-OR-12.1","evQuote":"Where an existing approved article is not available in the market, this is confirmed by the warehouse team in coordination with the purchase department.","taskId":"PA-15-T01","taskDesc":"Shortage identification - Production reports the unavailable ingredient","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-15-S020', N'PA-15', 226, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-15-S020","pa":"PA-15","phase":"2. Evaluate & approve","scor":"Make – Enable","stype":"Activity","asis":"Alternates are organised with a sample, mostly sent directly to the kitchen and received by the CPU Administrator.","asisActor":"CPU Administrator","asisSys":"Physical sample","change":"Modify","tobe":"Approved alternatives (substitute variants) reviewed first; a new alternate sample is logged against the shortage.","dept":"CPU / CBU","role":"CPU Chef","sys":"D365 — Substitute list","input":"Shortage record","output":"Candidate substitute","pillars":"Process | Master Data","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-15-S010","next":"PA-15-S030","evId":"EV-CPU-OR-13.2; EV-CPU-OR-13.3","evQuote":"most of them they are directly sent to kitchen.","taskId":"PA-15-T02","taskDesc":"Substitute evaluation - Approved alternatives are reviewed","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-15-S030', N'PA-15', 227, N'R&D', N'Modify', N'Partial', N'{"id":"PA-15-S030","pa":"PA-15","phase":"2. Evaluate & approve","scor":"Make – Enable","stype":"Approval","asis":"R&D takes the final call on the alternate, with the consent of the CPU chefs.","asisActor":"R&D; CPU Chefs","asisSys":"Verbal","gapFlag":"Gap","gapDesc":"Decision not recorded. (Root cause: outside the system)","change":"Modify","tobe":"Culinary team (R&D with CPU chefs) confirms product impact in the ERP, completing the R&D food-safety checklist for the substitute or variant.","dept":"R&D","role":"R&D (approver); CPU Chef","sys":"D365 — Substitution workflow","input":"Candidate substitute","output":"Culinary approval","pillars":"Control","refs":"CTL-15-1 | POL-D17 | POL-D23","fit":"Partial","erpReq":"Confirm: Substitution approval workflow (culinary team → QC → authorised approver) linked to the batch / formula.","ricefw":"Customization","moscow":"Must","prev":"PA-15-S020","next":"PA-15-S040","evId":"EV-CPU-OR-13.4; EV-QL-QC01","evQuote":"the final call is taken by the R&D department, with the consent of the CPU chefs","taskId":"PA-15-T03","taskDesc":"Culinary and QA approval - Culinary team confirms product impact","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-15-S040', N'PA-15', 228, N'Quality Control', N'New', N'Partial', N'{"id":"PA-15-S040","pa":"PA-15","phase":"2. Evaluate & approve","scor":"Make – Enable","stype":"Control check","asis":"— (QC role in substitution not described)","change":"New","tobe":"QC notified of every approved substitute / variant and reviews all those introduced in the period monthly (quality, allergen impact); findings raise corrective actions. QC does not hold production.","dept":"Quality Control","role":"QC Officer (periodic review)","sys":"D365 — Substitution workflow","input":"Culinary approval","output":"QA approval","pillars":"Compliance & Food Safety","refs":"CTL-15-1 | POL-D15 | POL-D23","fit":"Partial","erpReq":"Confirm: Automatic QC notification on approved substitutes and monthly list of substitutes introduced.","ricefw":"Customization","moscow":"Must","prev":"PA-15-S030","next":"PA-15-S050","evId":"EV-QL-QC01","taskId":"PA-15-T04","taskDesc":"Culinary and QA approval - QA confirms quality and allergen impact","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-15-S050', N'PA-15', 229, N'CPU / CBU', N'Modify', N'Partial', N'{"id":"PA-15-S050","pa":"PA-15","phase":"2. Evaluate & approve","scor":"Make – Enable","stype":"Approval","asis":"When a different brand is supplied, CPU discusses with the team and accepts it if acceptable; R&D accepts or rejects from a WhatsApp photo.","asisActor":"CPU Administrator; R&D","asisSys":"WhatsApp photo","gapFlag":"Control Gap","gapDesc":"Acceptance informal. (Root cause: outside the system)","change":"Modify","tobe":"Authorised person approves the substitution in the ERP. [SLA: before production starts on the substitute — proposed]","dept":"CPU / CBU","role":"CPU Manager (approver)","sys":"D365 — Substitution workflow","input":"QA approval","output":"Approved substitution","pillars":"Control","refs":"CTL-15-1 | POL-D17 | K-15-1","fit":"Partial","erpReq":"Confirm: Substitute cannot be issued to a batch without approval in the ERP.","ricefw":"Customization","moscow":"Must","prev":"PA-15-S040","next":"PA-15-S060","evId":"EV-CPU-OR-5.5; EV-RND-4.2","evQuote":"if it is acceptable, you will discuss with your team and you will accept.","taskId":"PA-15-T05","taskDesc":"Culinary and QA approval - Authorized person approves the substitution","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-15-S060', N'PA-15', 230, N'R&D', N'Retire', N'Non-system', N'{"id":"PA-15-S060","pa":"PA-15","phase":"2. Evaluate & approve","scor":"Make – Enable","stype":"Activity","asis":"R&D tells Purchase of the approval through WhatsApp, sometimes email, in one group.","asisActor":"R&D","asisSys":"WhatsApp; email","gapFlag":"Gap","gapDesc":"Approval trail in chat. (Root cause: outside the system)","change":"Retire","tobe":"Retired — approval recorded in the ERP (S030–S050).","dept":"R&D","role":"R&D","pillars":"Control","refs":"POL-D11","fit":"Non-system","moscow":"Must","prev":"PA-15-S050","next":"PA-15-S070","evId":"EV-CPU-OR-13.5","evQuote":"through WhatsApp, sometimes through email — there is one group."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-15-S070', N'PA-15', 231, N'Cost Control', N'New', N'Partial', N'{"id":"PA-15-S070","pa":"PA-15","phase":"3. Record","scor":"Make – Enable","stype":"Activity","asis":"— (cost impact of substitutes not assessed)","change":"New","tobe":"Cost Control evaluates the cost impact of the substitute.","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Cost comparison","input":"Approved substitution","output":"Cost impact","pillars":"Finance","fit":"Partial","erpReq":"Confirm: Cost comparison of substitute vs standard ingredient at approval.","ricefw":"Customization","moscow":"Should","prev":"PA-15-S060","next":"PA-15-S080","evId":"From task list","taskId":"PA-15-T06","taskDesc":"Cost-impact review - Cost Control evaluates cost","solType":"Customization + Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-15-S080', N'PA-15', 232, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-15-S080","pa":"PA-15","phase":"3. Record","scor":"Make – Enable","stype":"Activity","asis":"Brand, pack size or other variant differences in the item actually issued are not reflected in the system.","asisActor":"Warehouse; CPU","asisSys":"MC (Swish article level)","gapFlag":"Gap","gapDesc":"Variant used is invisible. (Root cause: no variant setup)","change":"Modify","tobe":"Correct substitute (variant) recorded against the batch order or formula.","dept":"CPU / CBU","role":"CPU Planner","sys":"D365 — Batch order line","input":"Cost impact","output":"Updated batch order","pillars":"Tracking & Traceability","refs":"POL-D02","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-15-S070","next":"PA-15-S090","evId":"EV-CPU-OR-16.6","evQuote":"some variant like brand or packaging size or some difference in the actual item issued","taskId":"PA-15-T07","taskDesc":"Formula or order update - Correct substitute is recorded against the batch order","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-15-S090', N'PA-15', 233, N'CPU / CBU', N'New', N'Partial', N'{"id":"PA-15-S090","pa":"PA-15","phase":"3. Record","scor":"Make – Enable","stype":"Activity","asis":"— (consumption of substitute not recorded)","change":"New","tobe":"Actual consumption of the substitute ingredient recorded against the batch.","dept":"CPU / CBU","role":"Section Supervisor","sys":"D365 — Picking list journal","input":"Updated batch order","output":"Substitute consumption","pillars":"Finance | Tracking & Traceability","refs":"POL-D11","fit":"Partial","erpReq":"Confirm: Actual substitute consumption recorded against the batch (batch-level traceability).","ricefw":"Configuration","moscow":"Must","prev":"PA-15-S080","next":"PA-15-S100","evId":"From task list","taskId":"PA-15-T08","taskDesc":"Consumption recording - Record actual consumption of the substitute ingredient against the batch order","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-15-S100', N'PA-15', 234, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-15-S100","pa":"PA-15","phase":"4. Review","scor":"Make – Enable","stype":"Control check","asis":"Substandard material raises yield loss and manpower; CPU asks the vendor to add more in the next supply and raises it with Purchase.","asisActor":"CPU Administrator; Purchase","asisSys":"Discussion","gapFlag":"Gap","gapDesc":"Impact not measured.","change":"Modify","tobe":"Resulting yield and quality reviewed after production; findings fed to vendor evaluation (PA-04-S270).","dept":"CPU / CBU","role":"CPU Chef; QC Officer","sys":"D365 — Yield / quality review","input":"Substitute consumption","output":"Post-production review","pillars":"Monitoring","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-15-S090","next":"PA-15-S110","evId":"EV-CPU-OR-14.9; EV-CPU-OR-14.5","evQuote":"whenever the substandard material received, the manpower is going to be spent more","taskId":"PA-15-T09","taskDesc":"Post-production review - Resulting yield and quality are reviewed","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-15-S110', N'PA-15', 235, N'Quality Control', N'Modify', N'Partial', N'{"id":"PA-15-S110","pa":"PA-15","phase":"4. Review","scor":"Make – Enable","stype":"Control check","asis":"CPU Administrator recommends production (and R&D where needed) join the warehouse receipt check for deviations.","asisActor":"CPU Administrator","change":"Modify","tobe":"Production / R&D representative joins the warehouse quality gate for substitutes and deviating items.","dept":"Quality Control","role":"QC Officer; CPU Chef","sys":"D365 — Quality order (receipt)","input":"Post-production review (PA-15-S100)","output":"Quality gate decision","pillars":"Compliance & Food Safety","refs":"POL-D15","fit":"Partial","erpReq":"Confirm: Quality order routing to include a production / R&D reviewer for substitutes and deviating items.","ricefw":"Configuration","moscow":"Could","prev":"PA-15-S100","next":"— (end)","evId":"EV-CPU-OR-17.2","evQuote":"The CPU administrator is recommending to engage production department"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-16-S010', N'PA-16', 236, N'Quality Control', N'Modify', N'Covered', N'{"id":"PA-16-S010","pa":"PA-16","phase":"1. Release","scor":"Deliver – Ship","stype":"Control check","asis":"QC and dispatch check that every pack carries expiry date and batch code; the sticker is physical only.","asisActor":"QC; dispatch","asisSys":"Physical sticker","gapFlag":"Gap","gapDesc":"Release not recorded. (Root cause: outside the system)","change":"Modify","tobe":"QA releases the production batch in the ERP. [SLA: before allocation and dispatch — proposed]","dept":"Quality Control","role":"QC Officer","sys":"D365 — Batch release","input":"Closed batch (PA-14)","output":"Released batch","pillars":"Compliance & Food Safety","refs":"CTL-16-1 | POL-D15","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"— (start)","next":"PA-16-S020","evId":"EV-QC-0.3; EV-CPU-PRD-8.2","evQuote":"QC and dispatch check that every pack carries expiry date and batch code","taskId":"PA-16-T01","taskDesc":"Quality release - QA releases the production batch","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-16-S020', N'PA-16', 237, N'CPU / CBU', N'New', N'Partial', N'{"id":"PA-16-S020","pa":"PA-16","phase":"1. Release","scor":"Deliver – Ship","stype":"Activity","asis":"— (not described)","change":"New","tobe":"Released finished-goods quantity confirmed available for allocation.","dept":"CPU / CBU","role":"Dispatch Supervisor","sys":"D365 — On-hand","input":"Released batch","output":"Available FG","pillars":"Process","fit":"Partial","erpReq":"Confirm: Finished-goods availability only after QA batch release (inventory status change).","ricefw":"Configuration","moscow":"Must","prev":"PA-16-S010","next":"PA-16-S030","evId":"From task list","taskId":"PA-16-T02","taskDesc":"Finished-goods availability - Confirm released finished-goods quantity available for allocation","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-16-S030', N'PA-16', 238, N'CPU / CBU', N'Modify', N'Partial', N'{"id":"PA-16-S030","pa":"PA-16","phase":"2. Allocate & pick","scor":"Deliver – Ship","stype":"Activity","asis":"A dedicated dispatch team holds the dispatch list from the finalised store MRs and allocates brand-wise bins.","asisActor":"Dispatch team","asisSys":"Dispatch list (paper)","change":"Modify","tobe":"Planner allocates output to outlets from the requirements.","dept":"CPU / CBU","role":"Dispatch Supervisor","sys":"D365 — Allocation","input":"Available FG","output":"Allocation","pillars":"Process","fit":"Partial","erpReq":"Confirm: Allocation of released output to outlets from transfer requirements (fair-share where short).","ricefw":"Customization","moscow":"Must","prev":"PA-16-S020","next":"PA-16-S040","evId":"EV-CPU-PRD-10.1","evQuote":"DEDICATED DISPATCH TEAM WITH BIN ALLOCATION","taskId":"PA-16-T03","taskDesc":"Allocation - Planner allocates output to outlets","solType":"Customization + Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-16-S040', N'PA-16', 239, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-16-S040","pa":"PA-16","phase":"2. Allocate & pick","scor":"Deliver – Ship","stype":"Hand-off","asis":"An MC entry is made at dispatch by the production team, cross-checked against the production plan and the store MRs.","asisActor":"Production / dispatch team","asisSys":"MC","change":"Modify","tobe":"Transfer orders created to each outlet from the allocation (same document as the outlet requirement), carrying EGC supply documentation at vendor-prototype level: CPU / CBU supply catalogue item, lead time and minimum issue quantity, delivery note, QC release reference, store receipt confirmation and the gate value for inter-company settlement (POL-D21). Not managed as a full vendor relationship (POL-D30).","dept":"CPU / CBU","role":"Dispatch Supervisor","sys":"D365 — Transfer order","input":"Allocation","output":"Transfer orders","pillars":"Tracking & Traceability","refs":"POL-D03 | POL-D30","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-16-S030","next":"PA-16-S050","evId":"EV-CPU-PRD-10.2; EV-QL-FD01; EV-FD-232","evQuote":"AN MC ENTRY IS MADE AT DISPATCH, BY THE PRODUCTION TEAM","taskId":"PA-16-T04","taskDesc":"Transfer creation - Transfer orders are created","solType":"Customization + Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-16-S050', N'PA-16', 240, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-16-S050","pa":"PA-16","phase":"2. Allocate & pick","scor":"Deliver – Ship","stype":"Activity","asis":"Carried-over bakery product is sent with a ''use first'' sticker; production date never changed.","asisActor":"CBU dispatch","asisSys":"Sticker","change":"Modify","tobe":"Warehouse picks finished goods using FEFO by batch.","dept":"CPU / CBU","role":"Picker","sys":"D365 — FEFO picking","input":"Transfer orders","output":"Picked FG","pillars":"Compliance & Food Safety | Tracking & Traceability","refs":"POL-D07","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-16-S040","next":"PA-16-S060","evId":"EV-CBU-7.1","evQuote":"Carried-over product is sent with a ''use first'' highlighter sticker.","taskId":"PA-16-T05","taskDesc":"Picking and staging - Warehouse picks using FEFO","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-16-S060', N'PA-16', 241, N'CPU / CBU', N'Keep', N'Partial', N'{"id":"PA-16-S060","pa":"PA-16","phase":"3. Dispatch","scor":"Deliver – Ship","stype":"Setup","asis":"Dispatch windows by brand mirror the ordering cut-offs; bakery has the whole day''s requirement ready by 7 a.m.","asisActor":"Dispatch team; CBU","asisSys":"Schedule","change":"Keep","tobe":"Dispatch windows held per brand and route in the delivery schedule.","dept":"CPU / CBU","role":"Dispatch Supervisor; Logistics","sys":"D365 — Delivery schedule","input":"Picked FG (PA-16-S050)","output":"Dispatch window schedule","pillars":"Process","fit":"Partial","erpReq":"Confirm: Delivery windows per brand / route held in master data and used by allocation and dispatch.","ricefw":"Configuration","moscow":"Should","prev":"PA-16-S050","next":"PA-16-S070","evId":"EV-CPU-PRD-10.5; EV-CBU-7.2; EV-CBU-7.5","evQuote":"DISPATCH WINDOWS BY BRAND"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-16-S070', N'PA-16', 242, N'Quality Control', N'Keep', N'Partial', N'{"id":"PA-16-S070","pa":"PA-16","phase":"3. Dispatch","scor":"Deliver – Ship","stype":"Control check","asis":"At loading, QC checks product and truck temperature and signs off the dispatch.","asisActor":"QC","asisSys":"Manual sign-off","change":"Keep","tobe":"QC dispatch and truck check recorded in the ERP before shipment (as PA-06-S180).","dept":"Quality Control","role":"QC Officer","sys":"D365 — Quality order on shipment","input":"Picked FG","output":"QC dispatch release","pillars":"Compliance & Food Safety | Control","refs":"CTL-16-1 | POL-D15","fit":"Partial","erpReq":"Confirm: QC dispatch / truck checklist recorded before shipment confirmation (block dispatch until done).","ricefw":"Customization","moscow":"Must","prev":"PA-16-S060","next":"PA-16-S080","evId":"EV-CPU-PRD-10.3; EV-QC-8.1","evQuote":"LOADING AND QC CHECK AT DISPATCH"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-16-S080', N'PA-16', 243, N'CPU / CBU', N'New', N'Covered', N'{"id":"PA-16-S080","pa":"PA-16","phase":"3. Dispatch","scor":"Deliver – Ship","stype":"Activity","asis":"— (dispatch confirmed in MC without batch)","change":"New","tobe":"Dispatcher confirms item, batch and quantity.","dept":"CPU / CBU","role":"Dispatcher","sys":"D365 — Transfer shipment","input":"QC dispatch release","output":"Shipment","pillars":"Tracking & Traceability","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-16-S070","next":"PA-16-S090","evId":"From task list","taskId":"PA-16-T06","taskDesc":"Dispatch - Dispatcher confirms item, batch and quantity","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-16-S090', N'PA-16', 244, N'Store Operations', N'Modify', N'Covered', N'{"id":"PA-16-S090","pa":"PA-16","phase":"4. Receipt & differences","scor":"Deliver – Ship","stype":"Activity","asis":"Once the store places the MR it is closed and not editable, so the store cannot confirm the received quantity.","asisActor":"Store Manager","asisSys":"MR printout","gapFlag":"Control Gap","gapDesc":"Receipt not confirmed. (Root cause: outside the system)","change":"Modify","tobe":"Receiving outlet records the actual receipt on the transfer. [SLA: at receipt — proposed]","dept":"Store Operations","role":"Store Manager / Store Chef","sys":"D365 — Transfer receipt","input":"Shipment","output":"Outlet receipt","pillars":"Control","refs":"POL-D06","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-16-S080","next":"PA-16-S100","evId":"EV-OPS-4.1","evQuote":"once the store places the MR it is CLOSED and NOT EDITABLE","taskId":"PA-16-T07","taskDesc":"Outlet or warehouse receipt - Receiving location records actual receipt","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-16-S100', N'PA-16', 245, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-16-S100","pa":"PA-16","phase":"4. Receipt & differences","scor":"Deliver – Ship","stype":"Exception","asis":"Over- and under-supply against the request are both handled by store-side correction.","asisActor":"Stores; CPU","asisSys":"MC","gapFlag":"Gap","gapDesc":"Differences resolved informally.","change":"Modify","tobe":"Shortage or damage investigated and resolved on the transfer.","dept":"CPU / CBU","role":"Dispatch Supervisor; Store Manager","sys":"D365 — Transfer difference","input":"Outlet receipt","output":"Resolved difference","pillars":"Control","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-16-S090","next":"PA-16-S110","evId":"EV-CPU-PRD-10.7","evQuote":"BOTH HANDLED BY STORE-SIDE CORRECTION","taskId":"PA-16-T08","taskDesc":"Difference resolution - Shortage or damage is investigated","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-16-S110', N'PA-16', 246, N'CPU / CBU', N'Modify', N'Partial', N'{"id":"PA-16-S110","pa":"PA-16","phase":"4. Receipt & differences","scor":"Deliver – Ship","stype":"Control check","asis":"Chilled bakery products (e.g. pizza dough) have a 72-hour total shelf life; frozen products about two weeks.","asisActor":"CBU","asisSys":"Physical","gapFlag":"Gap","gapDesc":"Shelf life tracked by hand.","change":"Modify","tobe":"Shelf life per finished-goods batch drives FEFO and a near-expiry alert at CPU and stores.","dept":"CPU / CBU","role":"CBU Manager; Store Manager","sys":"D365 — Batch expiry alert","input":"Resolved difference (PA-16-S100)","output":"Near-expiry alert","pillars":"Compliance & Food Safety | Monitoring","refs":"POL-D07 | K-16-1","fit":"Partial","erpReq":"Confirm: Shelf-life dates per finished-goods batch; FEFO and near-expiry alerts at CPU and stores.","ricefw":"Report","moscow":"Should","prev":"PA-16-S100","next":"— (end)","evId":"EV-CBU-6.2; EV-CBU-7.4","evQuote":"Chilled products such as pizza dough have a 72-hour total shelf life"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-17-S010', N'PA-17', 247, N'IT / ERP', N'Modify', N'Partial', N'{"id":"PA-17-S010","pa":"PA-17","phase":"1. Sales & recipe","scor":"Enable – Manage performance","stype":"Activity","asis":"Sales usage is calculated by hand from the POS and entered in the store Excel; POS is not integrated with inventory.","asisActor":"Store Manager","asisSys":"Foodics POS (read manually); Excel","gapFlag":"Gap","gapDesc":"Sales not posted to inventory. (Root cause: outside the system)","change":"Modify","tobe":"POS item sales imported daily by outlet from Foodics. Foodics item sales reconciled to day-end cash collection before they are used for consumption, product mix or forecast; unmatched days flagged to the store and Finance.","dept":"IT / ERP","role":"IT / ERP; Cost Controller","sys":"D365 + Foodics integration","input":"Trigger: start of process","output":"Imported sales","pillars":"Data & Reporting","refs":"POL-D01","fit":"Partial","erpReq":"Foodics sales interface by outlet and menu item.","ricefw":"Interface","moscow":"Must","prev":"— (start)","next":"PA-17-S020","evId":"EV-OPS-7.1; EV-CC-3.3; EV-FD-029; EV-FD-146","evQuote":"sales usage is calculated by hand from POS and entered in the store Excel","taskId":"PA-17-T01","taskDesc":"POS sales import - Import item sales by outlet","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-17-S020', N'PA-17', 248, N'Store Operations', N'Retire', N'Non-system', N'{"id":"PA-17-S020","pa":"PA-17","phase":"1. Sales & recipe","scor":"Enable – Manage performance","stype":"Activity","asis":"Stores calculate usage by hand from the POS in Excel.","asisActor":"Store Manager","asisSys":"Excel","gapFlag":"Gap","gapDesc":"Manual usage calculation. (Root cause: outside the system)","change":"Retire","tobe":"Retired — replaced by S010–S060.","dept":"Store Operations","role":"Store Manager","pillars":"Data & Reporting","fit":"Non-system","moscow":"Must","prev":"PA-17-S010","next":"PA-17-S030","evId":"EV-CC-3.3","evQuote":"Stores calculate usage by hand from POS in Excel; POS not integrated with inventory."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-17-S030', N'PA-17', 249, N'Call Center', N'New', N'Not covered', N'{"id":"PA-17-S030","pa":"PA-17","phase":"1. Sales & recipe","scor":"Enable – Manage performance","stype":"Activity","asis":"Call Center order flow not described in any interview; Call Center brought into scope by the user.","change":"New","tobe":"Call Center orders are posted into Foodics under the fulfilling store, so they reach the ERP through the same Foodics sales interface as PA-17-S010; store item availability visible to the Call Center.","dept":"Call Center","role":"Call Center Supervisor; IT / ERP","sys":"Call Center platform ↔ Foodics ↔ D365","input":"Call Center orders","output":"Store sales incl. Call Center","pillars":"Data & Reporting | Tracking & Traceability","refs":"POL-D13 | POL-D27","fit":"Not covered","erpReq":"Call Center order channel in the sales interface; store availability view.","ricefw":"Interface","moscow":"Should","prev":"PA-17-S020","next":"PA-17-S040","evId":"EV-QL-P13; EV-QL-ES01"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-17-S040', N'PA-17', 250, N'Cost Control', N'Modify', N'Covered', N'{"id":"PA-17-S040","pa":"PA-17","phase":"1. Sales & recipe","scor":"Enable – Manage performance","stype":"Setup","asis":"Cost Control maps each production recipe to stores by brand; the branch recipe is the menu selling quantity.","asisActor":"Cost Control","asisSys":"MC","change":"Modify","tobe":"Every sold menu item mapped to an approved menu recipe and exploded into ingredients.","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Recipe explosion","input":"Imported sales; menu recipe (PA-11-S140)","output":"Exploded ingredients","pillars":"Master Data | Finance","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-17-S030","next":"PA-17-S050","evId":"EV-CC-7.1","evQuote":"Cost Control maps each production recipe to stores by brand","taskId":"PA-17-T02","taskDesc":"Recipe explosion - Map every sold item to an approved recipe","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-17-S050', N'PA-17', 251, N'Cost Control', N'New', N'Covered', N'{"id":"PA-17-S050","pa":"PA-17","phase":"2. Theoretical vs actual","scor":"Enable – Manage performance","stype":"Activity","asis":"— (no theoretical consumption today)","change":"New","tobe":"System calculates theoretical ingredient consumption from sales and recipes.","dept":"Cost Control","role":"System","sys":"D365 — Consumption","input":"Exploded ingredients","output":"Theoretical consumption","pillars":"Finance","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-17-S040","next":"PA-17-S060","evId":"From task list","taskId":"PA-17-T03","taskDesc":"Theoretical-consumption calculation - Calculate theoretical ingredient consumption","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-17-S060', N'PA-17', 252, N'Cost Control', N'Modify', N'Covered', N'{"id":"PA-17-S060","pa":"PA-17","phase":"2. Theoretical vs actual","scor":"Enable – Manage performance","stype":"Activity","asis":"User decision: actual consumption drives the cost.","change":"Modify","tobe":"System calculates actual stock movement and usage per site.","dept":"Cost Control","role":"System","sys":"D365 — Inventory transactions","input":"Stock movements","output":"Actual consumption","pillars":"Finance","refs":"POL-D11 | POL-D10","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-17-S050","next":"PA-17-S070","evId":"EV-QL-P11; EV-CC-3.1","evQuote":"actual consumption drives the cost","taskId":"PA-17-T04","taskDesc":"Actual-consumption calculation - Calculate actual stock movement and usage","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-17-S070', N'PA-17', 253, N'Cost Control', N'New', N'Partial', N'{"id":"PA-17-S070","pa":"PA-17","phase":"2. Theoretical vs actual","scor":"Enable – Manage performance","stype":"Activity","asis":"— (not separated today)","change":"New","tobe":"Approved wastage, transfers and count corrections excluded from usage before comparison.","dept":"Cost Control","role":"System","sys":"D365 — Consumption","input":"Actual consumption; wastage (PA-10); counts (PA-09)","output":"Net usage","pillars":"Finance","fit":"Partial","erpReq":"Confirm: Exclude approved wastage, transfers and count corrections from usage before theoretical vs actual.","ricefw":"Customization","moscow":"Must","prev":"PA-17-S060","next":"PA-17-S080","evId":"From task list","taskId":"PA-17-T05","taskDesc":"Wastage separation - Exclude approved wastage, transfers and count corrections correctly","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-17-S080', N'PA-17', 254, N'Cost Control', N'Modify', N'Partial', N'{"id":"PA-17-S080","pa":"PA-17","phase":"3. Variance & action","scor":"Enable – Manage performance","stype":"Control check","asis":"Costing verifies yield daily on a sample, gross-level basis; production chiefs check batch-wise; the two are not reconciled.","asisActor":"Costing; production chiefs","asisSys":"Sample checks","gapFlag":"Control Gap","gapDesc":"No actual-vs-standard report. (Root cause: outside the system)","openPoint":"D5 (FD review): daily inventory audit and daily entry into the system is not operationally feasible — review once to finalise the variance frequency (weekly by item / outlet proposed; daily for main items per POL-D06?)","confirmWith":"User; Finance Director; Cost Control; Operations","change":"Modify","tobe":"Theoretical vs actual compared by item, outlet / section and period. Variance feedback to stores today takes 10–15 days; target is in-month feedback (frequency per D5 review). [SLA: weekly by item and outlet; monthly for close — proposed]","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Variance report","input":"Theoretical consumption; net usage","output":"Consumption variance (RPT-17)","pillars":"Monitoring | Finance","refs":"CTL-17-1 | K-17-1","fit":"Partial","erpReq":"Confirm: Theoretical vs actual consumption report by item, outlet / section and period (Foodics sales × recipe).","ricefw":"Report","moscow":"Must","prev":"PA-17-S070","next":"PA-17-S090","evId":"EV-CC-3.2; EV-CPU-PRD-6.6; EV-QL-FD01; EV-FD-272; EV-FD-137; EV-FD-140","evQuote":"Costing verifies yield daily on a sample, gross-level basis; production chiefs check batch-wise; the two are not reconciled.","taskId":"PA-17-T06","taskDesc":"Variance calculation - Compare theoretical and actual quantities","solType":"Customization"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-17-S090', N'PA-17', 255, N'Cost Control', N'New', N'Non-system', N'{"id":"PA-17-S090","pa":"PA-17","phase":"3. Variance & action","scor":"Enable – Manage performance","stype":"Activity","asis":"— (deviation record kept ''somewhere'')","change":"New","tobe":"Consumption variances within the agreed level (AM-04) are actioned by the store / CPU owner; above the level they are investigated and signed off by Costing.","dept":"Cost Control","role":"Store Manager / CPU Chef (within AM-04); Costing (above level)","sys":"Manual (case log)","input":"Consumption variance","output":"Investigation","pillars":"Monitoring","refs":"POL-D22 | K-17-2","fit":"Non-system","moscow":"Must","prev":"PA-17-S080","next":"PA-17-S100","evId":"EV-QL-AM01; EV-FD-233","taskId":"PA-17-T07","taskDesc":"Investigation - Investigate material differences","solType":"Manual Process"}');
