INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-18-S010', N'PA-18', 258, N'Quality Control', N'Modify', N'Partial', N'{"id":"PA-18-S010","pa":"PA-18","phase":"1. Batch capture (prerequisite)","scor":"Return – Recall","stype":"Setup","asis":"Batch ID, production day and expiry printed on a physical sticker only; expiry and batch held only in the WMS; receiving checklist kept on paper.","asisActor":"CPU; Warehouse; QC","asisSys":"Sticker; WMS; paper","gapFlag":"Control Gap","gapDesc":"No end-to-end batch record. (Root cause: outside the system)","change":"Modify","tobe":"Batch and expiry recorded at receipt, production and dispatch for all items (fresh / daily by the agreed method) so the chain can be traced.","dept":"Quality Control","role":"QC Head","sys":"D365 — Batch tracking","input":"Trigger: start of process","output":"Batch trail","pillars":"Tracking & Traceability | Compliance & Food Safety","refs":"POL-D08","fit":"Partial","erpReq":"Confirm: Batch and expiry mandatory at receipt, production and dispatch; agreed method for fresh / daily items.","ricefw":"Configuration","moscow":"Must","prev":"— (start)","next":"PA-18-S020","evId":"EV-CPU-PRD-8.2; EV-WH-4.1; EV-QC-9.1","evQuote":"BATCH STICKER WITH EXPIRY — PHYSICAL ONLY, NOT IN THE SYSTEM"}');
