INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-19-S010', N'PA-19', 268, N'Cost Control', N'Retire', N'Non-system', N'{"id":"PA-19-S010","pa":"PA-19","phase":"1. Cut-off","scor":"Enable – Manage finance","stype":"Activity","asis":"Stores enter closing stock for all items in MC at month end when Costing opens it.","asisActor":"Stores; Costing","asisSys":"MC","gapFlag":"Gap","gapDesc":"Close depends on a once-a-month stock entry.","change":"Retire","tobe":"Retired — counts on schedule (PA-09) feed the close.","dept":"Cost Control","role":"Costing","pillars":"Finance","fit":"Non-system","moscow":"Must","prev":"— (start)","next":"PA-19-S020","evId":"EV-CC-6.1; EV-CC-6.2","evQuote":"Stores enter closing stock for all items in MC at month end when Costing opens it"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-19-S020', N'PA-19', 269, N'Warehouse', N'New', N'Covered', N'{"id":"PA-19-S020","pa":"PA-19","phase":"1. Cut-off","scor":"Enable – Manage finance","stype":"Control check","asis":"— (month-end close not described in any interview)","change":"New","tobe":"Close calendar (working days): WD-1 movements and transfers cut off; WD+2 counts and adjustments posted; WD+3 open receipts / transfers cleared and negative stock resolved; WD+4 overhead settlement (POL-D21) and inventory close; WD+5 Costing Head sign-off. Warehouse, CPU and outlets confirm all movements entered by WD-1. Open PO balances are never deleted at month end: each is closed or carried forward with a reason code and owner, before the next month''s PO is raised. Historic open PO lines (back to 2020 in the SPS extract) cleaned up before migration.","dept":"Warehouse","role":"Warehouse / CPU / Store leads","sys":"D365 — Close checklist","input":"Trigger: period end","output":"Close calendar","pillars":"Finance | Control","refs":"POL-D24","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-19-S010","next":"PA-19-S030","evId":"EV-QL-CC01; EV-FD-058; EV-SPS-04","taskId":"PA-19-T01","taskDesc":"Inventory-period cutoff - Warehouse confirms all movements are entered","solType":"Out of the Box"}');
