INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-20-S010', N'PA-20', 281, N'Data & Analytics', N'Modify', N'Partial', N'{"id":"PA-20-S010","pa":"PA-20","phase":"1. Define","scor":"Enable – Manage data","stype":"Setup","asis":"Batch / expiry data captured in the warehouse system is not developed to the stage that all stakeholders can access and use the reports.","asisActor":"Warehouse; stakeholders","asisSys":"Swish WMS","gapFlag":"Gap","gapDesc":"No agreed KPI catalogue; data not reportable to users.","change":"Modify","tobe":"KPI catalogue and one approved data definition per measure agreed.","dept":"Data & Analytics","role":"Data & Analytics lead; process owners","sys":"KPI catalogue","input":"Trigger: start of process","output":"Approved KPI catalogue","pillars":"Data & Reporting","refs":"POL-D12","fit":"Partial","erpReq":"Solution type ''To Be Assessed'' in tasks — provider to confirm.","ricefw":"Report","moscow":"Must","prev":"— (start)","next":"PA-20-S020","evId":"EV-CPU-OR-19.2","evQuote":"that system is not developed to the stage that all the stakeholders","taskId":"PA-20-T01","taskDesc":"Define KPI catalogue and data definitions - Agree one approved data definition per KPI with Finance and Cost Control","solType":"To Be Assessed (TBA)"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-20-S020', N'PA-20', 282, N'Data & Analytics', N'Modify', N'Partial', N'{"id":"PA-20-S020","pa":"PA-20","phase":"2. Build","scor":"Enable – Manage data","stype":"Report","asis":"MC gives no collective screen or report of production volume at product / Swish-article level; manual sheets used.","asisActor":"CBU; CPU","asisSys":"Manual sheets","gapFlag":"Gap","gapDesc":"No operational views. (Root cause: outside the system)","change":"Modify","tobe":"ERP workspaces and inquiries built for each role (production volume by section, open transfers, near-expiry, variances).","dept":"Data & Analytics","role":"Data & Analytics; IT / ERP","sys":"D365 workspaces","input":"Approved KPI catalogue","output":"Workspaces","pillars":"Data & Reporting","fit":"Partial","erpReq":"Solution type ''To Be Assessed'' in tasks — provider to confirm.","ricefw":"Report","moscow":"Must","prev":"PA-20-S010","next":"PA-20-S030","evId":"EV-CBU-3.9","evQuote":"NO CONSOLIDATED PRODUCTION-VOLUME VIEW IN MC","taskId":"PA-20-T02","taskDesc":"Build Dynamics workspaces and inquiries - Build required Dynamics workspaces and saved inquiries","solType":"To Be Assessed (TBA)"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-20-S030', N'PA-20', 283, N'Data & Analytics', N'Modify', N'Partial', N'{"id":"PA-20-S030","pa":"PA-20","phase":"2. Build","scor":"Enable – Manage data","stype":"Report","asis":"Interim demand-planning output in Power BI is store-wise, not mapped to the CPU production line by section or product group.","asisActor":"Data & Analytics","asisSys":"Power BI (interim)","gapFlag":"Gap","gapDesc":"Reports not shaped to users.","change":"Modify","tobe":"Power BI dashboards configured by company, brand, section and role.","dept":"Data & Analytics","role":"Data & Analytics","sys":"Power BI","input":"Workspaces","output":"Dashboards","pillars":"Data & Reporting","fit":"Partial","erpReq":"Solution type ''To Be Assessed'' in tasks — provider to confirm.","ricefw":"Report","moscow":"Must","prev":"PA-20-S020","next":"PA-20-S040","evId":"EV-CPU-MGT-4.2","evQuote":"It is NOT mapped to the CPU production line by section or by product group.","taskId":"PA-20-T03","taskDesc":"Configure Power BI dashboards by role and brand - Configure Power BI dashboards segmented by company, brand and role","solType":"To Be Assessed (TBA)"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-20-S040', N'PA-20', 284, N'IT / ERP', N'New', N'Partial', N'{"id":"PA-20-S040","pa":"PA-20","phase":"3. Assure","scor":"Enable – Manage data","stype":"Control check","asis":"— (not described)","change":"New","tobe":"Alerts configured for data-integration failures (Foodics, WMS, temperature system).","dept":"IT / ERP","role":"IT / ERP","sys":"Integration monitor","input":"Dashboards (PA-20-S030)","output":"Integration failure alerts","pillars":"Monitoring | Data & Reporting","refs":"CTL-20-1","fit":"Partial","erpReq":"Solution type ''To Be Assessed'' in tasks — provider to confirm.","ricefw":"Interface","moscow":"Must","prev":"PA-20-S030","next":"PA-20-S050","evId":"From task list","taskId":"PA-20-T04","taskDesc":"Set data-integration monitoring and alerting - Configure alerting for data-integration failures","solType":"To Be Assessed (TBA)"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-20-S050', N'PA-20', 285, N'Data & Analytics', N'New', N'Partial', N'{"id":"PA-20-S050","pa":"PA-20","phase":"3. Assure","scor":"Enable – Manage data","stype":"Setup","asis":"— (not described)","change":"New","tobe":"Named owners and escalation rules assigned for each report exception.","dept":"Data & Analytics","role":"Data & Analytics; process owners","sys":"RACI / workspace","input":"Integration failure alerts (PA-20-S040)","output":"Report exception owner list","pillars":"Monitoring","fit":"Partial","erpReq":"Solution type ''To Be Assessed'' in tasks — provider to confirm.","moscow":"Should","prev":"PA-20-S040","next":"PA-20-S060","evId":"From task list","taskId":"PA-20-T05","taskDesc":"Assign exception ownership and escalation rules - Assign named owners for each reporting exception category","solType":"To Be Assessed (TBA)"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-20-S060', N'PA-20', 286, N'Data & Analytics', N'New', N'Partial', N'{"id":"PA-20-S060","pa":"PA-20","phase":"3. Assure","scor":"Enable – Manage data","stype":"Control check","asis":"— (not described)","change":"New","tobe":"Sample dashboard figures reconciled to ERP transactions before release.","dept":"Data & Analytics","role":"Data & Analytics; Cost Controller","sys":"Power BI / D365","input":"Report exception owner list (PA-20-S050)","output":"Dashboard reconciliation","pillars":"Control | Data & Reporting","refs":"CTL-20-1 | K-20-1","fit":"Partial","erpReq":"Solution type ''To Be Assessed'' in tasks — provider to confirm.","ricefw":"Report","moscow":"Must","prev":"PA-20-S050","next":"PA-20-S070","evId":"From task list","taskId":"PA-20-T06","taskDesc":"Validate dashboard-to-transaction reconciliation - Reconcile sample dashboard figures to underlying transactions before go-live","solType":"To Be Assessed (TBA)"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-20-S070', N'PA-20', 287, N'IT / ERP', N'New', N'Partial', N'{"id":"PA-20-S070","pa":"PA-20","phase":"3. Assure","scor":"Enable – Manage data","stype":"Control check","asis":"— (not described)","change":"New","tobe":"Access tested and confirmed by company, brand and role.","dept":"IT / ERP","role":"IT / ERP security","sys":"D365 / Power BI security","input":"Dashboard reconciliation (PA-20-S060)","output":"Access test record","pillars":"Access & Segregation of Duties","refs":"CTL-20-2","fit":"Partial","erpReq":"Solution type ''To Be Assessed'' in tasks — provider to confirm.","ricefw":"Configuration","moscow":"Must","prev":"PA-20-S060","next":"— (end)","evId":"From task list","taskId":"PA-20-T07","taskDesc":"Roll out access control by company, brand and role - Test and confirm access-control boundaries by company, brand and role","solType":"To Be Assessed (TBA)"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-21-S010', N'PA-21', 288, N'Purchase', N'Modify', N'Covered', N'{"id":"PA-21-S010","pa":"PA-21","phase":"1. Setup","scor":"Source – Receive","stype":"Setup","asis":"Direct-issue items (dairy, vegetables, chilled, some frozen, meat, poultry) are approved Swish articles with a fixed approved vendor list given to CPU.","asisActor":"Purchase; CPU","asisSys":"Approved lists","change":"Modify","tobe":"Categories eligible for direct-to-CPU delivery approved and flagged per item / vendor.","dept":"Purchase","role":"Purchase Chief (approver)","sys":"D365 — Item / vendor flag","input":"Trigger: start of process","output":"Direct-to-CPU list","pillars":"Master Data","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"— (start)","next":"PA-21-S020","evId":"EV-CPU-OR-3.2; EV-CPU-OR-3.1","evQuote":"These items are already approved Swish article and the approved vendor list is also fixed and finalized, given to the CPU team.","taskId":"PA-21-T01","taskDesc":"Category eligibility approval (which items may route direct-to-CPU) - Approve category list eligible for direct-to-CPU delivery","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-21-S020', N'PA-21', 289, N'Purchase', N'Modify', N'Covered', N'{"id":"PA-21-S020","pa":"PA-21","phase":"1. Setup","scor":"Source – Receive","stype":"Setup","asis":"Bulk PO on a monthly volume, derived from historical pattern and upcoming trend, revised monthly; registered and approved in MC by Purchase with Costing''s supervision.","asisActor":"Purchase; Costing","asisSys":"MC bulk PO","change":"Modify","tobe":"Bulk PO / purchase agreement raised with the direct-to-CPU delivery flag, rates and validity; a monthly forecast-vs-actual consumption report per agreement is reviewed by Purchase and Costing before the next month''s volume is set.","dept":"Purchase","role":"Buyer; Cost Controller (rate approval)","sys":"D365 — Purchase agreement","input":"Direct-to-CPU list","output":"Bulk agreement","pillars":"Finance | Control","refs":"POL-D09","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-21-S010","next":"PA-21-S030","evId":"EV-CPU-OR-2.1; EV-CPU-OR-2.5; EV-CC-5.3","evQuote":"approximately derived based on the historical pattern and the upcoming trend","taskId":"PA-21-T02","taskDesc":"PO creation with direct-to-CPU delivery flag - Raise PO flagged for direct-to-CPU routing","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-21-S030', N'PA-21', 290, N'CPU / CBU', N'Retire', N'Non-system', N'{"id":"PA-21-S030","pa":"PA-21","phase":"2. Order","scor":"Source – Receive","stype":"Activity","asis":"CPU Administrator places daily orders in a separate WhatsApp group per approved vendor, treated as official communication.","asisActor":"CPU Administrator","asisSys":"WhatsApp groups","gapFlag":"Control Gap","gapDesc":"Orders exist only in chat. (Root cause: outside the system)","change":"Retire","tobe":"Retired — replaced by S040.","dept":"CPU / CBU","role":"CPU Administrator","pillars":"Control","refs":"POL-D11","fit":"Non-system","moscow":"Must","prev":"PA-21-S020","next":"PA-21-S040","evId":"EV-CPU-OR-3.5; EV-CC-0.31","evQuote":"One separate WhatsApp group per approved vendor handling direct issue."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-21-S040', N'PA-21', 291, N'CPU / CBU', N'New', N'Not covered', N'{"id":"PA-21-S040","pa":"PA-21","phase":"2. Order","scor":"Source – Receive","stype":"Activity","asis":"— (see S030)","change":"New","tobe":"Daily call-off released in the ERP against the bulk agreement and sent to the vendor; WhatsApp for coordination only, outcome recorded. [SLA: daily, before the vendor''s cut-off — proposed]","dept":"CPU / CBU","role":"CPU Administrator","sys":"D365 — Release order","input":"Bulk agreement","output":"Call-off order","pillars":"Control | Process","refs":"POL-D11 | POL-D04","fit":"Not covered","erpReq":"Daily release order from agreement; vendor notification.","ricefw":"Configuration + Interface","moscow":"Must","prev":"PA-21-S030","next":"PA-21-S050","evId":"EV-CPU-OR-3.5 (Recommended)"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-21-S050', N'PA-21', 292, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-21-S050","pa":"PA-21","phase":"3. Receive","scor":"Source – Receive","stype":"Activity","asis":"For direct-issue deliveries the CPU Administrator checks quality, temperature and hygiene at the truck and any volume difference.","asisActor":"CPU Administrator","asisSys":"Physical","change":"Modify","tobe":"Delivery registered at the CPU receiving bay.","dept":"CPU / CBU","role":"CPU Receiver","sys":"D365 — Arrival","input":"Call-off order","output":"Arrival record","pillars":"Process","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-21-S040","next":"PA-21-S060","evId":"EV-CPU-OR-4.1","evQuote":"the CPU administrator is the prominent resource to check the quality, temperature, and the hygiene condition at the truck","taskId":"PA-21-T03","taskDesc":"CPU receiving-bay delivery arrival - Receive delivery at CPU receiving bay","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-21-S060', N'PA-21', 293, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-21-S060","pa":"PA-21","phase":"3. Receive","scor":"Source – Receive","stype":"Control check","asis":"Quantity is measured on receipt; declared 5 kg is often 4.5 kg (vegetables); vegetables come with a delivery note, not an invoice.","asisActor":"CPU Administrator","asisSys":"Scale; delivery note","gapFlag":"Gap","gapDesc":"Differences recorded by hand.","change":"Modify","tobe":"Quantity and documents checked against the call-off; measured quantity recorded.","dept":"CPU / CBU","role":"CPU Receiver","sys":"D365 — Product receipt","input":"Arrival record","output":"Checked quantity","pillars":"Control","refs":"CTL-21-1","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-21-S050","next":"PA-21-S070","evId":"EV-CPU-OR-4.3; EV-CPU-OR-4.2","evQuote":"the quantities they would have mentioned as 5 kg, but when we measure we will found 4.5 kg.","taskId":"PA-21-T04","taskDesc":"Document and quantity check - Check quantity and documents against PO","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-21-S070', N'PA-21', 294, N'Quality Control', N'Modify', N'Partial', N'{"id":"PA-21-S070","pa":"PA-21","phase":"3. Receive","scor":"Source – Receive","stype":"Control check","asis":"Supplier vehicle temperature is monitored and recorded by the quality team (CPU Administrator when QC is not available).","asisActor":"QC; CPU Administrator","asisSys":"Manual record","change":"Modify","tobe":"Batch, expiry and temperature captured on the receipt.","dept":"Quality Control","role":"QC Officer / CPU Receiver","sys":"D365 — Receipt (temperature, batch)","input":"Checked quantity","output":"Batch & temperature record","pillars":"Compliance & Food Safety | Tracking & Traceability","refs":"CTL-21-2 | POL-D07 | POL-D08 | POL-D15","fit":"Partial","erpReq":"Confirm: Batch, expiry and temperature fields mandatory on CPU receipt.","ricefw":"Customization","moscow":"Must","prev":"PA-21-S060","next":"PA-21-S080","evId":"EV-CPU-OR-4.5","evQuote":"the supplier vehicle temperature is monitored and recorded by the quality team","taskId":"PA-21-T05","taskDesc":"Batch, expiry and temperature check - Capture batch, expiry and temperature reading","solType":"Customization + Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-21-S080', N'PA-21', 295, N'Quality Control', N'Modify', N'Covered', N'{"id":"PA-21-S080","pa":"PA-21","phase":"3. Receive","scor":"Source – Receive","stype":"Control check","asis":"Specification discrepancies occur (e.g. tomato size and texture differ from the order).","asisActor":"CPU Administrator","asisSys":"Physical","gapFlag":"Gap","gapDesc":"No item specification on the order.","change":"Modify","tobe":"Quality decision recorded: accept, reject or quarantine, against the item specification.","dept":"Quality Control","role":"QC Officer","sys":"D365 — Quality order","input":"Batch & temperature record","output":"Quality decision","pillars":"Compliance & Food Safety","refs":"CTL-21-2 | POL-D15","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-21-S070","next":"PA-21-S090","evId":"EV-CPU-OR-4.4","evQuote":"we ordered for tomato with specific size and specific texture","taskId":"PA-21-T06","taskDesc":"Quality decision (accept / reject / quarantine) - Decide accept, reject or quarantine","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-21-S090', N'PA-21', 296, N'CPU / CBU', N'Retire', N'Non-system', N'{"id":"PA-21-S090","pa":"PA-21","phase":"3. Receive","scor":"Source – Receive","stype":"Exception","asis":"Differences and rejections are written by hand on the receiving document; rejected goods go back on the same truck with one copy.","asisActor":"CPU Administrator","asisSys":"Paper GRN","gapFlag":"Gap","gapDesc":"Rejections on paper. (Root cause: outside the system)","change":"Retire","tobe":"Retired — accepted, short and rejected quantities recorded on the receipt with return to vendor.","dept":"CPU / CBU","role":"CPU Administrator","pillars":"Control","fit":"Non-system","moscow":"Must","prev":"PA-21-S080","next":"PA-21-S100","evId":"EV-CPU-OR-4.7; EV-CPU-OR-4.6","evQuote":"Any rejection we will just mention in that manually in the document"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-21-S100', N'PA-21', 297, N'CPU / CBU', N'Modify', N'Covered', N'{"id":"PA-21-S100","pa":"PA-21","phase":"4. Post","scor":"Source – Receive","stype":"Control check","asis":"CPU Administrator enters the quantity alone (price prefixed on the bulk PO); the same person orders and receives; entered and physical quantity are not independently checked.","asisActor":"CPU Administrator","asisSys":"MC GRN","gapFlag":"Control Gap","gapDesc":"No segregation between ordering and receiving. (Root cause: open user administration)","change":"Modify","tobe":"Product receipt posted by an authorised receiver who did not place the order (CPU Chef / Supervisor). [SLA: same day as delivery — proposed]","dept":"CPU / CBU","role":"CPU Chef / Supervisor (receiver)","sys":"D365 — Product receipt; security roles","input":"Quality decision","output":"Posted receipt","pillars":"Access & Segregation of Duties | Control","refs":"CTL-R05 | CTL-21-1 | POL-D05 | K-21-1","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-21-S090","next":"PA-21-S110","evId":"EV-CPU-OR-4.8; EV-CC-0.41; EV-CC-0.43; EV-CPU-MGT-7.4","evQuote":"the CPU Administrator enters the QUANTITY ALONE in the system","taskId":"PA-21-T07","taskDesc":"Product receipt posting - Post product receipt in Dynamics","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-21-S110', N'PA-21', 298, N'Purchase', N'Modify', N'Partial', N'{"id":"PA-21-S110","pa":"PA-21","phase":"4. Post","scor":"Source – Receive","stype":"Exception","asis":"When the invoice price differs, CPU cannot enter the price; it enters quantity only and Purchase obtains a revised invoice; the vegetable invoice comes with the next delivery.","asisActor":"CPU Administrator; Purchase","asisSys":"MC","gapFlag":"Control Gap","gapDesc":"System value differs from supplier document. (Root cause: rate contract without timeline / audit trail)","change":"Modify","tobe":"Price or quantity differences settled by credit / debit note against the receipt; invoice matched in PA-25. [SLA: within the month of receipt — proposed]","dept":"Purchase","role":"Buyer; AP Accountant","sys":"D365 — Credit / debit note","input":"Posted receipt","output":"Settled difference","pillars":"Finance","refs":"POL-R02 | POL-D09","fit":"Partial","erpReq":"Confirm: Price / quantity differences settled by credit / debit note against the receipt; invoice matching.","ricefw":"Configuration","moscow":"Must","prev":"PA-21-S100","next":"PA-21-S120","evId":"EV-CPU-OR-7.3; EV-CPU-OR-7.5; EV-CPU-OR-7.6","evQuote":"the CPU is not allowed to enter the price content itself in the material control system"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-21-S120', N'PA-21', 299, N'CPU / CBU', N'Retire', N'Non-system', N'{"id":"PA-21-S120","pa":"PA-21","phase":"4. Post","scor":"Source – Receive","stype":"Exception","asis":"When quantity is rejected or wasted, either the invoice is amended or extra quantity is supplied the next day (not entered in the system).","asisActor":"Vendor; CPU","gapFlag":"Control Gap","gapDesc":"Unrecorded top-ups. (Root cause: outside the system)","change":"Retire","tobe":"Retired — top-ups received as zero-price lines (PA-04-S140).","dept":"CPU / CBU","role":"CPU Administrator","pillars":"Finance | Control","fit":"Non-system","moscow":"Must","prev":"PA-21-S110","next":"PA-21-S130","evId":"EV-CC-0.42; EV-CPU-OR-14.6","evQuote":"invoice should be amended or additional quantity will be supplied in next day"}');
