INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-22-S080', N'PA-22', 308, N'Finance', N'New', N'Not covered', N'{"id":"PA-22-S080","pa":"PA-22","phase":"4. Retail / cooperative channel","scor":"Enable – Manage business rules","stype":"Activity","asis":"Around 10–15% of bakery output is sold through a direct retail channel (frozen pizza-type items and similar); how retail / cooperative customers order, are supplied and invoiced is not described.","asisActor":"CBU","asisSys":"Not identified","change":"New","tobe":"CBU sells to registered retail / cooperative customers through ERP sales orders on an approved price list; dispatch through PA-16 with batch and expiry; invoiced by the entity that owns CBU (EGC); margin reported by channel.","dept":"Finance","role":"Commercial owner (to confirm); Finance Manager","sys":"D365 — Sales order, invoicing","input":"Customer order","output":"Dispatch; customer invoice; channel margin","pillars":"Finance | Tracking & Traceability","refs":"POL-D13 | POL-D27","fit":"Not covered","erpReq":"Customer master, price list, sales order to invoice.","ricefw":"Configuration","moscow":"Should","prev":"PA-22-S070","next":"— (end)","evId":"EV-CBU-7.6; EV-QL-P13; EV-QL-ES01","evQuote":"around 10 to 15 percent of total bakery output volume falls into a DIRECT RETAIL SALE category"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-23-S010', N'PA-23', 309, N'IT / ERP', N'New', N'Non-system', N'{"id":"PA-23-S010","pa":"PA-23","phase":"1. Data","scor":"Enable – Manage technology","stype":"Activity","asis":"Documentation and approvals sit in Word, Excel, PDF, email and WhatsApp; two recipe records exist.","gapFlag":"Gap","gapDesc":"Master and transaction data held in several places.","change":"New","tobe":"All legacy sources inventoried and cleansed (MC, Swish WMS and portals, Excel / Word files, manual recipe book). Duplicate article numbers from the ERMG merge resolved before migration; one article per item. Includes the Swish SPS replenishment workbook: about 2,250 article parameters cleansed (519 ''To be deactivated'' and 385 non-moving items reviewed before migration; duplicate descriptions resolved).","dept":"IT / ERP","role":"Data Migration Lead; data owners","sys":"Migration workbook","input":"N/A — project / readiness step","output":"N/A — project / readiness step","pillars":"Master Data","fit":"Non-system","erpReq":"Implementation activity.","ricefw":"Conversion","moscow":"Must","prev":"— (start)","next":"PA-23-S020","evId":"EV-PUR-9.2; EV-CPU-MGT-2.4; EV-FD-194; EV-SPS-07","evQuote":"all purchase documentation and the approval workflow are currently in Word, Excel or PDF","taskId":"PA-23-T01","taskDesc":"Legacy data inventory and cleansing - Inventory all legacy source files (MC system, warehouse app, maintenance app, Office costing/purchasing)","solType":"Implementation Activity"}');
