INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-23-S060', N'PA-23', 314, N'Operational Excellence', N'New', N'Non-system', N'{"id":"PA-23-S060","pa":"PA-23","phase":"3. UAT","scor":"Enable – Manage technology","stype":"Approval","asis":"— (implementation activity; no as-is)","change":"New","tobe":"UAT executed and formally signed off by department heads.","dept":"Operational Excellence","role":"Department heads (sign-off)","sys":"UAT log","input":"N/A — project / readiness step","output":"N/A — project / readiness step","pillars":"Control | People & Training","refs":"CTL-23-1","fit":"Non-system","erpReq":"Implementation activity.","moscow":"Must","prev":"PA-23-S050","next":"PA-23-S065","evId":"From task list","taskId":"PA-23-T06","taskDesc":"UAT execution and sign-off - Execute UAT and obtain formal sign-off","solType":"Implementation Activity"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-23-S065', N'PA-23', 315, N'IT / ERP', N'New', N'Non-system', N'{"id":"PA-23-S065","pa":"PA-23","phase":"4. Cutover","scor":"Enable – Manage technology","stype":"Approval","openPoint":"Wave order and dependencies to be finalised with the ERP consultant (implementation partner) at design stage.","confirmWith":"ERP consultant; IT / ERP Manager; department heads","change":"New","tobe":"Implementation waves within Project 1 (supply chain ERP) agreed with the ERP consultant before build, in dependency order: W1 Foundation (item / UOM / vendor / site / store masters, process ownership, EGC supply model POL-D30, approval matrix) → W2 Core inventory transactions (PO, receiving, storage, transfers, store receipt, counts, adjustments) → W3 CPU / CBU (catalogue, production / BOM, QC release, dispatch) → W4 Cost control (recipe / BOM governance, standard cost, wastage reasons, actual vs theoretical, COGS) → W5 Optimisation (advanced forecasting, safety-stock tuning, expiry analytics). Each wave has an entry gate (previous wave data signed off) and its own UAT. [SLA: agreed before build starts — proposed]","dept":"IT / ERP","role":"IT / ERP Manager; ERP consultant · Approver: Management (programme sponsor)","sys":"Implementation plan","input":"Master (all processes); UAT scenarios (PA-23-S050)","output":"Approved wave plan","pillars":"Control | Process","refs":"POL-D32 | POL-D01","fit":"Non-system","moscow":"Must","prev":"PA-23-S060","next":"PA-23-S070","evId":"EV-FD-297; EV-FD-299; EV-FD-300; EV-FD-301; EV-FD-302; EV-FD-303; EV-QL-FD02"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-23-S070', N'PA-23', 316, N'IT / ERP', N'New', N'Non-system', N'{"id":"PA-23-S070","pa":"PA-23","phase":"4. Cutover","scor":"Enable – Manage technology","stype":"Setup","asis":"MC and Swish platforms to be replaced in phases with integration in the meantime (user decision).","change":"New","tobe":"Programme cutover by project (POL-D32): Project 1 — supply chain ERP (core inventory, purchasing, warehouse, CPU / CBU production, costing and the Foodics integration), built in waves W1–W5 (PA-23-S065); MC is retired only when W1–W4 are live and reconciled, with MC and the ERP run in parallel for affected sites until then. Project 2 — Swish portals / warehouse system replaced (integrated with the ERP meanwhile) and overhead absorption (POL-D21). Project 3 — POS replacement (PA-24; Foodics stays integrated, limited D365 Store Commerce from Project 1 per POL-D31) and franchise readiness. [SLA: per approved programme plan — proposed]","dept":"IT / ERP","role":"Programme Manager","sys":"Cutover plan","input":"N/A — project / readiness step","output":"N/A — project / readiness step","pillars":"Control | Process","refs":"POL-D01 | POL-D27","fit":"Non-system","erpReq":"Implementation activity.","moscow":"Must","prev":"PA-23-S065","next":"PA-23-S080","evId":"EV-QL-P01; EV-QL-ES01","evQuote":"D365 or any ERP shall target replacing MC","taskId":"PA-23-T04","taskDesc":"Cutover planning and sequencing - Plan cutover sequence and freeze windows","solType":"Implementation Activity"}');
