INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-24-S080', N'PA-24', 327, N'IT / ERP', N'New', N'Non-system', N'{"id":"PA-24-S080","pa":"PA-24","phase":"2. POS replacement (Project 3)","scor":"Enable – Manage technology","stype":"Activity","asis":"— (Project 3 — POS replacement; out of current scope)","change":"New","tobe":"Project 3 (POS replacement): decommission Foodics.","dept":"IT / ERP","role":"IT / ERP; Operations","sys":"D365 Commerce (Project 3)","input":"N/A — project / readiness step","output":"N/A — project / readiness step","pillars":"Process","fit":"Non-system","erpReq":"Out of scope – Project 3 — POS replacement.","moscow":"Won''t","prev":"PA-24-S070","next":"— (end)","evId":"From task list","taskId":"PA-24-T07","taskDesc":"Decommission Foodics - Decommission Foodics once rollout is complete","solType":"Out of Scope – Phase 2"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S010', N'PA-25', 328, N'Purchase', N'Modify', N'Covered', N'{"id":"PA-25-S010","pa":"PA-25","phase":"1. Vendor & sourcing","scor":"Source – Identify sources","stype":"Setup","asis":"Purchase verifies the approved vendor list and the approved item list.","asisActor":"Purchase","asisSys":"MC — approved lists","gapFlag":"Check","gapDesc":"Not established whether the approved vendor list has a review or expiry cycle.","change":"Modify","tobe":"New vendors vetted and onboarded against approval criteria; each vendor approval carries a review date and lapses if not renewed. Supplier onboarding through an ERP workflow (required fields, price validity, lead time, MOQ, substitute rules) replacing the manual form; Legal and Finance approve and the authorised signatory signs before the vendor account is opened.","dept":"Purchase","role":"Purchase Chief (approver)","sys":"D365 — Vendor onboarding","input":"Trigger: start of process","output":"Approved vendor","pillars":"Master Data | Control","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"— (start)","next":"PA-25-S020","evId":"EV-INV-3.0; EV-PUR-0.2; EV-FD-045; EV-FD-062","evQuote":"Verify the approved vendor list and the approved item list.","taskId":"PA-25-T01","taskDesc":"Vendor onboarding and vetting - Vet and onboard new vendors against approved criteria","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S020', N'PA-25', 329, N'Purchase', N'Modify', N'Covered', N'{"id":"PA-25-S020","pa":"PA-25","phase":"1. Vendor & sourcing","scor":"Source – Identify sources","stype":"Activity","asis":"For a new item, an RFQ is raised, two to three quotations are received, compared and finalised; documents and approvals in Word / Excel / PDF with email and WhatsApp.","asisActor":"Purchase","asisSys":"Word / Excel / PDF; email","gapFlag":"Control Gap","gapDesc":"Sourcing outside any system; no audit trail. (Root cause: outside the system)","change":"Modify","tobe":"RFQ / tender run in the ERP for material categories; quotations captured and compared; selection reason recorded.","dept":"Purchase","role":"Buyer","sys":"D365 — RFQ","input":"Requirement","output":"Selected vendor / quote","pillars":"Control | Process","refs":"POL-D16","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-25-S010","next":"PA-25-S030","evId":"EV-PUR-3.1; EV-PUR-9.2; EV-PUR-0.7","evQuote":"an RFQ is raised, two to three suppliers'' quotations are received, compared and finalised","taskId":"PA-25-T02","taskDesc":"Tender / RFQ management - Run tender / RFQ process for material categories above threshold","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S030', N'PA-25', 330, N'Purchase', N'Modify', N'Partial', N'{"id":"PA-25-S030","pa":"PA-25","phase":"1. Vendor & sourcing","scor":"Source – Identify sources","stype":"Control check","asis":"Market stock availability is checked against the approved list before proceeding.","asisActor":"Purchase / Warehouse","asisSys":"Market enquiry","gapFlag":"Gap","gapDesc":"Finding not recorded.","change":"Modify","tobe":"Market availability confirmation recorded against the requisition line (vendor contacted, date, outcome).","dept":"Purchase","role":"Buyer","sys":"D365 — Requisition notes","input":"Selected vendor / quote (PA-25-S020)","output":"Market availability record","pillars":"Process","fit":"Partial","erpReq":"Confirm: Record vendor availability check (vendor, date, outcome) on the requisition line.","ricefw":"Configuration","moscow":"Could","prev":"PA-25-S020","next":"PA-25-S040","evId":"EV-INV-3.1","evQuote":"Check market stock availability against the approved list and proceed."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S040', N'PA-25', 331, N'Purchase', N'Modify', N'Partial', N'{"id":"PA-25-S040","pa":"PA-25","phase":"1. Vendor & sourcing","scor":"Source – Identify sources","stype":"Exception","asis":"If stock or an approved vendor option is not available, an alternate is confirmed by direct communication within the department.","asisActor":"Purchase","asisSys":"Oral / internal communication","gapFlag":"Control Gap","gapDesc":"No record of who approved the alternate. (Root cause: outside the system)","change":"Modify","tobe":"Alternate raised in the ERP with reason and routed through the substitution approval (PA-15); Costing notified of rate differences.","dept":"Purchase","role":"Buyer; Costing","sys":"D365 — Substitution workflow","input":"Market availability record (PA-25-S030)","output":"Alternate item request","pillars":"Control","refs":"POL-D17","fit":"Partial","erpReq":"Confirm: Alternate item / vendor request with reason routed to substitution approval; Costing notified.","ricefw":"Workflow","moscow":"Must","prev":"PA-25-S030","next":"PA-25-S050","evId":"EV-INV-3.2","evQuote":"direct communication within the department to confirm an alternate"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S050', N'PA-25', 332, N'R&D', N'Modify', N'Partial', N'{"id":"PA-25-S050","pa":"PA-25","phase":"1. Vendor & sourcing","scor":"Source – Identify sources","stype":"Approval","asis":"Non-approved-list items are encouraged with a sample issued to R&D, who may send it to the relevant department; what happens next is not recorded.","asisActor":"Purchase; R&D","asisSys":"Physical sample; email","gapFlag":"Control Gap","gapDesc":"Open-ended evaluation; R&D has no role in the system. (Root cause: outside the system)","change":"Modify","tobe":"Sample evaluation logged against the candidate vendor / item; R&D records approved / rejected / conditional; approved items added to the approved lists with an effective date.","dept":"R&D","role":"R&D (approver); Purchase","sys":"D365 — Vendor / item approval","input":"Alternate item request (PA-25-S040)","output":"Sample evaluation record","pillars":"Control | Master Data","refs":"POL-D17","fit":"Partial","erpReq":"Confirm: Sample evaluation record per vendor / item with R&D decision (approved / rejected / conditional).","ricefw":"Workflow","moscow":"Must","prev":"PA-25-S040","next":"PA-25-S060","evId":"EV-INV-3.3","evQuote":"Non-approved-list items are generally encouraged with a sample issued to R&D"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S060', N'PA-25', 333, N'Purchase', N'Modify', N'Covered', N'{"id":"PA-25-S060","pa":"PA-25","phase":"2. Purchase order","scor":"Source – Identify sources","stype":"Activity","asis":"Purchase request converted into a PO by selecting the purchase article, vendor article or purchase item name, with or without correction.","asisActor":"Purchase","asisSys":"MC — purchase order","gapFlag":"Control Gap","gapDesc":"Article can change at conversion. (Root cause: no variant setup)","change":"Modify","tobe":"Requirement converts to PO with the variant-level article carried through; any correction recorded as an amendment against the original line.","dept":"Purchase","role":"Buyer","sys":"D365 — Purchase order","input":"Firm order (PA-03-S150)","output":"Draft PO","pillars":"Control | Tracking & Traceability","refs":"POL-D03","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-25-S050","next":"PA-25-S070","evId":"EV-INV-4.0","evQuote":"Purchase request converted into a Purchase Order by selecting the purchase article, vendor article or purchase item name"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S070', N'PA-25', 334, N'Purchase', N'Modify', N'Partial', N'{"id":"PA-25-S070","pa":"PA-25","phase":"2. Purchase order","scor":"Source – Identify sources","stype":"Control check","asis":"Quantity can be amended between PR and PO, with no approval request back to the requesting department.","asisActor":"Purchase","asisSys":"MC — purchase order","gapFlag":"Control Gap","gapDesc":"Requester not informed of quantity change. (Root cause: outside the system)","change":"Modify","tobe":"Quantity change beyond tolerance routes to the requesting department for confirmation before release.","dept":"Purchase","role":"Buyer; Requesting department (confirms)","sys":"D365 — PO change workflow","input":"Draft PO (PA-25-S060)","output":"Requester quantity confirmation","pillars":"Control","refs":"POL-D03","fit":"Partial","erpReq":"Confirm: Quantity change beyond tolerance routed to the requester for confirmation before PO release.","ricefw":"Workflow","moscow":"Must","prev":"PA-25-S060","next":"PA-25-S080","evId":"EV-INV-4.1","evQuote":"Quantity can be amended between PR and PO."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S080', N'PA-25', 335, N'Purchase', N'Keep', N'Covered', N'{"id":"PA-25-S080","pa":"PA-25","phase":"2. Purchase order","scor":"Source – Identify sources","stype":"Approval","asis":"Purchase team applies maker and checker before final PO generation.","asisActor":"Purchase","asisSys":"MC","change":"Keep","tobe":"PO released under maker-checker: the preparer cannot approve their own PO; checker authority by value band. [SLA: within 1 working day of PO creation — proposed]","dept":"Purchase","role":"Purchase Chief (checker)","sys":"D365 — PO approval workflow","input":"Draft PO","output":"Approved PO","pillars":"Access & Segregation of Duties | Control","refs":"CTL-25-1 | POL-D05 | POL-D16","fit":"Covered","ricefw":"Workflow","moscow":"Must","prev":"PA-25-S070","next":"PA-25-S090","evId":"EV-CC-0.14","evQuote":"Purchase team have maker, checker concept before final PO generation"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S090', N'PA-25', 336, N'Purchase', N'Modify', N'Covered', N'{"id":"PA-25-S090","pa":"PA-25","phase":"2. Purchase order","scor":"Source – Identify sources","stype":"Hand-off","asis":"Digital PO shared to the vendor by an MC-generated link in email, plus a manual email and a WhatsApp update.","asisActor":"Purchase","asisSys":"MC link; email; WhatsApp","gapFlag":"Gap","gapDesc":"Three channels for one PO.","change":"Modify","tobe":"PO sent from the ERP with a logged send record and vendor acknowledgement.","dept":"Purchase","role":"Buyer","sys":"D365 — PO confirmation","input":"Approved PO","output":"PO sent","pillars":"Process","refs":"POL-D11","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-25-S080","next":"PA-25-S093","evId":"EV-CC-0.13","evQuote":"digital PO shared to vendor email with help of MC system generated hyperlink to email"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S093', N'PA-25', 337, N'Purchase', N'New', N'Partial', N'{"id":"PA-25-S093","pa":"PA-25","phase":"2. Purchase order","scor":"Source – Identify sources","stype":"Activity","asis":"International suppliers are handled directly or through a clearing and forwarding agent; PO, invoice and customs documents are coordinated by email; most transactions are paid in advance.","asisActor":"Purchase","asisSys":"Email; MC PO","gapFlag":"Gap","gapDesc":"Import charges and advance payments not linked to the receipt.","change":"New","tobe":"Import PO records the forwarding agent, incoterms and expected charges (freight, duty, clearing); advance payments recorded as vendor prepayments against the PO.","dept":"Purchase","role":"Purchase Officer; Finance (prepayment)","sys":"D365 — Landed cost; vendor prepayment","input":"Approved PO","output":"Import shipment record","pillars":"Finance | Tracking & Traceability","fit":"Partial","erpReq":"Confirm: landed cost (voyages / shipments) and vendor prepayment linked to the PO.","ricefw":"Configuration","moscow":"Should","prev":"PA-25-S090","next":"PA-25-S096","evId":"EV-PUR-2.5","evQuote":"A separate CLEARING AND FORWARDING AGENT is used.","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S096', N'PA-25', 338, N'Finance', N'New', N'Partial', N'{"id":"PA-25-S096","pa":"PA-25","phase":"2. Purchase order","scor":"Source – Identify sources","stype":"Control check","asis":"— (new step; no as-is activity reported)","change":"New","tobe":"Freight, duty and clearing invoices allocated to the received items so inventory carries full landed cost (IAS 2.11).","dept":"Finance","role":"Accountant; Costing review","sys":"D365 — Landed cost allocation","input":"Import shipment record; charge invoices","output":"Landed cost posted to inventory","pillars":"Finance","fit":"Partial","erpReq":"Confirm: allocation of landed cost charges to items by value / weight / quantity.","ricefw":"Configuration","moscow":"Should","prev":"PA-25-S093","next":"PA-25-S100","evId":"EV-PUR-2.5","evQuote":"A separate CLEARING AND FORWARDING AGENT is used.","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S100', N'PA-25', 339, N'Purchase', N'Modify', N'Covered', N'{"id":"PA-25-S100","pa":"PA-25","phase":"3. Rate control","scor":"Source – Identify sources","stype":"Setup","asis":"A purchase article is an approved-list item with a price fixed in the system, but a new price is still allowed because user administration is open.","asisActor":"Purchase","asisSys":"MC — purchase article","gapFlag":"Control Gap","gapDesc":"Fixed price can be overridden. (Root cause: open user administration)","change":"Modify","tobe":"Trade agreements and price lists set up in the ERP; price not editable at PO entry.","dept":"Purchase","role":"Buyer; Cost Controller","sys":"D365 — Trade agreements","input":"Landed cost posted to inventory (PA-25-S096)","output":"Price list","pillars":"Finance | Control","refs":"POL-D09","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-25-S096","next":"PA-25-S110","evId":"EV-INV-5.0; EV-PUR-0.4","evQuote":"A purchase article is an approved list item for which the price is fixed in the system","taskId":"PA-25-T03","taskDesc":"Trade agreement and price-list setup in Dynamics - Configure trade agreements and price lists in Dynamics","solType":"Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S110', N'PA-25', 340, N'Purchase', N'Modify', N'Covered', N'{"id":"PA-25-S110","pa":"PA-25","phase":"3. Rate control","scor":"Source – Identify sources","stype":"Control check","asis":"The rate can be changed while placing the PO; the MC rate contract cannot carry a validity date or quantity and has no audit trail.","asisActor":"Purchase","asisSys":"MC — purchase order","gapFlag":"Control Gap","gapDesc":"No rate validity. (Root cause: rate contract without timeline / audit trail)","change":"Modify","tobe":"PO rate taken from an active agreement with effective-from, expiry and contracted quantity; it cannot be typed over.","dept":"Purchase","role":"System","sys":"D365 — Purchase agreement","input":"Price list (PA-25-S100)","output":"PO price from agreement","pillars":"Control | Finance","refs":"POL-D09","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-25-S100","next":"PA-25-S120","evId":"EV-INV-5.1; EV-PUR-0.5","evQuote":"The purchase article or purchase item rate can be changed while placing the purchase order."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S120', N'PA-25', 341, N'Cost Control', N'Modify', N'Partial', N'{"id":"PA-25-S120","pa":"PA-25","phase":"3. Rate control","scor":"Source – Identify sources","stype":"Approval","asis":"Rate changes are allowed without limit or approval; Costing and other departments have visibility only.","asisActor":"Purchase; Costing (view only)","asisSys":"MC — purchase order","gapFlag":"Control Gap","gapDesc":"Largest financial exposure in the flow. (Root cause: rate contract without timeline / audit trail)","change":"Modify","tobe":"Rate revision raised as a request with justification and quotation; Costing approves above a threshold. Supplier price increases need at least 3 months'' notice; the decision during the notice period is recorded and communicated to the CEO, GM and Cost Control; fixed-price items are received at the PO price. [SLA: approved before the new rate is used — proposed]","dept":"Cost Control","role":"Cost Controller (approver)","sys":"D365 — Rate revision workflow","input":"PO price from agreement (PA-25-S110)","output":"Approved rate revision","pillars":"Control | Finance","refs":"CTL-25-2 | POL-D09","fit":"Partial","erpReq":"Confirm: Rate-revision request workflow with justification and quotation; Costing approval above threshold.","ricefw":"Workflow","moscow":"Must","prev":"PA-25-S110","next":"PA-25-S130","evId":"EV-INV-5.2; EV-CC-5.2; EV-FD-059; EV-FD-060","evQuote":"Purchase item rate changes are allowed without any limit and without any subsequent approval mechanism."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S130', N'PA-25', 342, N'Purchase', N'Modify', N'Partial', N'{"id":"PA-25-S130","pa":"PA-25","phase":"3. Rate control","scor":"Source – Identify sources","stype":"Control check","asis":"Rate changes are maintained, monitored and applied manually, outside the system.","asisActor":"Purchase","asisSys":"Manual register","gapFlag":"Control Gap","gapDesc":"No rate history. (Root cause: outside the system)","change":"Modify","tobe":"Contract renewal dates and compliance tracked; every rate revision kept as history (old rate, new rate, date, approver).","dept":"Purchase","role":"Buyer; Cost Controller","sys":"D365 — Agreement history / renewal alerts","input":"Approved rate revision (PA-25-S120)","output":"Rate history / renewal alert","pillars":"Control | Monitoring","refs":"CTL-25-2 | POL-D09","fit":"Partial","erpReq":"Confirm: Agreement validity / renewal alerts and full price history (old, new, date, approver).","ricefw":"Customization","moscow":"Must","prev":"PA-25-S120","next":"PA-25-S140","evId":"EV-INV-5.3","evQuote":"Rate changes are maintained, monitored and applied manually, outside the system.","taskId":"PA-25-T04","taskDesc":"Contract renewal and compliance tracking - Track contract renewal dates and compliance obligations","solType":"Customization + Out of the Box"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S140', N'PA-25', 343, N'Purchase', N'Modify', N'Partial', N'{"id":"PA-25-S140","pa":"PA-25","phase":"4. Bulk commitments","scor":"Source – Identify sources","stype":"Setup","asis":"The bulk-order PO is released as a Word file by email and not captured in MC; only called-off quantities are registered; the remaining commitment is tracked in Excel.","asisActor":"Purchase","asisSys":"Word PO; Excel","gapFlag":"Control Gap","gapDesc":"Commitments invisible to Finance and Costing. (Root cause: outside the system)","change":"Modify","tobe":"Bulk commitment held as a purchase agreement with release orders and remaining balance visible.","dept":"Purchase","role":"Buyer; Purchase Chief","sys":"D365 — Purchase agreement","input":"Rate history / renewal alert (PA-25-S130)","output":"Purchase agreement","pillars":"Finance | Control","refs":"POL-D09","fit":"Partial","erpReq":"Confirm: Purchase agreements with release orders and remaining balance by quantity / value and validity.","ricefw":"Configuration","moscow":"Must","prev":"PA-25-S130","next":"PA-25-S150","evId":"EV-PUR-6.5; EV-PUR-6.3","evQuote":"The bulk-order PO is released as a Word file by email and is NOT captured in MC."}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-25-S150', N'PA-25', 344, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-25-S150","pa":"PA-25","phase":"4. Bulk commitments","scor":"Source – Identify sources","stype":"Exception","asis":"Vendor holds stock on Swish''s behalf awaiting phased call-off, but Swish is sometimes unable to consume the commitment on time.","asisActor":"Purchase; vendor","asisSys":"Excel","gapFlag":"Gap","gapDesc":"Unconsumed commitments surface late.","change":"Modify","tobe":"Agreement balance and validity monitored; alert before expiry; escalation for extension or compensation.","dept":"Purchase","role":"Buyer; Cost Controller","sys":"D365 — Agreement alerts","input":"Purchase agreement (PA-25-S140)","output":"Agreement expiry alert","pillars":"Monitoring | Finance","fit":"Not covered","erpReq":"Agreement balance / expiry alert.","ricefw":"Extension","moscow":"Should","prev":"PA-25-S140","next":"PA-25-S160","evId":"EV-PUR-6.4","evQuote":"but Swish is not able to consume"}');
