INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-26-S090', N'PA-26', 357, N'Finance', N'New', N'Covered', N'{"id":"PA-26-S090","pa":"PA-26","phase":"4. Overhead allocation & transfer price (future)","scor":"Enable – Manage finance","stype":"Setup","asis":"The EGC service company incurs and collects factory and other overheads and recharges them as a periodical expense reimbursement at zero profit; products move to stores at material cost.","asisActor":"EGC service company; Finance","asisSys":"GL / periodic recharge","gapFlag":"Gap","gapDesc":"Overheads not linked to products or sections.","change":"New","tobe":"Phase 0 → 1: cost centres created per CPU section, CBU and shared support; overhead pools defined (direct labour, variable factory, fixed factory, production support, other).","dept":"Finance","role":"Finance Manager; Costing Head","sys":"D365 — Cost accounting (cost centres, cost element groups)","input":"Reforecast (PA-26-S080)","output":"Cost centres and pools","pillars":"Finance | Master Data","fit":"Covered","ricefw":"Configuration","moscow":"Should","prev":"PA-26-S080","next":"PA-26-S100","evId":"EV-QL-OH01","evQuote":"periodical expense reimbursement kind of structure at zero profit","solType":"Pending – ERP provider"}');
