INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-26-S110', N'PA-26', 359, N'Cost Control', N'New', N'Partial', N'{"id":"PA-26-S110","pa":"PA-26","phase":"4. Overhead allocation & transfer price (future)","scor":"Enable – Manage finance","stype":"Activity","asis":"— (no driver data)","change":"New","tobe":"Driver data captured monthly: kg output per section from batch orders, labour minutes from rosters, batches, kWh where metered (else floor area).","dept":"Cost Control","role":"Cost Controller; CPU / CBU Managers","sys":"D365 — Statistical dimensions / batch-order output","input":"Batch orders; rosters; meters","output":"Monthly drivers","pillars":"Data & Reporting | Finance","fit":"Partial","erpReq":"Statistical drivers per cost centre.","ricefw":"Configuration","moscow":"Should","prev":"PA-26-S100","next":"PA-26-S120","evId":"EV-QL-OH01 (Recommended)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-26-S120', N'PA-26', 360, N'Cost Control', N'New', N'Partial', N'{"id":"PA-26-S120","pa":"PA-26","phase":"4. Overhead allocation & transfer price (future)","scor":"Enable – Manage finance","stype":"Report","asis":"— (not measured)","change":"New","tobe":"Phase 1: memo (shadow) absorption rates calculated per pool and section and compared with the zero-profit recharge; transfer value unchanged.","dept":"Cost Control","role":"Costing Head","sys":"D365 — Cost allocation report / Power BI","input":"Actual overhead; drivers","output":"Memo rate & recharge comparison","pillars":"Finance | Monitoring","fit":"Partial","erpReq":"Memo allocation report.","ricefw":"Report","moscow":"Should","prev":"PA-26-S110","next":"PA-26-S130","evId":"EV-QL-OH01 (Recommended)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-26-S130', N'PA-26', 361, N'Cost Control', N'New', N'Covered', N'{"id":"PA-26-S130","pa":"PA-26","phase":"4. Overhead allocation & transfer price (future)","scor":"Enable – Manage finance","stype":"Approval","asis":"— (no absorption rates)","change":"New","tobe":"Phase 2: absorption rates set at normal capacity with the budget and reviewed QUARTERLY; prepared by Costing, approved by Finance and Management.","dept":"Cost Control","role":"Costing Head (prepares); Finance Manager and Management (approve)","sys":"D365 — Costing version / costing sheet rates","input":"Memo rates; budget (S040–S070)","output":"Approved absorption rates","pillars":"Finance | Control","refs":"POL-D21 | POL-D10","fit":"Covered","ricefw":"Configuration","moscow":"Could","prev":"PA-26-S120","next":"PA-26-S140","evId":"EV-QL-OH02","evQuote":"quaterly review of absorption rate based on normal capacity is fine","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-26-S140', N'PA-26', 362, N'Cost Control', N'New', N'Partial', N'{"id":"PA-26-S140","pa":"PA-26","phase":"4. Overhead allocation & transfer price (future)","scor":"Enable – Manage finance","stype":"Activity","asis":"Material movement is valued at recipe material cost; non-recipe items are not part of costing or valuation today.","asisActor":"Costing","asisSys":"MC recipe costing","gapFlag":"Gap","gapDesc":"Non-recipe items, labour and overhead not in product cost.","change":"New","tobe":"Gate value calculated per production article: recipe material (actual consumption) + non-recipe items and packaging + direct labour + variable and fixed factory overhead + production support; mark-up 0%.","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Costing sheet (indirect cost lines)","input":"Approved absorption rates; formula (PA-11)","output":"Gate value per article","pillars":"Finance","refs":"POL-D21 | POL-D10 | POL-D11","fit":"Partial","erpReq":"Costing sheet with labour and overhead lines; non-recipe items in cost.","ricefw":"Configuration","moscow":"Could","prev":"PA-26-S130","next":"PA-26-S150","evId":"EV-QL-OH01","evQuote":"actual material cost as per recipe + non recipe items (not part of costing or valuation as of now)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-26-S150', N'PA-26', 363, N'Finance', N'New', N'Partial', N'{"id":"PA-26-S150","pa":"PA-26","phase":"4. Overhead allocation & transfer price (future)","scor":"Enable – Manage finance","stype":"Approval","asis":"User''s stated direction: overheads allocated on a mutually and periodically measured and agreed value just before the factory exit gate.","change":"New","tobe":"Rates and gate values agreed quarterly between CPU / CBU (EGC) and the receiving store company; monthly settlement statement agreed by both Finance teams before posting. [SLA: quarterly, before the quarter starts — proposed]","dept":"Finance","role":"Finance Manager (approver); CPU / CBU Manager; Operations (receiving company)","sys":"D365 — Price agreement approval","input":"Gate value per article","output":"Agreed gate values","pillars":"Control | Finance","refs":"CTL-26-2 | POL-D21","fit":"Partial","erpReq":"Approval of inter-company price lists.","ricefw":"Workflow","moscow":"Could","prev":"PA-26-S140","next":"PA-26-S160","evId":"EV-QL-OH01","evQuote":"based on mutually & periodically measured and agreed value just before the factory exit gate","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-26-S160', N'PA-26', 364, N'Finance', N'New', N'Partial', N'{"id":"PA-26-S160","pa":"PA-26","phase":"4. Overhead allocation & transfer price (future)","scor":"Enable – Manage finance","stype":"Hand-off","asis":"Store transfers carry material cost only; overheads recovered separately by recharge.","asisActor":"CPU / CBU; Finance","asisSys":"MC; periodic recharge","change":"New","tobe":"CPU / CBU output transferred to the store company at the agreed gate value (inter-company), replacing the periodic overhead recharge (PA-06, PA-16).","dept":"Finance","role":"System; Inter-company accountant","sys":"D365 — Inter-company trade / transfer pricing","input":"Agreed gate values","output":"Inter-company invoice at gate value","pillars":"Finance","refs":"POL-D21","fit":"Partial","erpReq":"Inter-company pricing on transfers between legal entities.","ricefw":"Configuration","moscow":"Could","prev":"PA-26-S150","next":"PA-26-S170","evId":"EV-QL-OH01","evQuote":"it will become part of cost of material transferred to store (legally it is another group company)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-26-S170', N'PA-26', 365, N'Cost Control', N'New', N'Partial', N'{"id":"PA-26-S170","pa":"PA-26","phase":"4. Overhead allocation & transfer price (future)","scor":"Enable – Manage finance","stype":"Control check","asis":"User decision: over / under absorption arises in every pool at 0% mark-up; EGC holds no margin, so it is settled monthly.","change":"New","tobe":"At month-end costing, over / under absorption calculated in every pool (variable, semi-fixed incl. labour, fixed) and SETTLED MONTHLY: re-allocated to receiving store companies in proportion to production material cost consumed — debit note for under-absorption (cost recovery), credit note for over-absorption; receiver posts to cost of sales (inventory adjusted only where material); year-end reconciliation to EGC actual cost. [SLA: at month-end costing, by WD+5 — proposed]","dept":"Cost Control","role":"Cost Controller; Finance Manager","sys":"D365 — Absorption variance / inter-company credit note","input":"Actual overhead; absorbed overhead","output":"Absorption variance; true-up note","pillars":"Control | Finance","refs":"CTL-26-2 | POL-D21 | K-26-1","fit":"Partial","erpReq":"Absorption variance by pool; true-up posting.","ricefw":"Report + Configuration","moscow":"Could","prev":"PA-26-S160","next":"PA-26-S180","evId":"EV-QL-OH02; EV-QL-OH01","evQuote":"so quaterly review of absorption rate based on normal capacity is fine but with monthly settlement","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-26-S180', N'PA-26', 366, N'Cost Control', N'New', N'Covered', N'{"id":"PA-26-S180","pa":"PA-26","phase":"4. Overhead allocation & transfer price (future)","scor":"Enable – Manage finance","stype":"Exception","asis":"— (losses not separated in transfer value)","change":"New","tobe":"Normal loss kept inside the standard yield; abnormal waste and abnormal idle capacity identified separately, recovered in the monthly settlement and expensed by the receiver, not inventoried (IAS 2.13, 2.16).","dept":"Cost Control","role":"Cost Controller","sys":"D365 — Yield / scrap","input":"Batch results","output":"Loss classification","pillars":"Finance | Control","refs":"POL-D21 | POL-D10","fit":"Covered","ricefw":"Configuration","moscow":"Could","prev":"PA-26-S170","next":"PA-26-S190","evId":"EV-QL-OH01 (Recommended)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-26-S190', N'PA-26', 367, N'Cost Control', N'New', N'Partial', N'{"id":"PA-26-S190","pa":"PA-26","phase":"4. Overhead allocation & transfer price (future)","scor":"Enable – Manage finance","stype":"Report","asis":"— (not applicable today)","change":"New","tobe":"Overhead absorption and gate-value report reviewed monthly; the model reviewed annually with the budget; tax / legal review before any mark-up.","dept":"Cost Control","role":"Costing Head; Finance Manager","sys":"D365 / Power BI","input":"Absorption variance; gate values","output":"Overhead absorption report; annual review (RPT-26)","pillars":"Monitoring | Finance","refs":"POL-D21","fit":"Partial","erpReq":"Confirm: Overhead absorption and gate-value report by pool, section and month; supports annual model review.","ricefw":"Report","moscow":"Could","prev":"PA-26-S180","next":"— (end)","evId":"EV-QL-OH01 (Recommended)","solType":"Pending – ERP provider"}');
