INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-27-S020', N'PA-27', 369, N'IT / ERP', N'New', N'Non-system', N'{"id":"PA-27-S020","pa":"PA-27","phase":"1. Representatives & needs","scor":"Enable – Manage people","stype":"Activity","asis":"Users work on paper, Excel and WhatsApp today (e.g. paper ordering-cum-inventory sheet at stores).","gapFlag":"Gap","gapDesc":"Large move from manual to system work.","change":"New","tobe":"Training needs assessed by role (warehouse, CPU, CBU, outlet, Purchase, Finance, Cost Control, QC) by the ERP Administrator with the department representatives.","dept":"IT / ERP","role":"ERP Administrator; Department ERP representatives","sys":"Training plan","input":"Representative list","output":"Training needs","pillars":"People & Training","refs":"POL-D28","fit":"Non-system","erpReq":"Implementation activity.","moscow":"Must","prev":"PA-27-S010","next":"PA-27-S030","evId":"EV-OPS-2.1","evQuote":"ALL ON PAPER; nothing is captured in a digital sheet","taskId":"PA-27-T01","taskDesc":"Training needs assessment by role - Assess training needs by role across warehouse, CPU, outlet, Finance and Cost Control","solType":"Implementation Activity"}');
