INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-27-S040', N'PA-27', 371, N'IT / ERP', N'New', N'Non-system', N'{"id":"PA-27-S040","pa":"PA-27","phase":"2. Train","scor":"Enable – Manage people","stype":"Activity","asis":"— (implementation activity; no as-is)","change":"New","tobe":"Train-the-trainer: the ERP vendor trains the ERP Administrator and the department ERP representatives, coordinated by the ERP Administrator. ERP training is not a Training-department task (Training focuses on production and store operations).","dept":"IT / ERP","role":"ERP Administrator; ERP vendor","sys":"Training plan","input":"N/A — project / readiness step","output":"N/A — project / readiness step","pillars":"People & Training","refs":"POL-D28","fit":"Non-system","erpReq":"Implementation activity.","moscow":"Must","prev":"PA-27-S030","next":"PA-27-S050","evId":"EV-QL-IT01","evQuote":"ERP administrator coordinates along with ERP applicator (vendor) for initial training","taskId":"PA-27-T03","taskDesc":"Train-the-trainer programme - Run train-the-trainer sessions","solType":"Implementation Activity"}');
