INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-27-S060', N'PA-27', 373, N'IT / ERP', N'New', N'Non-system', N'{"id":"PA-27-S060","pa":"PA-27","phase":"2. Train","scor":"Enable – Manage people","stype":"Setup","asis":"— (implementation activity; no as-is)","change":"New","tobe":"Department ERP representatives act as the change-champion network at each site.","dept":"IT / ERP","role":"Programme Manager; Department ERP representatives","sys":"Programme RACI","input":"N/A — project / readiness step","output":"N/A — project / readiness step","pillars":"People & Training","refs":"POL-D28","fit":"Non-system","erpReq":"Implementation activity.","moscow":"Must","prev":"PA-27-S050","next":"PA-27-S070","evId":"From task list","taskId":"PA-27-T05","taskDesc":"Change-champion network setup - Establish a change-champion network at each site","solType":"Implementation Activity"}');
