INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-27-S090', N'PA-27', 376, N'IT / ERP', N'New', N'Partial', N'{"id":"PA-27-S090","pa":"PA-27","phase":"4. Adopt & support","scor":"Enable – Manage people","stype":"Activity","asis":"— (implementation activity; no as-is)","change":"New","tobe":"Hypercare and day-to-day grievance clearance: user → department ERP representative (first level, supervisory) → ERP Administrator (ticket) → ERP vendor; every ticket tracked to closure.","dept":"IT / ERP","role":"Department ERP representatives; ERP Administrator; ERP vendor","sys":"ERP ticket log","input":"N/A — project / readiness step","output":"N/A — project / readiness step","pillars":"People & Training | Control","refs":"POL-D28","fit":"Partial","erpReq":"Ticketing / helpdesk for ERP issues.","ricefw":"Configuration","moscow":"Must","prev":"PA-27-S080","next":"PA-27-S100","evId":"EV-QL-IT01","evQuote":"ERP day to day grievance clearance at user custodian supervisory level within the department","taskId":"PA-27-T07","taskDesc":"Hypercare helpdesk and issue triage - Run hypercare helpdesk and triage issues","solType":"Implementation Activity"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-27-S100', N'PA-27', 377, N'IT / ERP', N'New', N'Non-system', N'{"id":"PA-27-S100","pa":"PA-27","phase":"4. Adopt & support","scor":"Enable – Manage people","stype":"Activity","asis":"— (implementation activity; no as-is)","change":"New","tobe":"Lessons learned captured and refresher training run by the representatives; Training department refreshes production and store SOPs only.","dept":"IT / ERP","role":"Department ERP representatives; ERP Administrator","sys":"Training plan","input":"N/A — project / readiness step","output":"N/A — project / readiness step","pillars":"People & Training","refs":"POL-D28","fit":"Non-system","erpReq":"Implementation activity.","moscow":"Should","prev":"PA-27-S090","next":"PA-27-S110","evId":"From task list","taskId":"PA-27-T08","taskDesc":"Lessons-learned and refresher-training cycle - Capture lessons learned and run refresher training","solType":"Implementation Activity"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-27-S110', N'PA-27', 378, N'IT / ERP', N'New', N'Covered', N'{"id":"PA-27-S110","pa":"PA-27","phase":"5. ERP administration (ongoing)","scor":"Enable – Manage people","stype":"Control check","asis":"MC user administration is open (e.g. store users can reposition quantities; prices editable at PO entry).","gapFlag":"Control Gap","gapDesc":"No controlled user administration. (Root cause: open user administration)","change":"New","tobe":"ERP Administrator creates, changes and removes users and security roles strictly per the Role column of Master (joiners, movers, leavers); changes logged.","dept":"IT / ERP","role":"ERP Administrator","sys":"D365 — Security roles","input":"N/A — project / readiness step","output":"N/A — project / readiness step","pillars":"Access & Segregation of Duties","refs":"CTL-27-1 | POL-D28 | POL-D05","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-27-S100","next":"PA-27-S120","evId":"EV-OPS-0.3; EV-QL-IT01","evQuote":"the inventory repositioning / assortment privilege on store user IDs lets them order any quantity"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-27-S120', N'PA-27', 379, N'IT / ERP', N'New', N'Covered', N'{"id":"PA-27-S120","pa":"PA-27","phase":"5. ERP administration (ongoing)","scor":"Enable – Manage people","stype":"Control check","asis":"— (no access review today)","change":"New","tobe":"Monthly counter audit of user- and supervisory-level activity: access review, segregation-of-duties conflicts, use of overrides and approvals; findings to the department head and Costing / Finance as relevant.","dept":"IT / ERP","role":"ERP Administrator","sys":"D365 — User access / audit reports","input":"N/A — project / readiness step","output":"N/A — project / readiness step (RPT-27)","pillars":"Access & Segregation of Duties | Monitoring","refs":"CTL-27-1 | POL-D28 | POL-D05","fit":"Covered","ricefw":"Report","moscow":"Must","prev":"PA-27-S110","next":"PA-27-S130","evId":"EV-QL-IT01","evQuote":"counter audit role for user level and supervisory level function"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-27-S130', N'PA-27', 380, N'IT / ERP', N'New', N'Partial', N'{"id":"PA-27-S130","pa":"PA-27","phase":"5. ERP administration (ongoing)","scor":"Enable – Manage people","stype":"Control check","asis":"— (workarounds not recorded)","change":"New","tobe":"Every workaround or off-system processing is logged by the ERP Administrator against its Master step ID, with owner, reason and closure date; open workarounds reviewed monthly and fed into the annual Master review.","dept":"IT / ERP","role":"ERP Administrator","sys":"Workaround register (D365 / ticket log)","input":"N/A — project / readiness step","output":"N/A — project / readiness step","pillars":"Control | Monitoring","refs":"CTL-27-1 | POL-D28 | K-27-1","fit":"Partial","erpReq":"Workaround register linked to step ID.","ricefw":"Configuration","moscow":"Must","prev":"PA-27-S120","next":"— (end)","evId":"EV-QL-IT01","evQuote":"all work around as well as work in computer environment to be phased across the steps of process"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S010', N'PA-28', 381, N'CPU / CBU', N'Keep', N'Not covered', N'{"id":"PA-28-S010","pa":"PA-28","phase":"1. Requisition","scor":"Source – Identify sources","stype":"Activity","asis":"Need for a non-inventoriable item arises at the user location (fixed asset, new project item, service & maintenance, administrative, IT).","asisSys":"None — verbal / ad hoc","change":"Keep","tobe":"Need for a non-inventoriable item arises at the user location.","dept":"CPU / CBU","role":"Store / HO / CPU","input":"Trigger: start of process","output":"Identified need","pillars":"Process","fit":"Not covered","erpReq":"Trigger unchanged.","moscow":"Should","prev":"— (start)","next":"PA-28-S020","evId":"EV-NINV-1","evQuote":"Need for a non-inventoriable item arises at the user location (fixed asset, new project item, service & maintenance, administrative, IT).","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S020', N'PA-28', 382, N'CPU / CBU', N'Modify', N'Not covered', N'{"id":"PA-28-S020","pa":"PA-28","phase":"1. Requisition","scor":"Source – Identify sources","stype":"Activity","asis":"Requester prepares an RFQ (Request for Quotation) as a manual Word file describing the requirement.","asisSys":"Word file (offline)","gapFlag":"Gap","gapDesc":"Manual document outside any system; no unique reference number, no version control, not searchable or reportable.","change":"Modify","tobe":"Requester raises a Purchase Requisition in the system; auto-numbered, with item category selected from a controlled dropdown (asset / service / admin / IT / project).","dept":"CPU / CBU","role":"Store / HO / CPU","sys":"Procurement module — Requisition","input":"Identified need (PA-28-S010)","output":"Purchase requisition","pillars":"Process","fit":"Not covered","erpReq":"Unique auto-generated reference; mandatory fields; categorised at source; fully searchable and reportable.","moscow":"Must","prev":"PA-28-S010","next":"PA-28-S030","evId":"EV-NINV-1.1","evQuote":"Requester prepares an RFQ (Request for Quotation) as a manual Word file describing the requirement.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S030', N'PA-28', 383, N'IT / ERP', N'Modify', N'Not covered', N'{"id":"PA-28-S030","pa":"PA-28","phase":"1. Requisition","scor":"Source – Identify sources","stype":"Activity","asis":"Requester marks the requirement as Budgeted or Non-budgeted; status fixed by Dept Head or Business Head on the request.","asisSys":"Handwritten / typed on Word file","gapFlag":"Gap","gapDesc":"Budget status asserted manually with no validation against an actual budget ledger.","change":"Modify","tobe":"Requester selects a budget code / cost centre; system validates the request value against available budget and returns Budgeted or Non-budgeted automatically.","dept":"IT / ERP","role":"System (auto) / Requester","sys":"Procurement module — Budget check","input":"Purchase requisition (PA-28-S020)","output":"Budget-validated requisition","pillars":"Process","fit":"Not covered","erpReq":"System-validated budget position replaces manual assertion; budget consumption visible in real time.","moscow":"Must","prev":"PA-28-S020","next":"PA-28-S040","evId":"EV-NINV-1.2","evQuote":"Requester marks the requirement as Budgeted or Non-budgeted;","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S040', N'PA-28', 384, N'Requesting department', N'Modify', N'Not covered', N'{"id":"PA-28-S040","pa":"PA-28","phase":"1. Requisition","scor":"Source – Identify sources","stype":"Approval","asis":"RFQ signed and approved by the relevant Department Head as per the prevailing SOP.","asisSys":"Wet signature on Word printout","gapFlag":"Gap","gapDesc":"Physical signature; no timestamp, no delegation rule when the approver is absent, no audit trail.","change":"Modify","tobe":"Requisition routes automatically to the Department Head for electronic approval per the configured approval matrix. [SLA: within 2 working days — proposed]","dept":"Requesting department","role":"Department Head","sys":"Workflow engine","input":"Budget-validated requisition (PA-28-S030)","output":"Department Head approval","pillars":"Process","refs":"CTL-28-1","fit":"Not covered","erpReq":"Timestamped e-approval with delegation and escalation rules; approver cannot be bypassed.","moscow":"Must","prev":"PA-28-S030","next":"PA-28-S050","evId":"EV-NINV-1.3","evQuote":"RFQ signed and approved by the relevant Department Head as per the prevailing SOP.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S050', N'PA-28', 385, N'Requesting department', N'Modify', N'Not covered', N'{"id":"PA-28-S050","pa":"PA-28","phase":"1. Requisition","scor":"Source – Identify sources","stype":"Approval","asis":"RFQ further signed and approved by the Business Head as per the prevailing SOP.","asisSys":"Wet signature on Word printout","gapFlag":"Gap","gapDesc":"Same as above; approval sequence not enforced, both approvals sometimes obtained out of order.","change":"Modify","tobe":"On Department Head approval, the requisition routes to the Business Head; non-budgeted requests additionally route to a higher authority tier. [SLA: within 2 working days — proposed]","dept":"Requesting department","role":"Business Head","sys":"Workflow engine","input":"Department Head approval (PA-28-S040)","output":"Business Head approval","pillars":"Process","refs":"CTL-28-1","fit":"Not covered","erpReq":"Sequential enforced routing; value and budget-status driven approval tiers.","moscow":"Must","prev":"PA-28-S040","next":"PA-28-S060","evId":"EV-NINV-1.4","evQuote":"RFQ further signed and approved by the Business Head as per the prevailing SOP.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S060', N'PA-28', 386, N'Requesting department', N'Retire', N'Non-system', N'{"id":"PA-28-S060","pa":"PA-28","phase":"1. Requisition","scor":"Source – Identify sources","stype":"Approval","asis":"Approved RFQ forwarded to the Procurement department (email / hard copy).","asisSys":"Email / hard copy","gapFlag":"Gap","gapDesc":"Manual handoff; requests can be lost or delayed with no visibility of pending items.","change":"Retire","tobe":"— no separate handoff step. On final approval the requisition appears directly in the Procurement work queue. Replaced by PA-28-S070.","dept":"Requesting department","sys":"Procurement work queue","pillars":"Process","fit":"Non-system","erpReq":"Manual transmission eliminated; zero-latency, no loss of requests.","moscow":"Must","prev":"PA-28-S050","next":"PA-28-S070","evId":"EV-NINV-1.5","evQuote":"Approved RFQ forwarded to the Procurement department (email / hard copy).","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S070', N'PA-28', 387, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-28-S070","pa":"PA-28","phase":"2. Sourcing","scor":"Source – Identify sources","stype":"Activity","asis":"Procurement studies the requirement and identifies potential suppliers in the market.","asisSys":"Manual / buyer knowledge","gapFlag":"Gap","gapDesc":"No vendor master for this category; sourcing depends on individual buyer knowledge.","change":"Modify","tobe":"Procurement selects vendors from a category-wise registered vendor master maintained in the system.","dept":"Purchase","role":"Procurement","sys":"Vendor master","input":"Approved requisition (PA-28-S050)","output":"Selected vendor list","pillars":"Control","fit":"Not covered","erpReq":"Institutional vendor list replaces personal knowledge; vendor performance history visible.","moscow":"Must","prev":"PA-28-S060","next":"PA-28-S080","evId":"EV-PUR-3.1; EV-NINV-2","evQuote":"an RFQ is raised, two to three suppliers'' quotations are received, compared and finalised","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S080', N'PA-28', 388, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-28-S080","pa":"PA-28","phase":"2. Sourcing","scor":"Source – Identify sources","stype":"Activity","asis":"Quotations obtained from the market against the specific requirement. Timeline for quotation depends on the type of asset or item requested.","asisSys":"Email / phone / hard copy","gapFlag":"Gap","gapDesc":"Quotations collected outside the system; no record of who was approached or who did not respond.","change":"Modify","tobe":"RFQ floated from the system to selected vendors; vendor responses captured against the RFQ with response and non-response both logged.","dept":"Purchase","role":"Procurement","sys":"Procurement module — RFQ","input":"Selected vendor list (PA-28-S070)","output":"RFQ and vendor responses","pillars":"Control","fit":"Not covered","erpReq":"Complete sourcing audit trail; category-wise standard quotation timelines configured.","moscow":"Must","prev":"PA-28-S070","next":"PA-28-S090","evId":"EV-NINV-2.1","evQuote":"Quotations obtained from the market against the specific requirement.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S090', N'PA-28', 389, N'IT / ERP', N'Modify', N'Not covered', N'{"id":"PA-28-S090","pa":"PA-28","phase":"2. Sourcing","scor":"Source – Identify sources","stype":"Activity","asis":"Standard of 3 quotations is followed as per SOP.","asisSys":"SOP (offline)","change":"Modify","tobe":"Minimum quotation count enforced by the system, configurable by item category and purchase value band.","dept":"IT / ERP","role":"System (auto)","sys":"Procurement module — policy config","input":"RFQ and vendor responses (PA-28-S080)","output":"Quotation count check","pillars":"Control","refs":"CTL-28-1","fit":"Not covered","erpReq":"SOP rule embedded in the system rather than relying on manual compliance.","moscow":"Should","prev":"PA-28-S080","next":"PA-28-S100","evId":"EV-NINV-2.2","evQuote":"Standard of 3 quotations is followed as per SOP.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S100', N'PA-28', 390, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-28-S100","pa":"PA-28","phase":"2. Sourcing","scor":"Source – Identify sources","stype":"Control check","asis":"DECISION: Are 3 quotations available? If not, an exception is applied based on justification provided.","asisSys":"Verbal / noted on file","gapFlag":"Gap","gapDesc":"Exception is the norm in reality; justification not consistently documented and not separately approved.","change":"Modify","tobe":"DECISION: minimum quote count met? If not, exception path requires mandatory written justification and approval by a defined higher authority before proceeding.","dept":"Purchase","role":"Procurement / Approver","sys":"Workflow engine — exception path","input":"Quotation count check (PA-28-S090)","output":"Quotation exception justification","pillars":"Control","refs":"CTL-28-1","fit":"Not covered","erpReq":"Exception retained as a practical necessity but made visible, justified, separately approved and reportable.","moscow":"Must","prev":"PA-28-S090","next":"PA-28-S110","evId":"EV-NINV-2.3","evQuote":"DECISION: Are 3 quotations available? If not, an exception is applied based on justification provided.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S110', N'PA-28', 391, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-28-S110","pa":"PA-28","phase":"2. Sourcing","scor":"Source – Identify sources","stype":"Activity","asis":"Quotations compared and evaluated by Procurement; preferred quotation selected.","asisSys":"Manual comparison","gapFlag":"Gap","gapDesc":"No standard comparative statement; basis of selection not recorded where the lowest quote is not chosen.","change":"Modify","tobe":"System generates a comparative quotation statement; buyer records the selection reason, mandatory when the lowest quote is not selected.","dept":"Purchase","role":"Procurement","sys":"Procurement module — quote comparison","input":"Quotation exception justification (PA-28-S100)","output":"Comparative statement and selection","pillars":"Control","fit":"Not covered","erpReq":"Standardised comparison; documented justification for non-lowest award.","moscow":"Must","prev":"PA-28-S100","next":"PA-28-S120","evId":"EV-PUR-3.1; EV-NINV-2.4","evQuote":"two to three suppliers'' quotations are received, compared and finalised","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S120', N'PA-28', 392, N'Requesting department', N'Retire', N'Non-system', N'{"id":"PA-28-S120","pa":"PA-28","phase":"2. Sourcing","scor":"Source – Identify sources","stype":"Activity","asis":"Finalised quotation and technical specification returned to the requesting department.","asisSys":"Email / hard copy","change":"Retire","tobe":"— no return handoff. Selected quotation is attached to the same live requisition record, visible to the requester. Replaced by PA-28-S130.","dept":"Requesting department","sys":"Procurement module","pillars":"Control","fit":"Non-system","erpReq":"Single record replaces document ping-pong between departments.","moscow":"Should","prev":"PA-28-S110","next":"PA-28-S130","evId":"EV-NINV-2.5","evQuote":"Finalised quotation and technical specification returned to the requesting department.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S130', N'PA-28', 393, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-28-S130","pa":"PA-28","phase":"3. Purchase Request","scor":"Source – Identify sources","stype":"Activity","asis":"Finalised quotation and specification converted into a Purchase Request through a separate manual Word document.","asisSys":"Word file (second manual document)","gapFlag":"Gap","gapDesc":"Entire requirement re-keyed into a second document; transcription errors possible; no link to the originating RFQ.","change":"Modify","tobe":"Approved requisition with the selected quotation converts to a Purchase Request in one click, carrying all data forward.","dept":"Purchase","role":"Procurement / Requester","sys":"Procurement module — PR","input":"Comparative statement and selection (PA-28-S110)","output":"Purchase request","pillars":"Process","fit":"Not covered","erpReq":"No re-keying; PR permanently linked to its RFQ and quotation.","moscow":"Must","prev":"PA-28-S120","next":"PA-28-S140","evId":"EV-NINV-3","evQuote":"Finalised quotation and specification converted into a Purchase Request through a separate manual Word document.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S140', N'PA-28', 394, N'Requesting department', N'Modify', N'Not covered', N'{"id":"PA-28-S140","pa":"PA-28","phase":"3. Purchase Request","scor":"Source – Identify sources","stype":"Approval","asis":"Purchase Request approved by the relevant Department Head as per the prevailing SOP.","asisSys":"Wet signature","gapFlag":"Gap","gapDesc":"Second full approval cycle on paper, duplicating the RFQ-stage approval.","change":"Modify","tobe":"PR routes for e-approval only where the value or specification has changed from the approved requisition; otherwise the original approval stands.","dept":"Requesting department","role":"Department Head","sys":"Workflow engine","input":"Purchase request (PA-28-S130)","output":"PR variance approval","pillars":"Process","fit":"Not covered","erpReq":"Duplicate approval eliminated; re-approval triggered by variance rather than by routine.","moscow":"Must","prev":"PA-28-S130","next":"PA-28-S150","evId":"EV-NINV-3.1","evQuote":"Purchase Request approved by the relevant Department Head as per the prevailing SOP.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S150', N'PA-28', 395, N'Requesting department', N'Modify', N'Not covered', N'{"id":"PA-28-S150","pa":"PA-28","phase":"3. Purchase Request","scor":"Source – Identify sources","stype":"Approval","asis":"Purchase Request approved by the Business Head as per the prevailing SOP.","asisSys":"Wet signature","gapFlag":"Gap","gapDesc":"As above; approval turnaround depends on physical availability of the approver.","change":"Modify","tobe":"Business Head e-approval, triggered on the same variance rule and value thresholds.","dept":"Requesting department","role":"Business Head","sys":"Workflow engine","input":"PR variance approval (PA-28-S140)","output":"Business Head PR approval","pillars":"Process","fit":"Not covered","erpReq":"Approver availability no longer blocks the process; delegation configured.","moscow":"Must","prev":"PA-28-S140","next":"PA-28-S160","evId":"EV-NINV-3.2","evQuote":"Purchase Request approved by the Business Head as per the prevailing SOP.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S160', N'PA-28', 396, N'Requesting department', N'Retire', N'Non-system', N'{"id":"PA-28-S160","pa":"PA-28","phase":"3. Purchase Request","scor":"Source – Identify sources","stype":"Approval","asis":"Approved Purchase Request submitted to Procurement — sometimes only as a scanned copy.","asisSys":"Scan / email / hard copy","gapFlag":"Gap","gapDesc":"Scanned copies are not machine-readable, cannot be validated, and are easily superseded or duplicated.","change":"Retire","tobe":"— scanning and submission eliminated; the approved PR is already live in the system. Replaced by PA-28-S170.","dept":"Requesting department","pillars":"Process","fit":"Non-system","erpReq":"Scanned-document practice discontinued entirely.","moscow":"Must","prev":"PA-28-S150","next":"PA-28-S170","evId":"EV-NINV-3.3","evQuote":"Approved Purchase Request submitted to Procurement — sometimes only as a scanned copy.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S170', N'PA-28', 397, N'Requesting department', N'Retire', N'Non-system', N'{"id":"PA-28-S170","pa":"PA-28","phase":"3. Purchase Request","scor":"Source – Identify sources","stype":"Activity","asis":"Finalised Purchase Request updated into an Excel database controlled by the purchase department.","asisSys":"Excel file (departmental)","gapFlag":"Gap","gapDesc":"Shadow database held by one department; single point of failure, no access control, no integration with finance.","change":"Retire","tobe":"— Excel tracker retired. The system register of requisitions and PRs is the single source of truth. Replaced by PA-28-S180.","dept":"Requesting department","sys":"Procurement module — PR register","pillars":"Process","fit":"Non-system","erpReq":"Shadow spreadsheet eliminated; status, ageing and ownership reportable to all stakeholders.","moscow":"Must","prev":"PA-28-S160","next":"PA-28-S180","evId":"EV-NINV-3.4","evQuote":"Finalised Purchase Request updated into an Excel database controlled by the purchase department.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S180', N'PA-28', 398, N'Cost Control', N'New', N'Not covered', N'{"id":"PA-28-S180","pa":"PA-28","phase":"4. Item Master","scor":"Source – Identify sources","stype":"Activity","asis":"No item is created in the inventory item master, as this whole category is treated as non-inventoriable.","gapFlag":"Concept Gap","gapDesc":"Concept gap — there should be a solution. With no coded article, spend cannot be analysed by item, assets cannot be tracked, and duplicate purchasing is invisible.","change":"New","tobe":"NEW: Non-inventoriable article master introduced — a fixed-asset article master and a service catalogue, each with category, asset class and cost-centre mapping.","dept":"Cost Control","role":"Costing / Procurement","sys":"Item master — non-inventoriable class","input":"Trigger: master data setup","output":"Non-inventoriable article master","pillars":"Master Data","fit":"Not covered","erpReq":"Closes the stated concept gap: every non-MC purchase carries a coded article without entering inventory valuation or production cost.","moscow":"Must","prev":"PA-28-S170","next":"PA-28-S190","evId":"EV-NINV-4","evQuote":"No item is created in the inventory item master, as this whole category is treated as non-inventoriable.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S190', N'PA-28', 399, N'Cost Control', N'New', N'Not covered', N'{"id":"PA-28-S190","pa":"PA-28","phase":"4. Item Master","scor":"Source – Identify sources","stype":"Activity","asis":"— no equivalent step exists.","change":"New","tobe":"NEW: Requester selects an existing article or raises a new-article request; Costing validates it is not a duplicate before creation.","dept":"Cost Control","role":"Costing","sys":"Item master — new article workflow","input":"Non-inventoriable article master (PA-28-S180)","output":"Article selection / new-article request","pillars":"Master Data","fit":"Not covered","erpReq":"Duplicate-article control at the point of creation, mirroring the MC item-master discipline.","moscow":"Should","prev":"PA-28-S180","next":"PA-28-S200","evId":"EV-NINV-4.1","evQuote":"— no equivalent step exists.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S200', N'PA-28', 400, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-28-S200","pa":"PA-28","phase":"5. Purchase Order","scor":"Source – Identify sources","stype":"Activity","asis":"Purchase Order prepared manually by the purchase department.","asisSys":"Word file (offline)","gapFlag":"Gap","gapDesc":"Manual PO; no system PO number, terms not standardised, no link to PR or quotation.","change":"Modify","tobe":"PR converts to a system Purchase Order with auto-numbering and standard terms, linked to the PR, quotation and article.","dept":"Purchase","role":"Procurement (Maker)","sys":"Procurement module — PO","input":"Article selection / new-article request (PA-28-S190)","output":"Purchase order (draft)","pillars":"Control","fit":"Not covered","erpReq":"End-to-end document linkage from requisition through to PO.","moscow":"Must","prev":"PA-28-S190","next":"PA-28-S210","evId":"EV-NINV-5","evQuote":"Purchase Order prepared manually by the purchase department.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S210', N'PA-28', 401, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-28-S210","pa":"PA-28","phase":"5. Purchase Order","scor":"Source – Identify sources","stype":"Activity","asis":"Purchase Order signed by the purchase department.","asisSys":"Wet signature","gapFlag":"Gap","gapDesc":"Same person can prepare and release the PO — no maker-checker segregation in this category.","change":"Modify","tobe":"PO released under maker-checker: the preparer cannot approve their own PO; checker authority set by value band. [SLA: within 1 working day — proposed]","dept":"Purchase","role":"Procurement (Checker)","sys":"Workflow engine — maker-checker","input":"Purchase order (draft) (PA-28-S200)","output":"Released purchase order","pillars":"Control","refs":"CTL-28-2 | K-28-1","fit":"Not covered","erpReq":"Segregation of duties introduced, aligning this category with MC purchase practice.","moscow":"Must","prev":"PA-28-S200","next":"PA-28-S220","evId":"EV-NINV-5.1","evQuote":"Purchase Order signed by the purchase department.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S220', N'PA-28', 402, N'IT / ERP', N'Modify', N'Not covered', N'{"id":"PA-28-S220","pa":"PA-28","phase":"5. Purchase Order","scor":"Source – Identify sources","stype":"Hand-off","asis":"Signed Purchase Order sent to the supplier.","asisSys":"Email / hard copy","gapFlag":"Gap","gapDesc":"No record of when the PO was despatched or whether the vendor acknowledged it.","change":"Modify","tobe":"PO despatched to the vendor from the system with a logged send record and vendor acknowledgement capture.","dept":"IT / ERP","role":"System (auto)","sys":"Procurement module — PO despatch","input":"Released purchase order (PA-28-S210)","output":"PO send record and acknowledgement","pillars":"Control","fit":"Not covered","erpReq":"Despatch and acknowledgement timestamps establish the delivery clock.","moscow":"Must","prev":"PA-28-S210","next":"PA-28-S230","evId":"EV-NINV-5.2","evQuote":"Signed Purchase Order sent to the supplier.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S230', N'PA-28', 403, N'IT / ERP', N'Modify', N'Not covered', N'{"id":"PA-28-S230","pa":"PA-28","phase":"5. Purchase Order","scor":"Source – Identify sources","stype":"Activity","asis":"All open POs, multi-delivery, rejection, cancellation and non-delivered positions are maintained manually.","asisSys":"Manual register","gapFlag":"Control Gap","gapDesc":"Control gap — PO lifecycle tracked by hand. Open commitments are not visible to finance and stale POs are never closed.","change":"Modify","tobe":"System maintains PO status automatically — open, part-delivered, over-delivered, rejected, cancelled, closed — with an ageing dashboard.","dept":"IT / ERP","role":"System (auto)","sys":"Procurement module — PO lifecycle","input":"PO send record and acknowledgement (PA-28-S220)","output":"PO status","pillars":"Control","fit":"Not covered","erpReq":"Closes the stated control gap; open commitment visible to finance; auto-flagging of stale POs.","moscow":"Must","prev":"PA-28-S220","next":"PA-28-S240","evId":"EV-NINV-5.3","evQuote":"All open POs, multi-delivery, rejection, cancellation and non-delivered positions are maintained manually.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S240', N'PA-28', 404, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-28-S240","pa":"PA-28","phase":"5. Purchase Order","scor":"Source – Identify sources","stype":"Activity","asis":"Procurement follows up with the supplier for delivery of the item.","asisSys":"Phone / email","gapFlag":"Gap","gapDesc":"Follow-up depends on individual diligence; no reminder mechanism and no record of chase history.","change":"Modify","tobe":"System issues automated delivery-due reminders to vendor and buyer against the PO promised date, escalating on overdue lines.","dept":"Purchase","role":"System (auto) / Procurement","sys":"Procurement module — alerts","input":"PO status (PA-28-S230)","output":"Delivery-due reminder","pillars":"Control","fit":"Not covered","erpReq":"Systematic follow-up replaces individual diligence; chase history retained.","moscow":"Must","prev":"PA-28-S230","next":"PA-28-S250","evId":"EV-NINV-5.4","evQuote":"Procurement follows up with the supplier for delivery of the item.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S250', N'PA-28', 405, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-28-S250","pa":"PA-28","phase":"6. Delivery","scor":"Source – Receive","stype":"Control check","asis":"DECISION: delivery route decided informally — direct to requester, or via warehouse.","asisSys":"Verbal direction","gapFlag":"Control Gap","gapDesc":"Control gap — no proper logistics system equipped into the system. Route decided case by case with no record.","change":"Modify","tobe":"DECISION: delivery route is a mandatory field on the PO — direct-to-requester, via warehouse, or project site — set before release.","dept":"Purchase","role":"Procurement","sys":"Logistics module — route flag","input":"Delivery-due reminder (PA-28-S240)","output":"Delivery route on PO","pillars":"Tracking & Traceability","fit":"Not covered","erpReq":"Route becomes a recorded decision on the PO rather than a verbal instruction.","moscow":"Must","prev":"PA-28-S240","next":"PA-28-S260","evId":"EV-NINV-6","evQuote":"DECISION: delivery route decided informally — direct to requester, or via warehouse.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S260', N'PA-28', 406, N'Requesting department', N'Modify', N'Not covered', N'{"id":"PA-28-S260","pa":"PA-28","phase":"6. Delivery","scor":"Source – Receive","stype":"Hand-off","asis":"ROUTE A — Some items delivered directly to the requesting person on the direction of the procurement team.","gapFlag":"Control Gap","gapDesc":"Control gap — no logistics system. Goods reach the user with no organisational record that they arrived.","change":"Modify","tobe":"ROUTE A — Direct-to-requester delivery recorded in the system; requester confirms receipt digitally against the PO line.","dept":"Requesting department","role":"Supplier → Requester","sys":"Logistics module","input":"Delivery route on PO (PA-28-S250)","output":"Requester receipt (route A)","pillars":"Tracking & Traceability","fit":"Not covered","erpReq":"Custody recorded even when goods bypass the warehouse.","moscow":"Must","prev":"PA-28-S250","next":"PA-28-S270","evId":"EV-NINV-6.1","evQuote":"ROUTE A — Some items delivered directly to the requesting person on the direction of the procurement team.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S270', N'PA-28', 407, N'Warehouse', N'Modify', N'Not covered', N'{"id":"PA-28-S270","pa":"PA-28","phase":"6. Delivery","scor":"Source – Receive","stype":"Hand-off","asis":"ROUTE B — Some items delivered to warehouse; procurement and logistics coordinate onward delivery to the store or requester.","asisSys":"Manual coordination","gapFlag":"Control Gap","gapDesc":"Control gap — no proper logistics system. Onward movement is untracked; goods can sit at the warehouse unnoticed.","change":"Modify","tobe":"ROUTE B — Warehouse records inward receipt, then raises a system internal transfer to the end location; receiver confirms.","dept":"Warehouse","role":"Warehouse / Logistics","sys":"Logistics module — internal transfer","input":"Requester receipt (route A) (PA-28-S260)","output":"Warehouse receipt and internal transfer (route B)","pillars":"Tracking & Traceability","fit":"Not covered","erpReq":"Each custody leg recorded; goods cannot sit untracked at the warehouse.","moscow":"Must","prev":"PA-28-S260","next":"PA-28-S280","evId":"EV-NINV-6.2","evQuote":"ROUTE B — Some items delivered to warehouse;","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S280', N'PA-28', 408, N'Warehouse', N'Modify', N'Not covered', N'{"id":"PA-28-S280","pa":"PA-28","phase":"6. Delivery","scor":"Source – Receive","stype":"Hand-off","asis":"ROUTE C — New project items mostly routed to the warehouse.","asisSys":"Convention only","gapFlag":"Gap","gapDesc":"Practice by convention, not enforced; project materials not tracked against a project.","change":"Modify","tobe":"ROUTE C — Project-flagged POs default to warehouse routing and carry a project code for project-wise cost and delivery tracking.","dept":"Warehouse","role":"Warehouse","sys":"Logistics module — project code","input":"Warehouse receipt and internal transfer (route B) (PA-28-S270)","output":"Project-coded receipt (route C)","pillars":"Tracking & Traceability","fit":"Not covered","erpReq":"Convention converted into an enforced rule with project cost visibility.","moscow":"Must","prev":"PA-28-S270","next":"PA-28-S290","evId":"EV-NINV-6.3","evQuote":"ROUTE C — New project items mostly routed to the warehouse.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S290', N'PA-28', 409, N'Warehouse', N'Modify', N'Not covered', N'{"id":"PA-28-S290","pa":"PA-28","phase":"7. Receipt","scor":"Source – Receive","stype":"Activity","asis":"Warehouse has no system to capture the item and its transactions.","gapFlag":"Control Gap","gapDesc":"Control gap — goods physically held by the warehouse with no system record of receipt, location or issue.","change":"Modify","tobe":"Warehouse captures inward receipt, storage location and outward transfer for non-inventoriable items, including assets held pending installation.","dept":"Warehouse","role":"Warehouse","sys":"Warehouse module — non-inventoriable","input":"Project-coded receipt (route C) (PA-28-S280)","output":"Warehouse inward / outward record","pillars":"Control","fit":"Not covered","erpReq":"Closes the stated control gap without bringing these items into inventory valuation.","moscow":"Must","prev":"PA-28-S280","next":"PA-28-S300","evId":"EV-NINV-7","evQuote":"Warehouse has no system to capture the item and its transactions.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S300', N'PA-28', 410, N'CPU / CBU', N'Modify', N'Not covered', N'{"id":"PA-28-S300","pa":"PA-28","phase":"7. Receipt","scor":"Source – Receive","stype":"Activity","asis":"Delivery note signed by the receiver on physical receipt of goods.","asisSys":"Supplier delivery note","change":"Modify","tobe":"Receiver confirms receipt digitally against the PO line, recording quantity accepted and quantity rejected; signed delivery note attached as evidence. [SLA: within 2 working days of delivery — proposed]","dept":"CPU / CBU","role":"Store / HO / CPU","sys":"Procurement module — receipt","input":"Warehouse inward / outward record (PA-28-S290)","output":"Digital receipt confirmation","pillars":"Control","fit":"Not covered","erpReq":"Physical signature retained as evidence but the system record becomes the control.","moscow":"Should","prev":"PA-28-S290","next":"PA-28-S310","evId":"EV-NINV-7.1","evQuote":"Delivery note signed by the receiver on physical receipt of goods.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S310', N'PA-28', 411, N'CPU / CBU', N'Keep', N'Not covered', N'{"id":"PA-28-S310","pa":"PA-28","phase":"7. Receipt","scor":"Source – Receive","stype":"Activity","asis":"Invoice is generally not permitted to be handed over to the receiver.","asisSys":"SOP (offline)","change":"Keep","tobe":"Invoice continues to bypass the receiver and flow directly to Procurement / Finance.","dept":"CPU / CBU","role":"Store / HO / CPU","sys":"Policy","input":"Digital receipt confirmation (PA-28-S300)","output":"Invoice routed to Procurement / Finance","pillars":"Control","fit":"Not covered","erpReq":"Existing segregation of duties is sound — retained deliberately and unchanged.","moscow":"Should","prev":"PA-28-S300","next":"PA-28-S320","evId":"EV-NINV-7.2","evQuote":"Invoice is generally not permitted to be handed over to the receiver.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S320', N'PA-28', 412, N'Warehouse', N'New', N'Not covered', N'{"id":"PA-28-S320","pa":"PA-28","phase":"7. Receipt","scor":"Source – Receive","stype":"Activity","asis":"There is no option to enter a GRN for a non-inventoriable item.","gapFlag":"Control Gap","gapDesc":"Control gap — no goods receipt record exists, so payment can be processed without any system evidence that goods or services were received.","change":"New","tobe":"NEW: GRN enabled for this category — asset / goods GRN for physical items and a service entry sheet for service and maintenance POs.","dept":"Warehouse","role":"Store / HO / CPU / Warehouse","sys":"Procurement module — GRN / SES - Service Entry Sheet","input":"Invoice routed to Procurement / Finance (PA-28-S310)","output":"GRN / service entry","pillars":"Control","refs":"CTL-28-2","fit":"Not covered","erpReq":"Closes the stated control gap; receipt evidence becomes a precondition for payment.","moscow":"Must","prev":"PA-28-S310","next":"PA-28-S330","evId":"EV-NINV-7.3","evQuote":"There is no option to enter a GRN for a non-inventoriable item.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S330', N'PA-28', 413, N'Warehouse', N'New', N'Not covered', N'{"id":"PA-28-S330","pa":"PA-28","phase":"7. Receipt","scor":"Source – Receive","stype":"Activity","asis":"There is no option for a separate inspection or installation report for fixed assets.","gapFlag":"Control Gap","gapDesc":"Control gap — assets are paid for with no record of inspection, installation, commissioning, serial number, location or custodian.","change":"New","tobe":"NEW: Mandatory inspection and installation-acceptance report for fixed assets, capturing serial number, location, custodian and warranty period.","dept":"Warehouse","role":"Requester / Technical / Warehouse","sys":"Asset module — acceptance report","input":"GRN / service entry (PA-28-S320)","output":"Inspection and installation-acceptance report","pillars":"Control","fit":"Not covered","erpReq":"Closes the stated control gap; asset capitalised and payment released only on acceptance; asset register populated at source.","moscow":"Must","prev":"PA-28-S320","next":"PA-28-S335","evId":"EV-NINV-7.4","evQuote":"There is no option for a separate inspection or installation report for fixed assets.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S335', N'PA-28', 414, N'Finance', N'New', N'Covered', N'{"id":"PA-28-S335","pa":"PA-28","phase":"7. Receipt","scor":"Source – Receive","stype":"Activity","asis":"There is no option for a separate inspection or installation report for fixed assets; assets are recorded by Finance outside the purchase flow.","asisActor":"Finance","asisSys":"Manual","gapFlag":"Control Gap","gapDesc":"Asset capitalisation not linked to acceptance.","change":"New","tobe":"On installation acceptance the fixed asset is created and capitalised: asset number and tag, location, cost centre, useful life; depreciation starts when the asset is available for use (IAS 16).","dept":"Finance","role":"Fixed Asset Accountant","sys":"D365 — Fixed assets","input":"Installation acceptance report","output":"Asset register entry","pillars":"Finance | Tracking & Traceability","fit":"Covered","ricefw":"Configuration","moscow":"Must","prev":"PA-28-S330","next":"PA-28-S340","evId":"EV-NINV-7.4","evQuote":"There is no option for a separate inspection or installation report for fixed assets.","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S340', N'PA-28', 415, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-28-S340","pa":"PA-28","phase":"8. Invoice & Finance","scor":"Source – Authorise payment","stype":"Activity","asis":"Invoice received from the supplier along with the signed delivery note.","asisSys":"Hard copy invoice","gapFlag":"Gap","gapDesc":"Invoice received on paper; no system registration, so invoice ageing and liability are not visible.","change":"Modify","tobe":"Vendor invoice registered in the system against the PO on receipt, with the signed delivery note attached.","dept":"Purchase","role":"Procurement / Finance","sys":"Procurement module — invoice register","input":"Asset register entry (PA-28-S335)","output":"Registered vendor invoice","pillars":"Finance","fit":"Not covered","erpReq":"Invoice ageing and accrued liability visible from the date of receipt.","moscow":"Must","prev":"PA-28-S335","next":"PA-28-S350","evId":"EV-NINV-8","evQuote":"Invoice received from the supplier along with the signed delivery note.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S350', N'PA-28', 416, N'IT / ERP', N'New', N'Not covered', N'{"id":"PA-28-S350","pa":"PA-28","phase":"8. Invoice & Finance","scor":"Source – Authorise payment","stype":"Activity","asis":"— no equivalent step exists; matching is done by eye during verification.","change":"New","tobe":"NEW: System performs a three-way match of PO, GRN / service entry and invoice; variances beyond tolerance are blocked and routed for approval.","dept":"IT / ERP","role":"System (auto)","sys":"Procurement module — 3-way match","input":"Registered vendor invoice (PA-28-S340)","output":"Three-way match result","pillars":"Finance","refs":"CTL-28-2","fit":"Not covered","erpReq":"Automated matching control replaces visual verification; overbilling and duplicate invoices prevented.","moscow":"Should","prev":"PA-28-S340","next":"PA-28-S360","evId":"EV-NINV-8.1","evQuote":"— no equivalent step exists;","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S360', N'PA-28', 417, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-28-S360","pa":"PA-28","phase":"8. Invoice & Finance","scor":"Source – Authorise payment","stype":"Activity","asis":"Procurement verifies the invoice against the order and the delivery note.","asisSys":"Manual check","gapFlag":"Gap","gapDesc":"Manual verification; depends on the reviewer noticing discrepancies.","change":"Modify","tobe":"Procurement reviews only the exceptions raised by the three-way match rather than checking every invoice line by hand.","dept":"Purchase","role":"Procurement","sys":"Procurement module","input":"Three-way match result (PA-28-S350)","output":"Match exception review (RPT-28)","pillars":"Finance","refs":"K-28-2","fit":"Not covered","erpReq":"Exception-based review; effort focused where variance exists.","moscow":"Must","prev":"PA-28-S350","next":"PA-28-S370","evId":"EV-NINV-8.2","evQuote":"Procurement verifies the invoice against the order and the delivery note.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S370', N'PA-28', 418, N'Purchase', N'Modify', N'Not covered', N'{"id":"PA-28-S370","pa":"PA-28","phase":"8. Invoice & Finance","scor":"Source – Authorise payment","stype":"Approval","asis":"Procurement approves the verified invoice for payment processing.","asisSys":"Signature on file","change":"Modify","tobe":"Procurement approves electronically under the non-inventoriable value-band approval system (separate from POL-D22, which covers costing transactions only).","dept":"Purchase","role":"Procurement","sys":"Workflow engine","input":"Match exception review (PA-28-S360)","output":"Approved invoice","pillars":"Finance","fit":"Not covered","erpReq":"Timestamped approval with enforced authority limits.","moscow":"Should","prev":"PA-28-S360","next":"PA-28-S380","evId":"EV-NINV-8.3","evQuote":"Procurement approves the verified invoice for payment processing.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S380', N'PA-28', 419, N'Requesting department', N'Retire', N'Non-system', N'{"id":"PA-28-S380","pa":"PA-28","phase":"8. Invoice & Finance","scor":"Source – Authorise payment","stype":"Activity","asis":"Procurement attaches all supporting documents to the physical file.","asisSys":"Physical file","gapFlag":"Gap","gapDesc":"Physical document set; retrieval for audit is slow and documents can be lost.","change":"Retire","tobe":"— physical file assembly eliminated. All documents are already held against the PO record. Replaced by PA-28-S390.","dept":"Requesting department","sys":"Document repository","pillars":"Finance","fit":"Non-system","erpReq":"Instant audit retrieval; no risk of lost supporting documents.","moscow":"Must","prev":"PA-28-S370","next":"PA-28-S390","evId":"EV-NINV-8.4","evQuote":"Procurement attaches all supporting documents to the physical file.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S390', N'PA-28', 420, N'Finance', N'Modify', N'Not covered', N'{"id":"PA-28-S390","pa":"PA-28","phase":"8. Invoice & Finance","scor":"Source – Authorise payment","stype":"Hand-off","asis":"Complete file submitted to Finance for payment.","asisSys":"Physical file / email","gapFlag":"Gap","gapDesc":"Manual handoff; finance has no visibility of the pipeline until the file physically arrives.","change":"Modify","tobe":"Matched and approved invoice passes automatically to the Finance payment queue with the full document set linked.","dept":"Finance","role":"System (auto) / Finance","sys":"Finance / AP integration","input":"Approved invoice (PA-28-S370)","output":"Invoice in payment queue","pillars":"Finance","fit":"Not covered","erpReq":"Finance sees the payables pipeline in real time; no physical file movement.","moscow":"Must","prev":"PA-28-S380","next":"PA-28-S400","evId":"EV-NINV-8.5","evQuote":"Complete file submitted to Finance for payment.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S400', N'PA-28', 421, N'Finance', N'Modify', N'Not covered', N'{"id":"PA-28-S400","pa":"PA-28","phase":"9. Close","scor":"Source – Identify sources","stype":"Activity","asis":"Process ends on submission to Finance.","change":"Modify","tobe":"Process ends on payment posting; PO auto-closes and the asset record activates in the fixed-asset register.","dept":"Finance","role":"Finance","sys":"Finance / Asset register","input":"Invoice in payment queue (PA-28-S390)","output":"Payment posted; PO closed","pillars":"Process","fit":"Not covered","erpReq":"Closed-loop process: requisition through to asset capitalisation.","moscow":"Should","prev":"PA-28-S390","next":"PA-28-S410","evId":"EV-NINV-9","evQuote":"Process ends on submission to Finance.","taskId":"— (PA-28 not in tasks)","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S410', N'PA-28', 422, N'Operational Excellence', N'New', N'Not covered', N'{"id":"PA-28-S410","pa":"PA-28","phase":"10. Equipment maintenance (optional)","scor":"Source – Identify sources","stype":"Activity","asis":"Bakery equipment runs 18–20 hours a day with no periodic or preventive maintenance; repair only after breakdown; some critical equipment is a single unit with no backup.","asisSys":"None identified","gapFlag":"Control Gap","gapDesc":"No maintenance plan or equipment register. (Root cause: outside the system)","change":"New","tobe":"Production and store equipment held in an asset / equipment register owned by CPU / CBU managers within EGC; the existing Swish maintenance ticket portal is migrated into the ERP; preventive maintenance plans per machine with service history and cost.","dept":"Operational Excellence","role":"Maintenance owner (to confirm); CPU / CBU / Store managers","sys":"D365 — Asset management","input":"Fixed-asset / equipment list (FA SOP)","output":"Maintenance plan","pillars":"Monitoring | Process","refs":"POL-D13","fit":"Not covered","erpReq":"Equipment register and preventive maintenance schedule.","ricefw":"Configuration","moscow":"Could","prev":"PA-28-S400","next":"PA-28-S420","evId":"EV-CBU-5.5; see PA-12-S100; EV-QL-IT01","evQuote":"most equipment works an average of 18 to 20 hours a day","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_steps (id, process_id, seq, dept, change_type, fit, data) VALUES (N'PA-28-S420', N'PA-28', 423, N'Operational Excellence', N'New', N'Not covered', N'{"id":"PA-28-S420","pa":"PA-28","phase":"10. Equipment maintenance (optional)","scor":"Source – Identify sources","stype":"Activity","asis":"Repair after breakdown via workshop; request and cost not recorded against the equipment.","asisSys":"None identified","gapFlag":"Gap","gapDesc":"Breakdown history and maintenance cost not visible.","change":"New","tobe":"Breakdown or service request raised as a maintenance ticket in the ERP (replacing the Swish ticket portal) against the equipment; external work through a service PO; cost recorded per machine.","dept":"Operational Excellence","role":"Requester (CPU / CBU / Store); Maintenance owner; Purchase","sys":"D365 — Work orders; service PO","input":"Maintenance plan; breakdown","output":"Work order history; maintenance cost","pillars":"Monitoring | Finance","fit":"Not covered","erpReq":"Work orders linked to service PO and equipment cost.","ricefw":"Configuration","moscow":"Could","prev":"PA-28-S410","next":"— (end)","evId":"EV-CBU-5.5","evQuote":"most equipment works an average of 18 to 20 hours a day","solType":"Pending – ERP provider"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-R01', N'Control', N'{"t":"Control","proc":"PA-04","risk":"Unsafe or damaged goods accepted with no usable record","text":"Condition checklist captured in the ERP and linked to the receipt","type":"Preventive","steps":"PA-04-S060, S070"}');
