INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-R03', N'Control', N'{"t":"Control","proc":"PA-04","risk":"Defective goods put into stock","text":"QC quality order must pass before putaway","type":"Preventive","steps":"PA-04-S190"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-R04', N'Control', N'{"t":"Control","proc":"PA-04","risk":"Doubtful goods released by the receiving function itself","text":"Quarantine release approved only by QC or CPU Manager","type":"Preventive","steps":"PA-04-S200"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-R05', N'Control', N'{"t":"Control","proc":"PA-04","risk":"Same person orders and receives","text":"PO creator cannot post the receipt; Costing sample review","type":"Preventive + Detective","steps":"PA-04-S230"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-01-1', N'Control', N'{"t":"Control","proc":"PA-01","risk":"Duplicate or unapproved article created; wrong UOM or variant","text":"Duplicate check on request; Costing approves every new / changed article with change history","type":"Preventive","steps":"PA-01-S080, PA-01-S150"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-01-2', N'Control', N'{"t":"Control","proc":"PA-01","risk":"Store orders articles outside its assortment","text":"Assortment per store restricts orderable articles","type":"Preventive","steps":"PA-01-S160"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-02-1', N'Control', N'{"t":"Control","proc":"PA-02","risk":"Stock or cost booked to the wrong legal entity / site; quarantined stock used","text":"Each site mapped to its legal entity; quarantine and rejected locations blocked for issue","type":"Preventive","steps":"PA-02-S010, PA-02-S100"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-03-1', N'Control', N'{"t":"Control","proc":"PA-03","risk":"Unauthorised or inflated replenishment orders","text":"Planned orders approved (maker-checker) before firming","type":"Preventive","steps":"PA-03-S140"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-03-2', N'Control', N'{"t":"Control","proc":"PA-03","risk":"Quantity drifts between requirement, PO and receipt","text":"One quantity carried through; differences captured with reason and reported","type":"Detective","steps":"PA-03-S160"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-05-1', N'Control', N'{"t":"Control","proc":"PA-05","risk":"Items stored in the wrong or unsafe location / temperature","text":"System location validation; QC storage validation; temperature alarms logged against stock","type":"Preventive + Detective","steps":"PA-05-S050, PA-05-S060, PA-05-S070"}');
