INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-06-2', N'Control', N'{"t":"Control","proc":"PA-06","risk":"Store receipt differences not resolved; stock lost in transit","text":"Receipt confirmed on the same transfer; differences with photo resolved by supervisor; daily open-transfer report","type":"Detective","steps":"PA-06-S240, PA-06-S250, PA-06-S260"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-06-3', N'Control', N'{"t":"Control","proc":"PA-06","risk":"Uncontrolled changes to store orders","text":"Changes on the same order with reason code by authorised role only (POL-D03, POL-D04)","type":"Preventive","steps":"PA-06-S130"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-07-1', N'Control', N'{"t":"Control","proc":"PA-07","risk":"Unrecorded or unauthorised store-to-store moves","text":"Costing approves every store-to-store transfer in the ERP (POL-D26)","type":"Preventive","steps":"PA-07-S030"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-08-1', N'Control', N'{"t":"Control","proc":"PA-08","risk":"Direct-to-store goods received without order or by the person who ordered","text":"Release order against PO; receipt posted by a different authorised user","type":"Preventive","steps":"PA-08-S080"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-08-2', N'Control', N'{"t":"Control","proc":"PA-08","risk":"Vendor paid for goods not received","text":"Three-way match of PO, receipt and invoice","type":"Preventive","steps":"PA-08-S130"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-09-1', N'Control', N'{"t":"Control","proc":"PA-09","risk":"Count manipulated to match book stock","text":"Blind count; recount by a different employee above threshold","type":"Preventive","steps":"PA-09-S070, PA-09-S090"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-09-2', N'Control', N'{"t":"Control","proc":"PA-09","risk":"Unapproved or unexplained stock adjustments","text":"Mandatory reason code; approval per matrix (POL-D22) before posting","type":"Preventive","steps":"PA-09-S100, PA-09-S120"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-10-1', N'Control', N'{"t":"Control","proc":"PA-10","risk":"Wastage over-stated or used to cover losses","text":"Supervisor verifies the physical item before approval; review limit by Cost Control / QC","type":"Preventive + Detective","steps":"PA-10-S060"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-10-2', N'Control', N'{"t":"Control","proc":"PA-10","risk":"Expired stock kept in use","text":"Daily near-expiry list by batch; write-off within the SLA","type":"Detective","steps":"PA-10-S110"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-11-1', N'Control', N'{"t":"Control","proc":"PA-11","risk":"Wrong or unsafe recipe used in production","text":"Cost Control verifies formula; R&D food-safety checklist; QC notified; one version-controlled formula","type":"Preventive","steps":"PA-11-S050, PA-11-S110, PA-11-S100, PA-11-S130"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-12-1', N'Control', N'{"t":"Control","proc":"PA-12","risk":"Over-production or production without material","text":"Material availability check; CPU Manager approves batch orders","type":"Preventive","steps":"PA-12-S090, PA-12-S120"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-13-1', N'Control', N'{"t":"Control","proc":"PA-13","risk":"Materials issued without production need or not confirmed","text":"Issue driven by released batch orders; receipt confirmed on the same document","type":"Preventive","steps":"PA-13-S030, PA-13-S090"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-13-2', N'Control', N'{"t":"Control","proc":"PA-13","risk":"One person orders, receives and confirms CPU materials","text":"Roles split across CPU Administrator and section chef / supervisor","type":"Preventive","steps":"PA-13-S160"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-14-1', N'Control', N'{"t":"Control","proc":"PA-14","risk":"Yield losses hidden in production","text":"Actual consumption and output per batch; yield variance reason; Cost Control review","type":"Detective","steps":"PA-14-S100, PA-14-S130"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-14-2', N'Control', N'{"t":"Control","proc":"PA-14","risk":"Unsafe product released","text":"QA production checks recorded against the batch","type":"Preventive","steps":"PA-14-S040"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-15-1', N'Control', N'{"t":"Control","proc":"PA-15","risk":"Unauthorised or unsafe ingredient substitution","text":"Culinary team confirms impact; QC review (allergens); authorised approval in the ERP","type":"Preventive","steps":"PA-15-S030, PA-15-S040, PA-15-S050"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-16-1', N'Control', N'{"t":"Control","proc":"PA-16","risk":"Finished goods dispatched before QA release","text":"QA batch release before allocation; QC truck check","type":"Preventive","steps":"PA-16-S010, PA-16-S070"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-17-1', N'Control', N'{"t":"Control","proc":"PA-17","risk":"Consumption differences not detected","text":"Theoretical vs actual by item, outlet and period; corrective actions tracked; negative-stock alert","type":"Detective","steps":"PA-17-S080, PA-17-S100, PA-17-S110"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-18-1', N'Control', N'{"t":"Control","proc":"PA-18","risk":"Affected stock not found or not blocked in a recall","text":"Batch traceability; stock blocked at every location; recall closed with reconciliation; mock recall twice a year","type":"Corrective","steps":"PA-18-S080, PA-18-S100"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-19-1', N'Control', N'{"t":"Control","proc":"PA-19","risk":"Period closed with open transactions or unreconciled stock","text":"Close checklist WD+1..WD+5; negative stock resolved; inventory reconciled to GL; formal sign-off and lock","type":"Preventive + Detective","steps":"PA-19-S070, PA-19-S100, PA-19-S130"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-20-1', N'Control', N'{"t":"Control","proc":"PA-20","risk":"Management reports differ from the ERP","text":"One data definition per KPI; dashboard figures reconciled before release; integration-failure alerts","type":"Detective","steps":"PA-20-S040, PA-20-S060"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-20-2', N'Control', N'{"t":"Control","proc":"PA-20","risk":"Users see data outside their company / brand","text":"Role- and company-based access tested","type":"Preventive","steps":"PA-20-S070"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-21-1', N'Control', N'{"t":"Control","proc":"PA-21","risk":"Direct-to-CPU goods received without call-off or by the orderer","text":"Receipt against the call-off; receiver independent of the person who ordered","type":"Preventive","steps":"PA-21-S060, PA-21-S100"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-21-2', N'Control', N'{"t":"Control","proc":"PA-21","risk":"Unsafe goods accepted at CPU","text":"Batch, expiry and temperature captured; QC decision recorded","type":"Preventive","steps":"PA-21-S070, PA-21-S080"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-23-1', N'Control', N'{"t":"Control","proc":"PA-23","risk":"Incorrect data migrated; unready go-live","text":"Trial migration reconciled; mock cutover; UAT sign-off; named go / no-go","type":"Preventive","steps":"PA-23-S030, PA-23-S040, PA-23-S060, PA-23-S080"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-25-1', N'Control', N'{"t":"Control","proc":"PA-25","risk":"Self-approved or unauthorised purchase orders","text":"Maker-checker PO release","type":"Preventive","steps":"PA-25-S080"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-25-2', N'Control', N'{"t":"Control","proc":"PA-25","risk":"Unapproved price changes","text":"Rate revision approved by Costing before use; rate history kept","type":"Preventive","steps":"PA-25-S120, PA-25-S130"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-25-3', N'Control', N'{"t":"Control","proc":"PA-25","risk":"Payment for incorrect invoices","text":"Three-way match; monthly vendor statement reconciliation","type":"Preventive + Detective","steps":"PA-25-S160, PA-25-S180"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-26-1', N'Control', N'{"t":"Control","proc":"PA-26","risk":"Unapproved standard costs or budgets activated","text":"Standard costs and budget approved and locked before activation","type":"Preventive","steps":"PA-26-S030, PA-26-S070"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-26-2', N'Control', N'{"t":"Control","proc":"PA-26","risk":"Transfer values to the store company misstated","text":"Rates and gate values agreed quarterly; monthly over / under absorption settlement (POL-D21)","type":"Detective","steps":"PA-26-S150, PA-26-S170"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-27-1', N'Control', N'{"t":"Control","proc":"PA-27","risk":"Excess or inappropriate system access; off-system processing","text":"User and role changes by ERP Administrator per Master roles; monthly counter audit; workaround register","type":"Preventive + Detective","steps":"PA-27-S110, PA-27-S120, PA-27-S130"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-28-1', N'Control', N'{"t":"Control","proc":"PA-28","risk":"Non-inventoriable purchases without competition or approval","text":"Minimum quotation count; Department / Business Head e-approval by value band","type":"Preventive","steps":"PA-28-S090, PA-28-S100, PA-28-S040, PA-28-S050"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'CTL-28-2', N'Control', N'{"t":"Control","proc":"PA-28","risk":"Payment for undelivered goods / services","text":"GRN or service entry; three-way match; maker-checker PO","type":"Preventive","steps":"PA-28-S210, PA-28-S320, PA-28-S350"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-R01', N'Policy', N'{"t":"Policy","scope":"PA-04","text":"Every item carries a minimum acceptable remaining shelf life, finalised by QC; fresh and daily items use a separate criterion; short-dated receipts are parked for approval.","owner":"QC Head","source":"Warehouse 3.2; QC 0.5","q":""}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-R02', N'Policy', N'{"t":"Policy","scope":"PA-04","text":"Price or quantity differences against the PO are settled by credit / debit note or a tracked pending replacement, not by waiting for a revised invoice.","owner":"Purchase / Finance","source":"CPU - O&R 7.6; Ops 3.3; Purchase 4.3","q":""}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D01', N'Policy', N'{"t":"Policy","scope":"System column on every step; all Interface items; PA-20, PA-24","text":"D365 or any ERP shall target replacing MC and introduce tools and structured work flow for all department of Supply Chain and Production. It shall replace all existing self developed platforms in phased manner some time it may continue with integration with ERP for a while until required development completely built in ERP system | yes the current POS (Foodics) shall be integrated as per the workflow steps and process requirement or any other POS changed in future shall continue the same integration.","owner":"Management; IT / ERP","source":"User decision, Query Log Q-P01 (2026) — evidence EV-QL-P01","q":"System scope & phasing: Is D365 the target for inventory, production and warehouse, replacing MC? For each Swish tool — Swish WMS, demand-planning website / Power BI, approved-vendor / purchase website, QC restaurant checklist tool, OPEX platform, finance direct-supply tracker — replace with D365 or keep and integrate? POS: Phase 2 (per tasks) or integrated with inventory now (Operations ask)?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D02', N'Policy', N'{"t":"Policy","scope":"RC1 everywhere; PA-01, PA-11, PA-12, PA-15, PA-26","text":"Swish inventory article is primary, the variant affect mapped with relevant adjustment at configuration level itself subject to tested yield, unit of meassure change, etc. | the final authority and custodian for these will by Costing department and it shall be mandated for each variant level. | pack size shall be standalone option manually to be selected and mapped to each variant option","owner":"Cost Control","source":"User decision, Query Log Q-P02 (2026) — evidence EV-QL-P02","q":"Article & variant model: Adopt the ''inventory flow'' model as the design: one Swish inventory article with variants, mapped to purchase-article variants (brand / origin), with variant and yield effects auto-adjusted? Or should an origin / brand that changes recipe or yield be a separate article? Pack size set per product or per brand? Who creates articles — Costing only, on request?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D03', N'Policy', N'{"t":"Policy","scope":"PA-06, PA-12, PA-13, PA-16, PA-25","text":"Yes One document from start to finish, changed in place, rather than rejected and re-raised | if query not answered raise the query clearly","owner":"All process owners","source":"User decision, Query Log Q-P03 (2026) — evidence EV-QL-P03","q":"One document, corrected not replaced: Design rule for the ERP: an order keeps one record end to end (store order, MR, PR → PO, transfer), changed in place with reason and audit trail, instead of rejected / cancelled and re-raised? And for the as-is: which unit rejects, which edits, which re-raises today?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D04', N'Policy', N'{"t":"Policy","scope":"PA-03, PA-06, PA-12, PA-13","text":"48 hour for global |they can add additional order case to case for missed units | and can allow correction of order only on exceptional case with concern of production department before their workflow locks the production process","owner":"Operations; CPU / CBU","source":"User decision, Query Log Q-P04 (2026) — evidence EV-QL-P04","q":"Order lead time: Adopt the 48-hour order rule company-wide (order today for the day after tomorrow)? Which items are exceptions (same-day breads, fresh vegetables, others)? Keep a small adjustment window (like today''s 9 p.m.)?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D05', N'Policy', N'{"t":"Policy","scope":"PA-04, PA-08, PA-21, PA-25; approval matrix","text":"CPU administrator, CPU supervisor, CPU chefs holds coordination role for the QC audit | mandated to have QC officer as much as possible and exception on case to case with alternate approval matrix with support of CPU senior team | CPU and CBU (Bakery) behaves in same way across the production process and related work flow | as of now only CPU administrator does the work recommended to add CPU chef or Supervisor to strengthen the process | include WH supervisor / Manager as well | Store Manager / Store Chef / Area Manager | Recommended to have maker / checker concept across all workflow - with exception to department level simple day to day workflow | Yes Nothing without PO","owner":"All process owners","source":"User decision, Query Log Q-P05 (2026) — evidence EV-QL-P05","q":"Who does what — segregation of duties: (a) Does CPU have its own QC officer? (b) At CPU direct supply, who receives / posts GRN so it is not the CPU Administrator who ordered? (c) Quarantine release: QC or CPU Manager only, or also Warehouse Supervisor / Manager? (d) Store direct-vendor GRN: who checks it against the WhatsApp order and invoice? (e) Should the warehouse PR have maker-checker? (f) Block ordering / receiving without a PO?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D06', N'Policy', N'{"t":"Policy","scope":"PA-06–10, PA-16, PA-17","text":"Yes Receipts 100% | yes for main items | yes wastage daily for main items | monthly stock for 100% items","owner":"Store Operations","source":"User decision, Query Log Q-P06 (2026) — evidence EV-QL-P06","q":"Store data in the system: Will stores (a) confirm receipts in the ERP, (b) record daily closing stock for main items, (c) enter wastage daily? Or keep monthly stock only?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D07', N'Policy', N'{"t":"Policy","scope":"PA-04, PA-13, PA-18, PA-21, PA-25","text":"Yes | recommended to have it in PO itself | Fresh / daily items - applied on practical and physical audit of goods received condition basis | FEFO system directed as guidance but actual based on the user selection and entered by batch specified inputs mentioned and logged into the ERP system","owner":"Quality Control","source":"User decision, Query Log Q-P07 (2026) — evidence EV-QL-P07","q":"Shelf-life & expiry policy: Does QC own a minimum remaining shelf life per item? Stated on the PO? Criterion for fresh / daily items? FEFO system-directed?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D08', N'Policy', N'{"t":"Policy","scope":"PA-04, PA-14, PA-16, PA-18","text":"Yes | Yes for all item exception to daily and fresh need to have some other trackable system in the new ERP","owner":"Quality Control; Warehouse","source":"User decision, Query Log Q-P08 (2026) — evidence EV-QL-P08","q":"Batch & traceability depth: Batch / expiry captured at receipt for all items or selected categories? FG batch labels printed by the system? Full raw-to-FG tracing (recall) required?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D09', N'Policy', N'{"t":"Policy","scope":"PA-04, PA-21, PA-25","text":"Yes for all","owner":"Purchase; Cost Control","source":"User decision, Query Log Q-P09 (2026) — evidence EV-QL-P09","q":"Vendor commitments & price control: Bulk POs (packing, imported food) held in the ERP as purchase agreements? Rate contracts with validity date and quantity? Price change approval by Costing? Credit / debit notes for differences? Tolerance for receiving more / less than the PO (today ''kept open for convenience'')?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D10', N'Policy', N'{"t":"Policy","scope":"PA-11, PA-13, PA-14, PA-17, PA-19, PA-26","text":"Stay and Standard and whenever inventory logs closes with inventory leftover with batch details locks the actual | same applies to yield as well - yield probably will be locked during each stage of the production process if ERP bring the suitable solution otherwise based on overall production process level | Treatement for Factory overhead - needs the ERP to equip with system and solution, whenever the management decides to initiate the process | also leave cost control review confirmation here","owner":"Cost Control","source":"User decision, Query Log Q-P10 (2026) — evidence EV-QL-P10","q":"Consumption & costing basis: CPU / CBU record actual consumption against the batch, or stay at standard? Yield % held on the recipe? Factory and labour cost added to production articles (inventory flow Y, Z)? By-products and staff cooking valued how? Wastage and usage costed daily or month end? (Or leave for the Cost Control interview.)"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D11', N'Policy', N'{"t":"Policy","scope":"All RC3 steps","text":"allow with outcome recorded in the system with approval matrix | predominantly the actual consumption shall conquer the cost flow  | yes \"actual consumption drives the cost\".","owner":"All process owners","source":"User decision, Query Log Q-P11 (2026) — evidence EV-QL-P11","q":"WhatsApp / email as working channels: Vendor ordering groups, sample and variant approvals, store order corrections, inter-section requests: replace with system transactions, or allow with the outcome recorded in the system?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D12', N'Policy', N'{"t":"Policy","scope":"PA-03, PA-12, PA-20","text":"As of now Data & Analytics Team | we can add Operation GM, CPU chief, Warehouse Head and Costing Head into this pool","owner":"Data & Analytics","source":"User decision, Query Log Q-P12 (2026) — evidence EV-QL-P12","q":"Forecasting ownership: Who is the ''forecast team'' (costing sheet)? Same as the Power BI demand plan (Ms Melanie) or the Data & Analytics team? Who owns the demand plan going forward — central planning, CPU / CBU, Operations?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D13', N'Policy', N'{"t":"Policy","scope":"New PA-28+; PA-22, PA-23, PA-27","text":"ok | bakery equip maintenance is generic to all production equipment at CPU as well as store level - which is an optional point more of value addition process - can add suitable setup in the ERP system if possible | all in","owner":"Management","source":"User decision, Query Log Q-P13 (2026) — evidence EV-QL-P13","q":"Scope boundaries: In or out: (a) PA-28 Non-inventoriable procurement (N-Inv) aligned with the FA SOP; (b) bakery equipment maintenance; (c) retail / cooperative sales channel; (d) Call Center; (e) store-level QC; (f) Training department ordering; (g) programme tasks (migration, training) carried from tasks as is."}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D14', N'Policy', N'{"t":"Policy","scope":"PA-17, 19, 20, 22–27","text":"Yes | our master shall be complete | workout the flow in such a way they (chiefs and other department) have already given the inputs through their sub ordinates interview or as ground observation input and anyway will be confirmed will review this docket","owner":"Programme","source":"User decision, Query Log Q-P14 (2026) — evidence EV-QL-P14","q":"Pending interviews: Confirm the interviews still to hold (Cost Control, Warehouse other roles, Purchase Chief, Logistics, Operations GM, Data & Analytics, Marketing, IT / ERP, Call Center, Finance, R&D, Training) and whether, meanwhile, those areas are built from the task list marked ''From task list''."}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D15', N'Policy', N'{"t":"Policy","scope":"PA-21-S070, S080","text":"CPU or CBU or Warehouse or any in (source point) out (despatch point) QC will be there - if not other relevant and equiavalent participant of related functional department will present","owner":"Quality Control","source":"User decision, Query Log Q-C01 (2026) — evidence EV-QL-C01","q":"QC at CPU receipt: Mr Osman lists QC officers at CBU and two warehouses only; Mr Subin says QC attends CPU receipt ''when available''. Which is right?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D16', N'Policy', N'{"t":"Policy","scope":"PA-25","text":"Yes to be should resolve this as per global standard","owner":"Purchase","source":"User decision, Query Log Q-C10 (2026) — evidence EV-QL-C10","q":"PO maker-checker: costing sheet: Purchase has maker-checker before PO. Inv - Steps: rate changes without approval (RC2) and maker-checker only RECOMMENDED (4.3)."}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D17', N'Policy', N'{"t":"Policy","scope":"PA-15-S030, S050","text":"Now the work flow at convenient it shall be mandated with clear process in future","owner":"CPU / CBU; Quality Control","source":"User decision, Query Log Q-C11 (2026) — evidence EV-QL-C11","q":"Brand / variant acceptance at CPU: CPU accepts informally (CPU - O&R 5.5) vs R&D approves with photograph (16.6)."}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D18', N'Policy', N'{"t":"Policy","scope":"PA-11-S070","text":"CPU and Costing | because yield at R&D sample size will be different when it compared at relatable production batch size | costing shall evident this","owner":"CPU / CBU; Cost Control","source":"User decision, Query Log Q-C12 (2026) — evidence EV-QL-C12","q":"Yield test owner: R&D sheet: ''yield and costing not handled by R&D''. Master PA-11-S040 assigns yield test to R&D (from CPU Mgmt 0.13). Who runs the yield test — CPU, Costing?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D19', N'Policy', N'{"t":"Policy","scope":"PA-13-S120","text":"standard on daily basis and adjusted to actual periodically probably on monthly, anyway it shall totally revamped into new ERP system","owner":"Cost Control","source":"User decision, Query Log Q-D10 (2026) — evidence EV-QL-D10","q":"Issues at standard: Are MC issues / transfers posted at standard recipe quantity or actual?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D20', N'Policy', N'{"t":"Policy","scope":"PA-12-S070; PA-01-S160","text":"it is a MC system administration issue with no clear evidence, in new system it shall be resolved","owner":"IT / ERP","source":"User decision, Query Log Q-D11 (2026) — evidence EV-QL-D11","q":"Repositioning privilege: Which store user IDs hold the inventory repositioning / assortment privilege and why?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D21', N'Policy', N'{"t":"Policy","scope":"PA-26-S090 to S190; PA-11; PA-14; PA-16; PA-06","text":"CONFIRMED (user, 30-Oct-2026): CPU / CBU output is transferred to the store company at a gate value = actual material (recipe items) + non-recipe items and packaging + direct labour + production overhead, absorbed at standard rates on normal capacity; mark-up 0%; head office, IT / ERP and logistics outside the gate value. Rates reviewed quarterly. Over / under absorption in every pool (variable, semi-fixed and fixed) is settled MONTHLY at month-end costing by re-allocation to receiving store companies in proportion to production material cost consumed (debit note for under-absorption, credit note for over-absorption). Normal loss inside standard yield; abnormal waste and abnormal idle capacity recovered but expensed by the receiver (IAS 2.13, 2.16). Phased: 0 today → 1 memo → 2 absorb → 3 refine. Detail: Master - Lists §L.","owner":"Costing Head; Finance Manager (approver)","source":"User decision 30-Oct-2026 on analyst proposal — evidence EV-QL-OH01, EV-QL-OH02","q":"How should factory, production and other overheads and direct labour be allocated and settled for CPU / CBU output?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D22', N'Policy', N'{"t":"Policy","scope":"PA-06-S060; PA-09-S110; PA-10-S070; PA-17-S090; PA-19-S130; PA-26-S010","text":"Single agreed approval level per transaction (Master - Lists §M). Within the level, the operational approver named in the step approves; any exception above the level is approved by Costing — no separate Operations or Finance approval, as Costing is the dedicated department responsible. Period sign-off by the Costing Head. KWD levels adopted as recommended; reviewed and, if required, amended by the Costing Head and the Finance Director. Not applicable to non-inventoriable procurement (PA-28), which follows its own value-band approval system (EV-QL-IT01).","owner":"Costing Head","source":"User decision 30-Oct-2026 — evidence EV-QL-AM01","q":"Who approves what, above what value?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D23', N'Policy', N'{"t":"Policy","scope":"PA-11-S100, S110; PA-15-S030, S040; PA-01-S060","text":"Food safety is built in at the R&D approval stage, not added as a production gate: R&D completes a mandatory food-safety checklist (allergens, shelf-life basis, critical control points, labelling) before signing off any new or changed recipe, substitute or variant. QC does not hold production; QC is notified automatically and reviews all recipes, changes, substitutes and variants introduced in the period on a periodic (monthly) basis, raising corrective actions where needed.","owner":"R&D Head (checklist); QC Head (periodic review)","source":"User decision 30-Oct-2026 on analyst guidance — evidence EV-QL-QC01","q":"Should QC approve each new recipe / substitute, or review periodically?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D24', N'Policy', N'{"t":"Policy","scope":"PA-19-S020 to S130; PA-04-S240","text":"Month-end close calendar: WD-1 cut-off of movements and transfers; WD+2 counts and adjustments posted; WD+3 open receipts / transfers cleared and negative stock resolved; WD+4 overhead settlement and inventory close; WD+5 Costing Head sign-off. Receipts reviewed by exception (100% of flagged variances plus a random 5% of clean receipts monthly).","owner":"Costing Head","source":"User decision 30-Oct-2026 on analyst proposal — evidence EV-QL-CC01","q":"When and how is the month closed?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D25', N'Policy', N'{"t":"Policy","scope":"PA-10-S100; PA-02-S040; PA-14","text":"By-products valued at net realisable value / standard and credited to the main product (co-product method). Staff meals: the staff cafeteria is a section of CPU / CBU; issues to it are at standard cost and form part of factory overhead (production support pool, POL-D21), not wastage.","owner":"Costing Head","source":"User decision 30-Oct-2026 — evidence EV-QL-CC01","q":"How are by-products and staff meals valued?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D26', N'Policy', N'{"t":"Policy","scope":"PA-06-S040, S080; PA-07-S010, S030; PA-08-S010","text":"Store ordering and supply: order guidance from the ERP demand-forecast tool and the existing demand-planning / Data & Analytics tool, decided by the Store Manager and finalised per the approval matrix. Every store-to-store transfer is notified to and approved by Costing in the ERP regardless of value, lodged before the move (emergency: within 2 hours) and approved within 4 working hours. Direct-delivery items and suppliers are selected centrally (Purchase proposes, Costing approves); stores do not select or decide direct items.","owner":"Costing Head; Purchase Chief","source":"User decision 30-Oct-2026 — evidence EV-QL-SO01","q":"How are store orders guided, transfers controlled and direct items decided?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D27', N'Policy', N'{"t":"Policy","scope":"PA-02-S010, S040; PA-23-S070; PA-22-S080; PA-17-S030","text":"Entity and site structure: EGC (service company) owns CPU, CBU, the central warehouse and the staff cafeteria; the store company owns the outlets. CPU sections, R&D and the cafeteria are sub-warehouses with their own cost centres. Cutover by project per POL-D32 (Project 1 supply chain ERP in waves W1–W5; Project 2 portals / warehouse system and overhead absorption; Project 3 POS replacement and franchise readiness). Retail / cooperative sales by ERP sales order invoiced by EGC; Call Center orders posted via Foodics under the fulfilling store.","owner":"Management; Finance Manager; IT / ERP","source":"User decision 30-Oct-2026 on analyst proposal — evidence EV-QL-ES01","q":"How are entities, sites and phases structured?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D28', N'Policy', N'{"t":"Policy","scope":"PA-27 (all); PA-23; every step (Role / System columns)","text":"ERP administration and department ERP representatives: the ERP Administrator (IT / ERP support) administers users and security roles, performs a periodic counter audit of user- and supervisory-level activity, logs every workaround or off-system processing against its step, and coordinates with the ERP vendor for initial training and day-to-day grievance clearance. Each department head nominates one department ERP representative who takes part extensively in structural inputs, UAT, migration and training in the early implementation stages, trains their own team, and clears day-to-day user grievances at supervisory level within the department. ERP training is not a Training-department responsibility; Training focuses on production and store operations. The ERP Administrator also owns the process control matrix and the brand-exception register (FD review D7, 31-Oct-2026).","owner":"IT / ERP Manager (ERP Administrator); Department heads (representatives)","source":"User decision 30-Oct-2026 — evidence EV-QL-IT01","q":"Who administers the ERP and supports users?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D29', N'Policy', N'{"t":"Policy","scope":"PA-11-S010, S110; PA-15","text":"Recipe ownership: R&D prepares the sample / test-batch recipe and hands it over to CPU; CPU tests and finalises the recipe for the production-level batch and coordinates with R&D to get it confirmed; Costing lodges the confirmed recipe into the system (Master position retained over the Finance Director proposal that Cost Control creates and approves).","owner":"R&D Head; CPU Manager; Costing Head","source":"User decision 31-Oct-2026 (FD review D2) — evidence EV-QL-FD01, EV-FD-179","q":"Who creates, finalises and lodges recipes in the ERP?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D30', N'Policy', N'{"t":"Policy","scope":"PA-16-S040; PA-06; PA-26-S150, S170","text":"EGC (CPU / CBU) supply to the store company: documentation and workflow control at par with a vendor prototype (supply catalogue, lead time, minimum issue quantity, delivery note, quality release, receipt confirmation, gate value and settlement), without managing EGC as a full vendor relationship.","owner":"Costing Head; Finance Manager","source":"User decision 31-Oct-2026 (FD review D1) — evidence EV-QL-FD01, EV-FD-229, EV-FD-232","q":"How are CPU / CBU supplies to stores documented and controlled?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D31', N'Policy', N'{"t":"Policy","scope":"PA-24-S010; PA-06-S230; PA-08; PA-09; PA-10","text":"A limited version of D365 Store Commerce is activated at stores for store inventory features (inbound / outbound inventory, stock count, inventory lookup) and integrated reporting, irrespective of Foodics or any other POS brought in. Full POS replacement remains Project 3 (PA-24, POL-D32).","owner":"IT / ERP Manager; Operations","source":"User decision 31-Oct-2026 (FD review D3) — evidence EV-QL-FD01, EV-FD-243","q":"Is D365 Store Commerce used at stores while Foodics remains the POS?"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'POL-D32', N'Policy', N'{"t":"Policy","scope":"PA-23-S065, S070, S100; PA-24; PA-27","text":"Programme phasing at two levels. (1) Projects: Project 1 — supply chain ERP (core inventory, purchasing, warehouse, CPU / CBU production, costing, Foodics integration; MC retired); Project 2 — Swish portals / warehouse system replacement and overhead absorption; Project 3 — POS replacement and franchise readiness. (2) Implementation waves inside Project 1, per the Finance Director''s roll-out order: W1 Foundation → W2 Core inventory transactions → W3 CPU / CBU → W4 Cost control → W5 Optimisation; the order and dependencies are finalised with the ERP consultant. Mitigation: each wave has an entry gate (previous wave data signed off) and UAT; MC runs in parallel for affected sites until W1–W4 are live and reconciled, then MC is retired; self-developed portals stay integrated until Project 2 replaces them; Foodics stays integrated (with limited D365 Store Commerce, POL-D31) until Project 3.","owner":"Programme sponsor (Management); IT / ERP Manager; ERP consultant","source":"User decision 31-Oct-2026 (FD review D6) — evidence EV-QL-FD02, EV-FD-297–303","q":"In what order are the projects and the supply chain implementation waves rolled out, and how is migration mitigated?"}');
