INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-10', N'Docket review', N'{"t":"Docket review","step":"PA-09-S030","q":"Warehouse and CPU count cycle today?","confirm":"Mr Ahmed Hafez; Ms Melanie","tobe":"Counts scheduled by location and frequency, generated automatically from the plan.","status":"Closed (30-Oct-2026) — not material to the design; to-be stands"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-11', N'Docket review', N'{"t":"Docket review","step":"PA-10-S110","q":"How warehouse expired stock is identified and written off today.","confirm":"Mr Ahmed Hafez","tobe":"Near-expiry and expired stock listed by batch daily; write-off raised through the same wastage approval.","status":"Closed (30-Oct-2026) — not material to the design; to-be stands"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-12', N'Docket review', N'{"t":"Docket review","step":"PA-21-S020","q":"Is forecast vs actual consumption compared for the monthly volume?","confirm":"Mr Subin; Purchase","tobe":"Bulk PO / purchase agreement raised with the direct-to-CPU delivery flag, rates and validity; a monthly forecast-vs-actual consumption report per agreement is reviewed by Purchase and Costing before the next month''s volume is set.","status":"Closed (30-Oct-2026) — not material to the design; to-be stands"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-13', N'Docket review', N'{"t":"Docket review","step":"PA-25-S140","q":"Value of open bulk commitments today (EV-QL-D12, deferred).","confirm":"Purchase","tobe":"Bulk commitment held as a purchase agreement with release orders and remaining balance visible.","status":"Implementation input — Opening balances of bulk commitments (PA-23-S020)"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-14', N'Docket review', N'{"t":"Docket review","step":"PA-26-S040","q":"How outlet and CPU budgets are prepared today.","confirm":"Finance; Cost Control","tobe":"Budget templates and planning assumptions issued.","status":"Closed (30-Oct-2026) — not material to the design; to-be stands"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-15', N'Docket review', N'{"t":"Docket review","step":"PA-06-S030","q":"Basis of order quantity (par level, POS, judgement)?","confirm":"Mr Walid Adel","tobe":"Retired — replaced by S040 / S050.","status":"Closed (30-Oct-2026) — not material to the design; to-be stands"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-16', N'Docket review', N'{"t":"Docket review","step":"PA-07-S010","q":"How do emergency transfers between stores happen today, and who approves?","confirm":"Mr Walid Adel","tobe":"Requesting outlet records the shortage in an outlet transfer request in the ERP; Costing is notified automatically (mandatory). The request is lodged before the physical move; in an emergency move it must be lodged within 2 hours of the move.","status":"Closed (30-Oct-2026) — not material to the design; to-be stands"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-17', N'Docket review', N'{"t":"Docket review","step":"PA-08-S010","q":"Which items and vendors go direct today?","confirm":"Mr Walid Adel; Purchase","tobe":"Direct-delivery items and suppliers are selected and approved centrally — proposed by Purchase and approved by Costing — and flagged per store in the ERP; stores have no role in selecting or deciding direct items. Items such as fries may move to dire","status":"Implementation input — Direct-delivery item / vendor master (PA-08-S010; PA-23-S020)"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-18', N'Docket review', N'{"t":"Docket review","step":"PA-02-S010","q":"Legal-entity list and which sites sit under each (incl. retail / cooperative channel).","confirm":"Finance","tobe":"Each site mapped to its legal entity: the EGC service company owns CPU, CBU, the central warehouse and the staff cafeteria; the store company (or companies) owns the outlets — matching the gate-value transfers of POL-D21.","status":"Implementation input — Legal-entity setup (PA-02-S010; PA-23)"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-19', N'Docket review', N'{"t":"Docket review","step":"PA-17-S030","q":"How Call Center orders reach stores and POS today (Foodics, aggregator apps); do they post to the same store sales?","confirm":"Call Center; IT / ERP","tobe":"Call Center orders are posted into Foodics under the fulfilling store, so they reach the ERP through the same Foodics sales interface as PA-17-S010; store item availability visible to the Call Center.","status":"Implementation input — Call Center interface design (PA-17-S030; PA-23)"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-20', N'Docket review', N'{"t":"Docket review","step":"PA-22-S080","q":"Retail / cooperative customers, ordering channel, pricing and who invoices.","confirm":"Management; CBU","tobe":"CBU sells to registered retail / cooperative customers through ERP sales orders on an approved price list; dispatch through PA-16 with batch and expiry; invoiced by the entity that owns CBU (EGC); margin reported by channel.","status":"Implementation input — Retail customer and price-list setup (PA-22-S080; PA-23-S020)"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-21', N'Docket review', N'{"t":"Docket review","step":"PA-11-S130","q":"How are old recipe-book copies recalled when a recipe changes (EV-QL-D08)?","confirm":"Ms Melanie; Costing","tobe":"One version-controlled formula; previous version expired, not deleted; printed recipe books withdrawn at go-live and staff view the current recipe version in the ERP.","status":"Closed (30-Oct-2026) — not material to the design; to-be stands"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-22', N'Docket review', N'{"t":"Docket review","step":"PA-14-S010","q":"How a production run starts and is tracked today, per section.","confirm":"Mr Sunil","tobe":"Production Supervisor starts the batch order.","status":"Closed (30-Oct-2026) — not material to the design; to-be stands"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-23', N'Docket review', N'{"t":"Docket review","step":"PA-16-S060","q":"Confirm Yellow Pizza dispatch time (EV-QL-D01).","confirm":"Mr Sunil","tobe":"Dispatch windows held per brand and route in the delivery schedule.","status":"Implementation input — Dispatch-window configuration (PA-16-S060; PA-23)"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-24', N'Docket review', N'{"t":"Docket review","step":"PA-20-S010","q":"Data & Analytics not yet interviewed.","confirm":"Data & Analytics","tobe":"KPI catalogue and one approved data definition per measure agreed.","status":"Implementation input — KPI catalogue (PA-20-S010; PA-23)"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-25', N'Docket review', N'{"t":"Docket review","step":"PA-28-S360","q":"Inferred step — confirm against actual practice (N-Inv open point).","confirm":"Purchase (Procurement)","tobe":"Procurement reviews only the exceptions raised by the three-way match rather than checking every invoice line by hand.","status":"Closed (30-Oct-2026) — not material to the design; to-be stands"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-26', N'Docket review', N'{"t":"Docket review","step":"PA-28-S370","q":"Inferred step — confirm against actual practice (N-Inv open point).","confirm":"Purchase (Procurement); Finance","tobe":"Procurement approves electronically under the non-inventoriable value-band approval system (separate from POL-D22, which covers costing transactions only).","status":"Closed (30-Oct-2026) — not material to the design; to-be stands"}');
INSERT INTO dbo.sc_sop_refs (id, ref_type, data) VALUES (N'DR-27', N'Docket review', N'{"t":"Docket review","step":"PA-18-S020","q":"Has a recall or mock recall ever been run, how was it traced, and who led it?","confirm":"Mr Osman","tobe":"QC leads recalls; mock recall twice a year; full trace within 4 hours (recommended)","status":"Implementation input — Recall procedure — compliance (PA-18-S020; PA-23-S050 UAT)"}');
